function redactSecrets(text) {
  return String(text)
    .replace(/(['"]?)([A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD|PASS|AUTH)[A-Z0-9_]*)(\1?\s*[:=]\s*)(['"])[^'"]+\4/gi, "$1$2$3$4[REDACTED]$4")
    .replace(/(Bearer\s+)[A-Za-z0-9._~+/-]+=*/gi, "$1[REDACTED]")
    .replace(/([?&](?:api_key|token|key|password)=)[^&\s'"]+/gi, "$1[REDACTED]");
}

function sanitizeEvidence(items) {
  return items.map((item) => {
    if (typeof item === "string") return redactSecrets(item);
    return item;
  });
}

function stableHash(input) {
  return createHash("sha256").update(JSON.stringify(input)).digest("hex").slice(0, 24);
}

function atomicWriteText(path, text, encoding = "utf8") {
  mkdirSync(dirname(path), { recursive: true });
  const tmp = `${path}.tmp-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  writeFileSync(tmp, text, encoding);
  renameSync(tmp, path);
}

function atomicWriteJson(path, payload, options = {}) {
  const spaces = options.pretty ? 2 : 0;
  atomicWriteText(path, JSON.stringify(payload, null, spaces) + "\n", "utf8");
  return path;
}

function readRuntimePolicy() {
  ensureDirs();
  const fallback = {
    schema: "mercury-runtime-policy-v1",
    mode: process.env.MERCURY_RUNTIME_MODE || "normal",
    slow_worker: process.env.MERCURY_DISABLE_SLOW_WORKER ? "defer" : "allowed",
    broad_scan: process.env.MERCURY_RUNTIME_MODE === "low-impact" ? "defer" : "allowed",
    disk_write_guard: process.env.MERCURY_RUNTIME_MODE === "low-impact" ? "strict" : "normal",
    reason: process.env.MERCURY_RUNTIME_MODE === "low-impact" ? "environment low-impact mode" : "default normal mode",
    updated_at: nowIso()
  };
  if (!existsSync(RUNTIME_POLICY_PATH)) return fallback;
  try {
    return { ...fallback, ...JSON.parse(readFileSync(RUNTIME_POLICY_PATH, "utf8")) };
  } catch {
    return fallback;
  }
}

function writeRuntimePolicy(mode, reason = "") {
  ensureDirs();
  const normalized = mode === "normal" ? "normal" : "low-impact";
  const policy = {
    schema: "mercury-runtime-policy-v1",
    mode: normalized,
    slow_worker: normalized === "low-impact" ? "defer" : "allowed",
    broad_scan: normalized === "low-impact" ? "defer" : "allowed",
    disk_write_guard: normalized === "low-impact" ? "strict" : "normal",
    reason: reason || (normalized === "low-impact"
      ? "keep computer/game/benchmark foreground performance first"
      : "normal background acceleration enabled"),
    updated_at: nowIso()
  };
  atomicWriteJson(RUNTIME_POLICY_PATH, policy, { pretty: true });
  return policy;
}

function sleepSync(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, Math.max(1, Number(ms) || 1));
}

function cachePath(namespace, keyParts) {
  return join(CACHE_DIR, `${namespace}_${stableHash(keyParts)}.json`);
}

function readJsonCache(namespace, keyParts) {
  ensureDirs();
  const path = cachePath(namespace, keyParts);
  if (JSON_CACHE_MEMORY.has(path)) return JSON_CACHE_MEMORY.get(path);
  if (!existsSync(path)) return null;
  try {
    const parsed = JSON.parse(readFileSync(path, "utf8"));
    JSON_CACHE_MEMORY.set(path, parsed);
    return parsed;
  } catch {
    return null;
  }
}

function writeJsonCache(namespace, keyParts, payload) {
  ensureDirs();
  const path = cachePath(namespace, keyParts);
  atomicWriteJson(path, payload);
  JSON_CACHE_MEMORY.set(path, payload);
  return path;
}

function fileFingerprint(path) {
  const abs = resolve(process.cwd(), path);
  const st = statSync(abs);
  return {
    cwd: process.cwd(),
    path,
    abs,
    mtimeMs: st.mtimeMs,
    size: st.size
  };
}

function strictFileFingerprint(path) {
  const fingerprint = fileFingerprint(path);
  const content = readFileSync(fingerprint.abs);
  return {
    ...fingerprint,
    sha256: createHash("sha256").update(content).digest("hex")
  };
}

function loadNeurons() {
  if (!NEURONS_CACHE) NEURONS_CACHE = normalizeNeuronCatalog(JSON.parse(readFileSync(NEURONS_PATH, "utf8")));
  return NEURONS_CACHE;
}

function shellAvailable(name) {
  const finder = platform() === "win32" ? "where.exe" : "which";
  const result = spawnSync(finder, [name], { encoding: "utf8" });
  return result.status === 0;
}

function safeExec(name, args, options = {}) {
  try {
    const output = execFileSync(name, args, {
      cwd: options.cwd || process.cwd(),
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      timeout: options.timeout || 5000,
      maxBuffer: options.maxBuffer || 512 * 1024
    });
    return { ok: true, output: output.trim() };
  } catch (error) {
    return {
      ok: false,
      output: String(error.stdout || error.stderr || error.message || "").trim()
    };
  }
}

function commandProbe(name, args = ["--version"], options = {}) {
  const available = shellAvailable(name);
  if (!available) return { name, available: false, version: null, detail: "not_on_path" };
  const probed = safeExec(name, args, {
    timeout: options.timeout || 1500,
    maxBuffer: options.maxBuffer || 128 * 1024
  });
  return {
    name,
    available: true,
    ok: probed.ok,
    version: probed.output ? probed.output.split(/\r?\n/)[0].slice(0, 180) : null
  };
}

function pythonModuleProbe(moduleName) {
  const py = shellAvailable("python3") ? "python3" : shellAvailable("python") ? "python" : null;
  if (!py) return { module: moduleName, available: false, detail: "python_missing" };
  const probed = safeExec(py, ["-c", `import ${moduleName}; print(getattr(${moduleName}, "__version__", "ok"))`], {
    timeout: 1800,
    maxBuffer: 64 * 1024
  });
  return {
    module: moduleName,
    available: probed.ok,
    version: probed.ok ? probed.output.split(/\r?\n/)[0].slice(0, 120) : null,
    error: probed.ok ? null : probed.output.slice(0, 160)
  };
}

function wslProbe() {
  if (platform() !== "win32" || !shellAvailable("wsl.exe")) {
    return { available: false, detail: platform() === "win32" ? "wsl_missing" : "non_windows" };
  }
  const probed = safeExec("wsl.exe", [
    "bash",
    "-lc",
    `OLLAMA_BIN=""; if [ -x ${WSL_OLLAMA_BIN} ]; then OLLAMA_BIN=${WSL_OLLAMA_BIN}; elif command -v ollama >/dev/null 2>&1; then OLLAMA_BIN=$(command -v ollama); fi; if [ -n "$OLLAMA_BIN" ]; then echo OLLAMA=present; echo OLLAMA_BIN=$OLLAMA_BIN; "$OLLAMA_BIN" --version 2>/dev/null | head -1 | sed 's/^/OLLAMA_VERSION=/'; curl -fsS --max-time 1 http://127.0.0.1:11434/api/tags 2>/dev/null | grep -o '"name":"[^"]*"' | sed 's/"name":"//;s/"//' | while read -r model; do echo OLLAMA_MODEL=$model; done; else echo OLLAMA=missing; fi; if command -v nvidia-smi >/dev/null 2>&1; then echo NVIDIA=$(nvidia-smi --query-gpu=name,memory.total,memory.used,utilization.gpu --format=csv,noheader,nounits | head -1); else echo NVIDIA=missing; fi`
  ], { timeout: 3500, maxBuffer: 64 * 1024 });
  const lines = probed.output.split(/\r?\n/);
  const ollamaLine = lines.find((line) => line.startsWith("OLLAMA=")) || "OLLAMA=missing";
  const ollamaVersionLine = lines.find((line) => line.startsWith("OLLAMA_VERSION=")) || "";
  const ollamaBinLine = lines.find((line) => line.startsWith("OLLAMA_BIN=")) || "OLLAMA_BIN=";
  const modelLines = lines.filter((line) => line.startsWith("OLLAMA_MODEL="));
  const nvidiaLine = lines.find((line) => line.startsWith("NVIDIA=")) || "NVIDIA=missing";
  const ollamaValue = ollamaLine.replace(/^OLLAMA=/, "").trim();
  const ollamaModels = modelLines.map((line) => line.replace(/^OLLAMA_MODEL=/, "").trim()).filter(Boolean);
  const nvidiaValue = nvidiaLine.replace(/^NVIDIA=/, "").trim();
  return {
    available: true,
    ok: probed.ok,
    ollama_available: probed.ok && ollamaValue && ollamaValue !== "missing",
    ollama_version: ollamaVersionLine.replace(/^OLLAMA_VERSION=/, "").trim().slice(0, 160) || null,
    ollama_bin: ollamaBinLine.replace(/^OLLAMA_BIN=/, "").trim() || null,
    ollama_models: ollamaModels,
    ollama_best_model: chooseLocalLlmModel(ollamaModels),
    nvidia_available: probed.ok && nvidiaValue && nvidiaValue !== "missing",
    nvidia: probed.ok && nvidiaValue !== "missing" ? nvidiaValue.slice(0, 160) : null
  };
}

function chooseLocalLlmModel(models = []) {
  const names = new Set((models || []).map((model) => String(model || "").trim()).filter(Boolean));
  if (names.has(DEFAULT_LOCAL_LLM_MODEL)) return DEFAULT_LOCAL_LLM_MODEL;
  if (names.has(FALLBACK_LOCAL_LLM_MODEL)) return FALLBACK_LOCAL_LLM_MODEL;
  return [...names].find((name) => /^qwen/i.test(name)) || [...names][0] || DEFAULT_LOCAL_LLM_MODEL;
}

function wslOllamaStatus() {
  if (platform() !== "win32" || !shellAvailable("wsl.exe")) return null;
  const probed = safeExec("wsl.exe", ["bash", "-lc", `if [ -x ${WSL_OLLAMA_BIN} ]; then echo OLLAMA_BIN=${WSL_OLLAMA_BIN}; fi; curl -fsS --max-time 2 http://127.0.0.1:11434/api/tags 2>/dev/null || true; find /home/norika/.ollama/models/manifests/registry.ollama.ai/library -mindepth 2 -maxdepth 2 -type f 2>/dev/null | sed 's#.*/library/##;s#/#:#' | sed 's/^/MANIFEST_MODEL=/' | head -12`], { timeout: 3500, maxBuffer: 128 * 1024 });
  let models = [];
  const bin = (probed.output.match(/OLLAMA_BIN=([^\n]+)/) || [])[1] || null;
  try {
    const jsonStart = probed.output.indexOf("{");
    const jsonEnd = probed.output.lastIndexOf("}");
    const jsonText = jsonStart >= 0 && jsonEnd >= jsonStart ? probed.output.slice(jsonStart, jsonEnd + 1) : "";
    models = (JSON.parse(jsonText).models || []).map((model) => model.name).filter(Boolean);
  } catch {}
  if (!models.length) {
    models = probed.output
      .split(/\r?\n/)
      .filter((line) => line.startsWith("MANIFEST_MODEL="))
      .map((line) => line.replace(/^MANIFEST_MODEL=/, "").trim())
      .filter(Boolean);
  }
  return {
    ok: probed.ok && (models.length > 0 || Boolean(bin)),
    bin,
    models,
    best_model: chooseLocalLlmModel(models)
  };
}

function buildAccelerationRoute(profile) {
  const providers = profile.provider_priority || [];
  const hasNvidia = profile.gpus?.length > 0 || providers.includes("nvidia_tensorrt_or_cuda") || providers.includes("wsl_cuda_bridge");
  const hasFastServing = providers.some((item) => /vllm|sglang|tensorrt_llm/i.test(item));
  const hasLocalModel = providers.some((item) => /ollama|llama_cpp|mlx|openvino|onnxruntime/i.test(item));
  const slowPath = [];
  if (hasFastServing) slowPath.push("batched_provider_refresh");
  if (providers.includes("wsl_ollama_qwer_slow_path") || providers.includes("ollama_reflex_slow_path")) slowPath.push("qwer_ollama_distill_once");
  if (providers.includes("llama_cpp_local")) slowPath.push("llama_cpp_distill_once");
  if (!slowPath.length && hasLocalModel) slowPath.push("local_model_refresh_only");
  if (!slowPath.length && hasNvidia) slowPath.push("gpu_ready_provider_missing");
  if (!slowPath.length) slowPath.push("no_model_call_use_reflex_queue");
  return {
    schema: "mercury-acceleration-route-v1",
    hot_path: [
      "reflex_exact_cache",
      "semantic_cache_low_risk_only",
      "project_uma_target_file_first",
      "code_cortex_symbol_first",
      "deterministic_tool_kernel"
    ],
    slow_path: slowPath,
    gpu_policy: hasNvidia
      ? "GPU is reserved for batched slow-path model refresh or provider serving; user-facing hot path stays cache/UMA first."
      : "No GPU route detected; keep model calls out of the hot path.",
    missing_for_extreme_speed: [
      hasFastServing ? null : "install or expose vLLM/SGLang/TensorRT-LLM for batched local inference",
      hasLocalModel ? null : "expose Ollama/llama.cpp/ONNX/OpenVINO/MLX for slow-path distillation",
      hasNvidia ? null : "install NVIDIA driver telemetry or CUDA-visible runtime"
    ].filter(Boolean)
  };
}

function extractTargetFiles(text) {
  const matches = text.match(/[A-Za-z0-9_.@/\\-]+\.(?:js|ts|py|json|toml|md|html|css|sql|sh|service|timer)/g) || [];
  return [...new Set(matches)].filter((candidate) => existsSync(resolve(process.cwd(), candidate)));
}

function parseEvidenceLine(line) {
  const match = line.match(/^(.*?):(\d+):(.*)$/);
  if (!match) return { path: null, line: null, text: line };
  return {
    path: match[1],
    line: Number(match[2]),
    text: match[3].trim()
  };
}

const LINE_CONTEXT_CACHE = new Map();

function readLineContext(path, lineNumber, radius = 2) {
  if (!path || !lineNumber) return [];
  const abs = resolve(process.cwd(), path);
  if (!existsSync(abs)) return [];
  const st = statSync(abs);
  const cacheKey = `${abs}:${st.mtimeMs}:${st.size}:${lineNumber}:${radius}`;
  if (LINE_CONTEXT_CACHE.has(cacheKey)) return LINE_CONTEXT_CACHE.get(cacheKey);
  const lines = readCachedLines(path);
  const start = Math.max(1, lineNumber - radius);
  const end = Math.min(lines.length, lineNumber + radius);
  const out = [];
  for (let i = start; i <= end; i += 1) {
    out.push(redactSecrets(`${path}:${i}:${lines[i - 1]}`));
  }
  LINE_CONTEXT_CACHE.set(cacheKey, out);
  return out;
}

function analyzeFileOutline(path) {
  const abs = resolve(process.cwd(), path);
  if (!existsSync(abs)) return { path, symbols: [] };
  const fingerprint = fileFingerprint(path);
  const cached = readJsonCache("outline", fingerprint);
  if (cached?.outline) return { ...cached.outline, cache: "hit" };

  const lines = readCachedLines(path);
  const symbols = [];
  const depths = [];
  let depth = 0;
  for (const line of lines) {
    depths.push(depth);
    const stripped = line
      .replace(/(["'`])(?:\\.|(?!\1).)*\1/g, "")
      .replace(/\/\/.*$/, "");
    const opens = (stripped.match(/{/g) || []).length;
    const closes = (stripped.match(/}/g) || []).length;
    depth += opens - closes;
    if (depth < 0) depth = 0;
  }

  const patterns = [
    { type: "function", re: /^\s*(?:async\s+)?function\s+([A-Za-z0-9_$]+)\s*\(/ },
    { type: "function", re: /^\s*(?:const|let|var)\s+([A-Za-z0-9_$]+)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>/ },
    { type: "function", re: /^\s*(?:const|let|var)\s+([A-Za-z0-9_$]+)\s*=\s*(?:async\s*)?function\b/ },
    { type: "class", re: /^\s*class\s+([A-Za-z0-9_$]+)/ },
    { type: "route", re: /^\s*(?:app|router)\.(get|post|put|patch|delete)\s*\(\s*['"`]([^'"`]+)/ },
    { type: "listener", re: /^\s*([A-Za-z0-9_$.]+)\.on\s*\(\s*['"`]([^'"`]+)/ }
  ];

  for (let i = 0; i < lines.length; i += 1) {
    if (depths[i] > 0) continue;
    for (const pattern of patterns) {
      const match = lines[i].match(pattern.re);
      if (!match) continue;
      const name = pattern.type === "route"
        ? `${match[1].toUpperCase()} ${match[2]}`
        : pattern.type === "listener"
          ? `${match[1]}.on(${match[2]})`
          : match[1];
      symbols.push({ name, type: pattern.type, start: i + 1, end: lines.length, depth: depths[i] });
      break;
    }
  }

  for (let i = 0; i < symbols.length; i += 1) {
    let end = i + 1 < symbols.length ? symbols[i + 1].start - 1 : lines.length;
    for (let lineIndex = symbols[i].start; lineIndex < end; lineIndex += 1) {
      if (lineIndex > symbols[i].start && depths[lineIndex] <= symbols[i].depth && /^\s*}/.test(lines[lineIndex - 1] || "")) {
        end = lineIndex;
        break;
      }
    }
    symbols[i].end = end;
    delete symbols[i].depth;
  }

  const outline = { path, symbols };
  writeJsonCache("outline", fingerprint, { created_at: nowIso(), outline });
  return outline;
}

function findSymbol(outlines, path, line) {
  const outline = outlines.find((item) => item.path === path);
  if (!outline) return null;
  return outline.symbols.find((symbol) => line >= symbol.start && line <= symbol.end) || null;
}

function normalizeEvidence(items) {
  return items.map((item) => {
    if (typeof item === "string") return parseEvidenceLine(item);
    return item;
  });
}

function uniqueEvidence(items) {
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const key = `${item.path || ""}:${item.line || ""}:${item.text || ""}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

function rankEvidence(item, findingId) {
  const text = String(item.text || "");
  const lower = text.toLowerCase();
  const selfReference = lower.includes("circuit.add(")
    || lower.includes("neuron.id")
    || lower.includes("activation_terms")
    || lower.includes("risk.");
  if (selfReference) return { rank: "noisy", score: 0.1 };

  const exact = {
    "risk.sqlite_timeout": ["sqlite3", "sql.connect", "database", "db.", "begin", "commit", "busy"],
    "risk.aggregate_scan": ["count(*)", "avg(", "group by", "order by", "fetchall", "full scan"],
    "risk.sync_exec": ["execfilesync", "spawnsync", "readfilesync", "writefilesync", "appendfilesync"],
    "risk.network_timeout": ["http.request", "https.request", "fetch(", "timeoutms", "abortcontroller"],
    "risk.retry_loop": ["settimeout", "setinterval", "retry", "queue", "backoff", "while ("],
    "risk.hot_path": ["settimeout", "setinterval", "http.request", "queue", "worker", "drain", ".on("],
    "risk.secret_exposure": ["[redacted]", "key", "token", "secret", "password", "auth"],
    "risk.atomic_write": ["write_text", "writetext", "open(\"w\"", "open('w'", "writefilesync", "latest", "manifest", "jsonl", "report"],
    "risk.silent_data_loss": ["jsondecodeerror", "continue", "pass", "except", "load_jsonl", "invalid json"],
    "risk.packaging_entrypoint": ["project.scripts", ":main", "package-dir", "packages", "missing module", "missing function"],
    "risk.uma_stale_memory": ["stale", "mtime", "fingerprint", "invalidate", "coherence"],
    "risk.cross_project_leak": ["namespace", "cross-project", "self namespace", "afu", "lobster", "memory gate"],
    "risk.rag_overfetch": ["fulltext", "scanlimit", "excerpt", "overfetch", "broad token"],
    "risk.rag_underfetch": ["missing", "sparse", "recall", "symbol", "pages_by_source"],
    "risk.semantic_false_hit": ["semantic", "threshold", "permission", "billing", "admin"],
    "risk.model_hot_path": ["ollamagenerate", "api/generate", "model_hot_path", "qwer", "generate"],
    "risk.provider_probe_hot_path": ["runtime-detect", "wsl.exe", "nvidia-smi", "detectaccelerationruntimes", "provider hint"],
    "risk.slow_worker_spin": ["slow-worker", "slow job", "deferred", "failed", "provider"],
    "risk.context_bloat": ["packet", "raw_bytes", "packet_bytes", "prompt", "context"],
    "risk.unbounded_swarm": ["swarm", "neuron", "circuit", "max_neurons", "resource guard"]
  };
  const terms = exact[findingId] || [];
  if (terms.some((term) => lower.includes(term))) return { rank: "high", score: 1 };
  if (item.symbol) return { rank: "medium", score: 0.55 };
  return { rank: "low", score: 0.3 };
}

