function isUmaPhaseNeuron(id) {
  return UMA_PHASE_PREFIXES.some((prefix) => id.startsWith(prefix));
}

function normalizeNeuronCatalog(neurons = []) {
  const normalized = neurons.map((neuron, index) => {
    const type = neuron.type || String(neuron.id || "").split(".")[0] || "synthesis";
    const cluster = neuron.cluster || neuronCluster(neuron.id);
    const lane = neuron.lane || neuronParallelLane({ ...neuron, type, cluster });
    const dispatchPhase = neuron.dispatch_phase ?? neuronDispatchPhase(lane);
    const domain = neuron.placement?.domain || neuronDomain(neuron);
    return {
      ...neuron,
      type,
      cluster,
      lane,
      dispatch_phase: dispatchPhase,
      substrate: neuron.substrate || NEURON_TYPE_SUBSTRATE[type] || "cpu.l1_hot_path",
      shard_family: neuron.shard_family || NEURON_TYPE_SHARD_FAMILY[type] || "misc-shards",
      placement: neuron.placement || {
        ring: cluster,
        domain,
        wave: dispatchPhase === 0 ? "sense" : dispatchPhase === 1 ? "decide" : "stabilize",
        slot: index
      },
      entangles_with: Array.isArray(neuron.entangles_with) ? neuron.entangles_with : []
    };
  });
  const byDomain = new Map();
  for (const neuron of normalized) {
    const domain = neuronDomain(neuron);
    if (!byDomain.has(domain)) byDomain.set(domain, []);
    byDomain.get(domain).push(neuron);
  }
  for (const neuron of normalized) {
    if (neuron.entangles_with.length) continue;
    const family = byDomain.get(neuronDomain(neuron)) || [];
    const phaseMate = family.find((item) => item.dispatch_phase !== neuron.dispatch_phase)?.id;
    const laneMate = family.find((item) => item.lane !== neuron.lane)?.id;
    const clusterMate = normalized.find((item) => item.cluster === neuron.cluster && item.id !== neuron.id)?.id
      || normalized.find((item) => item.lane === neuron.lane && item.id !== neuron.id)?.id
      || normalized.find((item) => item.id !== neuron.id)?.id;
    neuron.entangles_with = [...new Set([phaseMate, laneMate, clusterMate, family[0]?.id].filter(Boolean).filter((id) => id !== neuron.id))].slice(0, 4);
  }
  return normalized;
}

function readCachedFile(path) {
  const abs = resolve(process.cwd(), path);
  const st = statSync(abs);
  const cached = FILE_TEXT_CACHE.get(abs);
  if (cached && cached.mtimeMs === st.mtimeMs && cached.size === st.size) return cached.text;
  const text = readFileSync(abs, "utf8");
  FILE_TEXT_CACHE.set(abs, { text, lines: null, mtimeMs: st.mtimeMs, size: st.size });
  return text;
}

function readCachedLines(path) {
  const abs = resolve(process.cwd(), path);
  const text = readCachedFile(path);
  const st = statSync(abs);
  const cached = FILE_TEXT_CACHE.get(abs);
  if (cached?.lines && cached.mtimeMs === st.mtimeMs && cached.size === st.size) return cached.lines;
  const lines = text.split(/\r?\n/);
  FILE_TEXT_CACHE.set(abs, { ...cached, text, lines, mtimeMs: st.mtimeMs, size: st.size });
  return lines;
}

function parsePyprojectEntrypoints(path) {
  const lines = readCachedLines(path);
  let inScripts = false;
  let packageRoot = "";
  const entries = [];

  for (let i = 0; i < lines.length; i += 1) {
    const raw = lines[i];
    const line = raw.trim();
    if (/^\[/.test(line)) inScripts = line === "[project.scripts]";

    const packageDir = line.match(/^package-dir\s*=\s*\{\s*""\s*=\s*["']([^"']+)["']\s*\}/);
    if (packageDir) packageRoot = packageDir[1];

    if (!inScripts) continue;
    const entry = line.match(/^([A-Za-z0-9_.-]+)\s*=\s*["']([A-Za-z0-9_.]+):([A-Za-z0-9_]+)["']/);
    if (!entry) continue;
    entries.push({
      line: i + 1,
      command: entry[1],
      moduleName: entry[2],
      functionName: entry[3],
      target: `${entry[2]}:${entry[3]}`,
      packageRoot
    });
  }

  return entries;
}

function entrypointModulePath(entry) {
  return join(entry.packageRoot || "", ...entry.moduleName.split(".")) + ".py";
}

function functionExistsInPythonModule(path, functionName) {
  if (!existsSync(resolve(process.cwd(), path))) return false;
  const lines = readCachedLines(path);
  const defRe = new RegExp(`^\\s*def\\s+${functionName}\\s*\\(`);
  const asyncDefRe = new RegExp(`^\\s*async\\s+def\\s+${functionName}\\s*\\(`);
  return lines.some((line) => defRe.test(line) || asyncDefRe.test(line));
}

function packagingEntrypointValidationLines(targets = []) {
  const out = [];
  for (const target of targets.filter((item) => item.endsWith("pyproject.toml"))) {
    const entries = parsePyprojectEntrypoints(target);
    for (const entry of entries) {
      const modulePath = entrypointModulePath(entry);
      if (!existsSync(resolve(process.cwd(), modulePath))) {
        out.push(`${target}:${entry.line}:missing module ${modulePath} for ${entry.command} = ${entry.target}`);
        continue;
      }
      if (!functionExistsInPythonModule(modulePath, entry.functionName)) {
        out.push(`${target}:${entry.line}:missing function ${entry.functionName} in ${modulePath} for ${entry.command}`);
      }
    }
  }
  return out;
}

function targetBundleKey(targets) {
  const fingerprints = targets
    .filter((target) => existsSync(resolve(process.cwd(), target)))
    .map(fileFingerprint);
  return {
    cwd: process.cwd(),
    families: Object.fromEntries(Object.entries(TARGET_SEARCH_FAMILIES).map(([name, re]) => [name, re.source])),
    targets: fingerprints
  };
}

function buildTargetSearchBundle(targets = []) {
  if (!targets.length) return null;
  const key = targetBundleKey(targets);
  if (!key.targets.length) return null;
  const localKey = stableHash(key);
  if (TARGET_BUNDLE_CACHE.has(localKey)) return TARGET_BUNDLE_CACHE.get(localKey);

  const cached = readJsonCache("target_bundle", key);
  if (cached?.bundle) {
    const bundle = { ...cached.bundle, engine: "cache" };
    TARGET_BUNDLE_CACHE.set(localKey, bundle);
    return bundle;
  }

  const bundle = {
    engine: "batch_in_process",
    families: Object.fromEntries(Object.keys(TARGET_SEARCH_FAMILIES).map((name) => [name, []]))
  };
  for (const target of targets) {
    const abs = resolve(process.cwd(), target);
    if (!existsSync(abs)) continue;
    const lines = readCachedLines(target);
    for (let i = 0; i < lines.length; i += 1) {
      if (!TARGET_SEARCH_ANY.test(lines[i])) continue;
      for (const [family, re] of Object.entries(TARGET_SEARCH_FAMILIES)) {
        if (bundle.families[family].length >= 200) continue;
        if (re.test(lines[i])) bundle.families[family].push(`${target}:${i + 1}:${redactSecrets(lines[i])}`);
      }
    }
  }
  writeJsonCache("target_bundle", key, { created_at: nowIso(), bundle });
  TARGET_BUNDLE_CACHE.set(localKey, bundle);
  return bundle;
}

function targetFamilySearch(family, targets = []) {
  const bundle = buildTargetSearchBundle(targets);
  if (!bundle || !bundle.families?.[family]) return null;
  const lines = bundle.families[family];
  return { ok: lines.length > 0, output: lines.join("\n"), engine: bundle.engine };
}

function targetFamilyLines(family, pattern, targets = [], context = null) {
  let bundle = null;
  if (context && context.targetFiles === targets) {
    if (!context.targetBundle) context.targetBundle = buildTargetSearchBundle(targets);
    bundle = context.targetBundle;
  } else {
    bundle = buildTargetSearchBundle(targets);
  }
  if (bundle?.families?.[family]) return bundle.families[family];
  const search = searchText(pattern, targets);
  return search.output ? search.output.split("\n") : [];
}

function createRunContext(taskText) {
  return {
    taskText,
    cwd: process.cwd(),
    targetFiles: extractTargetFiles(taskText),
    targetBundle: null,
    umaHits: [],
    umaElapsedMs: 0,
    umaRoute: null,
    gitRecent: null,
    profile: false
  };
}

function compactEvidenceText(text, maxChars = 220) {
  return String(text || "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maxChars);
}

function buildUmaEvidencePacket(context, options = {}) {
  const hits = context.umaHits || [];
  const route = context.umaRoute || {};
  const excerptChars = options.excerptChars || 120;
  const sourceList = [...new Set(hits.map((hit) => hit.source_path).filter(Boolean))].slice(0, 8);
  const sourceIndex = new Map(sourceList.map((source, index) => [source, index]));
  const tokenHints = [...semanticTokens(`${context.taskText || ""} ${sourceList.join(" ")}`)].slice(0, 16);
  const items = hits.slice(0, 6).map((hit) => ({
    pointer: hit.pointer,
    source: sourceIndex.get(hit.source_path) ?? null,
    score: hit.score,
    excerpt: compactEvidenceText(hit.text, excerptChars)
  }));
  return {
    schema: "uma-evidence-packet-v2",
    route: route.target_file_first ? "target_file_first" : route.symbol_first ? "symbol_first" : route.hot_page_first ? "hot_page_first" : "token_postings",
    candidate_pages: route.candidate_pages || 0,
    hit_count: hits.length,
    sources: sourceList,
    token_hints: tokenHints,
    compression: {
      source: "uma_hits",
      max_items: 6,
      excerpt_chars: excerptChars
    },
    items
	  };
	}

function buildRosenBridgeArtifact(context) {
  const route = context.rosenRoute || null;
  const pair = context.rosenPair || null;
  if (!route) {
    return {
      neuron_id: "memory.rosen_bridge_preload",
      kernel: "rosen_cortex",
      signal: "rosen_bridge_skipped",
      evidence: ["No Rosen bridge route was computed for this task."],
      confidence: 0.2,
      elapsed_ms: 0,
      details: { selected_count: 0 }
    };
  }
  return {
    neuron_id: "memory.rosen_bridge_preload",
    kernel: "rosen_cortex",
    signal: route.selected_count ? "rosen_bridge_route_ready" : "rosen_bridge_route_sparse",
    evidence: [
      ...route.selected.slice(0, 6).map((bridge) => `${bridge.type}:${bridge.to} score=${bridge.score} source=${bridge.source} risk=${bridge.risk}`),
      pair ? `rosen_pair:${pair.mode} changed=${pair.changed ? "yes" : "no"} confidence=${pair.confidence}` : null
    ].filter(Boolean),
    confidence: route.selected_count ? Math.min(0.92, 0.42 + route.selected_count * 0.04) : 0.28,
    elapsed_ms: route.elapsed_ms || 0,
    details: {
      namespace: route.namespace,
      risk_families: route.entry?.risk_families?.map((family) => family.id) || [],
      candidates: route.candidates,
      selected_count: route.selected_count,
      pair: pair ? {
        id: pair.pair_id,
        mode: pair.mode,
        changed: pair.changed,
        confidence: pair.confidence,
        elapsed_ms: pair.elapsed_ms
      } : null,
      probe_plan: route.probe_plan,
      guard: route.guard
    }
  };
}

function evidencePacketPrompt(packet) {
  const sources = (packet.sources || [])
    .map((source, index) => `S${index}: ${source}`)
    .join("\n");
  const evidence = (packet.items || [])
    .map((item, index) => `E${index + 1}: ${item.pointer} score=${item.score} ${item.excerpt}`)
    .join("\n");
  const tokens = (packet.token_hints || []).join(", ");
  return [
    `UMA route: ${packet.route}`,
    `hits: ${packet.hit_count}, candidate_pages: ${packet.candidate_pages}`,
    sources ? `sources:\n${sources}` : "sources: -",
    evidence ? `evidence:\n${evidence}` : "evidence: -",
    tokens ? `token_hints: ${tokens}` : "token_hints: -"
  ].join("\n");
}

function buildColdStartScaffold(taskText, packet, options = {}) {
  const task = String(taskText || "accelerate task").trim();
  const intent = /\b(report|article|5000|write|draft|generate)\b/i.test(task)
    ? "long_form_first_draft"
    : /\b(debug|diagnose|latency|slow|leak|cost|spend|anthropic|claude)\b/i.test(task)
    ? "diagnosis_first_pass"
    : "general_first_pass";
  const evidenceItems = (packet.items || []).slice(0, options.maxEvidence || 5);
  const facts = evidenceItems.length
    ? evidenceItems.map((item, index) => `${index + 1}. ${item.pointer}: ${item.excerpt}`)
    : ["1. No UMA page hit yet; keep answer scoped and ask slow path to fill missing facts."];
  const actions = intent === "long_form_first_draft"
    ? [
        "Open with the claim/answer, then expand from UMA evidence.",
        "Use source pointers as anchors, not as decoration.",
        "Leave unknown sections as TODO for the slow model instead of inventing facts."
      ]
    : intent === "diagnosis_first_pass"
    ? [
        "Rank likely hot paths before reading more files.",
        "Check paid-provider loops, sync IO, queues, retries, and stale UMA first.",
        "Return concrete file pointers before any large model call."
      ]
    : [
        "Answer from deterministic evidence first.",
        "Use UMA pointers to reduce model context.",
        "Queue the slow model only for synthesis gaps."
      ];
  return [
    `Cold-start Mercury scaffold for: ${task}`,
    `Intent: ${intent}`,
    `Route: ${packet.route}, UMA hits: ${packet.hit_count}`,
    "",
    "Immediate useful draft:",
    ...facts,
    "",
    "Next actions:",
    ...actions.map((line, index) => `${index + 1}. ${line}`),
    "",
    "Slow-path instruction:",
    "Use the evidence packet below. Do not rescan the whole repo unless the packet is empty."
  ].join("\n");
}

function getRecentGitChanges(context) {
  const key = context?.cwd || process.cwd();
  if (context?.gitRecent) return context.gitRecent;
  if (GIT_RECENT_CACHE.has(key)) {
    const cached = GIT_RECENT_CACHE.get(key);
    if (context) context.gitRecent = cached;
    return cached;
  }
  const git = safeExec("git", ["log", "--oneline", "-8"], { timeout: 4000 });
  GIT_RECENT_CACHE.set(key, git);
  if (context) context.gitRecent = git;
  return git;
}

function taskNeedsGitHistory(taskText) {
  return /\b(git|commit|commits|recent changes?|history|diff|branch)\b/i.test(taskText);
}

function neuronCluster(id = "") {
  const prefix = id.split(".")[0];
  if (prefix === "intent" || prefix === "decompose") return "decompose";
  if (prefix === "retrieval" || prefix === "git" || prefix === "tool" || prefix === "explore") return "retrieval";
  if (prefix === "risk" || prefix === "analyze") return "risk";
  if (prefix === "accelerate") return "accelerate";
  if (prefix === "memory") return "memory";
  if (prefix === "evidence") return "evidence";
  if (prefix === "critic" || prefix === "safety") return "judge";
  if (prefix === "compression" || prefix === "synthesis" || prefix === "recompose" || prefix === "verify") return "synthesis";
  return "other";
}

function neuronClusterRank(id) {
  return {
    decompose: 0,
    retrieval: 1,
    risk: 2,
    accelerate: 3,
    memory: 4,
    evidence: 5,
    judge: 6,
    synthesis: 7,
    other: 8
  }[neuronCluster(id)] ?? 8;
}

function neuronParallelLane(neuron) {
  if (neuron.lane) return neuron.lane;
  const cluster = neuronCluster(neuron.id);
  const type = neuron.type || neuron.id.split(".")[0];
  if (cluster === "decompose") return "goal_lane";
  if (cluster === "retrieval") return type === "explore" ? "surface_lane" : "memory_retrieval_lane";
  if (cluster === "risk") return type === "analyze" ? "analysis_lane" : "risk_lane";
  if (cluster === "accelerate") return "acceleration_lane";
  if (cluster === "memory") return "writeback_lane";
  if (cluster === "judge" || cluster === "evidence") return "judge_lane";
  if (cluster === "synthesis") return type === "verify" ? "verification_lane" : "synthesis_lane";
  return "support_lane";
}

function neuronLaneBudget(lane, context, taskText) {
  const targetFileFastPath = Boolean(context.targetFiles?.length);
  const wantsBroad = /\b(uma|rag|neuron|agent|swarm|monster|architecture|map|control|scheduler|acceleration)\b/i.test(taskText);
  const base = {
    goal_lane: wantsBroad ? 4 : 2,
    memory_retrieval_lane: targetFileFastPath ? 3 : 2,
    surface_lane: targetFileFastPath ? 1 : 3,
    analysis_lane: targetFileFastPath ? 4 : 3,
    risk_lane: targetFileFastPath ? 8 : 0,
    acceleration_lane: wantsBroad ? 4 : 2,
    writeback_lane: wantsBroad ? 3 : 1,
    judge_lane: 3,
    verification_lane: targetFileFastPath ? 3 : 2,
    synthesis_lane: 3,
    support_lane: 1
  };
  return base[lane] ?? 1;
}

function rosenNeuronBoost(neuron, context = {}) {
  const route = context.rosenRoute || null;
  if (!route?.selected?.length) return 0;
  const text = [
    neuron.id,
    neuron.type,
    neuron.specialty,
    ...(neuron.activation_terms || [])
  ].join(" ").toLowerCase();
  const families = new Set(route.entry?.risk_families?.map((family) => family.id) || []);
  let boost = 0;
  const addIf = (condition, value) => { if (condition) boost += value; };
  addIf(families.has("provider_spend") && /\b(cost|spend|provider|anthropic|openai|claude|secret|credential|risk|judge|safety)\b/i.test(text), 0.34);
  addIf(families.has("latency_hot_path") && /\b(latency|slow|hot|path|cache|timeout|retry|budget|accelerate|queue)\b/i.test(text), 0.3);
  addIf(families.has("local_llm_speed") && /\b(qwen|qwer|llm|model|provider|cache|avoidance|slow|worker|distill)\b/i.test(text), 0.32);
  addIf(families.has("memory_route") && /\b(uma|rag|memory|namespace|coherence|hot|page|packet|pointer)\b/i.test(text), 0.3);
  addIf(families.has("security_hardening") && /\b(security|secret|credential|private|boundary|safety|risk|verify|tribunal)\b/i.test(text), 0.32);
  addIf(families.has("first_generation") && /\b(first|generation|report|draft|section|synthesis|compression|distill|reflex)\b/i.test(text), 0.28);
  for (const bridge of route.selected.slice(0, 8)) {
    const bridgeText = `${bridge.to || ""} ${bridge.type || ""} ${bridge.evidence || ""}`.toLowerCase();
    const terms = (neuron.activation_terms || []).map((term) => String(term).toLowerCase()).filter((term) => term.length >= 3);
    if (terms.some((term) => bridgeText.includes(term))) boost += 0.04;
    if (bridge.to?.startsWith("tool:") && neuron.id.startsWith("tool.")) boost += 0.05;
    if (bridge.to?.startsWith("uma:") && /\b(uma|rag|retrieval|memory|compression)\b/i.test(text)) boost += 0.04;
    if ((bridge.type === "blocked_by" || bridge.type === "unsafe_if") && /\b(safety|risk|verify|critic|judge)\b/i.test(text)) boost += 0.05;
  }
  return Number(Math.min(0.72, boost).toFixed(4));
}

function neuronDomain(neuron = {}) {
  if (neuron.placement?.domain) return neuron.placement.domain;
  const body = String(neuron.id || "").split(".").slice(1).join(".");
  return body.replace(/_v\d+.*/i, "").replace(/\.\d+.*/i, "") || "core";
}

function neuronStateBinding(neuron) {
  const domain = neuronDomain(neuron);
  const lane = neuron.lane || neuronParallelLane(neuron);
  const cluster = neuron.cluster || neuronCluster(neuron.id);
  const text = `${neuron.id} ${neuron.type} ${domain} ${neuron.specialty || ""} ${cluster} ${lane}`.toLowerCase();
  let observable = "project.memory";
  let sensor = "uma_project";
  let stateKey = "uma.pages";
  if (/qwen|qwer|ollama|provider|model|llm/.test(text)) {
    observable = "local_llm.provider";
    sensor = "qwer_speed";
    stateKey = /queue|worker|defer|pending/.test(text) ? "qwen.queue"
      : /hint|route|provider/.test(text) ? "qwen.provider_route"
      : /cache|reflex|distill|replay/.test(text) ? "qwen.cache"
      : "qwen.latency";
  } else if (/gpu|3060|diskspd|windows|hardware|runtime|installer/.test(text)) {
    observable = "host.hardware";
    sensor = "speed_state";
    stateKey = /diskspd|throughput|latency|benchmark/.test(text) ? "product.diskspd"
      : /installer|activate|product|runtime/.test(text) ? "product.activation"
      : /memory|pressure|ram/.test(text) ? "host.memory"
      : "host.gpu_memory";
  } else if (/spend|anthropic|claude|secret|credential|cost|billing/.test(text)) {
    observable = "external.spend";
    sensor = "spend_guard";
    stateKey = /secret|credential|key|token|env/.test(text) ? "spend.credentials"
      : /loop|interval|cron|worker|runtime/.test(text) ? "spend.loop"
      : "spend.findings";
  } else if (/rosen|bridge|pair|state|wormhole|entangle/.test(text)) {
    observable = "rosen.state_pair";
    sensor = "rosen_pairs";
    stateKey = /bridge|route/.test(text) ? "rosen.bridges"
      : /pair|pulse|state|entangle|wormhole/.test(text) ? "rosen.pairs"
      : "rosen.pulses";
  } else if (/uma|rag|namespace|page|symbol|cortex|memory|cache|hot/.test(text)) {
    observable = "project.memory";
    sensor = /symbol|cortex/.test(text) ? "code_cortex" : "uma_project";
    stateKey = /namespace|isolation|project/.test(text) ? "uma.namespace"
      : /coherence|stale|invalid|refresh/.test(text) ? "uma.coherence"
      : /hot|promotion|demotion|cache/.test(text) ? "uma.hot_pages"
      : /symbol|cortex|code/.test(text) ? "uma.symbols"
      : /rag|packet|evidence|pointer/.test(text) ? "rag.packet"
      : "uma.pages";
  } else if (/bench|proof|trend|integrity|verify|regression/.test(text)) {
    observable = "proof.benchmark";
    sensor = "bench_history";
    stateKey = /fresh|age|stale/.test(text) ? "proof.freshness"
      : /qwen|cold/.test(text) ? "proof.qwen"
      : /diskspd|hardware/.test(text) ? "proof.diskspd"
      : "bench.latest";
  } else if (/lane|scheduler|overactivation|neuron|swarm|agent/.test(text)) {
    observable = "neuron.control";
    sensor = "score_ledger";
    stateKey = /lane|wave|dispatch/.test(text) ? "neuron.lanes"
      : /overactivation|sparse|budget/.test(text) ? "neuron.sparse_gate"
      : /score|utility|ledger/.test(text) ? "neuron.score"
      : "neuron.coverage";
  } else if (/repo|monster|afu|lobster|doctor|latency|db|sqlite|io|queue|retry|hot_path/.test(text)) {
    observable = "software.surface";
    sensor = "monster_doctor";
    stateKey = /db|sqlite|aggregate/.test(text) ? "repo.db_pressure"
      : /io|disk|file|atomic/.test(text) ? "repo.io_pressure"
      : /queue|retry|worker/.test(text) ? "repo.queue_pressure"
      : "repo.risk_surface";
  }
  const thresholds = neuronThermalThresholds({ observable, sensor, state_key: stateKey, cluster, lane });
  return {
    schema: "mercury-neuron-state-binding-v1",
    observable,
    sensor,
    state_key: stateKey,
    domain,
    lane,
    cluster,
    thresholds,
    writeback: neuronThermalWriteback({ observable, sensor, state_key: stateKey, cluster, lane }),
    importance: Number((0.45
      + (cluster === "accelerate" ? 0.18 : 0)
      + (cluster === "judge" || cluster === "risk" ? 0.12 : 0)
      + (lane === "acceleration_lane" ? 0.1 : 0)
      + (/qwen|3060|uma|rag|rosen|spend|monster|benchmark/.test(text) ? 0.12 : 0)).toFixed(3))
  };
}

function neuronThermalThresholds(binding = {}) {
  const stateKey = binding.state_key || "";
  const criticalBias = /spend|credential|coherence|gpu|memory|proof|diskspd/.test(stateKey) ? -0.04 : 0;
  const hotBias = /uma\.hot_pages|rosen|qwen|product/.test(stateKey) ? -0.03 : 0;
  return {
    warming: 0.56,
    hot: Number((0.72 + hotBias).toFixed(3)),
    critical: Number((0.9 + criticalBias).toFixed(3)),
    decay: 0.08,
    max_hot_neurons: 160
  };
}

function neuronThermalWriteback(binding = {}) {
  const stateKey = binding.state_key || "";
  const out = ["score_ledger"];
  if (/uma|rag/.test(stateKey)) out.push("uma_hit_stats", "hot_page_cache");
  if (/rosen/.test(stateKey)) out.push("rosen_bridge_score", "rosen_pair_pulse");
  if (/qwen|provider/.test(stateKey)) out.push("provider_cache", "slow_job_policy");
  if (/spend/.test(stateKey)) out.push("spend_guard_memory");
  if (/bench|proof|product/.test(stateKey)) out.push("bench_trend");
  return [...new Set(out)];
}

function collapseNeuronThermalState({ binding, heat, changed, prior, sensors }) {
  const thresholds = binding.thresholds || neuronThermalThresholds(binding);
  const stateKey = binding.state_key || "";
  if (/uma\.coherence/.test(stateKey) && sensors?.uma?.needs_file_table_refresh) return "needs_refresh";
  if (/host\.memory/.test(stateKey) && Number(sensors?.host?.memory_free_ratio || 1) < 0.12) return "avoid";
  if (/product\.diskspd|proof\.diskspd/.test(stateKey) && Number(sensors?.product?.disk_ratio || 1) > 0 && Number(sensors.product.disk_ratio) < 0.9) return "avoid";
  if (heat >= thresholds.critical) return changed ? "critical" : "hot";
  if (changed && heat >= thresholds.hot) return "ready_to_route";
  if (heat >= thresholds.hot) return "promote";
  if (heat >= thresholds.warming) return "warming";
  if (prior && Number(prior.heat || 0) >= thresholds.hot && heat < thresholds.warming) return "demote";
  return "cold";
}

function stateFieldSensorSnapshot(options = {}) {
  const started = Date.now();
  const namespace = options.namespace || projectUmaNamespace();
  const fast = Boolean(options.fast);
  const uma = umaNamespaceStatus(namespace);
  const hot = hotCacheSummary(namespace);
  const qwer = fast && !QWER_SPEED_PLAN_CACHE
    ? { provider_hint: { provider: "fast_skip", route: "qwer_speed_plan_not_loaded_fast_skip" }, provider_cache: { qwen_files: 0 }, queue: { qwer_pending: 0 } }
    : silencedConsole(() => cachedQwerSpeedPlan({ ttlMs: 1000 }));
  const spend = spendGuardSummary();
  const latestRosen = readJsonFileOrNull(join(ROSEN_DIR, "latest-route.json"));
  const pairs = rosenPairsSummary(namespace, { fast });
  const latestCoverage = fast ? readJsonFileOrNull(join(BENCH_DIR, "neuron-coverage-trend.json")) : null;
  const lane = fast && latestCoverage?.trend
    ? latestCoverage.trend
    : neuronCoverageTrendSummary(4000, { taskLimit: 12 });
  const product = windows3060ProductProof();
  const host = hostSpeedSnapshot({ probeLlm: false, fast: true });
  const benchRows = latestBenchRows(8);
  return {
    schema: "mercury-state-field-sensor-snapshot-v1",
    created_at: nowIso(),
    namespace,
    uma,
    hot,
    qwer: {
      provider: qwer.provider_hint?.provider || "none",
      route: qwer.provider_hint?.route || "none",
      qwen_cache: qwer.provider_cache?.qwen_files || 0,
      pending: qwer.queue?.qwer_pending || 0
    },
    spend: {
      findings: spend.findings || 0,
      providers: spend.providers || 0,
      risky_files: spend.risky_files || 0
    },
    rosen: {
      bridges: latestRosen?.candidates || latestRosen?.selected_count || 0,
      latest_selected: latestRosen?.selected_count || 0,
      pairs: pairs.pairs || 0,
      correction_pulse: pairs.correction_pulse || 0,
      state_replay: pairs.state_replay || 0
    },
    lane: {
      selected: lane.unique_selected_neurons || 0,
      executed: lane.unique_executed_neurons || 0,
      exploration: lane.unique_exploration_neurons || 0,
      lanes: lane.lanes_covered || 0
    },
    product: {
      pass: Boolean(product?.pass),
      speedup: product?.metrics?.qwen_first_request_speedup || 0,
      disk_ratio: product?.metrics?.diskspd_min_throughput_ratio || 0
    },
    host: {
      memory_free_ratio: host.memory?.free_ratio || 0,
      gpu_count: host.gpus?.length || 0,
      reflex_files: host.reflex_cache?.files || 0
    },
    bench: {
      rows: benchRows.length,
      latest_suite: benchRows.at(-1)?.suite || null,
      latest_ms: benchRows.at(-1)?.max_run_ms ?? benchRows.at(-1)?.total_ms ?? 0
    },
    fast,
    elapsed_ms: Date.now() - started
  };
}

function stateValueForBinding(binding, sensors) {
  const values = {
    "qwen.cache": [sensors.qwer.provider, sensors.qwer.route, sensors.qwer.qwen_cache, sensors.qwer.pending],
    "qwen.queue": [sensors.qwer.pending, sensors.qwer.provider, sensors.qwer.route],
    "qwen.provider_route": [sensors.qwer.provider, sensors.qwer.route],
    "qwen.latency": [sensors.product.speedup, sensors.qwer.provider, sensors.qwer.qwen_cache],
    "host.gpu_memory": [sensors.host.gpu_count, sensors.host.memory_free_ratio],
    "host.memory": [sensors.host.memory_free_ratio, sensors.host.reflex_files],
    "product.diskspd": [sensors.product.pass, sensors.product.disk_ratio, sensors.product.speedup],
    "product.activation": [sensors.product.pass, sensors.product.speedup, sensors.host.gpu_count],
    "spend.findings": [sensors.spend.findings, sensors.spend.providers, sensors.spend.risky_files],
    "spend.credentials": [sensors.spend.providers, sensors.spend.risky_files],
    "spend.loop": [sensors.spend.findings, sensors.spend.risky_files],
    "rosen.pulses": [sensors.rosen.bridges, sensors.rosen.latest_selected, sensors.rosen.pairs, sensors.rosen.correction_pulse, sensors.rosen.state_replay],
    "rosen.bridges": [sensors.rosen.bridges, sensors.rosen.latest_selected],
    "rosen.pairs": [sensors.rosen.pairs, sensors.rosen.correction_pulse, sensors.rosen.state_replay],
    "uma.hot_pages": [sensors.hot.pages, sensors.hot.events, sensors.uma.updated_at],
    "uma.symbols": [sensors.uma.symbol_count, sensors.uma.page_table_files, sensors.uma.updated_at],
    "uma.pages": [sensors.uma.pages, sensors.uma.files, sensors.uma.needs_file_table_refresh, sensors.uma.updated_at],
    "uma.namespace": [sensors.uma.namespace, sensors.uma.pages, sensors.uma.files],
    "uma.coherence": [sensors.uma.needs_file_table_refresh, sensors.uma.updated_at, sensors.hot.pages],
    "rag.packet": [sensors.uma.pages, sensors.uma.symbol_count, sensors.hot.pages],
    "bench.latest": [sensors.bench.rows, sensors.bench.latest_suite, sensors.bench.latest_ms],
    "proof.freshness": [sensors.product.pass, sensors.bench.rows, sensors.bench.latest_ms],
    "proof.qwen": [sensors.product.pass, sensors.product.speedup, sensors.qwer.qwen_cache],
    "proof.diskspd": [sensors.product.pass, sensors.product.disk_ratio],
    "neuron.coverage": [sensors.lane.selected, sensors.lane.executed, sensors.lane.exploration, sensors.lane.lanes],
    "neuron.lanes": [sensors.lane.lanes, sensors.lane.executed],
    "neuron.sparse_gate": [sensors.lane.selected, sensors.lane.exploration],
    "neuron.score": [sensors.lane.selected, sensors.lane.executed, sensors.bench.latest_ms],
    "repo.risk_surface": [sensors.uma.pages, sensors.spend.findings, sensors.bench.latest_ms],
    "repo.db_pressure": [sensors.uma.symbol_count, sensors.bench.latest_ms],
    "repo.io_pressure": [sensors.uma.files, sensors.product.disk_ratio],
    "repo.queue_pressure": [sensors.qwer.pending, sensors.bench.latest_ms]
  };
  return values[binding.state_key] || [sensors.uma.pages, sensors.host.reflex_files];
}

function observeNeuronStateField(options = {}) {
  const started = Date.now();
  ensureDirs();
  const ttlMs = Math.max(0, Number(options.ttlMs ?? 750));
  const cacheKey = stableHash([options.namespace || projectUmaNamespace(), options.persist === false ? "volatile" : "persisted"]);
  if (!options.refresh && options.persist === false && NEURON_STATE_FIELD_CACHE?.key === cacheKey && Date.now() - NEURON_STATE_FIELD_CACHE.at <= ttlMs) {
    return {
      ...NEURON_STATE_FIELD_CACHE.report,
      cache: {
        mode: "neuron_state_field_cache_hit",
        age_ms: Date.now() - NEURON_STATE_FIELD_CACHE.at,
        ttl_ms: ttlMs
      },
      elapsed_ms: 0
    };
  }
  const previousPath = join(STATE_FIELD_DIR, "latest.json");
  const hotPath = join(STATE_FIELD_DIR, "latest-hot.json");
  if (!options.refresh && options.persist === false && existsSync(previousPath)) {
    const latestHot = readJsonFileOrNull(hotPath);
    if (latestHot?.schema === "mercury-neuron-state-field-hot-v1") {
      const latest = {
        schema: NEURON_STATE_FIELD_SCHEMA,
        created_at: latestHot.created_at,
        mode: "state_hot_replay",
        neurons: latestHot.neurons || [],
        summary: latestHot.summary || {},
        elapsed_ms: 0
      };
      NEURON_STATE_FIELD_CACHE = { key: cacheKey, at: Date.now(), report: latest };
      return {
        ...latest,
        cache: {
          mode: "neuron_state_field_hot_replay",
          age_ms: 0,
          ttl_ms: ttlMs
        },
        elapsed_ms: 0
      };
    }
  }
  const neurons = loadNeurons();
  const sensors = options.sensors || stateFieldSensorSnapshot(options);
  const previous = readJsonFileOrNull(previousPath);
  const previousById = new Map((previous?.neurons || []).map((item) => [item.id, item]));
  const observed = neurons.map((neuron) => {
    const binding = neuronStateBinding(neuron);
    const value = stateValueForBinding(binding, sensors);
    const digest = stableHash([binding.state_key, value]);
    const prior = previousById.get(neuron.id);
    const changed = !prior || prior.digest !== digest;
    const pulse = changed ? "correction_pulse" : "state_replay";
    const priorHeat = Number(prior?.heat || 0);
    const thresholds = binding.thresholds || neuronThermalThresholds(binding);
    const decayedPrior = Math.max(0, priorHeat - Number(thresholds.decay || 0.08));
    const heat = Number(Math.min(1, Math.max(decayedPrior, binding.importance)
      + (changed ? 0.28 : 0)
      + (prior?.pulse === "correction_pulse" ? 0.08 : 0)).toFixed(3));
    const collapse_state = collapseNeuronThermalState({ binding, heat, changed, prior, sensors });
    return {
      id: neuron.id,
      type: neuron.type,
      binding,
      digest,
      changed,
      pulse,
      heat,
      collapse_state,
      thresholds,
      writeback: binding.writeback || [],
      last_pulse_at: nowIso(),
      prior_digest: prior?.digest || null
    };
  });
  const changed = observed.filter((item) => item.changed);
  const byCollapse = observed.reduce((acc, item) => {
    acc[item.collapse_state || "unknown"] = (acc[item.collapse_state || "unknown"] || 0) + 1;
    return acc;
  }, {});
  const hot = observed
    .filter((item) => item.changed || item.heat >= (item.thresholds?.hot || 0.72) || ["ready_to_route", "critical", "needs_refresh", "promote", "avoid"].includes(item.collapse_state))
    .sort((a, b) => b.heat - a.heat || a.id.localeCompare(b.id));
  const byObservable = observed.reduce((acc, item) => {
    acc[item.binding.observable] = (acc[item.binding.observable] || 0) + 1;
    return acc;
  }, {});
  const report = {
    schema: NEURON_STATE_FIELD_SCHEMA,
    created_at: nowIso(),
    mode: previous ? "state_observe" : "state_seed",
    sensors,
    neurons: observed,
    summary: {
      total_neurons: observed.length,
      changed_neurons: changed.length,
      hot_neurons: hot.length,
      collapse_states: byCollapse,
      observables: byObservable,
      top_hot: hot.slice(0, 32).map((item) => ({ id: item.id, heat: item.heat, state_key: item.binding.state_key, pulse: item.pulse, collapse_state: item.collapse_state }))
    },
    elapsed_ms: Date.now() - started
  };
  if (options.persist !== false) {
    atomicWriteJson(previousPath, report);
    atomicWriteJson(hotPath, {
      schema: "mercury-neuron-state-field-hot-v1",
      created_at: report.created_at,
      summary: report.summary,
      neurons: hot.slice(0, 160),
      elapsed_ms: report.elapsed_ms
    });
    atomicWriteJson(join(STATE_FIELD_DIR, "latest-summary.json"), { ...report.summary, created_at: report.created_at, elapsed_ms: report.elapsed_ms }, { pretty: true });
  } else {
    NEURON_STATE_FIELD_CACHE = { key: cacheKey, at: Date.now(), report };
  }
  return report;
}

function readNeuronStateHotMap(options = {}) {
  const ttlMs = Math.max(0, Number(options.ttlMs ?? 750));
  const path = join(STATE_FIELD_DIR, "latest-hot.json");
  const now = Date.now();
  if (!options.refresh && NEURON_STATE_HOT_CACHE && now - NEURON_STATE_HOT_CACHE.at <= ttlMs) {
    return NEURON_STATE_HOT_CACHE.map;
  }
  if (!existsSync(path)) {
    const empty = new Map();
    NEURON_STATE_HOT_CACHE = { at: now, map: empty };
    return empty;
  }
  const payload = readJsonFileOrNull(path);
  const rows = Array.isArray(payload?.neurons) ? payload.neurons : [];
  const map = new Map(rows
    .filter((item) => item?.id)
    .slice(0, 160)
    .map((item) => [item.id, {
      id: item.id,
      heat: item.heat || 0,
      state_key: item.binding?.state_key || item.state_key || null,
      pulse: item.pulse || "state_replay",
      collapse_state: item.collapse_state || "cold",
      writeback: item.writeback || item.binding?.writeback || []
    }]));
  NEURON_STATE_HOT_CACHE = { at: now, map };
  return map;
}

function neuronStateFieldCommand(args = []) {
  const json = args.includes("--json");
  const report = observeNeuronStateField({});
  if (json) {
    console.log(JSON.stringify(report));
    return report;
  }
  console.log("Neuron Mercury neuron state field");
  console.log(`mode: ${report.mode}`);
  console.log(`neurons: ${report.summary.total_neurons}`);
  console.log(`changed: ${report.summary.changed_neurons}`);
  console.log(`hot: ${report.summary.hot_neurons}`);
  console.log(`observables: ${Object.keys(report.summary.observables).length}`);
  console.log(`elapsed_ms: ${report.elapsed_ms}`);
  for (const item of report.summary.top_hot.slice(0, 8)) {
    console.log(`- ${item.id} ${item.state_key} heat=${item.heat} ${item.pulse}`);
  }
  return report;
}

function neuronExplorationSet(taskText, catalog = loadNeurons(), activeIds = new Set(), context = {}) {
  const lower = String(taskText || "").toLowerCase();
  const scoreRows = readScoreRows(12000).rows;
  const used = new Set(scoreRows
    .filter((row) => row.lane_selected || row.executed)
    .map((row) => row.neuron_id)
    .filter(Boolean));
  const taskHash = Number.parseInt(stableHash([process.cwd(), taskText, scoreRows.length]).slice(0, 8), 16);
  const domains = new Map();
  for (const neuron of catalog) {
    const domain = neuronDomain(neuron);
    if (!domains.has(domain)) domains.set(domain, []);
    domains.get(domain).push(neuron);
  }
  const selected = new Set();
  const domainEntries = [...domains.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  for (let i = 0; i < domainEntries.length; i += 1) {
    const [domain, neurons] = domainEntries[i];
    const domainHit = lower.includes(domain.replace(/_/g, " ")) || lower.includes(domain);
    const budget = domainHit ? 3 : 1;
    const ordered = neurons
      .map((neuron, index) => ({
        neuron,
        index,
        unused: used.has(neuron.id) ? 0 : 1,
        active: activeIds.has(neuron.id) ? 1 : 0,
        roll: Number.parseInt(stableHash([taskHash, domain, neuron.id]).slice(0, 8), 16)
      }))
      .sort((a, b) => b.unused - a.unused || a.active - b.active || a.roll - b.roll || a.index - b.index);
    for (const item of ordered.slice(0, budget)) selected.add(item.neuron.id);
  }
  const globalBudget = context.targetFiles?.length ? 24 : 48;
  return new Set([...selected].slice(0, globalBudget));
}

function neuronTaskAffinity(neuron, taskText) {
  const taskKey = stableHash(taskText || "");
  let taskProfile = NEURON_TASK_TOKEN_CACHE.get(taskKey);
  if (!taskProfile) {
    taskProfile = {
      lower: String(taskText || "").toLowerCase(),
      tokens: semanticTokens(taskText)
    };
    if (NEURON_TASK_TOKEN_CACHE.size > 256) NEURON_TASK_TOKEN_CACHE.clear();
    NEURON_TASK_TOKEN_CACHE.set(taskKey, taskProfile);
  }
  let neuronProfile = NEURON_AFFINITY_PROFILE_CACHE.get(neuron.id);
  if (!neuronProfile) {
    neuronProfile = {
      domain: neuronDomain(neuron),
      activationTerms: Array.isArray(neuron.activation_terms) ? neuron.activation_terms.slice(0, 12).map((term) => String(term || "").toLowerCase()).filter(Boolean) : [],
      specialtyTokens: semanticTokens(`${neuron.id || ""} ${neuron.specialty || ""} ${neuron.cluster || ""} ${neuron.shard_family || ""}`)
    };
    NEURON_AFFINITY_PROFILE_CACHE.set(neuron.id, neuronProfile);
  }
  let score = 0;
  if (taskProfile.lower.includes(neuronProfile.domain) || taskProfile.lower.includes(neuronProfile.domain.replace(/_/g, " "))) score += 0.35;
  for (const normalized of neuronProfile.activationTerms) {
    if (taskProfile.lower.includes(normalized) || taskProfile.tokens.has(normalized)) score += 0.08;
  }
  let shared = 0;
  for (const token of neuronProfile.specialtyTokens) {
    if (taskProfile.tokens.has(token)) shared += 1;
  }
  score += Math.min(0.28, shared * 0.04);
  return Number(Math.min(0.7, score).toFixed(4));
}

function fastNeuronRoll(taskText, neuronId, lane) {
  const text = `${taskText}|${neuronId}|${lane}`;
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return ((hash >>> 0) / 0xffffffff);
}

function buildNeuronControlMap(circuit, context, taskText) {
  const scoreSummary = neuronScoreSummary();
  const lanes = {};
  const activeIds = new Set(circuit.map((neuron) => neuron.id));
  const catalog = loadNeurons();
  const explorationIds = neuronExplorationSet(taskText, catalog, activeIds, context);
  const stateHot = context.neuronStateHotMap || readNeuronStateHotMap({ ttlMs: 750 });
  context.neuronStateHotMap = stateHot;
  for (const neuron of catalog) {
    const lane = neuronParallelLane(neuron);
    if (!lanes[lane]) lanes[lane] = {
      lane,
      budget: neuronLaneBudget(lane, context, taskText),
      catalog_count: 0,
      candidate_count: 0,
      selected_count: 0,
      selected: []
    };
    const boost = rosenNeuronBoost(neuron, context);
    const exploring = explorationIds.has(neuron.id);
    const statePulse = stateHot.get(neuron.id);
    const modelFieldBoost = neuron.model_field && /\b(model field|open local|qwen|qwer|ollama|kv|decode|logit|attention|prompt|inference|speculative|provider gate|reflex cache|uma context)\b/i.test(taskText)
      ? Number((0.24
        + (neuron.model_field.side === "external" && /\b(external|prompt|uma|reflex|provider|cache)\b/i.test(taskText) ? 0.12 : 0)
        + (neuron.model_field.side === "internal" && /\b(internal|kv|decode|logit|attention|speculative|inside)\b/i.test(taskText) ? 0.12 : 0)).toFixed(4))
      : 0;
    const collapseBoost = statePulse?.collapse_state === "critical" ? 0.2
      : statePulse?.collapse_state === "ready_to_route" ? 0.16
      : statePulse?.collapse_state === "needs_refresh" ? 0.14
      : statePulse?.collapse_state === "promote" ? 0.1
      : statePulse?.collapse_state === "warming" ? 0.04
      : statePulse?.collapse_state === "avoid" ? -0.1
      : 0;
    const stateBoost = statePulse ? Math.max(0, Math.min(0.42, Number(statePulse.heat || 0) * 0.22 + (statePulse.pulse === "correction_pulse" ? 0.12 : 0) + collapseBoost)) : 0;
    const active = activeIds.has(neuron.id) || boost > 0 || exploring || stateBoost > 0 || modelFieldBoost > 0;
    const affinity = active ? neuronTaskAffinity(neuron, taskText) : 0;
    const rotation = active ? Number((fastNeuronRoll(taskText, neuron.id, lane) * 0.08).toFixed(4)) : 0;
    const genericPenalty = activeIds.has(neuron.id) && affinity <= 0 ? 0.12 : 0;
    const scored = {
      id: neuron.id,
      type: neuron.type,
      cluster: neuronCluster(neuron.id),
      score: active ? Number((neuronSchedulerScore(neuron, scoreSummary) + boost + stateBoost + modelFieldBoost + affinity + rotation + (exploring ? 0.26 : 0) - genericPenalty).toFixed(4)) : 0,
      rosen_boost: active ? boost : 0,
      state_boost: active ? Number(stateBoost.toFixed(4)) : 0,
      model_field_boost: active ? modelFieldBoost : 0,
      state_key: statePulse?.state_key || neuronStateBinding(neuron).state_key,
      collapse_state: statePulse?.collapse_state || "cold",
      task_affinity: affinity,
      active,
      source: activeIds.has(neuron.id) ? "classified" : modelFieldBoost > 0 ? "model_field" : stateBoost > 0 ? "state_field" : boost > 0 ? "rosen_bridge" : exploring ? "topology_exploration" : "dormant"
    };
    lanes[lane].catalog_count += 1;
    if (scored.active) {
      lanes[lane].candidate_count += 1;
      lanes[lane].selected.push(scored);
    }
  }
  for (const lane of Object.values(lanes)) {
    const collapseRank = (item) => ({
      critical: 9,
      ready_to_route: 8,
      needs_refresh: 7,
      promote: 6,
      hot: 5,
      warming: 4,
      avoid: 2,
      demote: 1,
      cold: 0
    }[item.collapse_state || "cold"] || 0);
    const sorted = lane.selected.sort((a, b) => b.score - a.score || collapseRank(b) - collapseRank(a) || b.task_affinity - a.task_affinity || a.id.localeCompare(b.id));
    const reservedState = sorted
      .filter((item) => Number(item.state_boost || 0) > 0 && item.source !== "classified")
      .sort((a, b) => collapseRank(b) - collapseRank(a) || b.score - a.score || a.id.localeCompare(b.id))
      .slice(0, Math.min(3, Math.max(1, Math.floor(lane.budget / 2))));
    const reservedExploration = sorted
      .filter((item) => item.source === "topology_exploration")
      .slice(0, Math.min(3, Math.max(1, Math.ceil(lane.budget / 2))));
    const reservedIds = new Set([...reservedState, ...reservedExploration].map((item) => item.id));
    lane.selected = [
      ...reservedState,
      ...reservedExploration,
      ...sorted.filter((item) => !reservedIds.has(item.id)).slice(0, Math.max(0, lane.budget - reservedState.length - reservedExploration.length))
    ].slice(0, lane.budget);
    lane.selected_count = lane.selected.length;
    lane.selected_by_source = lane.selected.reduce((acc, item) => {
      acc[item.source || "unknown"] = (acc[item.source || "unknown"] || 0) + 1;
      return acc;
    }, {});
    lane.selected_by_collapse_state = lane.selected.reduce((acc, item) => {
      acc[item.collapse_state || "unknown"] = (acc[item.collapse_state || "unknown"] || 0) + 1;
      return acc;
    }, {});
  }
  const selectedBySource = {};
  const selectedByCollapseState = {};
  for (const lane of Object.values(lanes)) {
    for (const [key, value] of Object.entries(lane.selected_by_source || {})) selectedBySource[key] = (selectedBySource[key] || 0) + value;
    for (const [key, value] of Object.entries(lane.selected_by_collapse_state || {})) selectedByCollapseState[key] = (selectedByCollapseState[key] || 0) + value;
  }
  return {
    schema: "neuron-control-map-v1",
    total_catalog_neurons: catalog.length,
    active_candidates: Object.values(lanes).reduce((sum, lane) => sum + lane.candidate_count, 0),
    classified_candidates: activeIds.size,
    topology_exploration_candidates: explorationIds.size,
    state_field_hot_neurons: stateHot.size,
    selected_for_parallel_lanes: Object.values(lanes).reduce((sum, lane) => sum + lane.selected_count, 0),
    selected_by_source: selectedBySource,
    selected_by_collapse_state: selectedByCollapseState,
    lanes
  };
}

function neuronControlActivationMetrics(controlMap = {}) {
  const lanes = Object.values(controlMap.lanes || {});
  const activeCandidates = controlMap.active_candidates || lanes.reduce((sum, lane) => sum + (lane.candidate_count || 0), 0);
  const selected = controlMap.selected_for_parallel_lanes || lanes.reduce((sum, lane) => sum + (lane.selected_count || 0), 0);
  const suppressed = Math.max(0, activeCandidates - selected);
  const catalog = controlMap.total_catalog_neurons || lanes.reduce((sum, lane) => sum + (lane.catalog_count || 0), 0);
  const densestLane = lanes
    .map((lane) => ({
      lane: lane.lane,
      candidate_count: lane.candidate_count || 0,
      selected_count: lane.selected_count || 0,
      suppressed: Math.max(0, (lane.candidate_count || 0) - (lane.selected_count || 0))
    }))
    .sort((a, b) => b.suppressed - a.suppressed || b.candidate_count - a.candidate_count)[0] || null;
  return {
    schema: "neuron-control-activation-metrics-v1",
    catalog_neurons: catalog,
    active_candidates: activeCandidates,
    classified_candidates: controlMap.classified_candidates || 0,
    topology_exploration_candidates: controlMap.topology_exploration_candidates || 0,
    state_field_hot_neurons: controlMap.state_field_hot_neurons || 0,
    selected_neurons: selected,
    selected_by_source: controlMap.selected_by_source || {},
    selected_by_collapse_state: controlMap.selected_by_collapse_state || {},
    suppressed_neurons: suppressed,
    activation_ratio: activeCandidates ? Number((selected / activeCandidates).toFixed(3)) : 0,
    catalog_activation_ratio: catalog ? Number((selected / catalog).toFixed(3)) : 0,
    overactivation_blocked: suppressed > 0,
    densest_suppressed_lane: densestLane
  };
}

function buildNeuronControlArtifact(controlMap) {
  const metrics = neuronControlActivationMetrics(controlMap);
  const rosenBoosted = Object.values(controlMap.lanes || {})
    .flatMap((lane) => lane.selected || [])
    .filter((item) => Number(item.rosen_boost || 0) > 0);
  const laneSummary = Object.values(controlMap.lanes)
    .filter((lane) => lane.candidate_count || lane.selected_count)
    .map((lane) => `${lane.lane}: ${lane.selected_count}/${lane.candidate_count} selected of ${lane.catalog_count}`);
  return {
    neuron_id: "control.neuron_map",
    kernel: "control",
    signal: "parallel_neuron_lanes_ready",
    evidence: [
      `catalog=${controlMap.total_catalog_neurons}`,
      `active_candidates=${controlMap.active_candidates}`,
      `selected_parallel=${controlMap.selected_for_parallel_lanes}`,
      `suppressed=${metrics.suppressed_neurons}`,
      `activation_ratio=${metrics.activation_ratio}`,
      `rosen_boosted=${rosenBoosted.length}`,
      ...laneSummary.slice(0, 10)
    ],
    confidence: 0.82,
    elapsed_ms: 0,
    details: { ...controlMap, activation_metrics: metrics, rosen_boosted: rosenBoosted.slice(0, 12) }
  };
}

function neuronDispatchPhase(lane) {
  return {
    goal_lane: 0,
    memory_retrieval_lane: 0,
    surface_lane: 0,
    analysis_lane: 1,
    risk_lane: 1,
    acceleration_lane: 1,
    writeback_lane: 2,
    judge_lane: 2,
    verification_lane: 2,
    synthesis_lane: 2,
    support_lane: 2
  }[lane] ?? 2;
}

function buildNeuronDispatchPlan(executableCircuit, controlMap, context = {}) {
  const selection = neuronControlSelectionIndex(controlMap);
  const lanes = new Map();
  for (const neuron of executableCircuit) {
    const meta = selection.get(neuron.id) || {};
    const lane = meta.lane || neuronParallelLane(neuron);
    if (!lanes.has(lane)) {
      lanes.set(lane, {
        lane,
        phase: neuronDispatchPhase(lane),
        substrate: NEURON_TYPE_SUBSTRATE[neuron.type] || "cpu.l1_hot_path",
        neurons: []
      });
    }
    lanes.get(lane).neurons.push({
      id: neuron.id,
      type: neuron.type,
      score: meta.score ?? neuron.scheduler_score ?? neuronSchedulerScore(neuron),
      substrate: NEURON_TYPE_SUBSTRATE[neuron.type] || "cpu.l1_hot_path"
    });
  }
  const waveMap = new Map();
  for (const lane of lanes.values()) {
    if (!waveMap.has(lane.phase)) waveMap.set(lane.phase, []);
    waveMap.get(lane.phase).push(lane);
  }
  const waves = [...waveMap.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([phase, waveLanes]) => ({
      phase,
      parallel_lanes: waveLanes
        .sort((a, b) => a.lane.localeCompare(b.lane))
        .map((lane) => ({
          ...lane,
          neurons: lane.neurons.sort((a, b) => b.score - a.score || a.id.localeCompare(b.id))
        })),
      neuron_count: waveLanes.reduce((sum, lane) => sum + lane.neurons.length, 0)
    }));
  const maxParallelLanes = waves.reduce((max, wave) => Math.max(max, wave.parallel_lanes.length), 0);
  return {
    schema: "neuron-dispatch-plan-v1",
    mode: "lane_wavefront",
    target_file_fast_path: Boolean(context.targetFiles?.length),
    total_neurons: executableCircuit.length,
    waves,
    wave_count: waves.length,
    max_parallel_lanes: maxParallelLanes,
    max_parallel_neurons: waves.reduce((max, wave) => Math.max(max, wave.neuron_count), 0),
    policy: "distribute selected neurons by lane and wave; keep model calls out of the hot path"
  };
}

function buildNeuronDispatchArtifact(dispatchPlan) {
  return {
    neuron_id: "control.dispatch_map",
    kernel: "control",
    signal: "lane_wavefront_dispatch_ready",
    evidence: [
      `mode=${dispatchPlan.mode}`,
      `waves=${dispatchPlan.wave_count}`,
      `max_parallel_lanes=${dispatchPlan.max_parallel_lanes}`,
      `max_parallel_neurons=${dispatchPlan.max_parallel_neurons}`,
      `total_neurons=${dispatchPlan.total_neurons}`
    ],
    confidence: 0.84,
    elapsed_ms: 0,
    details: dispatchPlan
  };
}

function neuronUmaBatchRequests(executableCircuit, taskText, context = {}) {
  const target = (context.targetFiles || [])[0] || "";
  return executableCircuit
    .filter((neuron) => neuron.id !== "memory.uma_rag_preload")
    .slice(0, 64)
    .map((neuron) => {
      const specialty = neuron.specialty || neuron.id;
      const query = target
        ? `${taskText} ${target} ${neuron.id} ${specialty}`
        : `${taskText} ${neuron.id} ${specialty}`;
      return { neuron_id: neuron.id, query };
    });
}

function buildUmaBatchPreloadArtifact(batch) {
  return {
    neuron_id: "memory.uma_batch_preload",
    kernel: "memory",
    signal: batch?.ok ? "uma_batch_preload_ready" : "uma_batch_preload_sparse",
    evidence: [
      `queries=${batch?.queries || 0}`,
      `target_file_first=${batch?.route_counts?.target_file_first || 0}`,
      `symbol_first=${batch?.route_counts?.symbol_first || 0}`,
      `elapsed_ms=${batch?.elapsed_ms || 0}`
    ],
    confidence: batch?.ok ? 0.78 : 0.35,
    elapsed_ms: batch?.elapsed_ms || 0,
    details: {
      mode: batch?.mode || "uma_batch_search",
      route_counts: batch?.route_counts || {},
      cache_state: batch?.cache_state || {}
    }
  };
}

function mapUmaBatchByNeuron(requests, batch) {
  const out = new Map();
  const rows = batch?.results || [];
  for (let i = 0; i < requests.length; i += 1) {
    const neuronId = requests[i]?.neuron_id;
    if (!neuronId) continue;
    const search = rows[i]?.search;
    if (!search?.results?.length) continue;
    out.set(neuronId, search.results);
  }
  return out;
}

function umaEvidenceForNeuron(context, neuronId, limit = 3) {
  return (context.umaBatchByNeuron?.get(neuronId) || [])
    .slice(0, limit)
    .map((hit) => `${hit.source_path || hit.pointer}:UMA:${compactEvidenceText(hit.text, 140)}`);
}

function dispatchNeurons(executableCircuit, taskText, context) {
  const dispatchPlan = buildNeuronDispatchPlan(executableCircuit, context.neuronControlMap, context);
  context.neuronDispatchPlan = dispatchPlan;
  const byId = new Map(executableCircuit.map((neuron) => [neuron.id, neuron]));
  const artifacts = [];
  if (executableCircuit.length >= 10 && context.umaNamespace) {
    const requests = neuronUmaBatchRequests(executableCircuit, taskText, context);
    const batch = umaBatchSearch(requests.map((item) => item.query), {
      namespace: context.umaNamespace,
      limit: 2,
      budgetMs: 4,
      maxQueries: 64
    });
    context.umaBatchPreload = batch;
    context.umaBatchByNeuron = mapUmaBatchByNeuron(requests, batch);
    artifacts.push(buildUmaBatchPreloadArtifact(batch));
  }
  for (const wave of dispatchPlan.waves) {
    for (const lane of wave.parallel_lanes) {
      for (const item of lane.neurons) {
        const neuron = byId.get(item.id);
        if (neuron) artifacts.push(runNeuron(neuron, taskText, context));
      }
    }
  }
  return { dispatchPlan, artifacts };
}

function neuronControlSelectionIndex(controlMap = null) {
  const out = new Map();
  for (const lane of Object.values(controlMap?.lanes || {})) {
    for (const item of lane.selected || []) {
      out.set(item.id, {
        lane: lane.lane,
        score: item.score,
        rosen_boost: item.rosen_boost || 0,
        state_boost: item.state_boost || 0,
        state_key: item.state_key || null,
        task_affinity: item.task_affinity || 0,
        source: item.source || null,
        selected_count: lane.selected_count,
        candidate_count: lane.candidate_count
      });
    }
  }
  return out;
}

function neuronScoreSummary(limit = 2000) {
  if (NEURON_SCORE_SUMMARY_CACHE) return NEURON_SCORE_SUMMARY_CACHE;
  const { rows } = readScoreRows(limit);
  const byNeuron = new Map();
  for (const row of rows) {
    const item = byNeuron.get(row.neuron_id) || { runs: 0, utility: 0, elapsed: 0, high: 0 };
    item.runs += 1;
    item.utility += row.utility_score || 0;
    item.elapsed += row.elapsed_ms || 0;
    item.high += row.high_evidence_count || 0;
    byNeuron.set(row.neuron_id, item);
  }
  NEURON_SCORE_SUMMARY_CACHE = byNeuron;
  return byNeuron;
}

function neuronSchedulerScore(neuron, scoreSummary = neuronScoreSummary()) {
  const item = scoreSummary.get(neuron.id);
  if (!item || !item.runs) return neuron.activation || 0.5;
  const avgUtility = item.utility / item.runs;
  const avgElapsed = item.elapsed / item.runs;
  return Number(((neuron.activation || 0.5) + avgUtility * 0.08 + Math.min(item.high, 50) * 0.002 - avgElapsed * 0.02).toFixed(4));
}

function scheduleCircuit(circuit) {
  const scoreSummary = neuronScoreSummary();
  return circuit
    .map((neuron, index) => ({
      neuron,
      index,
      cluster_rank: neuronClusterRank(neuron.id),
      scheduler_score: neuronSchedulerScore(neuron, scoreSummary)
    }))
    .sort((a, b) =>
      a.cluster_rank - b.cluster_rank
      || b.scheduler_score - a.scheduler_score
      || a.index - b.index
    )
    .map((item) => ({
      ...item.neuron,
      cluster: neuronCluster(item.neuron.id),
      scheduler_score: item.scheduler_score
    }));
}

function executableCircuitForPlan(circuit, context, taskText) {
  const scheduledBase = scheduleCircuit(circuit);
  const controlMap = context.neuronControlMap || buildNeuronControlMap(scheduledBase, context, taskText);
  const selectedIds = new Set(neuronControlSelectionIndex(controlMap).keys());
  const scheduledIds = new Set(scheduledBase.map((neuron) => neuron.id));
  const selection = neuronControlSelectionIndex(controlMap);
  const rosenSelected = loadNeurons()
    .filter((neuron) => selectedIds.has(neuron.id) && !scheduledIds.has(neuron.id))
    .map((neuron) => ({
      ...neuron,
      cluster: neuronCluster(neuron.id),
      scheduler_score: selection.get(neuron.id)?.score ?? neuronSchedulerScore(neuron)
    }));
  const scheduled = [...scheduledBase, ...rosenSelected]
    .sort((a, b) => neuronClusterRank(a.id) - neuronClusterRank(b.id) || (b.scheduler_score || 0) - (a.scheduler_score || 0) || a.id.localeCompare(b.id));
  const mustKeepIds = new Set(["safety.destructive_action", "compression.evidence_packet", "evidence.rank", "critic.risk_surface"]);
  const selected = (neuron) => selectedIds.has(neuron.id) || mustKeepIds.has(neuron.id);
  const route = context.umaRoute || {};
  const directUmaHit = Boolean(route.target_file_first || route.symbol_first);
  if (controlMap.selected_for_parallel_lanes >= 20 && !context.targetFiles.length) {
    return scheduled.filter((neuron) =>
      selected(neuron)
      && !neuron.id.startsWith("git.")
      && neuron.id !== "tool.file_outline"
    );
  }
  if (directUmaHit && context.targetFiles.length) {
    return scheduled.filter((neuron) =>
      selected(neuron) && (neuron.id.startsWith("risk.")
      || neuron.id.startsWith("verify.")
      || neuron.id === "evidence.rank"
      || neuron.id === "critic.risk_surface"
      || neuron.id === "compression.evidence_packet"
      || neuron.id === "safety.destructive_action")
    );
  }
  if (route.symbol_first && !context.targetFiles.length) {
    return scheduled.filter((neuron) =>
      selected(neuron) && (neuron.id.startsWith("risk.")
      || neuron.id === "compression.evidence_packet"
      || neuron.id === "evidence.rank"
      || neuron.id === "critic.risk_surface"
      || neuron.id === "safety.destructive_action")
    );
  }
  if (!context.targetFiles.length && !taskNeedsGitHistory(taskText)) {
    return scheduled.filter((neuron) =>
      selected(neuron) && (isUmaPhaseNeuron(neuron.id)
      || (neuron.type && !["risk", "tool"].includes(neuron.type) && !neuron.id.startsWith("git."))
      || neuron.id === "safety.destructive_action"
      || neuron.id === "compression.evidence_packet"
      || neuron.id === "evidence.rank"
      || neuron.id === "critic.risk_surface")
    );
  }
  if (!context.targetFiles.length || taskNeedsGitHistory(taskText)) {
    return scheduled.filter((neuron) => selected(neuron) && neuron.id !== "synthesis.patch_plan");
  }
  return scheduled.filter((neuron) =>
    selected(neuron) && (neuron.id.startsWith("risk.")
    || neuron.id === "safety.destructive_action"
    || neuron.id === "compression.evidence_packet")
  );
}

function planCacheKey(taskText, context, circuit) {
  return {
    schema: PLAN_CACHE_SCHEMA,
    cwd: context.cwd,
    task: taskText,
    targets: context.targetFiles
      .filter((target) => existsSync(resolve(process.cwd(), target)))
      .map(fileFingerprint),
    circuit: circuit.map((neuron) => neuron.id).sort()
  };
}

function buildPlanArtifact(patchPlan) {
  return {
    neuron_id: "synthesis.patch_plan",
    kernel: "synthesis",
    signal: "patch_plan_ready",
    evidence: [patchPlan.summary],
    confidence: patchPlan.findings.length ? 0.78 : 0.45,
    elapsed_ms: 0,
    details: {
      finding_count: patchPlan.findings.length,
      target_files: patchPlan.target_files,
      verification_count: patchPlan.verification.length
    }
  };
}

function searchTargetsInProcess(pattern, targets = []) {
  if (!targets.length) return null;
  let re;
  try {
    re = new RegExp(pattern, "i");
  } catch {
    return null;
  }
  const fingerprints = targets
    .filter((target) => existsSync(resolve(process.cwd(), target)))
    .map(fileFingerprint);
  const cacheKey = {
    cwd: process.cwd(),
    pattern,
    targets: fingerprints
  };
  const cached = fingerprints.length ? readJsonCache("target_scan", cacheKey) : null;
  if (cached?.result) return { ...cached.result, engine: "cache" };

  const hits = [];
  for (const target of targets) {
    const abs = resolve(process.cwd(), target);
    if (!existsSync(abs)) continue;
    const lines = readCachedLines(target);
    for (let i = 0; i < lines.length; i += 1) {
      if (re.test(lines[i])) hits.push(`${target}:${i + 1}:${redactSecrets(lines[i])}`);
      if (hits.length >= 200) break;
    }
    if (hits.length >= 200) break;
  }
  const result = { ok: hits.length > 0, output: hits.join("\n"), engine: "in_process" };
  if (fingerprints.length) writeJsonCache("target_scan", cacheKey, { created_at: nowIso(), result });
  return result;
}

function searchText(pattern, targets = []) {
  const inProcess = searchTargetsInProcess(pattern, targets);
  if (inProcess) return inProcess;

  const searchRoots = targets.length ? targets : ["."];
  if (shellAvailable("rg")) {
    return safeExec("rg", [
      "-n",
      "--with-filename",
      "--glob", "!var/**",
      "--glob", "!node_modules/**",
      "--glob", "!.bun/**",
      "--glob", "!.cache/**",
      "--glob", "!.claude/**",
      "--glob", "!.config/**",
      "--glob", "!.npm/**",
      "--glob", "!._*",
      "--glob", "!*.bak*",
      pattern,
      ...searchRoots
    ], {
      timeout: 5000,
      maxBuffer: 1024 * 1024
    });
  }
  if (shellAvailable("grep")) {
    return safeExec("grep", [
      "-RInE",
      "-H",
      "--exclude-dir=.git",
      "--exclude-dir=var",
      "--exclude-dir=node_modules",
      "--exclude-dir=.bun",
      "--exclude-dir=.cache",
      "--exclude-dir=.claude",
      "--exclude-dir=.config",
      "--exclude-dir=.npm",
      "--exclude=._*",
      "--exclude=*.bak*",
      pattern,
      ...searchRoots
    ], {
      timeout: 5000,
      maxBuffer: 1024 * 1024
    });
  }
  return { ok: false, output: "no text search tool available" };
}

function classifyTask(text, neurons) {
  const cached = CLASSIFY_TASK_CACHE.get(text);
  if (cached) {
    return cached.map((neuron) => ({
      ...neuron,
      hits: [...(neuron.hits || [])]
    }));
  }
  const lower = text.toLowerCase();
  const active = [];
  for (const neuron of neurons) {
    const hits = neuron.activation_terms.filter((term) => lower.includes(term.toLowerCase()));
    if (hits.length > 0) {
      active.push({ ...neuron, hits, activation: Math.min(1, 0.35 + hits.length * 0.18) });
    }
  }

  if (active.length === 0) {
    active.push({
      ...neurons.find((n) => n.id === "compression.evidence_packet"),
      hits: ["default"],
      activation: 0.35
    });
  }

  const hasRepo = active.some((n) => n.id === "intent.repo_diagnosis");
  const hasSafety = active.some((n) => n.id === "safety.destructive_action");
  const asksPlan = lower.includes("plan") || lower.includes("patch") || lower.includes("fix") || lower.includes("risk");

  const circuit = new Set(active.map((n) => n.id));
  if (hasRepo) {
    for (const neuron of neurons) {
      if (isUmaPhaseNeuron(neuron.id)) circuit.add(neuron.id);
    }
    circuit.add("retrieval.target_file");
    circuit.add("retrieval.repo_files");
    circuit.add("tool.file_outline");
    circuit.add("git.recent_changes");
    circuit.add("tool.rg_latency_terms");
    circuit.add("risk.sqlite_timeout");
    circuit.add("risk.aggregate_scan");
    circuit.add("risk.sync_exec");
    circuit.add("risk.network_timeout");
    circuit.add("risk.retry_loop");
    circuit.add("risk.secret_exposure");
    circuit.add("risk.hot_path");
    circuit.add("risk.atomic_write");
    circuit.add("risk.silent_data_loss");
    circuit.add("risk.packaging_entrypoint");
    circuit.add("evidence.rank");
    circuit.add("critic.risk_surface");
  }
  if (asksPlan) circuit.add("synthesis.patch_plan");
  circuit.add("compression.evidence_packet");
  if (hasSafety) circuit.add("safety.destructive_action");

  const classified = neurons.filter((n) => circuit.has(n.id)).map((neuron) => {
    const found = active.find((n) => n.id === neuron.id);
    return found || { ...neuron, hits: ["circuit"], activation: 0.55 };
  });
  CLASSIFY_TASK_CACHE.set(text, classified);
  return classified.map((neuron) => ({
    ...neuron,
    hits: [...(neuron.hits || [])]
  }));
}

function listFiles(limit = 80, preferred = []) {
  if (preferred.length) return [...preferred];
  const ignored = new Set([".git", ".bun", ".cache", ".claude", ".config", ".npm", "node_modules", "__pycache__", "var"]);
  const results = [...preferred];
  function walk(dir) {
    if (results.length >= limit) return;
    for (const name of readdirSync(dir)) {
      if (ignored.has(name) || name.startsWith(".")) continue;
      const path = join(dir, name);
      let st;
      try {
        st = statSync(path);
      } catch {
        continue;
      }
      if (st.isDirectory()) {
        walk(path);
      } else if (!name.includes(".bak") && /\.(js|ts|py|json|toml|md|html|css|sql|sh|service|timer)$/i.test(name)) {
        const relative = path.replace(process.cwd() + "/", "");
        if (!results.includes(relative)) results.push(relative);
      }
      if (results.length >= limit) return;
    }
  }
  walk(process.cwd());
  return results;
}

function parseScoutArgs(args) {
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const filesArg = args.find((arg) => arg.startsWith("--files="));
  return {
    limit: limitArg ? Math.max(1, Number(limitArg.split("=")[1]) || 12) : 12,
    files: filesArg ? Math.max(20, Number(filesArg.split("=")[1]) || 220) : 220
  };
}

function scoutFile(path) {
  const abs = resolve(process.cwd(), path);
  if (!existsSync(abs)) return null;
  const st = statSync(abs);
  if (!st.isFile() || st.size > 2 * 1024 * 1024) return null;
  const lines = readCachedLines(path);
  const families = {};
  const samples = [];
  const seenSamples = new Set();
  const weights = {
    aggregate_scan: 4,
    atomic_write: 4,
    silent_data_loss: 4,
    packaging_entrypoint: 4,
    sqlite_timeout: 3,
    network_timeout: 3,
    retry_loop: 2,
    hot_path: 2,
    sync_exec: 2,
    secret_exposure: 1,
    latency_terms: 1
  };
  const extMultiplier = /\.(py|js|ts|sh|sql|toml|service|timer)$/i.test(path)
    ? 1
    : /\.(json|md)$/i.test(path)
      ? 0.35
      : 0.15;

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (!TARGET_SEARCH_ANY.test(line)) continue;
    for (const [family, re] of Object.entries(TARGET_SEARCH_FAMILIES)) {
      if (!re.test(line)) continue;
      families[family] = (families[family] || 0) + 1;
      const sample = `${path}:${i + 1}:${redactSecrets(line.trim())}`;
      if (samples.length < 5 && !seenSamples.has(sample)) {
        samples.push(sample);
        seenSamples.add(sample);
      }
    }
  }

  const rawScore = Object.entries(families).reduce((sum, [family, count]) => {
    return sum + Math.min(count, 20) * (weights[family] || 1);
  }, 0);
  const score = Math.round(rawScore * extMultiplier);
  if (score <= 0) return null;
  const topFamilies = Object.entries(families)
    .sort((a, b) => (Math.min(b[1], 20) * (weights[b[0]] || 1)) - (Math.min(a[1], 20) * (weights[a[0]] || 1)))
    .map(([family]) => family);
  return {
    path,
    score,
    raw_score: rawScore,
    size: st.size,
    families,
    samples,
    suggested_task: `analyze ${path} for ${topFamilies.slice(0, 4).join(", ")} risk`
  };
}

function scout(args) {
  const parsed = parseScoutArgs(args);
  const started = Date.now();
  const files = listFiles(parsed.files);
  const ranked = files
    .map(scoutFile)
    .filter(Boolean)
    .sort((a, b) => b.score - a.score)
    .slice(0, parsed.limit);
  console.log("Neuron Mercury scout");
  console.log(`cwd: ${process.cwd()}`);
  console.log(`scanned files: ${files.length}`);
  console.log(`ranked targets: ${ranked.length}`);
  console.log(`elapsed: ${Date.now() - started}ms`);
  for (const item of ranked) {
    console.log("");
    console.log(`## ${item.path}`);
    console.log(`score: ${item.score} (raw=${item.raw_score})`);
    console.log(`families: ${JSON.stringify(item.families)}`);
    console.log(`doctor: node "/root/Neuron Mercury/src/mercury.js" doctor "${item.suggested_task}"`);
    for (const sample of item.samples) console.log(`- ${sample}`);
  }
}

function runNeuron(neuron, taskText, context = createRunContext(taskText)) {
  const started = context.profile ? Date.now() : 0;
  const targetFiles = context.targetFiles || [];
  let artifact = {
    neuron_id: neuron.id,
    kernel: neuron.type,
    signal: "observed",
    evidence: [],
    confidence: neuron.activation || 0.5
  };

  if (neuron.id === "retrieval.repo_files") {
    artifact.signal = "candidate_files";
    artifact.evidence = listFiles(60, targetFiles);
    artifact.confidence = artifact.evidence.length ? 0.72 : 0.35;
  }

  if (neuron.id === "retrieval.target_file") {
    artifact.signal = targetFiles.length ? "target_files_detected" : "target_files_missing";
    artifact.evidence = sanitizeEvidence(targetFiles);
    artifact.confidence = targetFiles.length ? 0.95 : 0.25;
  }

  if (neuron.id === "tool.file_outline") {
    const outlines = targetFiles.map((file) => analyzeFileOutline(file));
    artifact.signal = outlines.length ? "file_outline_ready" : "file_outline_missing";
    artifact.evidence = outlines.flatMap((outline) =>
      outline.symbols.slice(0, 30).map((symbol) =>
        `${outline.path}:${symbol.start}-${symbol.end}:${symbol.type}:${symbol.name}`
      )
    );
    artifact.details = { outlines };
    artifact.confidence = outlines.length ? 0.82 : 0.25;
  }

  if (neuron.id === "git.recent_changes") {
    if (targetFiles.length && !taskNeedsGitHistory(taskText)) {
      artifact.signal = "recent_commits_skipped_for_speed";
      artifact.evidence = ["Explicit target file detected; git history skipped on the fast path."];
      artifact.confidence = 0.62;
    } else {
      const git = getRecentGitChanges(context);
      artifact.signal = git.ok ? "recent_commits_loaded" : "recent_commits_unavailable";
      artifact.evidence = git.output ? sanitizeEvidence(git.output.split("\n").slice(0, 8)) : [];
      artifact.confidence = git.ok ? 0.68 : 0.25;
    }
  }

  if (isUmaPhaseNeuron(neuron.id)) {
    const phase = neuron.id.split(".")[0];
    artifact.signal = `${phase}_phase_ready`;
    artifact.evidence = [
      `Task: ${taskText}`,
      targetFiles.length
        ? `Targets: ${targetFiles.join(", ")}`
        : "Targets: not narrowed yet",
      `Specialty: ${neuron.specialty}`
    ];
    artifact.details = {
      phase,
      sparse: targetFiles.length > 0,
      note: targetFiles.length
        ? "Recorded in circuit; target-file plan execution remains risk-neuron sparse for speed."
        : "Available for broad repo exploration and synthesis structure."
    };
    artifact.confidence = neuron.activation || 0.55;
  }

  if (neuron.id === "tool.rg_latency_terms") {
    if (targetFiles.length) {
      artifact.signal = "latency_terms_skipped_for_speed";
      artifact.evidence = ["Explicit target file detected; risk-family bundle covers latency terms on the fast path."];
      artifact.confidence = 0.62;
    } else {
      const lines = targetFamilyLines("latency_terms", "timeout|sleep|retry|blocking|cache|latency|slow", targetFiles, context);
      artifact.signal = lines.length ? "latency_terms_found" : "latency_terms_sparse";
      artifact.evidence = sanitizeEvidence(lines.slice(0, RISK_CANDIDATE_LIMIT));
      artifact.confidence = artifact.evidence.length ? 0.7 : 0.4;
    }
  }

  if (neuron.id === "risk.sqlite_timeout") {
    const lines = targetFamilyLines("sqlite_timeout", "sqlite|better-sqlite|SQLITE|busy|BEGIN|COMMIT|db\\.|Database", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "sqlite_risk_candidates" : "sqlite_risk_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.76 : 0.35;
  }

  if (neuron.id === "risk.aggregate_scan") {
    const lines = targetFamilyLines("aggregate_scan", "COUNT\\s*\\(\\s*\\*\\s*\\)|AVG\\s*\\(|GROUP\\s+BY|ORDER\\s+BY|fetchall\\(|fetchone\\(|SELECT\\s+.+\\s+FROM", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "aggregate_scan_candidates" : "aggregate_scan_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.79 : 0.35;
  }

  if (neuron.id === "risk.sync_exec") {
    const lines = targetFamilyLines("sync_exec", "execFileSync|spawnSync|readFileSync|writeFileSync|appendFileSync|readdirSync|statSync", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "sync_blocking_candidates" : "sync_blocking_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.78 : 0.35;
  }

  if (neuron.id === "risk.network_timeout") {
    const lines = targetFamilyLines("network_timeout", "fetch\\(|http\\.request|https\\.request|axios|timeoutMs|AbortController|setTimeout", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "network_timeout_candidates" : "network_timeout_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.72 : 0.35;
  }

  if (neuron.id === "risk.retry_loop") {
    const lines = targetFamilyLines("retry_loop", "retry|while\\s*\\(|setInterval|setTimeout|queue|backoff", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "retry_loop_candidates" : "retry_loop_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.7 : 0.35;
  }

  if (neuron.id === "risk.secret_exposure") {
    const lines = targetFamilyLines("secret_exposure", "KEY|TOKEN|SECRET|PASSWORD|PASS|AUTH|Bearer|api_key", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "secret_like_context_redacted" : "secret_like_context_sparse";
    artifact.evidence = sanitizeEvidence(lines.slice(0, RISK_CANDIDATE_LIMIT));
    artifact.confidence = lines.length ? 0.9 : 0.35;
  }

  if (neuron.id === "risk.hot_path") {
    const lines = targetFamilyLines("hot_path", "setInterval|setTimeout|http\\.request|createServer|listen\\(|queue|worker|drain|while\\s*\\(|for\\s+await|process\\.on|\\.on\\(", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "hot_path_candidates" : "hot_path_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.74 : 0.35;
  }

  if (neuron.id === "risk.atomic_write") {
    const lines = targetFamilyLines("atomic_write", "write_text\\(|writeText\\(|writeFileSync\\(|\\.open\\(\\s*[\"']w[\"']|open\\(\\s*[\"']w[\"']|latest|manifest\\.json|report\\.json|\\.jsonl", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "atomic_write_candidates" : "atomic_write_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.82 : 0.35;
  }

  if (neuron.id === "risk.silent_data_loss") {
    const lines = targetFamilyLines("silent_data_loss", "JSONDecodeError|json\\.loads|JSON\\.parse|load_jsonl|invalid JSON|continue|pass|except\\s+\\w*Error", targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "silent_data_loss_candidates" : "silent_data_loss_sparse";
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.8 : 0.35;
  }

  if (neuron.id === "risk.packaging_entrypoint") {
    const validationLines = packagingEntrypointValidationLines(targetFiles);
    const lines = [
      ...validationLines,
      ...targetFamilyLines("packaging_entrypoint", "\\[project\\.scripts\\]|console_scripts|entry_points|package-dir|packages|[A-Za-z0-9_-]+\\s*=\\s*[\"'][A-Za-z0-9_.]+:[A-Za-z0-9_]+[\"']", targetFiles, context)
    ].slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? "packaging_entrypoint_candidates" : "packaging_entrypoint_sparse";
    artifact.evidence = sanitizeEvidence(lines.slice(0, CONTEXT_EVIDENCE_LIMIT));
    artifact.confidence = lines.length ? 0.76 : 0.35;
  }

  if (EXTRA_RISK_FAMILY_CONFIG[neuron.id]) {
    const config = EXTRA_RISK_FAMILY_CONFIG[neuron.id];
    const lines = targetFamilyLines(config.family, config.pattern, targetFiles, context).slice(0, RISK_CANDIDATE_LIMIT);
    artifact.signal = lines.length ? `${config.family}_candidates` : `${config.family}_sparse`;
    artifact.evidence = sanitizeEvidence([...lines.slice(0, CONTEXT_EVIDENCE_LIMIT), ...umaEvidenceForNeuron(context, neuron.id)]);
    artifact.confidence = lines.length ? 0.7 : 0.32;
  }

  if (neuron.id === "evidence.rank") {
    artifact.signal = "ranking_rules_ready";
    artifact.evidence = [
      "high: exact risky primitive on target file",
      "medium: nearby context inside a relevant function",
      "low/noisy: self-reference, neuron registry, or generic keyword match"
    ];
    artifact.confidence = 0.68;
  }

  if (neuron.id === "critic.risk_surface") {
    artifact.signal = "verification_needed";
    artifact.evidence = [
      "Treat tool output as leads, not conclusions.",
      "Run tests before patching.",
      "Do not execute destructive commands without approval."
    ];
    artifact.confidence = 0.8;
  }

  if (neuron.id === "safety.destructive_action") {
    artifact.signal = "approval_required";
    artifact.evidence = ["Task text may imply destructive, external, or production action."];
    artifact.confidence = 0.9;
  }

  if (neuron.id === "compression.evidence_packet") {
    const packet = buildUmaEvidencePacket(context);
    artifact.signal = "packet_ready";
    artifact.evidence = [
      `Task: ${taskText}`,
      `UMA route=${packet.route} hits=${packet.hit_count} candidate_pages=${packet.candidate_pages}`,
      ...packet.items.slice(0, 4).map((item) => `${item.pointer} score=${item.score} ${item.excerpt}`)
    ];
    artifact.confidence = 0.6;
    artifact.details = { ...(artifact.details || {}), packet };
  }

  if (neuron.id === "synthesis.patch_plan") {
    artifact.signal = "patch_plan_requested";
    artifact.evidence = ["Patch plan synthesis should use verified risk artifacts before proposing edits."];
    artifact.confidence = 0.65;
  }

  return {
    ...artifact,
    evidence: sanitizeEvidence(artifact.evidence),
    elapsed_ms: context.profile ? Date.now() - started : 0
  };
}

function buildRiskFindings(artifacts) {
  const riskMap = {
    "risk.sqlite_timeout": {
      title: "SQLite / database timeout risk",
      plan: "Centralize DB access behind a queued helper, add busy-timeout logging, and make timeout fallback explicit.",
      verification: ["Run syntax checks.", "Run a smoke path that touches database reads/writes.", "Rerun Mercury and confirm fewer unclassified DB timeout hotspots."]
    },
    "risk.aggregate_scan": {
      title: "Large aggregate scan pressure risk",
      plan: "Measure aggregate queries against production-sized data, add indexed/materialized summaries where needed, and keep the hot path bounded.",
      verification: ["Run syntax checks.", "Run EXPLAIN QUERY PLAN or timing on the aggregate query.", "Confirm the pipeline records row counts and elapsed time."]
    },
    "risk.sync_exec": {
      title: "Synchronous blocking call risk",
      plan: "Replace blocking sync calls on hot paths with bounded async helpers or precomputed cache, then emit timeout artifacts.",
      verification: ["Run node syntax checks.", "Exercise the affected command path.", "Measure time-to-first-useful-signal before and after."]
    },
    "risk.network_timeout": {
      title: "Network timeout / slow API path risk",
      plan: "Wrap external fetches with explicit timeout, retry budget, and cached degraded fallback.",
      verification: ["Simulate timeout/failure.", "Check fallback output.", "Confirm the caller does not block the main loop indefinitely."]
    },
    "risk.retry_loop": {
      title: "Retry loop / queue pressure risk",
      plan: "Add bounded retry count, jitter/backoff, and queue-depth telemetry before changing behavior.",
      verification: ["Force a failing dependency.", "Confirm retries stop.", "Confirm telemetry records the failure mode."]
    },
    "risk.secret_exposure": {
      title: "Secret exposure in evidence context",
      plan: "Keep redaction before blackboard writeback and move sensitive constants to environment variables when patching nearby code.",
      verification: ["Search blackboard traces for unredacted key fragments.", "Confirm output keeps secrets redacted.", "Avoid copying secret-adjacent context into LLM prompts."]
    },
    "risk.hot_path": {
      title: "Hot path / loop pressure risk",
      plan: "Identify whether the risky primitive sits inside a recurring worker, request path, or queue drain before editing.",
      verification: ["Map evidence to function context.", "Trigger the hot path once in a smoke run.", "Confirm telemetry records elapsed time."]
    },
    "risk.atomic_write": {
      title: "Non-atomic latest/manifest write risk",
      plan: "Replace direct latest, manifest, report, or JSONL overwrites with temp-file write, flush/fsync where available, and atomic rename.",
      verification: ["Run syntax checks.", "Interrupt or simulate a failed write in a temp output directory.", "Confirm downstream readers never consume partial latest/manifest files."]
    },
    "risk.silent_data_loss": {
      title: "Silent JSON/JSONL data-loss risk",
      plan: "Fail fast or emit a structured error when JSONL decode errors occur, and add row-count floors for pipeline outputs.",
      verification: ["Feed one malformed JSONL row.", "Confirm the command fails or reports the bad line.", "Confirm eval gates reject abnormal row-count drops."]
    },
    "risk.packaging_entrypoint": {
      title: "Packaging entrypoint / install usability risk",
      plan: "Verify declared console entrypoints import successfully, remove stale commands, or add missing modules before publishing.",
      verification: ["Run import checks for every declared entrypoint.", "Run package install smoke test.", "Confirm CLI help works for each public command."]
    }
  };
  for (const [id, config] of Object.entries(EXTRA_RISK_FAMILY_CONFIG)) {
    riskMap[id] = {
      title: config.title,
      plan: config.plan,
      verification: ["Run the relevant Mercury benchmark.", "Confirm target evidence is direct and not a self-reference.", "Check the hot path remains within budget."]
    };
  }
  const outlines = artifacts
    .filter((artifact) => artifact.neuron_id === "tool.file_outline" && artifact.details?.outlines)
    .flatMap((artifact) => artifact.details.outlines);

  return artifacts
    .filter((artifact) => riskMap[artifact.neuron_id] && artifact.evidence.length)
    .map((artifact) => {
      const meta = riskMap[artifact.neuron_id];
      let evidence = uniqueEvidence(normalizeEvidence(artifact.evidence))
        .filter((item) => item.path || item.text)
        .map((item) => {
          const symbol = item.path && item.line ? findSymbol(outlines, item.path, item.line) : null;
          const enriched = {
            ...item,
            symbol: symbol ? `${symbol.type}:${symbol.name}` : null
          };
          const ranked = rankEvidence(enriched, artifact.neuron_id);
          return { ...enriched, rank: ranked.rank, score: ranked.score };
        })
        .sort((a, b) => b.score - a.score);

      const nonNoisy = evidence.filter((item) => item.rank !== "noisy");
      if (nonNoisy.length >= 3) evidence = nonNoisy;
      evidence = evidence.slice(0, 6);

      return {
        neuron_id: artifact.neuron_id,
        title: meta.title,
        confidence: artifact.confidence,
        signal: artifact.signal,
        evidence,
        evidence_rank_summary: evidence.reduce((acc, item) => {
          acc[item.rank] = (acc[item.rank] || 0) + 1;
          return acc;
        }, {}),
        plan: meta.plan,
        verification: meta.verification
      };
    });
}

function buildPatchPlan(taskText, artifacts, context = createRunContext(taskText)) {
  const targetFiles = context.targetFiles || [];
  const findings = buildRiskFindings(artifacts);
  const verification = [
    ...new Set([
      ...targetFiles.filter((file) => file.endsWith(".js")).map((file) => `node -c ${file}`),
      ...targetFiles.filter((file) => file.endsWith(".py")).map((file) => `python3 -m py_compile ${file}`),
      "rerun Neuron Mercury plan on the same task"
    ])
  ];

  const plan = {
    task: taskText,
    target_files: targetFiles,
    summary: findings.length
      ? `Found ${findings.length} risk families worth verifying before patching.`
      : "No strong risk family was detected; inspect the evidence packet before patching.",
    findings,
    patch_order: findings.map((finding, index) => ({
      step: index + 1,
      focus: finding.title,
      action: finding.plan
    })),
    verification,
    safety_gate: "Do not apply destructive, production, payment, or external-send actions without owner approval."
  };

  return plan;
}

function buildNestedNeuronDag(taskText, circuit, artifacts, patchPlan) {
  const artifactByNeuron = new Map(artifacts.map((artifact) => [artifact.neuron_id, artifact]));
  const clusters = {};
  for (const neuron of circuit) {
    const cluster = neuronCluster(neuron.id);
    if (!clusters[cluster]) clusters[cluster] = [];
    const artifact = artifactByNeuron.get(neuron.id);
    clusters[cluster].push({
      id: neuron.id,
      activation: neuron.activation || 0,
      scheduler_score: neuron.scheduler_score ?? neuronSchedulerScore(neuron),
      signal: artifact?.signal || "not_executed",
      evidence_count: artifact?.evidence?.length || 0
    });
  }
  const evidence = artifacts
    .filter((artifact) => artifact.evidence?.length)
    .slice(0, 12)
    .map((artifact) => ({
      neuron_id: artifact.neuron_id,
      signal: artifact.signal,
      evidence_count: artifact.evidence.length,
      confidence: artifact.confidence
    }));
  return {
    schema: "nested-neuron-dag-v1",
    goal: taskText,
    subgoals: [
      { id: "decompose", depends_on: [], neurons: clusters.decompose || [] },
      { id: "retrieve", depends_on: ["decompose"], neurons: clusters.retrieval || [] },
      { id: "risk", depends_on: ["retrieve"], neurons: clusters.risk || [] },
      { id: "accelerate", depends_on: ["risk"], neurons: clusters.accelerate || [] },
      { id: "memory", depends_on: ["accelerate"], neurons: clusters.memory || [] },
      { id: "judge", depends_on: ["risk", "memory"], neurons: [...(clusters.evidence || []), ...(clusters.judge || [])] },
      { id: "synthesis", depends_on: ["judge"], neurons: clusters.synthesis || [] }
    ],
    evidence,
    judge: {
      finding_count: patchPlan?.findings?.length || 0,
      target_files: patchPlan?.target_files || [],
      high_evidence_count: (patchPlan?.findings || []).reduce((sum, finding) => sum + (finding.evidence_rank_summary?.high || 0), 0)
    },
    synthesis: {
      summary: patchPlan?.summary || "pending",
      patch_steps: patchPlan?.patch_order?.length || 0
    }
  };
}

function writeTrace(taskText, circuit, artifacts, patchPlan = null) {
  ensureDirs();
  const taskId = `task_${Date.now()}`;
  const trace = {
    task_id: taskId,
    created_at: nowIso(),
    cwd: process.cwd(),
    task: taskText,
    nested_neuron_dag: buildNestedNeuronDag(taskText, circuit, artifacts, patchPlan),
    circuit: circuit.map((n) => ({
      id: n.id,
      type: n.type,
      cluster: neuronCluster(n.id),
      scheduler_score: n.scheduler_score,
      activation: n.activation,
      hits: n.hits || []
    })),
    artifacts
  };
  const path = join(BLACKBOARD_DIR, `${taskId}.json`);
  enqueueTraceWrite(path, trace);
  return { taskId, path, trace };
}

function workflowCachePathFor(taskText, namespace = projectUmaNamespace()) {
  ensureDirs();
  return join(WORKFLOW_CACHE_DIR, `workflow_${stableHash(["workflow-cache-v1", namespace, normalizePrompt(taskText)])}.json`);
}

function listWorkflowCacheFiles(limit = 4096) {
  ensureDirs();
  return readdirSync(WORKFLOW_CACHE_DIR)
    .filter((name) => /^workflow_[a-f0-9]{24}\.json$/.test(name))
    .slice(0, limit)
    .flatMap((name) => {
      const path = join(WORKFLOW_CACHE_DIR, name);
      try {
        const st = statSync(path);
        return [{ name, path, size: st.size, mtimeMs: st.mtimeMs }];
      } catch {
        return [];
      }
    });
}

function workflowReplayCacheSummary(namespace = projectUmaNamespace(), options = {}) {
  ensureDirs();
  if (options.fast) {
    const latest = readJsonFileOrNull(join(BENCH_DIR, "accelerate-task-latest.json"))
      || readJsonFileOrNull(join(PRODUCT_DIR, "boost-latest.json"));
    const fastPath = join(CACHE_DIR, "workflow-fast-summary.json");
    const cached = readJsonFileOrNull(fastPath);
    return {
      schema: "mercury-workflow-replay-cache-summary-v1",
      namespace,
      workflows: cached?.workflows || 0,
      namespace_workflows: cached?.namespace_workflows || 0,
      accelerate_task_fast: cached?.accelerate_task_fast || (latest ? 1 : 0),
      accelerate_task_replay: cached?.accelerate_task_replay || (latest ? 1 : 0),
      latest_workflow_at: cached?.latest_workflow_at || latest?.created_at || null,
      ready: Boolean(cached?.ready || latest),
      fast: true
    };
  }
  const files = listWorkflowCacheFiles()
    .sort((a, b) => b.mtimeMs - a.mtimeMs);
  let namespaceFiles = 0;
  let latestAt = null;
  for (const file of files.slice(0, 128)) {
    try {
      const row = JSON.parse(readFileSync(file.path, "utf8"));
      if (row.namespace === namespace) {
        namespaceFiles += 1;
        if (!latestAt || String(row.created_at || "") > latestAt) latestAt = row.created_at || null;
      }
    } catch {}
  }
  const fastFiles = readdirSync(CACHE_DIR).filter((name) => /^accelerate_task_fast_[a-f0-9]{24}\.json$/.test(name)).length;
  const replayFiles = readdirSync(CACHE_DIR).filter((name) => /^accelerate_task_[a-f0-9]{24}\.json$/.test(name)).length;
  atomicWriteJson(join(CACHE_DIR, "workflow-fast-summary.json"), {
    workflows: files.length,
    namespace_workflows: namespaceFiles,
    accelerate_task_fast: fastFiles,
    accelerate_task_replay: replayFiles,
    latest_workflow_at: latestAt,
    ready: namespaceFiles > 0 || fastFiles > 0 || replayFiles > 0,
    updated_at: nowIso()
  });
  return {
    schema: "mercury-workflow-replay-cache-summary-v1",
    namespace,
    workflows: files.length,
    namespace_workflows: namespaceFiles,
    accelerate_task_fast: fastFiles,
    accelerate_task_replay: replayFiles,
    latest_workflow_at: latestAt,
    ready: namespaceFiles > 0 || fastFiles > 0 || replayFiles > 0
  };
}

function writeWorkflowCache(taskText, context, circuit, artifacts, patchPlan, timings = {}) {
  const path = workflowCachePathFor(taskText, context.umaNamespace || projectUmaNamespace());
  const record = {
    schema: "workflow-cache-v1",
    created_at: nowIso(),
    namespace: context.umaNamespace || projectUmaNamespace(),
    cwd: context.cwd,
    task_key: normalizePrompt(taskText),
    task_hash: stableHash([context.cwd, taskText]),
    target_files: context.targetFiles || [],
    circuit_ids: circuit.map((neuron) => neuron.id),
    nested_dag: buildNestedNeuronDag(taskText, circuit, artifacts, patchPlan),
    evidence_packet: buildUmaEvidencePacket(context),
    findings: (patchPlan?.findings || []).map((finding) => ({
      neuron_id: finding.neuron_id,
      title: finding.title,
      high: finding.evidence_rank_summary?.high || 0,
      medium: finding.evidence_rank_summary?.medium || 0
    })),
    timings,
    reuse_policy: "same project namespace + similar task can reuse circuit/evidence shape before broad scans"
  };
  atomicWriteJson(path, record);
  return { path, record };
}

function memoryGraphPath() {
  ensureDirs();
  return join(MEMORY_GRAPH_DIR, "events.jsonl");
}

function appendMemoryGraphEvent(event) {
  ensureDirs();
  const row = {
    schema: "mercury-temporal-memory-event-v1",
    at: nowIso(),
    project: projectUmaIdentity().repo,
    namespace: projectUmaNamespace(),
    ...event
  };
  appendFileSync(memoryGraphPath(), JSON.stringify(row) + "\n", "utf8");
  return row;
}

function recordTaskMemoryGraph(taskText, context, circuit, patchPlan, workflowPath) {
  return appendMemoryGraphEvent({
    type: "task_workflow",
    task_hash: stableHash([context.cwd, taskText]),
    task: taskText,
    targets: context.targetFiles || [],
    workflow_path: workflowPath,
    route: context.umaRoute || null,
    circuit_ids: circuit.map((neuron) => neuron.id),
    finding_count: patchPlan?.findings?.length || 0,
    high_evidence_count: (patchPlan?.findings || []).reduce((sum, finding) => sum + (finding.evidence_rank_summary?.high || 0), 0)
  });
}

function rosenEntrySignals(taskText, options = {}) {
  const task = String(taskText || "").trim();
  const tokens = [...semanticTokens(task)].slice(0, 64);
  const targetFiles = [...new Set([...(options.targetFiles || []), ...extractTargetFiles(task)])]
    .filter((candidate) => existsSync(resolve(process.cwd(), candidate)));
  const joined = `${task} ${tokens.join(" ")}`.toLowerCase();
  const riskFamilies = [];
  const add = (id, reason) => {
    if (!riskFamilies.some((item) => item.id === id)) riskFamilies.push({ id, reason });
  };
  if (/\b(anthropic|claude|openai|gemini|api[_-]?key|provider|billing|spend|扣款|花費|付費)\b/i.test(joined)) add("provider_spend", "paid provider or hidden billing risk");
  if (/\b(latency|slow|timeout|hot[_-]?path|queue|retry|慢|卡|延遲|加速)\b/i.test(joined)) add("latency_hot_path", "slow path or repeated work risk");
  if (/\b(qwen|qwer|ollama|vllm|local[_-]?llm|nvidia|gpu|cuda)\b/i.test(joined)) add("local_llm_speed", "local model/provider acceleration route");
  if (/\b(rag|uma|memory|namespace|coherence|cache|記憶|蟲洞|rosen|bridge)\b/i.test(joined)) add("memory_route", "memory and bridge route required");
  if (/\b(security|secret|token|vulnerab|attack|安全|漏洞|滲透)\b/i.test(joined)) add("security_hardening", "defensive inspection and guard route");
  if (/\b(report|5000|longform|generate|draft|文章|報告)\b/i.test(joined)) add("first_generation", "first-generation scaffold and distillation route");
  if (/慢|卡|延遲|加速|等待|速度/.test(joined)) add("latency_hot_path", "slow path or repeated work risk");
  if (/模型|本地\s*(ai|llm)?|顯卡|3060|4060|gpu|cuda|ollama|qwen|deepseek/i.test(joined)) add("local_llm_speed", "local model/provider acceleration route");
  if (/記憶|快取|語意|羅森|蟲洞|橋|神經元|rosen|bridge|cache|memory|reflex/i.test(joined)) add("memory_route", "memory and bridge route required");
  if (/安全|漏洞|權限|密碼|金鑰|token|secret/i.test(joined)) add("security_hardening", "defensive inspection and guard route");
  if (/文章|報告|長文|草稿|生成|generate|draft|longform/i.test(joined)) add("first_generation", "first-generation scaffold and distillation route");
  return {
    task,
    tokens,
    target_files: targetFiles,
    risk_families: riskFamilies,
    namespace: options.namespace || projectUmaNamespace(),
    cwd: process.cwd()
  };
}

function rosenBridgeId(parts) {
  return stableHash(["rosen-bridge-v1", parts]);
}

function writeRosenBridge(bridge) {
  ensureDirs();
  const id = bridge.id || rosenBridgeId([bridge.from, bridge.to, bridge.type, bridge.namespace || projectUmaNamespace()]);
  const row = {
    schema: "mercury-rosen-bridge-v1",
    id,
    created_at: bridge.created_at || nowIso(),
    updated_at: nowIso(),
    namespace: bridge.namespace || projectUmaNamespace(),
    ...bridge,
    id
  };
  const path = join(ROSEN_BRIDGE_DIR, `bridge_${id}.json`);
  atomicWriteJson(path, row, { pretty: true });
  return { path, row };
}

function readRosenBridges(limit = 2048, namespace = projectUmaNamespace()) {
  ensureDirs();
  return readdirSync(ROSEN_BRIDGE_DIR)
    .filter((name) => /^bridge_[a-f0-9]{24}\.json$/.test(name))
    .slice(-Math.max(1, limit))
    .flatMap((name) => {
      try {
        const path = join(ROSEN_BRIDGE_DIR, name);
        const row = JSON.parse(readFileSync(path, "utf8"));
        if (namespace && row.namespace && row.namespace !== namespace) return [];
        return [{ ...row, path }];
      } catch {
        return [];
      }
    });
}

function rosenBridgeScore(candidate, entry) {
  const freshness = candidate.freshness === "stale" ? -0.25 : candidate.freshness === "fresh" ? 0.12 : 0;
  const riskPenalty = candidate.risk === "high" ? -0.12 : candidate.risk === "medium" ? -0.04 : 0;
  const costBoost = candidate.cost === "low" ? 0.08 : candidate.cost === "model" ? -0.18 : 0;
  const candidateTokens = Array.isArray(candidate.tokens)
    ? candidate.tokens
    : candidate.tokens && typeof candidate.tokens[Symbol.iterator] === "function"
    ? [...candidate.tokens]
    : semanticTokens(`${candidate.from || ""} ${candidate.to || ""} ${candidate.evidence || ""}`);
  const tokenOverlap = tokenSetSimilarity(new Set(entry.tokens), new Set(candidateTokens));
  const targetBoost = entry.target_files.some((file) => String(candidate.to || "").includes(file) || String(candidate.evidence || "").includes(file)) ? 0.2 : 0;
  const familyBoost = entry.risk_families.some((family) => family.id === candidate.risk_family) ? 0.24 : 0;
  const base = Number(candidate.confidence || 0.35);
  return Number(Math.max(0.01, Math.min(1, base + tokenOverlap + targetBoost + familyBoost + freshness + riskPenalty + costBoost)).toFixed(3));
}

function rosenStaticBridges(entry) {
  const familyBridges = {
    provider_spend: [
      ["entry:provider_spend", "tool:spend-guard+cost-scan", "accelerated_by", "low", "medium", "Scan paid provider env, call sites, loops, fanout, and cache bypasses before any model call."],
      ["entry:provider_spend", "neuron:risk.cost+judge", "verified_by", "low", "medium", "Use cost/risk neurons and judge before accusing a live process."]
    ],
    latency_hot_path: [
      ["entry:latency_hot_path", "tool:code-cortex+uma-target-file-first", "accelerated_by", "low", "low", "Route slow symptoms to hot files, symbols, queue/retry/cache patterns, and UMA evidence."],
      ["entry:latency_hot_path", "guard:hot-path-budget", "blocked_by", "low", "medium", "Do not let broad UMA preload or model calls enter the hot path."]
    ],
    local_llm_speed: [
      ["entry:local_llm_speed", "tool:llm-fast+provider-cache+slow-worker", "accelerated_by", "low", "medium", "Answer repeated intents from reflex/provider cache and queue Qwen for slow refresh."],
      ["entry:local_llm_speed", "guard:model-hot-path-forbidden", "unsafe_if", "low", "high", "Keep local LLM generation out of user-facing hot path unless benchmark-proven."]
    ],
    memory_route: [
      ["entry:memory_route", "tool:uma-batch-search+project-namespace", "accelerated_by", "low", "low", "Use project UMA namespace, batch search, hot pages, and coherence before broad scans."],
      ["entry:memory_route", "guard:namespace-coherence", "verified_by", "low", "medium", "Reject stale or cross-project memory bridges."]
    ],
    security_hardening: [
      ["entry:security_hardening", "neuron:security+risk+tribunal", "accelerated_by", "low", "high", "Use defensive-only inspection with evidence, risk ranking, and verification gates."],
      ["entry:security_hardening", "guard:authorized-scope", "blocked_by", "low", "high", "Do not cross authorization or destructive boundaries."]
    ],
    first_generation: [
      ["entry:first_generation", "tool:first-gen-accelerate+section-workers", "accelerated_by", "low", "medium", "Build evidence-bound section drafts before slow model completion."],
      ["entry:first_generation", "memory:distill-to-reflex-and-bridges", "distilled_from", "low", "low", "After a slow generation, keep the route and section shape, not only the text."]
    ]
  };
  return entry.risk_families.flatMap((family) => (familyBridges[family.id] || []).map(([from, to, type, cost, risk, evidence]) => ({
    from,
    to,
    type,
    namespace: entry.namespace,
    risk_family: family.id,
    confidence: 0.58,
    latency_ms: 1,
    cost,
    risk,
    freshness: "fresh",
    evidence,
    tokens: semanticTokens(`${from} ${to} ${evidence}`)
  })));
}

function rosenMemoryBridges(entry, options = {}) {
  const rows = readMemoryGraphRows(options.memoryLimit || 2000);
  const entryTokens = new Set(entry.tokens);
  return rows
    .map((row) => {
      const text = [
        row.type,
        row.task,
        row.route,
        ...(row.targets || []),
        ...(row.success_path || []),
        ...(row.failure_risks || [])
      ].filter(Boolean).join(" ");
      const tokens = semanticTokens(text);
      const similarity = tokenSetSimilarity(entryTokens, new Set(tokens));
      if (similarity < 0.08) return null;
      return {
        from: `entry:${entry.risk_families[0]?.id || "task"}`,
        to: `memory:${row.type || "event"}:${row.task_hash || stableHash(text)}`,
        type: row.type === "monster_doctor" || row.type === "task_workflow" ? "distilled_from" : "similar_to",
        namespace: row.namespace || entry.namespace,
        risk_family: entry.risk_families[0]?.id || null,
        confidence: Math.min(0.72, 0.35 + similarity),
        latency_ms: 2,
        cost: "low",
        risk: "low",
        freshness: "fresh",
        evidence: compactEvidenceText(text, 260),
        tokens
      };
    })
    .filter(Boolean)
    .sort((a, b) => rosenBridgeScore(b, entry) - rosenBridgeScore(a, entry))
    .slice(0, options.memoryBridges || 10);
}

function rosenUmaBridges(entry, options = {}) {
  const queries = [
    entry.task,
    ...entry.risk_families.map((family) => `${family.id} ${family.reason}`),
    ...entry.target_files.map((file) => `${file} ${entry.task}`)
  ].filter(Boolean).slice(0, options.maxQueries || 8);
  if (!queries.length) return [];
  const batch = umaBatchSearch(queries, {
    namespace: entry.namespace,
    limit: options.limit || 3,
    budgetMs: options.umaBudgetMs ?? 4,
    maxQueries: options.maxQueries || 8,
    hotCacheLimit: 48,
    symbolScanLimit: 32
  });
  return (batch.results || []).flatMap((item) => (item.search?.results || []).map((hit) => ({
    from: `entry:${entry.risk_families[0]?.id || "task"}`,
    to: `uma:${hit.pointer}`,
    type: "similar_to",
    namespace: entry.namespace,
    risk_family: entry.risk_families[0]?.id || null,
    confidence: Math.min(0.84, 0.38 + Number(hit.score || 0)),
    latency_ms: item.search.elapsed_ms || 0,
    cost: "low",
    risk: "low",
    freshness: "fresh",
    evidence: hit.text,
    tokens: semanticTokens(`${hit.pointer} ${hit.text}`)
  })));
}

function rosenRoute(taskText, options = {}) {
  ensureDirs();
  const started = Date.now();
  const entry = rosenEntrySignals(taskText, options);
  const existing = options.readStore === false
    ? []
    : readRosenBridges(options.bridgeLimit ?? 2048, entry.namespace)
      .map((bridge) => ({ ...bridge, source: "bridge_store" }));
  const generated = [
    ...rosenStaticBridges(entry).map((bridge) => ({ ...bridge, source: "static_family" })),
    ...rosenMemoryBridges(entry, options).map((bridge) => ({ ...bridge, source: "memory_graph" })),
    ...(options.uma === false ? [] : rosenUmaBridges(entry, options).map((bridge) => ({ ...bridge, source: "uma_batch" })))
  ];
  const merged = [...generated, ...existing]
    .map((bridge) => ({ ...bridge, score: rosenBridgeScore(bridge, entry) }))
    .filter((bridge) => bridge.score >= (options.threshold ?? 0.12))
    .sort((a, b) => b.score - a.score || String(a.to).localeCompare(String(b.to)));
  const seen = new Set();
  const selected = [];
  const addSelected = (bridge) => {
    const key = `${bridge.from}->${bridge.to}:${bridge.type}`;
    if (seen.has(key)) return false;
    seen.add(key);
    selected.push(bridge);
    return true;
  };
  for (const source of ["static_family", "uma_batch", "memory_graph", "bridge_store"]) {
    const bridge = source === "static_family"
      ? (
          entry.risk_families.some((family) => family.id === "provider_spend")
            ? merged.find((item) => item.source === source && /spend-guard|cost-scan/.test(String(item.to || "")))
            : null
        )
        || merged.find((item) => item.source === source && String(item.to || "").startsWith("tool:"))
        || merged.find((item) => item.source === source)
      : merged.find((item) => item.source === source);
    if (bridge) addSelected(bridge);
  }
  for (const bridge of merged) {
    if (selected.length >= (options.limit || 12)) break;
    addSelected(bridge);
  }
  const persistLimit = options.persist ?? 8;
  const persisted = selected.slice(0, persistLimit).map((bridge) => writeRosenBridge({
    ...bridge,
    hit_count: Number(bridge.hit_count || 0) + 1,
    miss_count: Number(bridge.miss_count || 0),
    activation_rule: bridge.activation_rule || entry.risk_families.map((family) => family.id).join("+") || "task_tokens"
  }));
  const guard = {
    namespace_isolated: true,
    model_hot_path: "forbidden",
    budget_ms: options.budgetMs ?? 12,
    coherence_required: selected.some((bridge) => String(bridge.to || "").startsWith("uma:") || String(bridge.to || "").startsWith("code:")),
    high_risk_requires_judge: selected.some((bridge) => bridge.risk === "high")
  };
  const report = {
    schema: "mercury-rosen-route-v1",
    created_at: nowIso(),
    mode: "rosen_route",
    namespace: entry.namespace,
    cwd: entry.cwd,
    task: entry.task,
    entry,
    candidates: merged.length,
    selected_count: selected.length,
    selected: selected.map((bridge) => ({
      id: bridge.id || rosenBridgeId([bridge.from, bridge.to, bridge.type, entry.namespace]),
      from: bridge.from,
      to: bridge.to,
      type: bridge.type,
      source: bridge.source,
      score: bridge.score,
      confidence: bridge.confidence,
      latency_ms: bridge.latency_ms,
      cost: bridge.cost,
      risk: bridge.risk,
      freshness: bridge.freshness,
      evidence: compactEvidenceText(bridge.evidence || "", 220)
    })),
    probe_plan: selected.slice(0, options.probes || 6).map((bridge, index) => ({
      probe_id: `rosen_probe_${index + 1}`,
      bridge_to: bridge.to,
      neuron_family: bridge.risk_family || "retrieval",
      action: bridge.type === "unsafe_if" || bridge.type === "blocked_by" ? "guard" : bridge.to.startsWith("tool:") ? "tool_probe" : "evidence_probe",
      budget_ms: Math.max(1, Math.min(4, Math.ceil((options.budgetMs ?? 12) / Math.max(1, selected.length))))
    })),
    guard,
    persisted: persisted.map((item) => item.path),
    elapsed_ms: Date.now() - started
  };
  atomicWriteJson(join(ROSEN_DIR, "latest-route.json"), report, { pretty: true });
  appendMemoryGraphEvent({
    type: "rosen_route",
    namespace: entry.namespace,
    task: entry.task,
    risk_families: entry.risk_families.map((family) => family.id),
    selected_count: report.selected_count,
    top_bridges: report.selected.slice(0, 5).map((bridge) => ({ to: bridge.to, score: bridge.score, type: bridge.type })),
    elapsed_ms: report.elapsed_ms
  });
  return report;
}

function rosenRouteCommand(args = []) {
  const json = args.includes("--json");
  const namespaceArg = args.find((arg) => arg.startsWith("--namespace="));
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const budgetArg = args.find((arg) => arg.startsWith("--budget-ms="));
  const task = args.filter((arg) => !arg.startsWith("--")).join(" ").trim();
  const report = rosenRoute(task || "find acceleration bridges for this project", {
    namespace: namespaceArg ? namespaceArg.split("=").slice(1).join("=") : projectUmaNamespace(),
    limit: limitArg ? Math.max(1, Number(limitArg.split("=")[1]) || 12) : 12,
    budgetMs: budgetArg ? Math.max(1, Number(budgetArg.split("=")[1]) || 12) : 12
  });
  if (json) {
    console.log(JSON.stringify(report));
    return report;
  }
  console.log("Neuron Mercury Rosen route");
  console.log(`namespace: ${report.namespace}`);
  console.log(`risk_families: ${report.entry.risk_families.map((family) => family.id).join(",") || "-"}`);
  console.log(`selected: ${report.selected_count}/${report.candidates}`);
  console.log(`elapsed_ms: ${report.elapsed_ms}`);
  for (const bridge of report.selected.slice(0, 10)) {
    console.log(`- ${bridge.score} ${bridge.type} ${bridge.to} source=${bridge.source} risk=${bridge.risk}`);
  }
  return report;
}

function rosenPairId(parts) {
  return stableHash(["rosen-pair-v1", parts]);
}

function rosenPairSourceDigest(entry) {
  const files = (entry.target_files || []).slice(0, 12);
  const sources = files.map((file) => {
    const abs = resolve(process.cwd(), file);
    try {
      const st = statSync(abs);
      const contentHash = st.size <= 1024 * 1024
        ? createHash("sha256").update(readFileSync(abs)).digest("hex").slice(0, 24)
        : null;
      return {
        file,
        size: st.size,
        mtimeMs: Math.round(st.mtimeMs),
        contentHash
      };
    } catch {
      return { file, missing: true };
    }
  });
  return {
    digest: stableHash([entry.namespace, sources]),
    sources
  };
}

function rosenPairState(entry, route) {
  const source = rosenPairSourceDigest(entry);
  const topBridges = (route?.selected || []).slice(0, 8).map((bridge) => ({
    to: bridge.to,
    type: bridge.type,
    source: bridge.source,
    score: bridge.score,
    risk: bridge.risk
  }));
  const state = {
    namespace: entry.namespace,
    task_signature: stableHash([entry.tokens.slice(0, 32), entry.target_files, entry.risk_families.map((family) => family.id)]),
    target_files: entry.target_files,
    risk_families: entry.risk_families.map((family) => family.id),
    source_digest: source.digest,
    sources: source.sources
  };
  const routeState = {
    rosen_selected: route?.selected_count || 0,
    top_bridges: topBridges
  };
  return {
    ...state,
    ...routeState,
    route_state_digest: stableHash(routeState),
    shared_state_digest: stableHash(state)
  };
}

function writeRosenPair(pair) {
  ensureDirs();
  const id = pair.id || rosenPairId([pair.namespace || projectUmaNamespace(), pair.state?.task_signature || pair.task || "", pair.kind || "state"]);
  const row = {
    schema: "mercury-rosen-pair-v1",
    id,
    created_at: pair.created_at || nowIso(),
    updated_at: nowIso(),
    namespace: pair.namespace || projectUmaNamespace(),
    ...pair,
    id
  };
  const path = join(ROSEN_PAIR_DIR, `pair_${id}.json`);
  atomicWriteJson(path, row, { pretty: true });
  return { path, row };
}

function readRosenPairs(limit = 2048, namespace = projectUmaNamespace()) {
  ensureDirs();
  return readdirSync(ROSEN_PAIR_DIR)
    .filter((name) => /^pair_[a-f0-9]{24}\.json$/.test(name))
    .slice(-Math.max(1, limit))
    .flatMap((name) => {
      try {
        const path = join(ROSEN_PAIR_DIR, name);
        const row = JSON.parse(readFileSync(path, "utf8"));
        if (namespace && row.namespace && row.namespace !== namespace) return [];
        return [{ ...row, path }];
      } catch {
        return [];
      }
    });
}

function rosenPairPulse(taskText, options = {}) {
  ensureDirs();
  const started = Date.now();
  const entry = rosenEntrySignals(taskText, options);
  const route = options.route || rosenRoute(taskText, {
    namespace: entry.namespace,
    targetFiles: options.targetFiles || [],
    limit: options.limit || 8,
    budgetMs: options.budgetMs ?? 8,
    umaBudgetMs: options.umaBudgetMs ?? 3,
    persist: options.persist ?? 2
  });
  const state = rosenPairState(entry, route);
  const id = rosenPairId([entry.namespace, state.task_signature, "state-field"]);
  const prior = readJsonFileOrNull(join(ROSEN_PAIR_DIR, `pair_${id}.json`));
  const changed = !prior || prior.shared_state_digest !== state.shared_state_digest;
  const mode = !prior ? "pair_seed" : changed ? "correction_pulse" : "state_replay";
  const confidence = Math.max(0.35, Math.min(0.98, 0.48 + (route.selected_count || 0) * 0.04 + (state.target_files.length ? 0.08 : 0)));
  const pair = {
    id,
    kind: "state_field_pair",
    namespace: entry.namespace,
    task: entry.task,
    local_neuron: {
      id: `local:${id}`,
      role: "mirror_state_and_route",
      activation: mode,
      cost: "constant_time_digest_read"
    },
    remote_neuron: {
      id: `remote:${id}`,
      role: "resident_project_sentinel",
      location: entry.cwd,
      activation: changed ? "pulse_on_delta" : "dormant"
    },
    state,
    shared_state_digest: state.shared_state_digest,
    prior_digest: prior?.shared_state_digest || null,
    changed,
    pulse: {
      mode,
      zero_wait_claim: "software_pre_synchronization_not_physics_signaling",
      reason: changed ? "state_delta_detected" : "digest_unchanged",
      budget_ms: options.budgetMs ?? 8,
      route_selected: route.selected_count || 0
    },
    mirror: {
      confidence: Number(confidence.toFixed(3)),
      risk_families: state.risk_families,
      target_files: state.target_files,
      top_bridges: state.top_bridges.slice(0, 5)
    },
    route_summary: {
      selected_count: route.selected_count || 0,
      candidates: route.candidates || 0,
      elapsed_ms: route.elapsed_ms || 0
    }
  };
  const written = writeRosenPair(pair);
  atomicWriteJson(join(ROSEN_DIR, "latest-pair.json"), { ...pair, path: written.path, elapsed_ms: Date.now() - started }, { pretty: true });
  appendMemoryGraphEvent({
    type: "rosen_pair_pulse",
    namespace: entry.namespace,
    task: entry.task,
    pair_id: id,
    mode,
    changed,
    shared_state_digest: state.shared_state_digest,
    target_files: state.target_files,
    risk_families: state.risk_families,
    route_selected: route.selected_count || 0,
    elapsed_ms: Date.now() - started
  });
  return {
    schema: "mercury-rosen-pair-pulse-v1",
    created_at: nowIso(),
    pair_id: id,
    namespace: entry.namespace,
    mode,
    changed,
    shared_state_digest: state.shared_state_digest,
    prior_digest: prior?.shared_state_digest || null,
    confidence: pair.mirror.confidence,
    route_selected: route.selected_count || 0,
    route_elapsed_ms: route.elapsed_ms || 0,
    target_files: state.target_files,
    risk_families: state.risk_families,
    path: written.path,
    elapsed_ms: Date.now() - started
  };
}

function rosenPairsSummary(namespace = projectUmaNamespace(), options = {}) {
  const fast = Boolean(options.fast);
  if (fast) {
    const latest = readJsonFileOrNull(join(ROSEN_DIR, "latest-pair.json"));
    return {
      schema: "mercury-rosen-pairs-summary-v1",
      namespace,
      ready: Boolean(latest),
      pairs: latest ? 1 : 0,
      pair_seed: latest?.pulse?.mode === "pair_seed" || latest?.mode === "pair_seed" ? 1 : 0,
      correction_pulse: latest?.pulse?.mode === "correction_pulse" || latest?.mode === "correction_pulse" ? 1 : 0,
      state_replay: latest?.pulse?.mode === "state_replay" || latest?.mode === "state_replay" ? 1 : 0,
      pulse_events: 0,
      pulse_events_skipped: true,
      event_pair_seed: 0,
      event_correction_pulse: 0,
      event_state_replay: 0,
      latest_pair_id: latest?.id || latest?.pair_id || null,
      latest_mode: latest?.pulse?.mode || latest?.mode || null,
      latest_changed: Boolean(latest?.changed),
      latest_elapsed_ms: latest?.elapsed_ms || 0,
      fast: true
    };
  }
  const pairs = readRosenPairs(fast ? 512 : 4096, namespace);
  const latest = readJsonFileOrNull(join(ROSEN_DIR, "latest-pair.json"));
  const byMode = pairs.reduce((acc, pair) => {
    const mode = pair.pulse?.mode || "unknown";
    acc[mode] = (acc[mode] || 0) + 1;
    return acc;
  }, {});
  const pulseEvents = fast ? [] : readMemoryGraphRows(5000).filter((row) => row.type === "rosen_pair_pulse" && row.namespace === namespace);
  const eventByMode = pulseEvents.reduce((acc, row) => {
    const mode = row.mode || "unknown";
    acc[mode] = (acc[mode] || 0) + 1;
    return acc;
  }, {});
  return {
    schema: "mercury-rosen-pairs-summary-v1",
    namespace,
    ready: pairs.length > 0,
    pairs: pairs.length,
    pair_seed: byMode.pair_seed || 0,
    correction_pulse: byMode.correction_pulse || 0,
    state_replay: byMode.state_replay || 0,
    pulse_events: pulseEvents.length,
    pulse_events_skipped: fast,
    event_pair_seed: eventByMode.pair_seed || 0,
    event_correction_pulse: eventByMode.correction_pulse || 0,
    event_state_replay: eventByMode.state_replay || 0,
    latest_pair_id: latest?.id || latest?.pair_id || null,
    latest_mode: latest?.pulse?.mode || latest?.mode || null,
    latest_changed: Boolean(latest?.changed),
    latest_elapsed_ms: latest?.elapsed_ms || 0
  };
}

function rosenPairCommand(args = []) {
  const json = args.includes("--json");
  const firstWord = args.find((arg) => !arg.startsWith("--")) || "status";
  const subcommand = ["status", "pulse", "init"].includes(firstWord) ? firstWord : "pulse";
  const namespaceArg = args.find((arg) => arg.startsWith("--namespace="));
  const namespace = namespaceArg ? namespaceArg.split("=").slice(1).join("=") : projectUmaNamespace();
  if (subcommand === "status") {
    const summary = rosenPairsSummary(namespace);
    if (json) {
      console.log(JSON.stringify(summary));
      return summary;
    }
    console.log("Neuron Mercury Rosen pairs");
    console.log(`namespace: ${summary.namespace}`);
    console.log(`pairs: ${summary.pairs}`);
    console.log(`latest: ${summary.latest_pair_id || "-"} mode=${summary.latest_mode || "-"}`);
    return summary;
  }
  const task = args.filter((arg) => !arg.startsWith("--") && (subcommand === "pulse" || subcommand === "init" ? arg !== firstWord || !["pulse", "init"].includes(firstWord) : true)).join(" ").trim()
    || "build a state field pair for project acceleration";
  const pulse = rosenPairPulse(task, { namespace });
  if (json) {
    console.log(JSON.stringify(pulse));
    return pulse;
  }
  console.log("Neuron Mercury Rosen pair pulse");
  console.log(`pair_id: ${pulse.pair_id}`);
  console.log(`mode: ${pulse.mode}`);
  console.log(`changed: ${pulse.changed ? "yes" : "no"}`);
  console.log(`confidence: ${pulse.confidence}`);
  console.log(`route_selected: ${pulse.route_selected}`);
  console.log(`elapsed_ms: ${pulse.elapsed_ms}`);
  return pulse;
}

function readMemoryGraphRows(limit = 5000) {
  const path = memoryGraphPath();
  if (!existsSync(path)) return [];
  const lines = readTailText(path, 2 * 1024 * 1024).split(/\r?\n/).filter(Boolean);
  return lines.slice(-limit).flatMap((line) => {
    try {
      return [JSON.parse(line)];
    } catch {
      return [];
    }
  });
}

function buildTaskMemorySummary(options = {}) {
  const rows = readMemoryGraphRows(options.limit || 5000);
  const byType = {};
  const successPaths = [];
  const riskHotspots = {};
  const toolRoutes = {};
  for (const row of rows) {
    byType[row.type || "unknown"] = (byType[row.type || "unknown"] || 0) + 1;
    if (row.type === "monster_doctor") {
      successPaths.push({
        at: row.at,
        namespace: row.namespace,
        path: row.path,
        task: row.task,
        diagnosis_ms: row.diagnosis_ms,
        cost_findings: row.cost_findings,
        hot_files: row.hot_files,
        failure_risks: row.failure_risks || [],
        next_route_hint: row.next_route_hint || null
      });
      toolRoutes.monster_doctor = (toolRoutes.monster_doctor || 0) + 1;
    }
    if (row.type === "first_gen_section_dispatch") {
      toolRoutes.first_gen_section_dispatch = (toolRoutes.first_gen_section_dispatch || 0) + 1;
      successPaths.push({
        at: row.at,
        namespace: row.namespace,
        path: row.path || "first-gen-latest",
        task: row.task || "first-generation section dispatch",
        diagnosis_ms: row.elapsed_ms,
        cost_findings: 0,
        hot_files: row.seeded || 0,
        section_results: row.section_results || [],
        next_route_hint: "first_gen_section_replay"
      });
    }
    if (row.type === "cost_scan" || row.type === "spend_guard") {
      toolRoutes[row.type] = (toolRoutes[row.type] || 0) + 1;
      for (const item of row.top_files || []) {
        riskHotspots[item.file] = (riskHotspots[item.file] || 0) + 1;
      }
    }
    if (row.type === "code_cortex") {
      toolRoutes.code_cortex = (toolRoutes.code_cortex || 0) + 1;
      for (const item of row.hot_files || []) {
        riskHotspots[item.file] = (riskHotspots[item.file] || 0) + 1;
      }
    }
  }
  const rankedHotspots = Object.entries(riskHotspots)
    .map(([file, hits]) => ({ file, hits }))
    .sort((a, b) => b.hits - a.hits || a.file.localeCompare(b.file))
    .slice(0, options.hotspotLimit || 20);
  return {
    schema: "mercury-task-memory-summary-v1",
    created_at: nowIso(),
    cwd: process.cwd(),
    namespace: projectUmaNamespace(),
    events: rows.length,
    by_type: byType,
    tool_routes: toolRoutes,
    success_paths: successPaths.slice(-20).reverse(),
    risk_hotspots: rankedHotspots,
    routing_lessons: [
      "Use spend-guard before paid-provider or long-form generation work.",
      "Use code-cortex before broad repo diagnosis so symbol/page routing can avoid full scans.",
      "Use uma-coherence before trusting old memory after source edits.",
      "Use monster-doctor for mixed provider-spend + hot-path investigations."
    ]
  };
}

function cachedTaskMemorySummary(options = {}) {
  const ttlMs = Math.max(0, Number(options.ttlMs ?? 3000));
  const key = stableHash(["task-memory-summary", process.cwd(), options.limit || 5000, options.hotspotLimit || 20]);
  const now = Date.now();
  const cached = TASK_MEMORY_SUMMARY_CACHE.get(key);
  if (!options.refresh && cached && now - cached.at <= ttlMs) {
    return {
      ...cached.summary,
      cache: {
        mode: "task_memory_summary_cache_hit",
        key,
        age_ms: now - cached.at,
        ttl_ms: ttlMs
      }
    };
  }
  const summary = buildTaskMemorySummary(options);
  TASK_MEMORY_SUMMARY_CACHE.set(key, { at: now, summary });
  if (TASK_MEMORY_SUMMARY_CACHE.size > TASK_MEMORY_SUMMARY_CACHE_LIMIT) {
    TASK_MEMORY_SUMMARY_CACHE.delete(TASK_MEMORY_SUMMARY_CACHE.keys().next().value);
  }
  return {
    ...summary,
    cache: {
      mode: "task_memory_summary_cache_miss",
      key,
      age_ms: 0,
      ttl_ms: ttlMs
    }
  };
}

function resourceGuardSnapshot(context, circuit) {
  const memoryFreeRatio = totalmem() ? freemem() / totalmem() : 1;
  const targetFileFastPath = Boolean(context.targetFiles?.length);
  const broad = !targetFileFastPath;
  const controlMap = context.neuronControlMap || null;
  const controlEngine = Boolean(controlMap);
  const targetMax = controlEngine ? Math.min(32, Math.max(12, controlMap.selected_for_parallel_lanes || 0)) : 18;
  const broadMax = controlEngine ? Math.min(28, Math.max(12, controlMap.selected_for_parallel_lanes || 0)) : 8;
  const maxNeurons = memoryFreeRatio < 0.18
    ? (controlEngine ? (targetFileFastPath ? Math.min(targetMax, 16) : Math.min(broadMax, 12)) : (targetFileFastPath ? 10 : 4))
    : targetFileFastPath ? targetMax : broadMax;
  return {
    schema: "resource-guard-v1",
    memory_free_ratio: Number(memoryFreeRatio.toFixed(3)),
    target_file_fast_path: targetFileFastPath,
    broad_scan: broad,
    input_circuit_size: circuit.length,
    max_neurons: maxNeurons,
    control_engine: controlEngine,
    selected_parallel_lanes: controlMap?.selected_for_parallel_lanes || 0,
    policy: memoryFreeRatio < 0.18 ? "pressure_sparse" : "normal_sparse",
    model_hot_path: "forbidden"
  };
}

function applyResourceGuard(executableCircuit, context, taskText) {
  const guard = resourceGuardSnapshot(context, executableCircuit);
  const mustKeep = new Set(["memory.uma_rag_preload", "compression.evidence_packet", "safety.destructive_action", "evidence.rank", "critic.risk_surface"]);
  let guarded = executableCircuit;
  if (executableCircuit.length > guard.max_neurons) {
    const kept = executableCircuit.filter((neuron) => mustKeep.has(neuron.id));
    const keptIds = new Set(kept.map((neuron) => neuron.id));
    const slots = Math.max(0, guard.max_neurons - kept.length);
    const fill = executableCircuit
      .filter((neuron) => !keptIds.has(neuron.id) && (guard.control_engine || neuron.id.startsWith("risk.") || neuron.id.startsWith("verify.")))
      .slice(0, slots);
    guarded = [...kept, ...fill];
  }
  guard.output_circuit_size = guarded.length;
  guard.task_hash = stableHash([context.cwd, taskText]);
  const path = join(RESOURCE_GUARD_DIR, `guard_${stableHash([guard.task_hash, Date.now(), executableCircuit.map((n) => n.id)])}.json`);
  atomicWriteJson(path, guard);
  context.resourceGuard = { ...guard, path };
  return guarded;
}

function enqueueTraceWrite(path, trace) {
  TRACE_WRITE_BUFFER.push({ path, trace });
  if (TRACE_WRITE_BUFFER.length >= 64) flushTraceWrites();
  else if (!TRACE_WRITE_TIMER) {
    TRACE_WRITE_TIMER = setTimeout(flushTraceWrites, 1000);
    TRACE_WRITE_TIMER.unref?.();
  }
}

function flushTraceWrites() {
  if (!TRACE_WRITE_BUFFER.length) {
    TRACE_WRITE_TIMER = null;
    return;
  }
  const writes = TRACE_WRITE_BUFFER;
  TRACE_WRITE_BUFFER = [];
  TRACE_WRITE_TIMER = null;
  for (const item of writes) {
    atomicWriteJson(item.path, item.trace);
  }
}

function executePlan(taskText, options = {}) {
  const started = Date.now();
  const timings = {};

  const contextStarted = Date.now();
  const context = createRunContext(taskText);
  context.profile = Boolean(options.profile);
  timings.context_ms = Date.now() - contextStarted;
  const umaNamespace = options.umaNamespace || projectUmaNamespace();
  context.umaNamespace = umaNamespace;

  const loadStarted = Date.now();
  const neurons = loadNeurons();
  timings.load_neurons_ms = Date.now() - loadStarted;

  const classifyStarted = Date.now();
  const precompiled = options.usePrecompiled === false ? null : precompiledCircuitForTask(taskText, neurons, umaNamespace);
  const classifiedCircuit = precompiled?.circuit || classifyTask(taskText, neurons);
  if (!classifiedCircuit.some((c) => c.id === "synthesis.patch_plan")) {
    classifiedCircuit.push(...neurons.filter((n) => n.id === "synthesis.patch_plan"));
  }
  const circuit = scheduleCircuit(classifiedCircuit);
  timings.classify_ms = Date.now() - classifyStarted;
  timings.precompiled_circuit_hit = Boolean(precompiled);
  if (precompiled) timings.precompiled_circuit_score = precompiled.score;

  const cacheStarted = Date.now();
  const cacheKey = planCacheKey(taskText, context, circuit);
  const cached = options.usePlanCache === false ? null : readJsonCache("plan_result", cacheKey);
  timings.plan_cache_ms = Date.now() - cacheStarted;
  if (cached?.patchPlan && Array.isArray(cached.artifacts)) {
    const traceStarted = Date.now();
    const umaArtifact = buildUmaArtifact(context);
    const artifacts = [umaArtifact, ...cached.artifacts.map((artifact) => ({ ...artifact, elapsed_ms: 0 }))];
    const planArtifact = buildPlanArtifact(cached.patchPlan);
    const cacheArtifact = {
      neuron_id: "cache.plan_result",
      kernel: "cache",
      signal: "plan_result_cache_hit",
      evidence: [`Reused ${artifacts.length} cached artifacts and ${cached.patchPlan.findings.length} findings.`],
      confidence: 0.95,
      elapsed_ms: 0,
      details: {
        artifact_count: artifacts.length,
        finding_count: cached.patchPlan.findings.length,
        target_files: cached.patchPlan.target_files
      }
    };
    const traceOut = options.traceCacheHit === true
      ? writeTrace(taskText, circuit, [umaArtifact, cacheArtifact, planArtifact], cached.patchPlan)
      : {
          taskId: `cache_${stableHash([context.cwd, taskText, "plan_result"])}`,
          path: null,
          trace: {
            cache_hit: true,
            task: taskText,
            cwd: context.cwd,
            circuit: circuit.map((n) => ({ id: n.id, cluster: neuronCluster(n.id), scheduler_score: n.scheduler_score }))
          }
        };
    const { taskId, path, trace } = traceOut;
    timings.trace_ms = Date.now() - traceStarted;
    const elapsedMs = Date.now() - started;
    timings.uma_ms = 0;
    timings.uma_timeout = false;
    timings.uma_skipped_cache_hit = true;
    timings.neurons_ms = 0;
    timings.patch_plan_ms = 0;
    timings.total_ms = elapsedMs;
    timings.cache_hit = true;
    return {
      taskId,
      tracePath: path,
      trace,
      circuit,
      artifacts,
      patchPlan: cached.patchPlan,
      elapsedMs,
      timings
    };
  }

  const rosenStarted = Date.now();
  context.rosenRoute = options.rosenRoute === false ? null : rosenRoute(taskText, {
    namespace: umaNamespace,
    limit: options.rosenLimit || 8,
    budgetMs: options.rosenBudgetMs ?? 8,
    umaBudgetMs: Math.min(4, options.umaBudgetMs ?? 8),
    persist: options.rosenPersist ?? 4,
    memoryLimit: options.rosenMemoryLimit ?? 800,
    bridgeLimit: options.rosenBridgeLimit ?? 1024,
    memoryBridges: options.rosenMemoryBridges ?? 6,
    maxQueries: options.rosenMaxQueries ?? 6
  });
  timings.rosen_ms = Date.now() - rosenStarted;
  timings.rosen_selected = context.rosenRoute?.selected_count || 0;

  const pairStarted = Date.now();
  context.rosenPair = options.rosenPair === false || options.rosenRoute === false ? null : rosenPairPulse(taskText, {
    namespace: umaNamespace,
    route: context.rosenRoute,
    budgetMs: options.rosenPairBudgetMs ?? 4,
    persist: 0
  });
  timings.rosen_pair_ms = Date.now() - pairStarted;
  timings.rosen_pair_mode = context.rosenPair?.mode || null;

  const umaStarted = Date.now();
  const uma = umaSearch(taskText, { namespace: umaNamespace, limit: 6, threshold: 0.01, budgetMs: options.umaBudgetMs ?? 8 });
  context.umaHits = uma.results;
  context.umaElapsedMs = uma.elapsed_ms;
  context.umaTimedOut = Boolean(uma.timed_out);
  context.umaRoute = {
    target_file_first: Boolean(uma.target_file_first),
    symbol_first: Boolean(uma.symbol_first),
    candidate_pages: uma.candidate_pages || 0
  };
  timings.uma_ms = Date.now() - umaStarted;
  timings.uma_timeout = Boolean(uma.timed_out);

  const umaArtifact = buildUmaArtifact(context);
  const rosenArtifact = buildRosenBridgeArtifact(context);
  const neuronsStarted = Date.now();
  context.neuronControlMap = buildNeuronControlMap(circuit, context, taskText);
  const controlArtifact = buildNeuronControlArtifact(context.neuronControlMap);
  const executableCircuit = applyResourceGuard(executableCircuitForPlan(circuit, context, taskText), context, taskText);
  const dispatched = dispatchNeurons(executableCircuit, taskText, context);
  const dispatchArtifact = buildNeuronDispatchArtifact(dispatched.dispatchPlan);
  const artifacts = [rosenArtifact, umaArtifact, controlArtifact, dispatchArtifact, ...dispatched.artifacts];
  timings.neurons_ms = Date.now() - neuronsStarted;
  timings.control_selected_neurons = context.neuronControlMap.selected_for_parallel_lanes;
  timings.dispatch_waves = dispatched.dispatchPlan.wave_count;
  timings.dispatch_parallel_lanes = dispatched.dispatchPlan.max_parallel_lanes;
  timings.dispatch_parallel_neurons = dispatched.dispatchPlan.max_parallel_neurons;

  const patchPlanStarted = Date.now();
  const patchPlan = buildPatchPlan(taskText, artifacts, context);
  timings.patch_plan_ms = Date.now() - patchPlanStarted;

  if (options.usePlanCache !== false) {
    writeJsonCache("plan_result", cacheKey, {
      created_at: nowIso(),
      patchPlan,
      artifacts
    });
  }

  const planArtifact = buildPlanArtifact(patchPlan);
  if (options.workflowCache !== false) {
    const workflow = writeWorkflowCache(taskText, context, circuit, [...artifacts, planArtifact], patchPlan, timings);
    if (options.memoryGraph !== false) recordTaskMemoryGraph(taskText, context, circuit, patchPlan, workflow.path);
  }
  const traceStarted = Date.now();
  const { taskId, path, trace } = writeTrace(taskText, circuit, [...artifacts, planArtifact], patchPlan);
  timings.trace_ms = Date.now() - traceStarted;
  const elapsedMs = Date.now() - started;
  timings.total_ms = elapsedMs;
  if (options.scoreLedger !== false) writeScoreLedger(taskText, circuit, artifacts, patchPlan, timings, context);
  return { taskId, tracePath: path, trace, circuit, artifacts, patchPlan, elapsedMs, timings };
}

function evidenceLabel(item) {
  const loc = item.path && item.line ? `${item.path}:${item.line}` : "context";
  const symbol = item.symbol ? ` [${item.symbol}]` : "";
  return `${loc}${symbol}: ${item.text}`;
}

function proposalForFinding(finding) {
  const evidence = finding.evidence.filter((item) => item.rank === "high").slice(0, 4);
  const primary = evidence[0] || finding.evidence[0] || {};
  const targetFile = primary.path || null;
  const symbol = primary.symbol || null;
  const base = {
    id: finding.neuron_id.replace("risk.", "proposal."),
    risk: finding.neuron_id,
    title: finding.title,
    target_file: targetFile,
    symbol,
    evidence: evidence.map(evidenceLabel),
    confidence: finding.confidence,
    apply_mode: "proposal_only",
    safety: "Do not edit files until an owner approves the proposal."
  };

  if (finding.neuron_id === "risk.sync_exec") {
    return {
      ...base,
      edit_type: "refactor",
      proposed_change: [
        "Move blocking sync work behind a named helper so hot paths can call a bounded async/queued version later.",
        "For python calls, prefer the existing DB queue pattern or introduce a small async wrapper with timeout and fallback.",
        "Emit a structured timeout artifact when the helper exceeds budget."
      ],
      rationale: "High-ranked evidence shows synchronous primitives on target code paths; these can pause the event loop or delay first useful response.",
      verification: [
        targetFile && targetFile.endsWith(".js") ? `node -c ${targetFile}` : "run syntax check",
        "rerun Neuron Mercury plan on the same task",
        "compare high-ranked sync_exec evidence before/after"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.sqlite_timeout") {
    return {
      ...base,
      edit_type: "guard",
      proposed_change: [
        "Create one DB access helper with explicit timeout/busy-timeout behavior.",
        "For embedded Python sqlite3 calls, set a timeout and record failures as structured artifacts.",
        "Avoid direct ad hoc sqlite snippets in hot paths unless they are read-only and bounded."
      ],
      rationale: "SQLite access is present near runtime paths; centralizing access makes lock behavior measurable and safer.",
      verification: [
        targetFile && targetFile.endsWith(".js") ? `node -c ${targetFile}` : "run syntax check",
        "run a smoke path that performs the affected DB read/write",
        "confirm timeout fallback is visible in logs or blackboard"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.aggregate_scan") {
    return {
      ...base,
      edit_type: "measure",
      proposed_change: [
        "Mark aggregate SQL as production-size sensitive before refactor.",
        "Add query timing and row-count telemetry around the aggregate path.",
        "If timing is high, replace repeated full aggregates with indexed summary tables or cached daily snapshots."
      ],
      rationale: "COUNT/AVG/GROUP BY queries can stay invisible on small data and become the dominant latency source as SQLite grows.",
      verification: [
        targetFile && targetFile.endsWith(".py") ? `python3 -m py_compile ${targetFile}` : "run syntax check",
        "run EXPLAIN QUERY PLAN or a timing smoke test",
        "compare elapsed time before/after adding summary or index strategy"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.network_timeout") {
    return {
      ...base,
      edit_type: "guard",
      proposed_change: [
        "Wrap external request/fetch calls in a shared bounded network helper.",
        "Add timeout, retry budget, and degraded fallback return shape.",
        "Record slow API path timing as structured evidence."
      ],
      rationale: "Network calls with unclear timeout or fallback behavior can dominate perceived latency.",
      verification: [
        targetFile && targetFile.endsWith(".js") ? `node -c ${targetFile}` : "run syntax check",
        "simulate timeout/failure",
        "confirm caller returns a degraded but bounded response"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.retry_loop") {
    return {
      ...base,
      edit_type: "instrument",
      proposed_change: [
        "Add queue-depth and retry-count telemetry before changing behavior.",
        "Set an explicit retry budget and minimum delay/jitter for recurring work.",
        "Expose a single observable signal when the loop gives up."
      ],
      rationale: "Recurring queues and timers need bounds before optimization; otherwise speed fixes can amplify pressure.",
      verification: [
        targetFile && targetFile.endsWith(".js") ? `node -c ${targetFile}` : "run syntax check",
        "force a failing dependency",
        "confirm retries stop and telemetry records the failure mode"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.secret_exposure") {
    return {
      ...base,
      edit_type: "safety",
      proposed_change: [
        "Keep redaction before blackboard writeback and console output.",
        "Move hardcoded secret-like constants to environment variables when touching nearby code.",
        "Add a post-run scan over generated artifacts for known secret fragments."
      ],
      rationale: "Evidence gathering can accidentally pull adjacent secrets into traces unless redaction is enforced early.",
      verification: [
        "grep generated var/ traces for known key fragments",
        "confirm output contains [REDACTED] for secret-like constants",
        "avoid sending secret-adjacent snippets to LLM synthesis"
      ]
    };
  }

  if (finding.neuron_id === "risk.hot_path") {
    return {
      ...base,
      edit_type: "measure",
      proposed_change: [
        "Mark the symbol as possible hot path and measure elapsed time before refactor.",
        "Add one lightweight timing artifact around queue/request/worker boundaries.",
        "Only optimize after confirming the path is frequently executed or user-visible."
      ],
      rationale: "Hot-path claims must be measured; otherwise patching can chase rare code paths.",
      verification: [
        targetFile && targetFile.endsWith(".js") ? `node -c ${targetFile}` : "run syntax check",
        "trigger the suspected hot path once",
        "confirm timing artifact appears"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.atomic_write") {
    return {
      ...base,
      edit_type: "durability",
      proposed_change: [
        "Introduce a small atomic write helper for JSON, JSONL, reports, and manifest files.",
        "Write to a same-directory temporary file, then rename over the final path.",
        "Use the helper for every latest/manifest/report output that feeds another pipeline step."
      ],
      rationale: "Direct overwrites can leave partial latest or manifest files if a timer, deploy, or process crashes mid-write.",
      verification: [
        targetFile && targetFile.endsWith(".py") ? `python3 -m py_compile ${targetFile}` : "run syntax check",
        "write to a temporary output directory",
        "simulate interruption and confirm downstream readers do not consume partial files"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.silent_data_loss") {
    return {
      ...base,
      edit_type: "guard",
      proposed_change: [
        "Turn silent JSON/JSONL parse skips into structured errors or explicit warning artifacts.",
        "Record input rows, rejected rows, and output rows for every pipeline stage.",
        "Add minimum row-count or monotonicity checks before marking eval/promotion as passed."
      ],
      rationale: "Silent parse skips convert upstream corruption into lower-quality data that still looks successful.",
      verification: [
        targetFile && targetFile.endsWith(".py") ? `python3 -m py_compile ${targetFile}` : "run syntax check",
        "feed malformed JSONL and confirm the bad line is reported",
        "confirm row-count drops fail the pipeline gate"
      ].filter(Boolean)
    };
  }

  if (finding.neuron_id === "risk.packaging_entrypoint") {
    return {
      ...base,
      edit_type: "smoke",
      proposed_change: [
        "Extract declared package scripts and import each referenced module:function.",
        "Remove stale entrypoints or add the missing module before release.",
        "Add a fast install/CLI smoke command to the benchmark suite."
      ],
      rationale: "Broken entrypoints slow every operator because install succeeds but commands fail at first use.",
      verification: [
        "run import checks for each declared entrypoint",
        "run package CLI help smoke tests",
        "rerun Neuron Mercury plan on the package metadata"
      ]
    };
  }

  return {
    ...base,
    edit_type: "inspect",
    proposed_change: [finding.plan],
    rationale: "Generic proposal generated from risk finding.",
    verification: finding.verification
  };
}

function buildProposal(taskText, planResult) {
  const findings = planResult.patchPlan.findings || [];
  const proposals = findings
    .filter((finding) => finding.evidence.some((item) => item.rank === "high"))
    .map(proposalForFinding);
  const verification = [
    ...new Set(proposals.flatMap((proposal) => proposal.verification || []))
  ];
  return {
    task: taskText,
    created_at: nowIso(),
    trace_path: planResult.tracePath,
    target_files: planResult.patchPlan.target_files,
    summary: proposals.length
      ? `Generated ${proposals.length} proposal-only edits from ranked evidence.`
      : "No proposal generated because no high-ranked evidence was available.",
    proposals,
    verification,
    approval_gate: "Proposal-only. No file changes were made."
  };
}

function writeProposal(proposal) {
  ensureDirs();
  const path = join(PROPOSAL_DIR, `proposal_${Date.now()}.json`);
  atomicWriteJson(path, proposal, { pretty: true });
  return path;
}

function printProposal(proposal) {
  console.log("Neuron Mercury patch proposal");
  console.log(`task: ${proposal.task}`);
  console.log(`targets: ${proposal.target_files.length ? proposal.target_files.join(", ") : "(none detected)"}`);
  console.log(`summary: ${proposal.summary}`);
  console.log("");
  for (const item of proposal.proposals) {
    console.log(`## ${item.title}`);
    console.log(`type: ${item.edit_type}`);
    console.log(`target: ${item.target_file || "(unknown)"}${item.symbol ? ` [${item.symbol}]` : ""}`);
    console.log("evidence:");
    for (const evidence of item.evidence.slice(0, 3)) console.log(`- ${evidence}`);
    console.log("proposal:");
    for (const change of item.proposed_change) console.log(`- ${change}`);
    console.log("verify:");
    for (const command of item.verification) console.log(`- ${command}`);
    console.log("");
  }
  console.log("Verification rollup:");
  for (const command of proposal.verification) console.log(`- ${command}`);
  console.log("");
  console.log(`Approval gate: ${proposal.approval_gate}`);
}

function latestJsonPath(dir) {
  ensureDirs();
  const files = readdirSync(dir)
    .filter((name) => name.endsWith(".json"))
    .sort();
  return files.length ? join(dir, files[files.length - 1]) : null;
}

function resolveArtifactPath(input, defaultDir) {
  if (!input || input === "latest") {
    const latest = latestJsonPath(defaultDir);
    if (!latest) throw new Error(`No JSON artifacts found in ${defaultDir}`);
    return latest;
  }
  return resolve(process.cwd(), input);
}

function loadJsonFile(path) {
  if (!existsSync(path)) throw new Error(`File not found: ${path}`);
  return JSON.parse(readFileSync(path, "utf8"));
}

function buildPatchDraft(proposal, sourcePath) {
  const lines = [];
  lines.push("# Neuron Mercury Patch Draft");
  lines.push("");
  lines.push(`Created: ${nowIso()}`);
  lines.push(`Source proposal: ${sourcePath}`);
  lines.push(`Task: ${proposal.task}`);
  lines.push(`Targets: ${proposal.target_files?.join(", ") || "(none)"}`);
  lines.push("");
  lines.push("> Proposal-only draft. This file does not modify source code.");
  lines.push("");
  lines.push("## Approval Gate");
  lines.push("");
  lines.push("- Status: pending");
  lines.push("- Required before applying: owner approval, syntax check, and smoke verification.");
  lines.push("- Forbidden without explicit approval: destructive commands, production changes, external sends, payments, or secret exposure.");
  lines.push("");

  for (const item of proposal.proposals || []) {
    lines.push(`## ${item.title}`);
    lines.push("");
    lines.push(`- Type: ${item.edit_type}`);
    lines.push(`- Target: ${item.target_file || "(unknown)"}`);
    lines.push(`- Symbol: ${item.symbol || "(unknown)"}`);
    lines.push(`- Confidence: ${item.confidence}`);
    lines.push("");
    lines.push("Evidence:");
    for (const evidence of item.evidence || []) lines.push(`- ${evidence}`);
    lines.push("");
    lines.push("Manual Patch Sketch:");
    for (const change of item.proposed_change || []) lines.push(`- ${change}`);
    lines.push("");
    lines.push("Rationale:");
    lines.push(item.rationale || "-");
    lines.push("");
    lines.push("Verification:");
    for (const command of item.verification || []) lines.push(`- ${command}`);
    lines.push("");
  }

  lines.push("## Verification Rollup");
  lines.push("");
  for (const command of proposal.verification || []) lines.push(`- ${command}`);
  lines.push("");
  lines.push("## Non-Goals");
  lines.push("");
  lines.push("- This draft is not a git patch.");
  lines.push("- This draft does not edit target files.");
  lines.push("- This draft should not be applied without a separate approval record.");
  lines.push("");
  return lines.join("\n");
}

function writePatchDraft(markdown) {
  ensureDirs();
  const path = join(PATCH_DRAFT_DIR, `draft_${Date.now()}.md`);
  writeFileSync(path, markdown, "utf8");
  return path;
}

function draft(input) {
  try {
    const proposalPath = resolveArtifactPath(input || "latest", PROPOSAL_DIR);
    const proposal = loadJsonFile(proposalPath);
    const draftPath = writePatchDraft(buildPatchDraft(proposal, proposalPath));
    console.log("Neuron Mercury patch draft");
    console.log(`proposal: ${proposalPath}`);
    console.log(`draft: ${draftPath}`);
    console.log("status: pending approval");
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

function parseApprovalArgs(args) {
  const parsed = { input: args[0] || "latest", owner: "unknown", note: "" };
  for (let i = 1; i < args.length; i += 1) {
    if (args[i] === "--owner" && args[i + 1]) {
      parsed.owner = args[i + 1];
      i += 1;
    } else if (args[i] === "--note" && args[i + 1]) {
      parsed.note = args[i + 1];
      i += 1;
    }
  }
  return parsed;
}

function approve(args) {
  try {
    const parsed = parseApprovalArgs(args);
    const proposalPath = resolveArtifactPath(parsed.input, PROPOSAL_DIR);
    const proposal = loadJsonFile(proposalPath);
    const record = {
      created_at: nowIso(),
      owner: parsed.owner,
      note: parsed.note,
      status: "approved_for_manual_patch_draft_only",
      proposal_path: proposalPath,
      task: proposal.task,
      target_files: proposal.target_files || [],
      guardrails: [
        "This approval does not apply changes automatically.",
        "Run verification commands before and after any manual edit.",
        "Stop if a proposed edit touches secrets or production/external actions."
      ]
    };
    ensureDirs();
    const path = join(APPROVAL_DIR, `approval_${Date.now()}.json`);
    atomicWriteJson(path, record, { pretty: true });
    console.log("Neuron Mercury approval record");
    console.log(`proposal: ${proposalPath}`);
    console.log(`approval: ${path}`);
    console.log(`owner: ${record.owner}`);
    console.log(`status: ${record.status}`);
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

function parseProposalEvidence(text) {
  const match = String(text).match(/^(.+?):(\d+)(?:\s+\[[^\]]+\])?:\s*(.*)$/);
  if (!match) return { path: null, line: null, text: String(text) };
  return {
    path: match[1],
    line: Number(match[2]),
    text: match[3]
  };
}

function patchCommentPrefix(path) {
  if (/\.(py|sh)$/i.test(path || "")) return "#";
  if (/\.md$/i.test(path || "")) return "<!--";
  return "//";
}

function patchCommentLine(path, text) {
  const prefix = patchCommentPrefix(path);
  const clean = redactSecrets(String(text).replace(/\*\//g, "* /").replace(/-->/g, "-- >"));
  if (prefix === "<!--") return `<!-- ${clean} -->`;
  return `${prefix} ${clean}`;
}

function parsePatchsetArgs(args) {
  const parsed = { input: "latest", mode: "scaffold" };
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === "--mode" && args[i + 1]) {
      parsed.mode = args[i + 1];
      i += 1;
    } else if (!args[i].startsWith("--")) {
      parsed.input = args[i];
    }
  }
  return parsed;
}

function safeEnvReplacementLine(line) {
  const match = line.match(/^(\s*const\s+)([A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD|PASS)[A-Z0-9_]*)(\s*=\s*)(['"])(.*)\4(\s*;?\s*)$/);
  if (!match) return null;
  const [, prefix, name, assignment, , value, suffix] = match;
  if (value.includes("process.env")) return null;
  return `${prefix}${name}${assignment}process.env.${name} || ''${suffix}`;
}

function buildTemplatePatchset(proposal, sourcePath) {
  const lines = [];
  const seen = new Set();
  for (const item of proposal.proposals || []) {
    if (item.risk !== "risk.secret_exposure") continue;
    for (const evidenceText of item.evidence || []) {
      const evidence = parseProposalEvidence(evidenceText);
      if (!evidence.path || !evidence.line) continue;
      const key = `${evidence.path}:${evidence.line}`;
      if (seen.has(key)) continue;
      seen.add(key);

      const abs = resolve(process.cwd(), evidence.path);
      if (!existsSync(abs)) continue;
      const sourceLine = readFileSync(abs, "utf8").split(/\r?\n/)[evidence.line - 1];
      const replacement = safeEnvReplacementLine(sourceLine);
      if (!replacement) continue;

      const safeFile = evidence.path.replace(/^\/+/, "");
      lines.push(`diff --git a/${safeFile} b/${safeFile}`);
      lines.push(`--- a/${safeFile}`);
      lines.push(`+++ b/${safeFile}`);
      lines.push(`@@ -${evidence.line},1 +${evidence.line},1 @@`);
      lines.push(`-${redactSecrets(sourceLine)}`);
      lines.push(`+${replacement}`);
      lines.push("");
    }
  }

  if (lines.length === 0) {
    lines.push(`# No safe template patch was generated.`);
    lines.push(`# Source proposal: ${sourcePath}`);
    lines.push(`# Mode: template`);
  }
  return lines.join("\n");
}

function buildUnifiedPatchset(proposal, sourcePath, mode = "scaffold") {
  if (mode === "template") return buildTemplatePatchset(proposal, sourcePath);
  const lines = [];

  const byFile = new Map();
  for (const item of proposal.proposals || []) {
    const evidence = (item.evidence || []).map(parseProposalEvidence).filter((entry) => entry.path && entry.line);
    const primary = evidence[0];
    if (!primary) continue;
    if (!byFile.has(primary.path)) byFile.set(primary.path, []);
    byFile.get(primary.path).push({ proposal: item, evidence: primary });
  }

  for (const [file, items] of byFile.entries()) {
    const safeFile = file.replace(/^\/+/, "");
    lines.push(`diff --git a/${safeFile} b/${safeFile}`);
    lines.push(`--- a/${safeFile}`);
    lines.push(`+++ b/${safeFile}`);

    const sorted = items.sort((a, b) => a.evidence.line - b.evidence.line);
    for (const { proposal: item, evidence } of sorted) {
      const insertions = [
        patchCommentLine(file, `NEURON MERCURY PATCHSET DRAFT: ${item.title}`),
        patchCommentLine(file, `Source proposal: ${sourcePath}`),
        patchCommentLine(file, `Created: ${nowIso()}`),
        patchCommentLine(file, `Risk=${item.risk}; type=${item.edit_type}; approval required before applying.`),
        patchCommentLine(file, `Evidence: ${evidence.path}:${evidence.line}: ${evidence.text}`),
        ...item.proposed_change.slice(0, 3).map((change) => patchCommentLine(file, `Proposal: ${change}`)),
        ...item.verification.slice(0, 2).map((verify) => patchCommentLine(file, `Verify: ${verify}`))
      ];
      lines.push(`@@ -${evidence.line},0 +${evidence.line + 1},${insertions.length} @@`);
      for (const insertion of insertions) lines.push(`+${insertion}`);
    }
    lines.push("");
  }

  if (byFile.size === 0) {
    lines.push(`# No file-addressable proposal evidence was available.`);
  }

  return lines.join("\n");
}

function writePatchset(content) {
  ensureDirs();
  const path = join(PATCHSET_DIR, `patchset_${Date.now()}.patch`);
  writeFileSync(path, content + "\n", "utf8");
  return path;
}

function patchset(args) {
  try {
    const parsed = parsePatchsetArgs(args);
    const proposalPath = resolveArtifactPath(parsed.input || "latest", PROPOSAL_DIR);
    const proposal = loadJsonFile(proposalPath);
    const patchsetPath = writePatchset(buildUnifiedPatchset(proposal, proposalPath, parsed.mode));
    console.log("Neuron Mercury unified diff draft");
    console.log(`proposal: ${proposalPath}`);
    console.log(`mode: ${parsed.mode}`);
    console.log(`patchset: ${patchsetPath}`);
    console.log(parsed.mode === "template"
      ? "status: generated only; redacted templates require manual application"
      : "status: generated only; not applied");
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

function latestTracePath() {
  ensureDirs();
  const files = readdirSync(BLACKBOARD_DIR)
    .filter((name) => name.endsWith(".json"))
    .sort();
  return files.length ? join(BLACKBOARD_DIR, files[files.length - 1]) : null;
}

function run(taskText) {
  const context = createRunContext(taskText);
  const uma = umaSearch(taskText, { namespace: projectUmaNamespace(), limit: 6, threshold: 0.01 });
  context.umaHits = uma.results;
  context.umaElapsedMs = uma.elapsed_ms;
  context.umaRoute = {
    target_file_first: Boolean(uma.target_file_first),
    symbol_first: Boolean(uma.symbol_first),
    candidate_pages: uma.candidate_pages || 0
  };
  const neurons = loadNeurons();
  const circuit = scheduleCircuit(classifyTask(taskText, neurons));
  const artifacts = [buildUmaArtifact(context), ...circuit.map((neuron) => runNeuron(neuron, taskText, context))];
  const { path } = writeTrace(taskText, circuit, artifacts);

  console.log("Neuron Mercury trace");
  console.log(`task: ${taskText}`);
  console.log(`circuit: ${circuit.map((n) => n.id).join(", ")}`);
  console.log(`blackboard: ${path}`);
  console.log("");
  for (const artifact of artifacts) {
    console.log(`- ${artifact.neuron_id}: ${artifact.signal} (${artifact.elapsed_ms}ms, confidence ${artifact.confidence})`);
    for (const item of artifact.evidence.slice(0, 5)) {
      console.log(`  - ${item}`);
    }
  }
}

function printPlan(plan) {
  console.log("Neuron Mercury patch plan");
  console.log(`task: ${plan.task}`);
  console.log(`targets: ${plan.target_files.length ? plan.target_files.join(", ") : "(none detected)"}`);
  console.log(`summary: ${plan.summary}`);
  console.log("");

  for (const finding of plan.findings) {
    console.log(`## ${finding.title}`);
    console.log(`neuron: ${finding.neuron_id}`);
    console.log(`signal: ${finding.signal}`);
    console.log(`confidence: ${finding.confidence}`);
    console.log(`ranks: ${JSON.stringify(finding.evidence_rank_summary)}`);
    console.log("evidence:");
    for (const item of finding.evidence.slice(0, 5)) {
      const loc = item.path && item.line ? `${item.path}:${item.line}` : "context";
      const symbol = item.symbol ? ` [${item.symbol}]` : "";
      console.log(`- ${item.rank} ${loc}${symbol}: ${item.text}`);
    }
    console.log("patch:");
    console.log(`- ${finding.plan}`);
    console.log("verify:");
    for (const command of finding.verification) console.log(`- ${command}`);
    console.log("");
  }

  console.log("Patch order:");
  for (const step of plan.patch_order) {
    console.log(`${step.step}. ${step.focus}: ${step.action}`);
  }
  console.log("");
  console.log("Verification commands:");
  for (const command of plan.verification) console.log(`- ${command}`);
  console.log("");
  console.log(`Safety: ${plan.safety_gate}`);
}

function plan(taskText) {
  const result = executePlan(taskText);
  printPlan(result.patchPlan);
  console.log("");
  console.log(`blackboard: ${result.tracePath}`);
}

function propose(taskText) {
  const result = executePlan(taskText);
  const proposal = buildProposal(taskText, result);
  const proposalPath = writeProposal(proposal);
  printProposal(proposal);
  console.log("");
  console.log(`blackboard: ${result.tracePath}`);
  console.log(`proposal: ${proposalPath}`);
}

function doctor(taskText) {
  const timings = {};
  const started = Date.now();

  const planStarted = Date.now();
  const result = executePlan(taskText);
  timings.plan_ms = Date.now() - planStarted;

  const proposalStarted = Date.now();
  const proposal = buildProposal(taskText, result);
  const proposalPath = writeProposal(proposal);
  timings.proposal_ms = Date.now() - proposalStarted;

  const draftStarted = Date.now();
  const draftPath = writePatchDraft(buildPatchDraft(proposal, proposalPath));
  timings.draft_ms = Date.now() - draftStarted;

  const patchsetStarted = Date.now();
  const patchsetPath = writePatchset(buildUnifiedPatchset(proposal, proposalPath, "scaffold"));
  timings.patchset_ms = Date.now() - patchsetStarted;
  timings.total_ms = Date.now() - started;

  console.log("Neuron Mercury doctor");
  console.log(`task: ${taskText}`);
  console.log(`targets: ${result.patchPlan.target_files.join(", ") || "(none detected)"}`);
  console.log(`findings: ${result.patchPlan.findings.length}`);
  console.log(`high evidence: ${result.patchPlan.findings.reduce((sum, finding) => sum + (finding.evidence_rank_summary.high || 0), 0)}`);
  console.log(`timings: ${JSON.stringify(timings)}`);
  console.log(`blackboard: ${result.tracePath}`);
  console.log(`proposal: ${proposalPath}`);
  console.log(`draft: ${draftPath}`);
  console.log(`patchset: ${patchsetPath}`);
  console.log("status: generated artifacts only; no target files modified");
}

function printNeurons() {
  for (const neuron of loadNeurons()) {
    console.log(`${neuron.id}\t${neuron.type}\t${neuron.specialty}`);
  }
}

function parseScalePlanArgs(args) {
  const targetArg = args.find((arg) => arg.startsWith("--target="));
  const shardArg = args.find((arg) => arg.startsWith("--shard-size="));
  return {
    target: targetArg ? Math.max(1, Number(targetArg.split("=")[1]) || ONE_HUNDRED_MILLION_NEURONS) : ONE_HUNDRED_MILLION_NEURONS,
    shardSize: shardArg ? Math.max(64, Number(shardArg.split("=")[1]) || VIRTUAL_NEURON_SHARD_SIZE) : VIRTUAL_NEURON_SHARD_SIZE
  };
}

function groupNeuronCatalog(neurons) {
  return neurons.reduce((acc, neuron) => {
    acc[neuron.type] = (acc[neuron.type] || 0) + 1;
    return acc;
  }, {});
}

function buildScalePlan(args = []) {
  const parsed = parseScalePlanArgs(args);
  const neurons = loadNeurons();
  const catalogGroups = groupNeuronCatalog(neurons);
  const virtualShards = Math.ceil(parsed.target / parsed.shardSize);
  const physicalCatalogRatio = Number((parsed.target / neurons.length).toFixed(0));
  const hotPathPolicy = [
    "activate sparse circuits from the physical neuron catalog",
    "materialize virtual neurons only as scored shards, not one process per neuron",
    "keep explicit target-file plans on finding-producing risk neurons",
    "batch file scans once per target and fan out slices to many neuron families",
    "write every accepted speed lesson back into cache, trace, and benchmark history"
  ];
  const shardFamilies = [
    { id: "goal-shards", source: "decompose.*", purpose: "split a large user goal into measurable subgoals" },
    { id: "surface-shards", source: "explore.*", purpose: "map files, services, data artifacts, and boundaries" },
    { id: "risk-shards", source: "risk.* + analyze.*", purpose: "score failure modes and production bottlenecks" },
    { id: "patch-shards", source: "recompose.*", purpose: "merge evidence into minimal patch order and rollback shape" },
    { id: "verify-shards", source: "verify.*", purpose: "guard syntax, smoke, speed, and artifact integrity" },
    { id: "speed-shards", source: "accelerate.*", purpose: "choose cache, parallelism, pruning, and hardware placement" },
    { id: "memory-shards", source: "memory.*", purpose: "promote useful lessons into future routing weights" }
  ];
  return {
    target_neurons: parsed.target,
    physical_catalog_neurons: neurons.length,
    virtual_shard_size: parsed.shardSize,
    virtual_shard_count: virtualShards,
    catalog_to_target_ratio: `1:${physicalCatalogRatio}`,
    catalog_groups: catalogGroups,
    hardware_substrates: HARDWARE_SUBSTRATES,
    shard_families: shardFamilies,
    hot_path_policy: hotPathPolicy,
    current_guardrail: "speed budgets must pass before broad neuron expansion is considered valid"
  };
}

function printScalePlan(args = []) {
  const plan = buildScalePlan(args);
  console.log("Neuron Mercury scale plan");
  console.log(`target neurons: ${plan.target_neurons}`);
  console.log(`physical catalog neurons: ${plan.physical_catalog_neurons}`);
  console.log(`virtual shard size: ${plan.virtual_shard_size}`);
  console.log(`virtual shard count: ${plan.virtual_shard_count}`);
  console.log(`catalog to target ratio: ${plan.catalog_to_target_ratio}`);
  console.log(`catalog groups: ${JSON.stringify(plan.catalog_groups)}`);
  console.log("");
  console.log("Hardware substrates:");
  for (const item of plan.hardware_substrates) {
    console.log(`- ${item.id}: ${item.role} (${item.latency_class})`);
  }
  console.log("");
  console.log("Shard families:");
  for (const item of plan.shard_families) {
    console.log(`- ${item.id}: ${item.source} -> ${item.purpose}`);
  }
  console.log("");
  console.log("Hot-path policy:");
  for (const item of plan.hot_path_policy) console.log(`- ${item}`);
  console.log(`guardrail: ${plan.current_guardrail}`);
}

function shardForNeuron(neuron, shardSize = VIRTUAL_NEURON_SHARD_SIZE) {
  const family = NEURON_TYPE_SHARD_FAMILY[neuron.type] || "misc-shards";
  const substrate = NEURON_TYPE_SUBSTRATE[neuron.type] || "cpu.l1_hot_path";
  const hash = Number.parseInt(stableHash([family, neuron.type, neuron.id]).slice(0, 8), 16);
  const localIndex = hash % shardSize;
  return {
    family,
    substrate,
    shard_id: `${family}:${Math.floor(hash / shardSize)}`,
    local_index: localIndex
  };
}

function buildShardRegistry(args = []) {
  const parsed = parseScalePlanArgs(args);
  const neurons = loadNeurons();
  const plan = buildScalePlan(args);
  const physical = neurons.map((neuron) => ({
    neuron_id: neuron.id,
    type: neuron.type,
    specialty: neuron.specialty,
    ...shardForNeuron(neuron, parsed.shardSize)
  }));
  const families = physical.reduce((acc, item) => {
    if (!acc[item.family]) {
      acc[item.family] = {
        family: item.family,
        physical_neurons: 0,
        virtual_shards: 0,
        substrates: {}
      };
    }
    acc[item.family].physical_neurons += 1;
    acc[item.family].substrates[item.substrate] = (acc[item.family].substrates[item.substrate] || 0) + 1;
    return acc;
  }, {});
  const familyNames = Object.keys(families);
  const baseVirtualShards = Math.floor(plan.virtual_shard_count / Math.max(1, familyNames.length));
  let remainder = plan.virtual_shard_count - baseVirtualShards * familyNames.length;
  for (const name of familyNames) {
    families[name].virtual_shards = baseVirtualShards + (remainder > 0 ? 1 : 0);
    remainder -= 1;
  }
  return {
    created_at: nowIso(),
    target_neurons: plan.target_neurons,
    virtual_shard_size: plan.virtual_shard_size,
    virtual_shard_count: plan.virtual_shard_count,
    hardware_substrates: plan.hardware_substrates,
    families: Object.values(families),
    physical
  };
}

function virtualNeuronField(args = []) {
  const started = Date.now();
  const targetArg = args.find((arg) => arg.startsWith("--target="));
  const lanesArg = args.find((arg) => arg.startsWith("--lanes="));
  const budgetArg = args.find((arg) => arg.startsWith("--budget="));
  const target = targetArg ? Math.max(MIN_PHYSICAL_NEURONS, Number(targetArg.split("=")[1]) || 10000) : 10000;
  const lanesWanted = lanesArg ? Math.max(4, Math.min(64, Number(lanesArg.split("=")[1]) || 16)) : 16;
  const perLaneBudget = budgetArg ? Math.max(1, Math.min(64, Number(budgetArg.split("=")[1]) || 8)) : 8;
  const registry = buildShardRegistry([`--target=${target}`, "--shard-size=256"]);
  const neurons = loadNeurons();
  const laneSeeds = [
    "first_packet_latency", "model_cortex", "uma_rag", "rosen_pair",
    "gpu_pressure", "memory_hot_pages", "resident_reflex", "background_completion",
    "judge_truthfulness", "cache_coherence", "spend_guard", "monster_doctor",
    "qwen", "deepseek", "windows_3060", "anti_overactivation"
  ].slice(0, lanesWanted);
  const families = registry.families || [];
  const baseShardsPerLane = Math.floor((registry.virtual_shard_count || 1) / Math.max(1, laneSeeds.length));
  let shardRemainder = (registry.virtual_shard_count || 1) - baseShardsPerLane * Math.max(1, laneSeeds.length);
  const lanes = laneSeeds.map((lane, laneIndex) => {
    const family = families[laneIndex % Math.max(1, families.length)] || {};
    const physicalCandidates = neurons
      .map((neuron, index) => ({ neuron, index, hash: stableHash([lane, neuron.id]) }))
      .sort((a, b) => a.hash.localeCompare(b.hash))
      .slice(0, Math.min(perLaneBudget, 8))
      .map((item) => item.neuron.id);
    const virtualShards = Math.max(1, baseShardsPerLane + (shardRemainder > 0 ? 1 : 0));
    shardRemainder -= 1;
    return {
      lane,
      family: family.family || "mixed-shards",
      virtual_shards: virtualShards,
      virtual_neurons: virtualShards * registry.virtual_shard_size,
      physical_control_neurons: physicalCandidates,
      activation_budget: physicalCandidates.length,
      hot_path_policy: "control shard state, do not materialize every virtual neuron"
    };
  });
  const controlledVirtual = lanes.reduce((sum, lane) => sum + lane.virtual_neurons, 0);
  const uniquePhysical = new Set(lanes.flatMap((lane) => lane.physical_control_neurons));
  return {
    schema: "mercury-virtual-neuron-field-v1",
    created_at: nowIso(),
    target_neurons: target,
    represented_virtual_neurons: Math.min(target, controlledVirtual),
    virtual_shard_size: registry.virtual_shard_size,
    virtual_shard_count: registry.virtual_shard_count,
    physical_catalog_neurons: neurons.length,
    task_lanes: lanes.length,
    unique_physical_control_neurons: uniquePhysical.size,
    max_activation_budget_per_lane: Math.max(...lanes.map((lane) => lane.activation_budget)),
    lanes,
    guardrail: "virtual neurons are addressable state shards; hot path wakes bounded physical controllers only",
    elapsed_ms: Date.now() - started
  };
}

function virtualFieldCommand(args = []) {
  const json = args.includes("--json");
  const out = virtualNeuronField(args);
  const proof = {
    ...out,
    pass: out.represented_virtual_neurons >= Math.min(out.target_neurons || 10000, 10000)
      && out.task_lanes >= 16
      && out.unique_physical_control_neurons >= 64
      && out.max_activation_budget_per_lane <= 8
      && out.elapsed_ms <= 500
  };
  atomicWriteJson(join(BENCH_DIR, "virtual-field.json"), proof, { pretty: true });
  atomicWriteJson(join(VAR_DIR, "virtual-field.json"), proof, { pretty: true });
  if (json) {
    console.log(JSON.stringify(proof));
    return proof;
  }
  console.log("Neuron Mercury virtual neuron field");
  console.log(`target: ${proof.target_neurons}`);
  console.log(`represented: ${proof.represented_virtual_neurons}`);
  console.log(`lanes: ${proof.task_lanes}`);
  console.log(`unique_physical_control_neurons: ${proof.unique_physical_control_neurons}`);
  console.log(`max_activation_budget_per_lane: ${proof.max_activation_budget_per_lane}`);
  console.log(`elapsed_ms: ${proof.elapsed_ms}`);
  return proof;
}

function benchVirtualNeuronField(args = []) {
  const targetArg = args.find((arg) => arg.startsWith("--target="));
  const target = targetArg ? Math.max(10000, Number(targetArg.split("=")[1]) || 10000) : 10000;
  const out = virtualNeuronField([`--target=${target}`, "--lanes=16", "--budget=8"]);
  const pass = out.target_neurons >= target
    && out.represented_virtual_neurons >= target
    && out.task_lanes >= 16
    && out.unique_physical_control_neurons >= 64
    && out.max_activation_budget_per_lane <= 8
    && out.elapsed_ms <= 500;
  atomicWriteJson(join(BENCH_DIR, "virtual-field.json"), { ...out, pass }, { pretty: true });
  console.log("Neuron Mercury virtual neuron field bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`target: ${out.target_neurons}`);
  console.log(`represented: ${out.represented_virtual_neurons}`);
  console.log(`lanes: ${out.task_lanes}`);
  console.log(`unique_physical_control_neurons: ${out.unique_physical_control_neurons}`);
  console.log(`max_activation_budget_per_lane: ${out.max_activation_budget_per_lane}`);
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return { ...out, pass };
}

function selectVirtualControllers(neurons, task, lane, budget) {
  const selected = [];
  const seen = new Set();
  const size = Math.max(1, neurons.length);
  const start = Number.parseInt(stableHash(["virtual-route-start", task, lane]).slice(0, 8), 16) % size;
  const step = (Number.parseInt(stableHash(["virtual-route-step", lane, task]).slice(0, 8), 16) % 251) + 1;
  for (let i = 0; selected.length < Math.min(budget, size) && i < size * 2; i += 1) {
    const neuron = neurons[(start + i * step) % size];
    if (!neuron || seen.has(neuron.id)) continue;
    seen.add(neuron.id);
    selected.push(neuron.id);
  }
  return selected;
}

function virtualFieldRoute(taskText, args = [], options = {}) {
  const started = Date.now();
  const laneArg = args.find((arg) => arg.startsWith("--lanes="));
  const budgetArg = args.find((arg) => arg.startsWith("--budget="));
  const lanesWanted = laneArg ? Math.max(4, Math.min(64, Number(laneArg.split("=")[1]) || 16)) : 16;
  const perLaneBudget = budgetArg ? Math.max(1, Math.min(16, Number(budgetArg.split("=")[1]) || 8)) : 8;
  const cachedField = options.field
    || readJsonFileOrNull(join(VAR_DIR, "virtual-field.json"))
    || readJsonFileOrNull(join(BENCH_DIR, "virtual-field.json"));
  const field = cachedField
    && Number(cachedField.represented_virtual_neurons || 0) >= 10000
    && Number(cachedField.task_lanes || 0) >= lanesWanted
    && Number(cachedField.max_activation_budget_per_lane || 9999) <= perLaneBudget
    ? cachedField
    : virtualNeuronField([`--target=${Math.max(10000, MIN_PHYSICAL_NEURONS)}`, `--lanes=${lanesWanted}`, `--budget=${perLaneBudget}`]);
  const neurons = options.neurons || loadNeurons();
  const task = String(taskText || "accelerate local model first useful packet with UMA and model cortex").trim();
  const taskTokens = new Set(task.toLowerCase().split(/[^a-z0-9_]+/).filter(Boolean));
  const laneHints = {
    first_packet_latency: ["first", "packet", "latency", "response", "qwen", "llm"],
    model_cortex: ["model", "gguf", "tensor", "qwen", "deepseek", "inside"],
    uma_rag: ["uma", "rag", "memory", "context", "evidence"],
    rosen_pair: ["rosen", "pair", "state", "bridge", "entangle"],
    gpu_pressure: ["gpu", "3060", "cuda", "vram", "nvidia"],
    memory_hot_pages: ["memory", "hot", "page", "cache"],
    resident_reflex: ["resident", "reflex", "daemon", "endpoint"],
    background_completion: ["background", "worker", "complete", "slow"],
    judge_truthfulness: ["judge", "truth", "verify", "proof"],
    cache_coherence: ["cache", "coherence", "invalidate", "stale"],
    spend_guard: ["spend", "cost", "anthropic", "claude", "billing"],
    monster_doctor: ["doctor", "monster", "diagnose", "repo"],
    qwen: ["qwen", "qwer", "ollama", "local"],
    deepseek: ["deepseek", "reason", "local"],
    windows_3060: ["windows", "3060", "laptop", "wsl"],
    anti_overactivation: ["budget", "sparse", "overactivation", "hotpath"]
  };
  const routed = (field.lanes || [])
    .map((lane) => {
      const hints = laneHints[lane.lane] || [];
      const hintScore = hints.filter((hint) => taskTokens.has(hint)).length * 10;
      const jitter = Number.parseInt(stableHash([task, lane.lane]).slice(0, 6), 16) % 7;
      const score = hintScore + jitter + Math.min(4, lane.activation_budget || 0);
      const controllers = selectVirtualControllers(neurons, task, lane.lane, Math.min(perLaneBudget, lane.activation_budget || perLaneBudget));
      return {
        lane: lane.lane,
        score,
        virtual_neurons: lane.virtual_neurons,
        controllers,
        activation_budget: controllers.length
      };
    })
    .sort((a, b) => b.score - a.score);
  const active = routed.slice(0, Math.min(4, routed.length));
  const uniqueControllers = new Set(active.flatMap((lane) => lane.controllers));
  return {
    schema: "mercury-virtual-field-route-v1",
    created_at: nowIso(),
    task_hash: stableHash(task),
    task,
    field_target: field.target_neurons,
    represented_virtual_neurons: field.represented_virtual_neurons,
    active_lanes: active.length,
    total_lanes: routed.length,
    active_virtual_neurons: active.reduce((sum, lane) => sum + lane.virtual_neurons, 0),
    unique_physical_control_neurons: uniqueControllers.size,
    max_activation_budget_per_lane: Math.max(...active.map((lane) => lane.activation_budget)),
    lanes: active,
    elapsed_ms: Date.now() - started
  };
}

