function benchVirtualFieldRouting(args = []) {
  const tasks = [
    "qwen 3060 first packet latency with ollama gguf",
    "deepseek local model tensor cortex route",
    "uma rag evidence packet hot page cache",
    "rosen pair state bridge coherence",
    "gpu pressure vram windows laptop low impact",
    "memory hot pages cache invalidate stale",
    "resident reflex endpoint product activation",
    "background worker slow completion distill",
    "judge truthfulness proof investor safe",
    "cache coherence stale artifact guard",
    "anthropic claude billing spend guard",
    "monster doctor diagnose large repo latency",
    "qwer ollama local llm reflex",
    "deepseek reasoning local model",
    "windows 3060 wsl product proof",
    "anti overactivation sparse hotpath budget",
    "first response report generation cold start",
    "model inside gguf bridge tensor map",
    "uma project memory namespace isolation",
    "rosen thermal state field collapse",
    "gpu benchmark diskspd no regression",
    "resident speed state runtime low impact",
    "spend scan hidden paid provider loop",
    "monster afu lobster diagnosis"
  ];
  const started = Date.now();
  const field = virtualNeuronField(["--target=10000", "--lanes=16", "--budget=8"]);
  const neurons = loadNeurons();
  const routes = tasks.map((task) => virtualFieldRoute(task, ["--lanes=16", "--budget=8"], { field, neurons }));
  const coveredLanes = new Set(routes.flatMap((route) => route.lanes.map((lane) => lane.lane)));
  const coveredControllers = new Set(routes.flatMap((route) => route.lanes.flatMap((lane) => lane.controllers)));
  const maxRouteMs = Math.max(...routes.map((route) => route.elapsed_ms));
  const pass = routes.every((route) => route.represented_virtual_neurons >= 10000)
    && coveredLanes.size >= 16
    && coveredControllers.size >= 256
    && maxRouteMs <= 250
    && Date.now() - started <= 3000;
  const report = {
    schema: "mercury-virtual-field-routing-bench-v1",
    created_at: nowIso(),
    pass,
    tasks: tasks.length,
    covered_lanes: coveredLanes.size,
    covered_physical_control_neurons: coveredControllers.size,
    max_route_ms: maxRouteMs,
    elapsed_ms: Date.now() - started,
    routes: routes.map((route) => ({
      task_hash: route.task_hash,
      active_lanes: route.lanes.map((lane) => lane.lane),
      active_virtual_neurons: route.active_virtual_neurons,
      unique_physical_control_neurons: route.unique_physical_control_neurons,
      elapsed_ms: route.elapsed_ms
    }))
  };
  atomicWriteJson(join(BENCH_DIR, "virtual-field-routing.json"), report, { pretty: true });
  console.log("Neuron Mercury virtual field routing bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`tasks: ${report.tasks}`);
  console.log(`covered_lanes: ${report.covered_lanes}`);
  console.log(`covered_physical_control_neurons: ${report.covered_physical_control_neurons}`);
  console.log(`max_route_ms: ${report.max_route_ms}`);
  console.log(`elapsed_ms: ${report.elapsed_ms}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return report;
}

function buildNeuronTopology(args = []) {
  const neurons = loadNeurons();
  const registry = buildShardRegistry(args);
  const nodes = neurons.map((neuron) => {
    const shard = shardForNeuron(neuron);
    return {
      id: neuron.id,
      type: neuron.type,
      cluster: neuron.cluster || neuronCluster(neuron.id),
      lane: neuron.lane || neuronParallelLane(neuron),
      dispatch_phase: neuron.dispatch_phase ?? neuronDispatchPhase(neuron.lane || neuronParallelLane(neuron)),
      substrate: neuron.substrate || shard.substrate,
      shard_family: neuron.shard_family || shard.family,
      domain: neuronDomain(neuron),
      state_binding: neuronStateBinding(neuron),
      placement: neuron.placement || {
        ring: neuron.cluster || neuronCluster(neuron.id),
        domain: neuronDomain(neuron),
        wave: "legacy",
        slot: Number.parseInt(stableHash(neuron.id).slice(0, 8), 16) % Math.max(1, neurons.length)
      },
      entangles_with: Array.isArray(neuron.entangles_with) ? neuron.entangles_with : []
    };
  });
  const byId = new Set(nodes.map((node) => node.id));
  const edges = [];
  for (const node of nodes) {
    for (const to of node.entangles_with || []) {
      if (byId.has(to) && to !== node.id) {
        edges.push({
          from: node.id,
          to,
          type: "state_pair",
          purpose: "pulse neighbor when domain, lane, or proof state changes"
        });
      }
    }
  }
  const clusters = nodes.reduce((acc, node) => {
    acc[node.cluster] = (acc[node.cluster] || 0) + 1;
    return acc;
  }, {});
  const lanes = nodes.reduce((acc, node) => {
    acc[node.lane] = (acc[node.lane] || 0) + 1;
    return acc;
  }, {});
  const domains = nodes.reduce((acc, node) => {
    acc[node.domain] = (acc[node.domain] || 0) + 1;
    return acc;
  }, {});
  return {
    schema: NEURON_TOPOLOGY_SCHEMA,
    created_at: nowIso(),
    neurons: nodes.length,
    edges: edges.length,
    clusters,
    lanes,
    domains,
    hardware_substrates: HARDWARE_SUBSTRATES,
    registry_summary: {
      target_neurons: registry.target_neurons,
      virtual_shard_count: registry.virtual_shard_count,
      families: registry.families
    },
    policy: {
      hot_path: "execute sparse selected neurons only",
      topology: "all physical neurons are placed and may pulse by domain/lane/state",
      exploration: "low-cost dormant neurons are rotated into candidate lanes so coverage grows without broad execution"
    },
    nodes,
    edges_sample: edges.slice(0, 200)
  };
}

