function benchModelInsideQualitativeShift(args = []) {
  const started = Date.now();
  const inside = silencedConsole(() => modelInsideMap(["--json", ...args.filter((arg) => arg.startsWith("--model="))]));
  const rosen = silencedConsole(() => modelRosenBridgePlan(["--json", ...args.filter((arg) => arg.startsWith("--model="))]));
  const field = silencedConsole(() => benchModelFieldNeurons500([]));
  const selected = field.selected || {};
  const insidePass = Boolean(inside.pass);
  const internalDominance = Number(selected.internal_boundary || 0) > Number(selected.external || 0);
  const internalRatio = Number(selected.total || 0) ? Number((Number(selected.internal_boundary || 0) / Number(selected.total || 1)).toFixed(3)) : 0;
  const hasInsideRoles = Number(inside.rosen_inside_map?.placement_summary?.role_count || 0) >= 8;
  const hasKvAttentionSpec = (inside.rosen_inside_map?.neuron_placements || []).some((row) => row.role === "kv_prefix_preheat")
    && (inside.rosen_inside_map?.neuron_placements || []).some((row) => row.role === "attention_bridge_probe")
    && (inside.rosen_inside_map?.neuron_placements || []).some((row) => row.role === "speculative_decode_probe");
  const qualitativeShift = insidePass
    && rosen.route === "inference_boundary_rosen_map"
    && inside.rosen_inside_map?.mode === "ollama_gguf_inside_map"
    && Number(inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0) === MODEL_FIELD_NEURONS / 2
    && internalDominance
    && hasInsideRoles
    && hasKvAttentionSpec;
  const out = {
    schema: "mercury-model-inside-qualitative-shift-v1",
    created_at: nowIso(),
    pass: qualitativeShift,
    elapsed_ms: Date.now() - started,
    verdict: qualitativeShift ? "qualitative_shift_detected" : insidePass ? "inside_map_ready_no_shift_yet" : "no_local_model_inside_map",
    route_before: "external_only_map",
    route_after: rosen.route,
    inside_mode: inside.rosen_inside_map?.mode || "unknown",
    placed_internal_neurons: inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0,
    inside_roles: inside.rosen_inside_map?.placement_summary?.role_count || 0,
    selected_model_field: selected,
    internal_selection_ratio: internalRatio,
    checks: [
      { id: "inside_map_pass", pass: insidePass, detail: inside.rosen_inside_map?.mode || "unknown" },
      { id: "route_shift", pass: rosen.route === "inference_boundary_rosen_map", detail: `${rosen.route}` },
      { id: "all_internal_placed", pass: Number(inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0) === MODEL_FIELD_NEURONS / 2, detail: `${inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0}/${MODEL_FIELD_NEURONS / 2}` },
      { id: "internal_selection_dominates", pass: internalDominance, detail: `${selected.internal_boundary || 0}/${selected.total || 0}` },
      { id: "inside_role_coverage", pass: hasInsideRoles, detail: `${inside.rosen_inside_map?.placement_summary?.role_count || 0} roles` },
      { id: "kv_attention_speculative_present", pass: hasKvAttentionSpec, detail: "kv + attention + speculative placement" }
    ]
  };
  atomicWriteJson(join(BENCH_DIR, "model-inside-qualitative-shift.json"), out, { pretty: true });
  console.log("Neuron Mercury model inside qualitative shift bench");
  console.log(`pass: ${qualitativeShift ? "yes" : "no"}`);
  console.log(`verdict: ${out.verdict}`);
  console.log(`route: ${out.route_before} -> ${out.route_after}`);
  console.log(`inside_mode: ${out.inside_mode}`);
  console.log(`placed_internal_neurons: ${out.placed_internal_neurons}`);
  console.log(`inside_roles: ${out.inside_roles}`);
  console.log(`selected_model_field: ${selected.total || 0} (${selected.external || 0} external / ${selected.internal_boundary || 0} internal)`);
  console.log(`internal_selection_ratio: ${internalRatio}`);
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  console.log(`speed budget: ${qualitativeShift ? "pass" : "fail"}`);
  if (!qualitativeShift) process.exitCode = 1;
  return out;
}

function benchModelInsidePreheat(args = []) {
  const started = Date.now();
  const modelArg = args.find((arg) => arg.startsWith("--model="));
  const model = modelArg ? modelArg.slice("--model=".length) : "qwen2.5:7b";
  const inside = silencedConsole(() => modelInsideMap(["--json", `--model=${model}`]));
  const namespace = `bench-model-inside-preheat-${stableHash([process.pid, Date.now(), model])}`;
  const benchDir = join(BENCH_DIR, "model-inside-preheat");
  mkdirSync(benchDir, { recursive: true });
  const mapRel = "var/bench/model-inside-preheat/model-inside-preheat.json";
  const placementRows = inside.rosen_inside_map?.neuron_placements || [];
  const preheatDoc = {
    schema: "mercury-model-inside-preheat-doc-v1",
    created_at: nowIso(),
    model,
    inside_mode: inside.rosen_inside_map?.mode || "unknown",
    placement_summary: inside.rosen_inside_map?.placement_summary || null,
    by_role: inside.rosen_inside_map?.by_role || {},
    preheat_targets: placementRows.map((row) => ({
      neuron_id: row.neuron_id,
      role: row.role,
      surface: row.surface,
      inside_target: row.placement?.inside_target,
      rosen_node: row.placement?.rosen_node,
      tensor_range: row.placement?.tensor_range,
      activation_terms: row.activation_terms
    })),
    text_index: placementRows.map((row) => [
      row.neuron_id,
      row.role,
      row.surface,
      row.placement?.inside_target,
      row.placement?.rosen_node,
      Array.isArray(row.placement?.tensor_range) ? `tensor ${row.placement.tensor_range.join("-")}` : "",
      (row.activation_terms || []).join(" ")
    ].filter(Boolean).join(" ")).join("\n")
  };
  atomicWriteJson(join(process.cwd(), mapRel), preheatDoc, { pretty: true });
  const pages = ingestUmaFile(mapRel, { namespace, maxChars: 1100, maxChunks: 32 });
  writeUmaNamespaceIndex(namespace, pages);
  const task = `preheat ${model} internal kv prefix attention bridge decode budget logit policy speculative draft uncertainty probe before generation`;
  const empty = umaSearch(task, { namespace: `empty-${namespace}`, limit: 8, budgetMs: 12 });
  const search = umaSearch(task, { namespace, limit: 8, budgetMs: 12 });
  const cold = silencedConsole(() => coldStartAccelerateCommand([
    task,
    `--namespace=${namespace}`,
    "--path=var/bench/model-inside-preheat",
    "--limit=32",
    "--budget-ms=12",
    "--no-queue",
    "--json"
  ]));
  const roleHits = new Set();
  for (const hit of search.results || []) {
    for (const role of Object.keys(preheatDoc.by_role || {})) {
      if (String(hit.text || "").includes(role)) roleHits.add(role);
    }
  }
  const pass = Boolean(inside.pass)
    && pages.length > 0
    && search.count > empty.count
    && search.elapsed_ms <= 12
    && cold.packet?.hit_count > 0
    && cold.timings?.elapsed_ms <= 80
    && roleHits.size >= 3
    && Number(inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0) === MODEL_FIELD_NEURONS / 2
    && Date.now() - started <= 1800;
  const out = {
    schema: "mercury-model-inside-preheat-bench-v1",
    created_at: nowIso(),
    pass,
    elapsed_ms: Date.now() - started,
    model,
    namespace,
    inside_mode: inside.rosen_inside_map?.mode || "unknown",
    pages: pages.length,
    empty_hits: empty.count,
    preheat_hits: search.count,
    preheat_search_ms: search.elapsed_ms,
    cold_packet_hits: cold.packet?.hit_count || 0,
    cold_elapsed_ms: cold.timings?.elapsed_ms || 0,
    role_hits: [...roleHits].sort(),
    placed_internal_neurons: inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0,
    first_hits: (search.results || []).slice(0, 5).map((hit) => ({ pointer: hit.pointer, score: hit.score, text: String(hit.text || "").slice(0, 180) }))
  };
  atomicWriteJson(join(BENCH_DIR, "model-inside-preheat.json"), out, { pretty: true });
  console.log("Neuron Mercury model inside preheat bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`inside_mode: ${out.inside_mode}`);
  console.log(`pages: ${out.pages}`);
  console.log(`hits: ${out.empty_hits} -> ${out.preheat_hits}`);
  console.log(`search_ms: ${out.preheat_search_ms}`);
  console.log(`cold_packet_hits: ${out.cold_packet_hits}`);
  console.log(`cold_elapsed_ms: ${out.cold_elapsed_ms}`);
  console.log(`role_hits: ${out.role_hits.length}`);
  console.log(`placed_internal_neurons: ${out.placed_internal_neurons}`);
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return out;
}

function modelPreheatNamespace(model) {
  return `model-preheat-${stableHash([projectUmaNamespace(process.cwd()), model || "qwen2.5:7b"])}`;
}

function modelPreheatCommand(args = []) {
  const started = Date.now();
  const json = args.includes("--json");
  const modelArg = args.find((arg) => arg.startsWith("--model="));
  const budgetArg = args.find((arg) => arg.startsWith("--budget-ms="));
  const model = modelArg ? modelArg.slice("--model=".length) : "qwen2.5:7b";
  const rawBudgetMs = Number(budgetArg ? budgetArg.slice("--budget-ms=".length) : 12) || 12;
  const budgetMs = Math.max(3, Math.min(80, rawBudgetMs));
  const inside = silencedConsole(() => modelInsideMap(["--json", `--model=${model}`]));
  const namespace = modelPreheatNamespace(model);
  const preheatDir = join(VAR_DIR, "model-preheat");
  mkdirSync(preheatDir, { recursive: true });
  const safeModel = model.replace(/[^A-Za-z0-9_.-]+/g, "_");
  const relPath = `var/model-preheat/${safeModel}.json`;
  const placementRows = inside.rosen_inside_map?.neuron_placements || [];
  const mode = inside.rosen_inside_map?.mode || "model_inside_unavailable";
  const doc = {
    schema: "mercury-model-preheat-v1",
    created_at: nowIso(),
    project_namespace: projectUmaNamespace(process.cwd()),
    namespace,
    model,
    mode,
    ready: Boolean(inside.pass),
    placement_summary: inside.rosen_inside_map?.placement_summary || null,
    bridge_nodes: inside.rosen_inside_map?.bridge_nodes || [],
    role_table: inside.rosen_inside_map?.by_role || {},
    preheat_targets: placementRows.map((row) => ({
      neuron_id: row.neuron_id,
      side: row.side,
      role: row.role,
      surface: row.surface,
      inside_target: row.placement?.inside_target,
      rosen_node: row.placement?.rosen_node,
      tensor_range: row.placement?.tensor_range,
      activation_terms: row.activation_terms
    })),
    acceleration_contract: {
      purpose: "Prepare UMA/RAG evidence for first useful local model response before slow generation.",
      hot_path_budget_ms: budgetMs,
      model_call_policy: "avoid or defer when reflex/UMA packet is sufficient",
      internal_boundary_hooks: mode === "ollama_gguf_inside_map" ? ["kv_prefix", "attention_bridge", "decode_budget", "logit_policy", "speculative_probe"] : []
    },
    searchable_text: placementRows.map((row) => [
      row.neuron_id,
      row.side,
      row.role,
      row.surface,
      row.placement?.inside_target,
      row.placement?.rosen_node,
      Array.isArray(row.placement?.tensor_range) ? `tensor ${row.placement.tensor_range.join("-")}` : "",
      (row.activation_terms || []).join(" ")
    ].filter(Boolean).join(" ")).join("\n")
  };
  atomicWriteJson(join(process.cwd(), relPath), doc, { pretty: true });
  const pages = ingestUmaFile(relPath, { namespace, maxChars: 1100, maxChunks: 64 });
  writeUmaNamespaceIndex(namespace, pages);
  const task = `preheat ${model} first response kv attention decode logit speculative uncertainty compression local llm`;
  const search = umaSearch(task, { namespace, limit: 8, budgetMs });
  const out = {
    schema: "mercury-model-preheat-result-v1",
    created_at: nowIso(),
    ready: Boolean(inside.pass && pages.length && search.count),
    elapsed_ms: Date.now() - started,
    model,
    namespace,
    mode,
    artifact: relPath,
    pages: pages.length,
    hits: search.count,
    search_ms: search.elapsed_ms,
    placed_internal_neurons: inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0,
    role_count: inside.rosen_inside_map?.placement_summary?.role_count || 0,
    first_hits: (search.results || []).slice(0, 5).map((hit) => ({
      pointer: hit.pointer,
      score: hit.score,
      text: String(hit.text || "").slice(0, 180)
    }))
  };
  atomicWriteJson(join(preheatDir, "latest.json"), out, { pretty: true });
  if (json) {
    console.log(JSON.stringify(out, null, 2));
  } else {
    console.log("Neuron Mercury model preheat");
    console.log(`ready: ${out.ready ? "yes" : "no"}`);
    console.log(`mode: ${out.mode}`);
    console.log(`namespace: ${out.namespace}`);
    console.log(`pages: ${out.pages}`);
    console.log(`hits: ${out.hits}`);
    console.log(`search_ms: ${out.search_ms}`);
    console.log(`placed_internal_neurons: ${out.placed_internal_neurons}`);
    console.log(`artifact: ${out.artifact}`);
  }
  return out;
}

function modelPreheatFirstPacket(parsed, options = {}) {
  const started = Date.now();
  const model = parsed.model || "qwen2.5:7b";
  const budgetMs = Math.max(3, Math.min(80, Number(options.budgetMs || 12) || 12));
  const namespace = modelPreheatNamespace(model);
  let status = umaNamespaceStatus(namespace);
  let preheat = readJsonFileOrNull(join(VAR_DIR, "model-preheat", "latest.json"));
  if (!status.exists || status.pages === 0 || preheat?.namespace !== namespace) {
    preheat = silencedConsole(() => modelPreheatCommand([`--model=${model}`, `--budget-ms=${budgetMs}`, "--json"]));
    status = umaNamespaceStatus(namespace);
  }
  const task = [
    parsed.prompt || "",
    "local model first useful response",
    "kv attention decode logit speculative uncertainty compression"
  ].join(" ");
  const search = umaSearch(task, {
    namespace,
    limit: 8,
    threshold: 0.01,
    budgetMs
  });
  const packet = {
    schema: "mercury-model-preheat-first-packet-v1",
    mode: "model_preheat_first_packet",
    model,
    namespace,
    ready: Boolean((preheat?.ready || status.pages > 0) && search.count > 0),
    prompt: parsed.prompt,
    intent_key: llmIntentKey(parsed),
    preheat_mode: preheat?.mode || "unknown",
    pages: status.pages || preheat?.pages || 0,
    hit_count: search.count,
    search_ms: search.elapsed_ms,
    elapsed_ms: Date.now() - started,
    hits: (search.results || []).slice(0, 5).map((hit) => ({
      pointer: hit.pointer,
      score: hit.score,
      text: String(hit.text || "").slice(0, 220)
    }))
  };
  return packet;
}

function buildModelPreheatFirstAnswer(packet, parsed = {}) {
  const prompt = String(parsed.prompt || packet.prompt || "").trim();
  const zh = /[\u4e00-\u9fff]/.test(prompt);
  const hits = Array.isArray(packet.hits) ? packet.hits : [];
  const promptTerms = [...semanticTokens(prompt)]
    .filter((item) => item.length >= 2)
    .filter((item) => !/^(please|reply|answer|with|this|that|如何|可以|說明|回答|繁體中文|兩句話|三句話)$/.test(item))
    .slice(0, 8);
  const terms = [...new Set(hits.flatMap((hit) => String(hit.text || "")
    .toLowerCase()
    .split(/[^a-z0-9_\u4e00-\u9fff]+/)
    .filter((item) => item.length >= 2)
    .filter((item) => !/^(the|and|for|with|this|that|model|neuron|mercury)$/.test(item))
  ))].slice(0, 8);
  const mode = packet.preheat_mode || "model_preheat";
  const packetMs = packet.elapsed_ms ?? packet.search_ms ?? 0;
  if (zh) {
    const question = promptTerms.length ? `針對「${promptTerms.slice(0, 4).join("、")}」` : "針對你的問題";
    const focus = terms.length ? `我先抓到的錨點是：${terms.slice(0, 5).join("、")}。` : "我先抓到模型邊界與快取路徑。";
    return [
      `${question}，先給你可用結論：Mercury 會先用已預熱的模型邊界與 UMA/RAG 記憶組出第一包回答，讓你不用等完整本地模型解碼完才看到內容。`,
      focus,
      `這次走 ${mode}，命中 ${packet.hit_count || 0} 個內部錨點，第一包約 ${packetMs}ms；完整模型回答可以在背景繼續補強。`
    ].join("");
  }
  const question = promptTerms.length ? `For ${promptTerms.slice(0, 4).join(", ")}, ` : "";
  const focus = terms.length ? ` Early anchors: ${terms.slice(0, 5).join(", ")}.` : " Early anchors came from the preheated model boundary.";
  return [
    `${question}Mercury can return a first useful answer before the full local model decode finishes by using preheated model-boundary packets plus UMA/RAG memory.`,
    focus,
    ` Route=${mode}; hits=${packet.hit_count || 0}; first_packet=${packetMs}ms. The full model completion can continue in the background.`
  ].join("");
}

function enqueueFirstPacketBackgroundCompletion(parsed, packet, response) {
  if (!parsed.enqueueMiss) return null;
  return enqueueSlowReflex({
    model: parsed.model || DEFAULT_LOCAL_LLM_MODEL,
    intent: parsed.intent || `first_packet_completion.${llmIntentKey(parsed)}`,
    prompt: parsed.prompt || "",
    source: "model_preheat_first_packet_background_completion",
    metadata: {
      family: "local_model_background_completion",
      first_packet_mode: packet.preheat_mode || packet.mode || "unknown",
      first_packet_ms: packet.elapsed_ms ?? packet.search_ms ?? 0,
      first_packet_hits: packet.hit_count || 0,
      first_answer_chars: response.length,
      first_answer_preview: response.slice(0, 220),
      policy: "user receives first useful answer immediately; slow worker may refine the full model answer later"
    }
  });
}

function slowJobStatusPayload(jobId) {
  const cleanId = String(jobId || "").replace(/^job_/, "").replace(/\.json$/, "");
  const path = cleanId ? slowJobPath(cleanId) : null;
  const job = path && existsSync(path) ? readSlowJobFile(path) : null;
  if (!job) {
    return {
      ok: false,
      mode: "slow_job_not_found",
      job_id: cleanId || null
    };
  }
  const providerCached = readLlmCache({
    url: job.provider_hint?.url || "slow-provider",
    model: job.provider_hint?.model || job.model || DEFAULT_LOCAL_LLM_MODEL,
    intent: job.intent,
    prompt: job.prompt_norm || ""
  });
  const reflexCached = readLlmCache({
    url: "local-reflex",
    model: job.model || "game-mode",
    intent: job.intent,
    prompt: job.prompt_norm || ""
  });
  const directCacheEntry = job.cache_path && existsSync(job.cache_path) ? readJsonFileOrNull(job.cache_path) : null;
  const providerCacheEntry = job.provider_cache_path && existsSync(job.provider_cache_path) ? readJsonFileOrNull(job.provider_cache_path) : null;
  const fullEntry = providerCached.entry || providerCacheEntry || reflexCached.entry || directCacheEntry || null;
  const fullResponse = fullEntry?.response || null;
  return {
    ok: true,
    mode: "slow_job_status",
    job_id: job.id,
    status: job.status || "unknown",
    source: job.source || null,
    model: job.model,
    intent: job.intent,
    intent_key: job.intent_key,
    seen_count: job.seen_count || 0,
    created_at: job.created_at || null,
    last_seen_at: job.last_seen_at || null,
    seeded_at: job.seeded_at || null,
    deferred_at: job.deferred_at || null,
    failed_at: job.failed_at || null,
    provider_hint: job.provider_hint || null,
    metadata: job.metadata || null,
    first_answer: job.metadata?.first_answer_preview || null,
    first_answer_chars: job.metadata?.first_answer_chars || 0,
    response_ready: Boolean(fullResponse),
    response_source: providerCached.entry ? "provider_intent_cache" : providerCacheEntry ? "provider_cache_path" : reflexCached.entry ? "reflex_intent_cache" : directCacheEntry ? "job_cache_path" : null,
    response: fullResponse,
    cache_path: reflexCached.entry ? reflexCached.path : (directCacheEntry ? job.cache_path : null),
    provider_cache_path: job.provider_cache_path || null,
    response_bytes: job.response_bytes || 0,
    error: job.error || null,
    defer_reason: job.defer_reason || null
  };
}

function mergeSlowJobFinalAnswer(jobId, response) {
  const started = Date.now();
  const cleanId = String(jobId || "").replace(/^job_/, "").replace(/\.json$/, "");
  const path = cleanId ? slowJobPath(cleanId) : null;
  const job = path && existsSync(path) ? readSlowJobFile(path) : null;
  const finalResponse = String(response || "").trim();
  if (!job) {
    return {
      ok: false,
      mode: "slow_job_not_found",
      job_id: cleanId || null,
      elapsed_ms: Date.now() - started
    };
  }
  if (!finalResponse) {
    return {
      ok: false,
      mode: "merge_rejected",
      job_id: job.id,
      error: "response is required",
      elapsed_ms: Date.now() - started
    };
  }
  const seeded = reflexSeed({
    model: job.model || DEFAULT_LOCAL_LLM_MODEL,
    intent: job.intent,
    prompt: job.prompt_norm,
    response: finalResponse
  });
  const providerCache = promoteSlowJobProviderCache(job, job.provider_hint || refreshSlowJobProviderHint(job), finalResponse, 0);
  job.status = "seeded";
  job.seeded_at = nowIso();
  job.generate_model = "background-merge";
  job.generate_ms = 0;
  job.response_bytes = Buffer.byteLength(finalResponse);
  job.cache_path = seeded.cache_path;
  job.provider_cache_path = providerCache?.path || null;
  writeSlowJob(job);
  const statusStarted = Date.now();
  const status = slowJobStatusPayload(job.id);
  const statusMs = Date.now() - statusStarted;
  const replayStarted = Date.now();
  const replay = readLlmCache({
    url: "local-reflex",
    model: job.model || DEFAULT_LOCAL_LLM_MODEL,
    intent: job.intent,
    prompt: job.prompt_norm
  });
  const replayMs = Date.now() - replayStarted;
  return {
    ok: Boolean(seeded.ok && status.ok && status.response_ready && replay.entry?.response),
    mode: "llm_fast_final_merge",
    job_id: job.id,
    status: status.status,
    status_ms: statusMs,
    replay_ms: replayMs,
    response_ready: Boolean(status.response_ready),
    response_source: status.response_source || null,
    response_chars: finalResponse.length,
    cache_path: seeded.cache_path || null,
    provider_cache_path: providerCache?.path || null,
    replay_mode: replay.entry ? "cache_hit" : "cache_miss",
    elapsed_ms: Date.now() - started
  };
}

function llmFastPreheatFirstResult(parsed, started = Date.now()) {
  const packet = modelPreheatFirstPacket(parsed, { budgetMs: 12 });
  if (!packet.ready) return null;
  const response = buildModelPreheatFirstAnswer(packet, parsed);
  const slowJob = enqueueFirstPacketBackgroundCompletion(parsed, packet, response);
  return {
    mode: "model_preheat_first_packet",
    elapsed_ms: Date.now() - started,
    model: parsed.model,
    intent_key: packet.intent_key,
    response,
    response_chars: response.length,
    background_completion: slowJob ? {
      queued: Boolean(slowJob.ok),
      job_id: slowJob.job_id,
      status: slowJob.status,
      mode: slowJob.mode,
      provider_hint: slowJob.provider_hint || null
    } : {
      queued: false,
      reason: "not_requested"
    },
    packet
  };
}

async function modelCortexCommand(args = []) {
  const started = Date.now();
  const json = args.includes("--json");
  const quiet = args.includes("--quiet");
  const modelArg = args.find((arg) => arg.startsWith("--model="));
  const modelsArg = args.find((arg) => arg.startsWith("--models="));
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const probePacket = !args.includes("--no-packet");
  const url = process.env.OLLAMA_URL || "http://127.0.0.1:11434";
  const limit = limitArg ? Math.max(1, Math.min(24, Number(limitArg.split("=")[1]) || 12)) : 12;
  let models = [];
  if (modelsArg) {
    models = modelsArg.split("=").slice(1).join("=").split(",").map((item) => item.trim()).filter(Boolean);
  } else if (modelArg) {
    models = [modelArg.split("=").slice(1).join("=")];
  } else {
    try {
      const tags = await fetchJson(`${url}/api/tags`, { timeout: 4000 });
      models = (tags.json?.models || []).map((model) => model.name).filter(Boolean);
    } catch {}
  }
  models = [...new Set(models)].slice(0, limit);
  const rows = [];
  for (const model of models) {
    const inside = silencedConsole(() => modelInsideMap(["--json", `--model=${model}`]));
    const preheat = silencedConsole(() => modelPreheatCommand([`--model=${model}`, "--budget-ms=12", "--json"]));
    const gguf = (inside.blobs || []).find((item) => item.blob?.gguf)?.blob?.gguf || null;
    const blobBytes = (inside.blobs || []).reduce((sum, item) => sum + Number(item.blob?.size || item.declared_size || 0), 0);
    const packet = probePacket
      ? modelPreheatFirstPacket({
          url,
          model,
          prompt: `Mercury model cortex probe for ${model}: first useful packet before local model response.`,
          intent: `model.cortex.${model}`,
          numPredict: 32
        }, { budgetMs: 12 })
      : null;
    const byRole = inside.rosen_inside_map?.by_role || {};
    rows.push({
      model,
      pass: Boolean(inside.pass && preheat.ready && (!probePacket || packet?.ready)),
      mode: inside.rosen_inside_map?.mode || "unknown",
      manifest_path: inside.manifest_path || null,
      layer_count: inside.layer_count || 0,
      blob_count: (inside.blobs || []).length,
      blob_bytes: blobBytes,
      gguf_layers: inside.gguf_layers || 0,
      gguf_version: gguf?.version || null,
      gguf_tensor_count: gguf?.tensor_count || 0,
      gguf_metadata_kv_count: gguf?.metadata_kv_count || 0,
      bridge_nodes: inside.rosen_inside_map?.bridge_nodes?.length || 0,
      placed_internal_neurons: inside.rosen_inside_map?.placement_summary?.placed_internal_neurons || 0,
      role_count: inside.rosen_inside_map?.placement_summary?.role_count || 0,
      role_distribution: byRole,
      preheat_namespace: preheat.namespace || null,
      preheat_pages: preheat.pages || 0,
      preheat_hits: preheat.hits || 0,
      preheat_search_ms: preheat.search_ms || 0,
      first_packet_ms: packet?.elapsed_ms ?? null,
      first_packet_hits: packet?.hit_count ?? null,
      first_packet_search_ms: packet?.search_ms ?? null,
      cortex_claim: "Map the local model artifact and inference boundary so Mercury can answer from preheated UMA/model-field packets before full decode."
    });
  }
  const out = {
    schema: "mercury-model-cortex-v1",
    created_at: nowIso(),
    pass: rows.length > 0 && rows.every((row) => row.pass),
    model_count: rows.length,
    passed: rows.filter((row) => row.pass).length,
    neuron_catalog: {
      total: loadNeurons().length,
      model_field: loadNeurons().filter((neuron) => neuron.model_field).length,
      internal_boundary: loadNeurons().filter((neuron) => neuron.model_field?.side === "internal").length,
      concurrent_control: loadNeurons().filter((neuron) => neuron.control_field).length
    },
    rows,
    elapsed_ms: Date.now() - started
  };
  atomicWriteJson(join(BENCH_DIR, "model-cortex.json"), out, { pretty: true });
  atomicWriteJson(join(VAR_DIR, "model-cortex.json"), out, { pretty: true });
  if (json) {
    if (!quiet) console.log(JSON.stringify(out));
    if (!out.pass) process.exitCode = 1;
    return out;
  }
  console.log("Neuron Mercury model cortex");
  console.log(`pass: ${out.pass ? "yes" : "no"}`);
  console.log(`models: ${out.passed}/${out.model_count}`);
  for (const row of rows) {
    console.log(`- ${row.model}: ${row.mode}, tensors=${row.gguf_tensor_count}, metadata=${row.gguf_metadata_kv_count}, placed=${row.placed_internal_neurons}, packet=${row.first_packet_ms ?? "-"}ms`);
  }
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  if (!out.pass) process.exitCode = 1;
  return out;
}

async function benchModelCortex(args = []) {
  const out = await modelCortexCommand(["--json", "--quiet", ...args.filter((arg) => arg.startsWith("--model=") || arg.startsWith("--models=") || arg.startsWith("--limit="))]);
  const rows = out.rows || [];
  const pass = Boolean(out.pass)
    && rows.length >= 1
    && rows.every((row) => row.mode === "ollama_gguf_inside_map")
    && rows.every((row) => row.gguf_tensor_count > 0)
    && rows.every((row) => row.placed_internal_neurons === MODEL_FIELD_NEURONS / 2)
    && rows.every((row) => Number(row.first_packet_ms ?? 9999) <= 50)
    && out.elapsed_ms <= 5000 * Math.max(1, rows.length);
  console.log("Neuron Mercury model cortex bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`models: ${out.passed}/${out.model_count}`);
  for (const row of rows) {
    console.log(`- ${row.model}: tensors=${row.gguf_tensor_count}, placed=${row.placed_internal_neurons}, packet=${row.first_packet_ms}ms, preheat=${row.preheat_search_ms}ms`);
  }
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return { ...out, pass };
}

function modelOpenabilityProbe(args = []) {
  const started = Date.now();
  const json = args.includes("--json");
  const modelArg = args.find((arg) => arg.startsWith("--model="));
  const localStatus = silencedConsole(() => localLlmCommand(["status", "--json"]));
  const model = modelArg ? modelArg.slice("--model=".length) : (chooseLocalLlmModel(localStatus?.models || []) || "qwen2.5:7b");
  const home = process.env.HOME || process.env.USERPROFILE || "";
  const ollamaTags = safeExec("curl", ["-s", "http://127.0.0.1:11434/api/tags"], { timeout: 1200, maxBuffer: 128 * 1024 });
  let ollamaModels = [];
  try {
    ollamaModels = (JSON.parse(ollamaTags.output).models || []).map((item) => item.name).filter(Boolean);
  } catch {}
  const ollamaDir = home ? join(home, ".ollama", "models") : "";
  const ollamaBlobs = ollamaDir ? safeListDir(join(ollamaDir, "blobs"), 32) : [];
  const ollamaManifests = ollamaDir ? safeListDir(join(ollamaDir, "manifests"), 32) : [];
  const hfHub = home ? join(home, ".cache", "huggingface", "hub") : "";
  const hfModels = safeListDir(hfHub, 64).filter((name) => /^models--/.test(name));
  const cwdModels = umaCandidateFiles(".", 500)
    .filter((file) => /\.(gguf|safetensors|bin|pt|pth|onnx)$/i.test(file.rel))
    .slice(0, 64)
    .map((file) => ({ path: file.rel, size: file.size }));
  const pythonTorch = pythonModuleProbe("torch");
  const pythonTransformers = pythonModuleProbe("transformers");
  const llamaCpp = commandProbe("llama-cli", ["--version"], { timeout: 1200 });
  const vllm = pythonModuleProbe("vllm");
  const sglang = pythonModuleProbe("sglang");
  const hasRawFile = cwdModels.length > 0 || hfModels.length > 0 || ollamaBlobs.length > 0;
  const canOpenWeights = cwdModels.some((item) => /\.(safetensors|bin|pt|pth)$/i.test(item.path)) || hfModels.length > 0 || cwdModels.some((item) => /\.gguf$/i.test(item.path)) || ollamaBlobs.length > 0;
  const canHookLayers = pythonTorch.available && pythonTransformers.available && (hfModels.length > 0 || cwdModels.some((item) => /\.(safetensors|bin|pt|pth)$/i.test(item.path)));
  const canHookInferenceBoundary = ollamaTags.ok || llamaCpp.available || vllm.available || sglang.available || cwdModels.some((item) => /\.gguf$/i.test(item.path));
  const recommended = canHookLayers
    ? "transformers_hooks"
    : canHookInferenceBoundary
      ? "inference_boundary_hooks"
      : hasRawFile
        ? "weight_file_inspection_only"
        : "model_file_not_found_yet";
  const neurons = loadNeurons();
  const modelField = neurons.filter((neuron) => neuron.model_field);
  const out = {
    ok: canOpenWeights || canHookInferenceBoundary,
    schema: "mercury-model-openability-v1",
    created_at: nowIso(),
    model,
    runtime: {
      ollama_http: ollamaTags.ok,
      ollama_models: ollamaModels,
      ollama_blob_count: ollamaBlobs.length,
      ollama_manifest_roots: ollamaManifests,
      huggingface_model_dirs: hfModels.slice(0, 12),
      local_model_files: cwdModels
    },
    toolchain: {
      torch: { available: pythonTorch.available, detail: pythonTorch.version || pythonTorch.error || pythonTorch.detail },
      transformers: { available: pythonTransformers.available, detail: pythonTransformers.version || pythonTransformers.error || pythonTransformers.detail },
      llama_cpp: { available: llamaCpp.available, detail: llamaCpp.version || llamaCpp.detail },
      vllm: { available: vllm.available, detail: vllm.version || vllm.error || vllm.detail },
      sglang: { available: sglang.available, detail: sglang.version || sglang.error || sglang.detail }
    },
    openness: {
      can_open_weight_file: Boolean(canOpenWeights),
      can_hook_live_layers: Boolean(canHookLayers),
      can_hook_inference_boundary: Boolean(canHookInferenceBoundary),
      recommended_path: recommended,
      caveat: "Ollama exposes model files and API behavior, but not live layer activations through its normal HTTP API. Live internal hooks need Transformers/vLLM/sglang/llama.cpp-style control."
    },
    model_field_neurons: {
      total: modelField.length,
      external: modelField.filter((neuron) => neuron.model_field.side === "external").length,
      internal_boundary: modelField.filter((neuron) => neuron.model_field.side === "internal").length,
      target: MODEL_FIELD_NEURONS
    },
    elapsed_ms: Date.now() - started
  };
  atomicWriteJson(join(BENCH_DIR, "model-openability.json"), out, { pretty: true });
  if (json) {
    console.log(JSON.stringify(out));
    return out;
  }
  console.log("Neuron Mercury model openability");
  console.log(`ok: ${out.ok ? "yes" : "no"}`);
  console.log(`model: ${out.model}`);
  console.log(`recommended_path: ${out.openness.recommended_path}`);
  console.log(`open_weight_file: ${out.openness.can_open_weight_file ? "yes" : "no"}`);
  console.log(`live_layer_hooks: ${out.openness.can_hook_live_layers ? "yes" : "no"}`);
  console.log(`inference_boundary_hooks: ${out.openness.can_hook_inference_boundary ? "yes" : "no"}`);
  console.log(`model_field_neurons: ${out.model_field_neurons.total} (${out.model_field_neurons.external} external / ${out.model_field_neurons.internal_boundary} internal-boundary)`);
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  if (!out.ok) process.exitCode = 1;
  return out;
}

function modelRosenBridgePlan(args = []) {
  const started = Date.now();
  const json = args.includes("--json");
  const modelArg = args.find((arg) => arg.startsWith("--model="));
  const model = modelArg ? modelArg.slice("--model=".length) : "qwen2.5:7b";
  const open = silencedConsole(() => modelOpenabilityProbe(["--json", `--model=${model}`]));
  const neurons = loadNeurons().filter((neuron) => neuron.model_field);
  const external = neurons.filter((neuron) => neuron.model_field.side === "external");
  const internal = neurons.filter((neuron) => neuron.model_field.side === "internal");
  const hookLayers = open.openness?.can_hook_live_layers;
  const boundary = open.openness?.can_hook_inference_boundary;
  const weight = open.openness?.can_open_weight_file;
  const route = hookLayers
    ? "live_layer_rosen_map"
    : boundary
      ? "inference_boundary_rosen_map"
      : weight
        ? "offline_weight_map"
        : "external_only_map";
  const bridgeSurfaces = [
    { surface: "prompt_intake", side: "external", bridge: "input -> normalized intent -> context budget" },
    { surface: "uma_context", side: "external", bridge: "UMA pointer packet -> compact prompt prefix" },
    { surface: "reflex_cache", side: "external", bridge: "semantic cache -> skip generation when exact enough" },
    { surface: "provider_gate", side: "external", bridge: "policy gate -> prevent slow model hot path" },
    { surface: "kv_prefix", side: "internal", bridge: "stable prefix -> reusable KV/cache route" },
    { surface: "attention_hint", side: "internal", bridge: "evidence anchors -> attention steering tokens" },
    { surface: "decode_budget", side: "internal", bridge: "token budget -> early useful completion" },
    { surface: "logit_policy", side: "internal", bridge: "runtime stop/logit processor when supported" },
    { surface: "speculative_draft", side: "internal", bridge: "fast draft -> verify -> accept/reject" },
    { surface: "uncertainty_probe", side: "internal", bridge: "detect insufficiency before long decode" }
  ];
  const actions = hookLayers ? [
    "Load model through Transformers with output_hidden_states/forward hooks.",
    "Attach layer probes to attention blocks and MLP residual streams.",
    "Build layer-to-task bridge scores from activation deltas.",
    "Prewarm KV prefixes for recurrent UMA/RAG evidence packets."
  ] : boundary ? [
    "Keep Ollama/Qwen as model engine but wrap prompt, prefix, decode budget, and speculative validation.",
    "Materialize reusable context prefixes and evidence anchors before generation.",
    `Use ${MODEL_FIELD_NEURONS / 2} external neurons for cache/UMA/provider routing and ${MODEL_FIELD_NEURONS / 2} internal-boundary neurons for KV/decode/logit/speculative policy.`,
    "Promote accepted drafts into reflex/UMA so second contact is sub-ms replay."
  ] : [
    "Inspect model files and build an offline layer/metadata map.",
    "Route through external UMA/reflex until hookable runtime is installed."
  ];
  const pass = neurons.length === MODEL_FIELD_NEURONS
    && external.length === MODEL_FIELD_NEURONS / 2
    && internal.length === MODEL_FIELD_NEURONS / 2
    && bridgeSurfaces.length >= 10
    && ["live_layer_rosen_map", "inference_boundary_rosen_map", "offline_weight_map", "external_only_map"].includes(route)
    && actions.length >= 2
    && Date.now() - started <= 1200;
  const out = {
    schema: "mercury-model-rosen-bridge-plan-v1",
    created_at: nowIso(),
    pass,
    model,
    route,
    openability: open.openness,
    model_field_neurons: {
      total: neurons.length,
      external: external.length,
      internal_boundary: internal.length
    },
    bridge_surfaces: bridgeSurfaces,
    actions,
    next_runtime_target: hookLayers ? "measure live layer hooks" : boundary ? "install/load hookable runtime for live layer hooks" : "find local model file or start provider",
    elapsed_ms: Date.now() - started
  };
  atomicWriteJson(join(BENCH_DIR, "model-rosen-bridge-plan.json"), out, { pretty: true });
  if (json) {
    console.log(JSON.stringify(out));
    return out;
  }
  console.log("Neuron Mercury model Rosen bridge plan");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`model: ${model}`);
  console.log(`route: ${route}`);
  console.log(`open_weight_file: ${open.openness?.can_open_weight_file ? "yes" : "no"}`);
  console.log(`live_layer_hooks: ${open.openness?.can_hook_live_layers ? "yes" : "no"}`);
  console.log(`inference_boundary_hooks: ${open.openness?.can_hook_inference_boundary ? "yes" : "no"}`);
  console.log(`model_field_neurons: ${neurons.length} (${external.length}/${internal.length})`);
  console.log(`next: ${out.next_runtime_target}`);
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return out;
}

function benchModelRosenBridgePlan(args = []) {
  const out = silencedConsole(() => modelRosenBridgePlan(["--json"]));
  const pass = Boolean(out.pass)
    && out.model_field_neurons?.total === MODEL_FIELD_NEURONS
    && out.bridge_surfaces?.some((surface) => surface.surface === "kv_prefix")
    && out.bridge_surfaces?.some((surface) => surface.surface === "speculative_draft")
    && /rosen_map|weight_map|external_only_map/.test(out.route || "")
    && typeof out.next_runtime_target === "string"
    && out.elapsed_ms <= 1200;
  console.log("Neuron Mercury model Rosen bridge plan bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`route: ${out.route}`);
  console.log(`model_field_neurons: ${out.model_field_neurons?.total || 0}`);
  console.log(`surfaces: ${out.bridge_surfaces?.length || 0}`);
  console.log(`next: ${out.next_runtime_target}`);
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return { pass, out };
}

function cachedQwerSpeedPlan(options = {}) {
  const ttlMs = Math.max(0, Number(options.ttlMs ?? 1000));
  const now = Date.now();
  if (!options.refresh && QWER_SPEED_PLAN_CACHE && now - QWER_SPEED_PLAN_CACHE.at <= ttlMs) {
    return {
      ...QWER_SPEED_PLAN_CACHE.plan,
      cache: {
        mode: "qwer_speed_plan_cache_hit",
        age_ms: now - QWER_SPEED_PLAN_CACHE.at,
        ttl_ms: ttlMs
      },
      elapsed_ms: 0
    };
  }
  const plan = buildQwerSpeedPlan();
  QWER_SPEED_PLAN_CACHE = { at: now, plan };
  return {
    ...plan,
    cache: {
      mode: "qwer_speed_plan_cache_miss",
      age_ms: 0,
      ttl_ms: ttlMs
    }
  };
}

function qwerSpeedPlan(args = []) {
  const json = args.includes("--json");
  const refresh = args.includes("--refresh");
  const ttlArg = args.find((arg) => arg.startsWith("--ttl-ms="));
  const ttlMs = ttlArg ? Number(ttlArg.split("=")[1]) || 1000 : 1000;
  const plan = cachedQwerSpeedPlan({ refresh, ttlMs });
  if (json) {
    console.log(JSON.stringify(plan));
    return plan;
  }
  console.log("Neuron Mercury Qwer speed plan");
  console.log(`provider: ${plan.provider_hint?.provider || "none"}`);
  console.log(`route: ${plan.provider_hint?.route || "none"}`);
  console.log(`cached_runtime_profile: ${plan.cached_runtime_profile ? "yes" : "no"}`);
  console.log(`queue: pending=${plan.queue.pending}, qwer=${plan.queue.qwer_pending}, deferred=${plan.queue.deferred}, failed=${plan.queue.failed}`);
  console.log(`provider_cache: files=${plan.provider_cache.files}, qwen=${plan.provider_cache.qwen_files}`);
  console.log(`cache: ${plan.cache?.mode || "-"}`);
  console.log(`elapsed_ms: ${plan.elapsed_ms}`);
  for (const command of plan.commands || []) console.log(`- ${command}`);
  return plan;
}

