function coldStartSpeedSummary() {
  const readSummary = (file, kind) => {
    const path = join(COLD_START_DIR, file);
    if (!existsSync(path)) return { kind, present: false, path };
    try {
      const report = JSON.parse(readFileSync(path, "utf8"));
      return {
        kind,
        present: true,
        path,
        created_at: report.created_at || null,
        mode: report.mode || null,
        task: report.task || null,
        route: report.packet?.route || null,
        hits: report.packet?.hit_count || 0,
        elapsed_ms: report.timings?.elapsed_ms || 0,
        slow_job_status: report.slow_job?.status || null,
        sections: report.sections || 0,
        workers: report.workers || 0,
        waves: Array.isArray(report.waves) ? report.waves.length : 0,
        dispatch_max_concurrency: report.dispatch_plan?.max_concurrency || 0,
        dispatch_critical_path_ms: report.dispatch_plan?.critical_path_ms || 0,
        immediate_draft_bytes: report.immediate_draft_bytes || 0,
        judge_score: report.judge?.score || 0,
        pointer_coverage: report.judge?.pointer_coverage || 0,
        distilled_reflexes: report.distillation?.seeded_count || 0,
        active_neurons: report.neuron_map?.active_neurons || 0,
        virtual_route_lanes: report.virtual_route?.active_lanes || report.packet?.virtual_route?.active_lanes || report.neuron_map?.virtual_route?.active_lanes || 0,
        virtual_route_controllers: report.virtual_route?.unique_physical_control_neurons || report.packet?.virtual_route?.unique_physical_control_neurons || report.neuron_map?.virtual_route?.unique_physical_control_neurons || 0,
        active_virtual_neurons: report.virtual_route?.active_virtual_neurons || report.packet?.virtual_route?.active_virtual_neurons || report.neuron_map?.virtual_route?.active_virtual_neurons || 0,
        virtual_route_ms: report.virtual_route?.elapsed_ms ?? report.packet?.virtual_route?.elapsed_ms ?? null,
        estimated_speedup: report.estimate?.speedup || 0
      };
    } catch {
      return { kind, present: false, path, error: "unreadable" };
    }
  };
  const cold = readSummary("latest.json", "cold_start");
  const firstGen = readSummary("first-gen-latest.json", "first_generation");
  return {
    schema: "mercury-cold-start-speed-summary-v1",
    cold_start: cold,
    first_generation: firstGen,
    ready: Boolean(cold.present || firstGen.present)
  };
}

function firstGenerationDispatchSummary() {
  const path = join(COLD_START_DIR, "first-gen-latest.json");
  if (!existsSync(path)) {
    return { schema: "mercury-first-gen-dispatch-summary-v1", present: false, path, sections: 0, workers: 0, waves: 0, pending: 0, seeded: 0, failed: 0, ready: false };
  }
  try {
    const report = JSON.parse(readFileSync(path, "utf8"));
    const jobs = Array.isArray(report.section_jobs) ? report.section_jobs : [];
    const statuses = jobs.map((job) => {
      const file = job.job_id ? readSlowJobFile(slowJobPath(job.job_id)) : null;
      return file?.status || job.status || "unknown";
    });
    const pending = statuses.filter((status) => status === "pending" || status === "deferred").length;
    const seeded = statuses.filter((status) => status === "seeded" || status === "done").length;
    const failed = statuses.filter((status) => status === "failed").length;
    const workers = report.workers || new Set(jobs.map((job) => job.worker).filter(Boolean)).size || 0;
    return {
      schema: "mercury-first-gen-dispatch-summary-v1",
      present: true,
      path,
      created_at: report.created_at || null,
      mode: report.mode || null,
      task: report.task || null,
      sections: jobs.length || report.sections || 0,
      workers,
      waves: Array.isArray(report.waves) ? report.waves.length : 0,
      dispatch_max_concurrency: report.dispatch_plan?.max_concurrency || 0,
      dispatch_critical_path_ms: report.dispatch_plan?.critical_path_ms || 0,
      pending,
      seeded,
      failed,
      active_neurons: report.neuron_map?.active_neurons || 0,
      virtual_route_lanes: report.neuron_map?.virtual_route?.active_lanes || 0,
      virtual_route_controllers: report.neuron_map?.virtual_route?.unique_physical_control_neurons || 0,
      active_virtual_neurons: report.neuron_map?.virtual_route?.active_virtual_neurons || 0,
      judge_score: report.judge?.score || 0,
      estimated_speedup: report.estimate?.speedup || 0,
      ready: Boolean(jobs.length && workers > 0)
    };
  } catch {
    return { schema: "mercury-first-gen-dispatch-summary-v1", present: false, path, sections: 0, workers: 0, waves: 0, pending: 0, seeded: 0, failed: 0, ready: false, error: "unreadable" };
  }
}

function firstGenDispatchArgs(args = []) {
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const modelArg = args.find((arg) => arg.startsWith("--model="));
  return {
    limit: limitArg ? Math.max(1, Math.min(64, Number(limitArg.split("=")[1]) || 8)) : 8,
    model: modelArg ? modelArg.split("=").slice(1).join("=") : DEFAULT_LOCAL_LLM_MODEL,
    json: args.includes("--json")
  };
}

function firstGenDispatchCommand(args = []) {
  ensureDirs();
  const parsed = firstGenDispatchArgs(args);
  const started = Date.now();
  const path = join(COLD_START_DIR, "first-gen-latest.json");
  if (!existsSync(path)) {
    const out = { ok: false, mode: "first_gen_dispatch_missing", elapsed_ms: Date.now() - started, path, results: [] };
    if (parsed.json) console.log(JSON.stringify(out));
    else console.log("Neuron Mercury first-generation dispatch\nmissing latest first-gen report");
    process.exitCode = 1;
    return out;
  }
  const report = JSON.parse(readFileSync(path, "utf8"));
  const drafts = new Map((report.section_drafts || []).map((draft) => [draft.section, draft]));
  const jobs = (report.section_jobs || [])
    .map((job) => ({ job, file: job.job_id ? readSlowJobFile(slowJobPath(job.job_id)) : null }))
    .filter((entry) => entry.file && ["pending", "deferred", "failed", "processing"].includes(entry.file.status || "pending"))
    .slice(0, parsed.limit);
  const results = [];
  for (const entry of jobs) {
    const draft = drafts.get(entry.job.section);
    const response = draft?.draft || [
      `## ${entry.job.section}. ${entry.job.title}`,
      "No section draft was available; preserve this slot for slow model refinement."
    ].join("\n");
    const seeded = seedReflex(entry.file.intent, entry.file.prompt_norm, response, entry.file.model || parsed.model);
    const providerHint = entry.file.provider_hint || selectSlowProviderHint();
    const providerCache = promoteSlowJobProviderCache(entry.file, providerHint, response, 0);
    entry.file.status = "seeded";
    entry.file.seeded_at = nowIso();
    entry.file.generate_model = "first-gen-section-draft";
    entry.file.provider_hint = providerHint;
    entry.file.response_bytes = Buffer.byteLength(response);
    entry.file.cache_path = seeded.path;
    entry.file.provider_cache_path = providerCache?.path || null;
    writeSlowJob(entry.file);
    recordReflexScore({
      event: "first_gen_section_dispatched",
      model: seeded.entry.model,
      intent_key: seeded.entry.intent_key,
      job_id: entry.file.id,
      section: entry.job.section,
      elapsed_ms: 0
    });
    results.push({
      ok: true,
      job_id: entry.file.id,
      section: entry.job.section,
      worker: entry.job.worker,
      cache_path: seeded.path,
      provider_cache_path: providerCache?.path || null,
      bytes: Buffer.byteLength(response)
    });
  }
  const statusByJob = new Map(results.map((item) => [item.job_id, "seeded"]));
  const statuses = (report.section_jobs || []).map((job) => statusByJob.get(job.job_id) || job.status || "unknown");
  const summary = {
    schema: "mercury-first-gen-dispatch-summary-v1",
    present: true,
    path,
    created_at: report.created_at || null,
    mode: report.mode || null,
    task: report.task || null,
    sections: report.section_jobs?.length || report.sections || 0,
    workers: report.workers || 0,
    waves: Array.isArray(report.waves) ? report.waves.length : 0,
    dispatch_max_concurrency: report.dispatch_plan?.max_concurrency || 0,
    dispatch_critical_path_ms: report.dispatch_plan?.critical_path_ms || 0,
    pending: statuses.filter((status) => status === "pending" || status === "deferred").length,
    seeded: statuses.filter((status) => status === "seeded" || status === "done").length,
    failed: statuses.filter((status) => status === "failed").length,
    active_neurons: report.neuron_map?.active_neurons || 0,
    judge_score: report.judge?.score || 0,
    estimated_speedup: report.estimate?.speedup || 0,
    ready: Boolean((report.section_jobs || []).length && report.workers > 0),
    source: "dispatch_hot_summary"
  };
  const out = {
    ok: results.every((item) => item.ok),
    schema: "mercury-first-gen-dispatch-run-v1",
    mode: "first_gen_section_dispatch",
    elapsed_ms: Date.now() - started,
    attempted: jobs.length,
    seeded: results.length,
    summary,
    results
  };
  appendMemoryGraphEvent({
    type: "first_gen_section_dispatch",
    task: report.task || null,
    path: report.path || null,
    attempted: out.attempted,
    seeded: out.seeded,
    pending: summary.pending,
    sections: summary.sections,
    workers: summary.workers,
    section_results: results.map((item) => ({
      section: item.section,
      worker: item.worker,
      bytes: item.bytes,
      cache_path: item.cache_path
    })),
    elapsed_ms: out.elapsed_ms
  });
  if (parsed.json) {
    console.log(JSON.stringify(out));
    return out;
  }
  console.log("Neuron Mercury first-generation dispatch");
  console.log(`attempted: ${out.attempted}`);
  console.log(`seeded: ${out.seeded}`);
  console.log(`remaining_pending: ${summary.pending}`);
  console.log(`elapsed_ms: ${out.elapsed_ms}`);
  for (const item of results) console.log(`- section=${item.section} worker=${item.worker} ${item.bytes} bytes`);
  return out;
}

