function aiInstantAnswer({ prompt, model, intent }) {
  const started = Date.now();
  const entry = rosenEntrySignals(prompt, { namespace: projectUmaNamespace() });
  const families = entry.risk_families.map((family) => family.id);
  const has = (id) => families.includes(id);
  const chinese = /[\u4e00-\u9fff]/.test(prompt);
  const lines = [];
  if (chinese) {
    lines.push("這是 Mercury 的毫秒級即時路徑：先回可用答案，再讓本地模型在背景補完。");
    if (has("local_llm_speed")) lines.push("1. 本地模型加速：保持 7B warm、避開 14B 慢路徑，重複任務直接 replay。");
    if (has("memory_route")) lines.push("2. Rosen/UMA 路由：把新問題折到已知任務族、記憶頁、工具與驗證規則，不從零搜尋。");
    if (has("latency_hot_path")) lines.push("3. 熱路徑控制：毫秒內只跑 CPU 反射弧與神經元路由，Qwen 生成排到慢路徑。");
    if (has("first_generation")) lines.push("4. 長文策略：先給章節骨架與可驗證指標，再由背景 worker 補完整段落。");
    if (!families.length) lines.push("1. 先用 reflex/cache/語意橋回覆；2. 背景補完；3. 下次同類問題毫秒 replay。");
    lines.push("界線：這不是清 RAM 或關程式；它加速的是本地 AI 工作流，不宣稱 GPU 算力真的變大。");
  } else {
    lines.push("Mercury instant path: return a useful scaffold now, then let the local model complete/refine in the background.");
    if (has("local_llm_speed")) lines.push("1. Local LLM speed: keep the selected model warm, avoid slow 14B routes when 7B is faster, and replay repeated work.");
    if (has("memory_route")) lines.push("2. Rosen/UMA routing: fold the request into known task families, memory pages, tools, and verification gates.");
    if (has("latency_hot_path")) lines.push("3. Hot path control: run only CPU reflex/neuron routing immediately; queue Qwen generation off the hot path.");
    if (has("first_generation")) lines.push("4. Long-form work: return a section scaffold first, then fill sections through background workers.");
    if (!families.length) lines.push("1. Answer from reflex/cache/semantic bridges first. 2. Complete in the background. 3. Replay the next similar request in milliseconds.");
    lines.push("Boundary: this is local AI workflow acceleration, not RAM cleaning or a generic PC booster.");
  }
  const bridges = rosenStaticBridges(entry).slice(0, 4).map((bridge) => ({
    to: bridge.to,
    risk_family: bridge.risk_family,
    evidence: bridge.evidence
  }));
  return {
    mode: "ai_accelerator_instant_rosen_scaffold",
    elapsed_ms: Date.now() - started,
    model,
    intent,
    response: lines.join("\n"),
    rosen: {
      risk_families: entry.risk_families,
      bridge_count: bridges.length,
      bridges
    },
    boundary: "instant scaffold; background model completion may refine it"
  };
}

