  mkdirSync(benchDir, { recursive: true });
  const target = "var/bench/uma-hot-pages/hot_cache.js";
  writeFileSync(resolve(process.cwd(), target), [
    "export function hotCacheLookup(input) {",
    "  return `cache latency uma hot page promotion ${input}`;",
    "}"
  ].join("\n"), "utf8");
  const pages = ingestUmaFile(target, { namespace, maxChars: 700, maxChunks: 4 });
  writeUmaNamespaceIndex(namespace, pages);
  const started = Date.now();
  for (let i = 0; i < 3; i += 1) {
    umaSearch(`diagnose ${target} cache latency hot page promotion`, { namespace, limit: 2 });
  }
  flushUmaHitStats();
  const summary = umaHotPageSummary(namespace, 4);
  const hotCache = writeUmaHotCache(namespace, 4);
