function benchNeuronCatalog500() {
  const coldStarted = Date.now();
  const neurons = loadNeurons();
  const ids = new Set(neurons.map((neuron) => neuron.id));
  const types = neurons.reduce((acc, neuron) => {
    acc[neuron.type] = (acc[neuron.type] || 0) + 1;
    return acc;
  }, {});
  const clusters = neurons.reduce((acc, neuron) => {
    acc[neuron.cluster || neuronCluster(neuron.id)] = (acc[neuron.cluster || neuronCluster(neuron.id)] || 0) + 1;
    return acc;
  }, {});
  const lanes = neurons.reduce((acc, neuron) => {
    acc[neuron.lane || neuronParallelLane(neuron)] = (acc[neuron.lane || neuronParallelLane(neuron)] || 0) + 1;
    return acc;
  }, {});
  const missingPlacement = neurons.filter((neuron) => !neuron.cluster || !neuron.lane || !neuron.substrate || !neuron.shard_family || neuron.dispatch_phase === undefined);
  const task = "accelerate UMA RAG qwer windows monster repo with hot page promotion and provider hint cache";
  const coldCircuit = classifyTask(task, neurons);
  const coldScheduled = scheduleCircuit(coldCircuit);
  const coldContext = createRunContext(task);
  coldContext.neuronControlMap = buildNeuronControlMap(coldScheduled, coldContext, task);
  const coldPreGuard = executableCircuitForPlan(coldScheduled, coldContext, coldContext.taskText);
  const coldExecutable = applyResourceGuard(coldPreGuard, coldContext, coldContext.taskText);
  const coldElapsed = Date.now() - coldStarted;
  const warmStarted = Date.now();
  const circuit = classifyTask(task, neurons);
  const scheduled = scheduleCircuit(circuit);
  const context = createRunContext(task);
  context.neuronControlMap = buildNeuronControlMap(scheduled, context, task);
  const preGuard = executableCircuitForPlan(scheduled, context, context.taskText);
  const executable = applyResourceGuard(preGuard, context, context.taskText);
  const elapsed = Date.now() - warmStarted;
  const requiredTypes = ["intent", "retrieval", "decompose", "explore", "analyze", "risk", "accelerate", "memory", "verify", "recompose", "critic", "safety", "compression", "synthesis"];
  const requiredClusters = ["decompose", "retrieval", "risk", "accelerate", "memory", "judge", "synthesis"];
  const requiredLanes = ["goal_lane", "memory_retrieval_lane", "surface_lane", "analysis_lane", "risk_lane", "acceleration_lane", "writeback_lane", "judge_lane", "verification_lane", "synthesis_lane"];
  const budgetOk = neurons.length >= MIN_PHYSICAL_NEURONS
    && ids.size === neurons.length
    && requiredTypes.every((type) => (types[type] || 0) >= 1)
    && requiredClusters.every((cluster) => (clusters[cluster] || 0) >= 1)
    && requiredLanes.every((lane) => (lanes[lane] || 0) >= 1)
    && missingPlacement.length === 0
    && circuit.length >= 20
    && context.neuronControlMap.selected_for_parallel_lanes >= 20
    && executable.length >= 12
    && executable.length <= 28
    && elapsed <= 120;
  console.log("Neuron Mercury physical neuron catalog bench");
  console.log(`neurons: ${neurons.length}`);
  console.log(`unique_ids: ${ids.size}`);
  console.log(`types: ${JSON.stringify(types)}`);
  console.log(`clusters: ${JSON.stringify(clusters)}`);
  console.log(`lanes: ${JSON.stringify(lanes)}`);
  console.log(`missing_placement: ${missingPlacement.length}`);
  console.log(`classified_circuit: ${circuit.length}`);
  console.log(`selected_parallel_lanes: ${context.neuronControlMap.selected_for_parallel_lanes}`);
  console.log(`pre_guard: ${preGuard.length}`);
  console.log(`cold_executable_after_guard: ${coldExecutable.length}`);
  console.log(`executable_after_guard: ${executable.length}`);
  console.log(`cold_elapsed_ms: ${coldElapsed}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log(`speed budget: ${budgetOk ? "pass" : "fail"}`);
  if (!budgetOk) process.exitCode = 1;
}

