  const topology = buildNeuronTopology(["--target=100000000"]);
  const missingPlacement = neurons.filter((neuron) => !neuron.cluster || !neuron.lane || !neuron.substrate || !neuron.shard_family || neuron.dispatch_phase === undefined || !neuron.placement || !Array.isArray(neuron.entangles_with));
  const orphaned = topology.nodes.filter((node) => !(node.entangles_with || []).length);
  const task = "accelerate qwen cold start windows diskspd uma rag rosen bridge monster repo scheduler coverage";
