  context.neuronControlMap = buildNeuronControlMap(scheduled, context, task);
  const preGuard = executableCircuitForPlan(scheduled, context, task);
  const executable = applyResourceGuard(preGuard, context, task);
  const metrics = neuronControlActivationMetrics(context.neuronControlMap);
  const explorationSelected = Object.values(context.neuronControlMap.lanes || {})
    .flatMap((lane) => lane.selected || [])
    .filter((item) => item.source === "topology_exploration");
  const elapsed = Date.now() - coldStarted;
