function benchNeuronDeploymentMap1000(args = []) {
  const started = Date.now();
  const neurons = loadNeurons();
  const topology = buildNeuronTopology(["--target=100000000"]);
  const sensors = stateFieldSensorSnapshot({ fast: true });
  const field = observeNeuronStateField({ persist: true, refresh: true, fast: true, sensors });
  const hot = readNeuronStateHotMap({ refresh: true });
  const task = "deploy 1000 thermal rosen neurons across uma rag qwen 3060 disk io memory spend monster doctor scheduler";
  const context = createRunContext(task);
  context.neuronStateHotMap = hot;
  const circuit = scheduleCircuit(classifyTask(task, neurons));
  context.neuronControlMap = buildNeuronControlMap(circuit, context, task);
  const selected = neuronControlSelectionIndex(context.neuronControlMap);
  const rows = neurons.map((neuron) => {
    const binding = neuronStateBinding(neuron);
    const hotState = hot.get(neuron.id);
    const control = selected.get(neuron.id);
    return {
      id: neuron.id,
      type: neuron.type,
      cluster: neuron.cluster || neuronCluster(neuron.id),
      lane: neuron.lane || neuronParallelLane(neuron),
      domain: neuronDomain(neuron),
      substrate: neuron.substrate || "runtime",
      shard_family: neuron.shard_family || "core",
      dispatch_phase: neuron.dispatch_phase || 0,
      observable: binding.observable,
      sensor: binding.sensor,
      state_key: binding.state_key,
      thresholds: binding.thresholds,
      writeback: binding.writeback,
      entangles_with: neuron.entangles_with || [],
      collapse_state: hotState?.collapse_state || "cold",
      heat: hotState?.heat || 0,
      control_source: control?.source || "not_selected",
      control_score: control?.score || 0,
      state_boost: control?.state_boost || 0,
      rosen_boost: control?.rosen_boost || 0
    };
  });
  const countBy = (key) => rows.reduce((acc, row) => {
    const value = row[key] || "unknown";
    acc[value] = (acc[value] || 0) + 1;
    return acc;
  }, {});
  const writebackTargets = {};
  for (const row of rows) {
    for (const target of row.writeback || []) writebackTargets[target] = (writebackTargets[target] || 0) + 1;
  }
  const controlSources = context.neuronControlMap.selected_by_source || {};
  const controlCollapseStates = context.neuronControlMap.selected_by_collapse_state || {};
  const stateKeys = new Set(rows.map((row) => row.state_key));
  const observables = new Set(rows.map((row) => row.observable));
  const entanglementEdges = rows.reduce((sum, row) => sum + (row.entangles_with || []).length, 0);
  const elapsed = Date.now() - started;
  const pass = rows.length >= MIN_PHYSICAL_NEURONS
    && topology.neurons >= MIN_PHYSICAL_NEURONS
    && observables.size >= 7
    && stateKeys.size >= 20
    && Object.keys(writebackTargets).length >= 8
    && entanglementEdges >= MIN_PHYSICAL_NEURONS
    && hot.size >= 24
    && (controlSources.state_field || 0) + (controlSources.topology_exploration || 0) >= 6
    && Object.keys(controlCollapseStates).length >= 2
    && context.neuronControlMap.selected_for_parallel_lanes >= 24
    && elapsed <= 2500;
  const artifact = {
    schema: "mercury-neuron-deployment-map-1000-v1",
    created_at: nowIso(),
    pass,
    elapsed_ms: elapsed,
    summary: {
      neurons: rows.length,
      observables: observables.size,
      state_keys: stateKeys.size,
      entanglement_edges: entanglementEdges,
      hot_map_size: hot.size,
      selected_for_parallel_lanes: context.neuronControlMap.selected_for_parallel_lanes,
      control_sources: controlSources,
      control_collapse_states: controlCollapseStates
    },
    surfaces: {
      observables: countBy("observable"),
      sensors: countBy("sensor"),
      state_keys: countBy("state_key"),
      clusters: countBy("cluster"),
      lanes: countBy("lane"),
      substrates: countBy("substrate"),
      collapse_states: countBy("collapse_state"),
      writeback_targets: writebackTargets
    },
    topology: {
      neurons: topology.neurons,
      edges: topology.edges,
      domains: Object.keys(topology.domains || {}).length,
      virtual_target: topology.virtual_target || ONE_HUNDRED_MILLION_NEURONS
    },
    top_selected: Object.values(context.neuronControlMap.lanes || {})
      .flatMap((lane) => lane.selected || [])
      .sort((a, b) => b.score - a.score)
      .slice(0, 40),
    placement: rows
  };
  const benchPath = join(BENCH_DIR, "neuron-deployment-map-1000.json");
  const mapPath = join(VAR_DIR, "neuron-deployment-map-1000.json");
  atomicWriteJson(benchPath, artifact, { pretty: true });
  atomicWriteJson(mapPath, artifact, { pretty: true });
  console.log("Neuron Mercury physical neuron deployment map bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`neurons: ${rows.length}`);
  console.log(`observables: ${observables.size}`);
  console.log(`state_keys: ${stateKeys.size}`);
  console.log(`entanglement_edges: ${entanglementEdges}`);
  console.log(`hot_map_size: ${hot.size}`);
  console.log(`selected_for_parallel_lanes: ${context.neuronControlMap.selected_for_parallel_lanes}`);
  console.log(`control_sources: ${JSON.stringify(controlSources)}`);
  console.log(`control_collapse_states: ${JSON.stringify(controlCollapseStates)}`);
  console.log(`map: ${mapPath}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return artifact;
}

