function benchNeuronConcurrentControl3000(args = []) {
  const started = Date.now();
  const neurons = loadNeurons();
  const tasks = [
    "qwen first useful packet big model local llm kv prefix attention decode",
    "deepseek first useful packet ollama large model speculative probe",
    "uma rag evidence context reduction before model call",
    "gpu pressure 3060 low impact foreground safe model preheat",
    "memory bandwidth hot pages cache coherence first answer",
    "provider avoidance spend guard slow path distill",
    "background completion merge first packet with full model",
    "judge packet quality truthfulness uncertainty probe",
    "multi model matrix qwen deepseek compare first packet",
    "windows hotpath wsl ext4 disk io no regression",
    "anti overactivation concurrent lane budget",
    "resident preheat speed state cache warm"
  ];
  const perTask = [];
  const selectedAll = new Map();
  for (const task of tasks) {
    const context = createRunContext(task);
    const scheduled = scheduleCircuit(classifyTask(task, neurons));
    context.neuronControlMap = buildNeuronControlMap(scheduled, context, task);
    const selected = [...neuronControlSelectionIndex(context.neuronControlMap).keys()];
    for (const id of selected) selectedAll.set(id, (selectedAll.get(id) || 0) + 1);
    perTask.push({
      task,
      classified: scheduled.length,
      selected: selected.length,
      model_field: selected.filter((id) => /\.model_(external|internal)_/.test(id)).length,
      concurrent_control: selected.filter((id) => /\.concurrent_/.test(id)).length,
      sources: context.neuronControlMap.selected_by_source || {},
      collapse_states: context.neuronControlMap.selected_by_collapse_state || {}
    });
  }
  const uniqueIds = [...selectedAll.keys()];
  const uniqueModelField = uniqueIds.filter((id) => /\.model_(external|internal)_/.test(id)).length;
  const uniqueConcurrent = uniqueIds.filter((id) => /\.concurrent_/.test(id)).length;
  const maxPerTask = Math.max(...perTask.map((row) => row.selected));
  const minPerTask = Math.min(...perTask.map((row) => row.selected));
  const elapsed = Date.now() - started;
  const pass = neurons.length >= MIN_PHYSICAL_NEURONS
    && perTask.length >= 12
    && uniqueIds.length >= 120
    && uniqueModelField >= 15
    && uniqueConcurrent >= 24
    && maxPerTask <= 36
    && minPerTask >= 12
    && elapsed <= 900;
  const out = {
    schema: "mercury-neuron-concurrent-control-3000-v1",
    created_at: nowIso(),
    pass,
    elapsed_ms: elapsed,
    catalog_neurons: neurons.length,
    task_lanes: perTask.length,
    unique_controlled_neurons: uniqueIds.length,
    unique_model_field_neurons: uniqueModelField,
    unique_concurrent_control_neurons: uniqueConcurrent,
    max_selected_per_task: maxPerTask,
    min_selected_per_task: minPerTask,
    policy: "control many neurons across simultaneous task lanes while keeping each hot path sparsely activated",
    per_task: perTask
  };
  atomicWriteJson(join(BENCH_DIR, "neuron-concurrent-control-3000.json"), out, { pretty: true });
  console.log("Neuron Mercury 3000-neuron concurrent control bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`catalog: ${neurons.length}`);
  console.log(`task_lanes: ${perTask.length}`);
  console.log(`unique_controlled_neurons: ${uniqueIds.length}`);
  console.log(`unique_model_field_neurons: ${uniqueModelField}`);
  console.log(`unique_concurrent_control_neurons: ${uniqueConcurrent}`);
  console.log(`selected_per_task: ${minPerTask}-${maxPerTask}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return out;
}

