  const selected = [...neuronControlSelectionIndex(context.neuronControlMap).values()];
  const stateBoosted = selected.filter((item) => Number(item.state_boost || 0) > 0);
  const elapsed = Date.now() - started;
  const pass = replay.schema === NEURON_STATE_FIELD_SCHEMA
    && replay.summary.total_neurons >= MIN_PHYSICAL_NEURONS
