function benchNeuronThermalCollapse(args = []) {
  const started = Date.now();
  const baseSensors = stateFieldSensorSnapshot({ fast: true });
  const seed = observeNeuronStateField({ persist: true, refresh: true, sensors: baseSensors });
  const heatedSensors = JSON.parse(JSON.stringify(baseSensors));
  heatedSensors.created_at = nowIso();
  heatedSensors.uma.needs_file_table_refresh = true;
  heatedSensors.uma.updated_at = `${baseSensors.uma.updated_at || ""}:thermal-delta`;
  heatedSensors.hot.pages = Number(heatedSensors.hot.pages || 0) + 7;
  heatedSensors.hot.events = Number(heatedSensors.hot.events || 0) + 11;
  heatedSensors.host.memory_free_ratio = 0.08;
  heatedSensors.product.disk_ratio = 0.84;
  heatedSensors.rosen.correction_pulse = Number(heatedSensors.rosen.correction_pulse || 0) + 1;
  const heated = observeNeuronStateField({ persist: true, refresh: true, sensors: heatedSensors });
  const hot = readNeuronStateHotMap({ refresh: true });
  const states = heated.summary.collapse_states || {};
  const hotRows = [...hot.values()];
  const writebackRows = hotRows.filter((item) => Array.isArray(item.writeback) && item.writeback.length);
  const readyRows = hotRows.filter((item) => ["ready_to_route", "critical", "needs_refresh", "promote", "avoid"].includes(item.collapse_state));
  const elapsed = Date.now() - started;
  const pass = heated.summary.total_neurons >= MIN_PHYSICAL_NEURONS
    && heated.summary.hot_neurons >= 24
    && Number(states.needs_refresh || 0) >= 1
    && Number(states.avoid || 0) >= 1
    && (Number(states.ready_to_route || 0) + Number(states.critical || 0) + Number(states.promote || 0)) >= 8
    && writebackRows.length >= 24
    && readyRows.length >= 12
    && hot.size <= 160
    && elapsed <= 2200;
  const artifact = {
    schema: "mercury-neuron-thermal-collapse-bench-v1",
    created_at: nowIso(),
    pass,
    elapsed_ms: elapsed,
    seed: {
      mode: seed.mode,
      hot_neurons: seed.summary.hot_neurons,
      collapse_states: seed.summary.collapse_states
    },
    heated: {
      mode: heated.mode,
      changed_neurons: heated.summary.changed_neurons,
      hot_neurons: heated.summary.hot_neurons,
      collapse_states: states
    },
    hot_map_size: hot.size,
    writeback_rows: writebackRows.length,
    ready_rows: readyRows.length,
    top_hot: heated.summary.top_hot.slice(0, 16),
    policy: "thermal pulses collapse state-bound neurons into route states before the task hot path reads latest-hot.json"
  };
  atomicWriteJson(join(BENCH_DIR, "neuron-thermal-collapse.json"), artifact, { pretty: true });
  console.log("Neuron Mercury neuron thermal collapse bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`hot_map_size: ${hot.size}`);
  console.log(`changed_neurons: ${heated.summary.changed_neurons}`);
  console.log(`states: ${Object.entries(states).map(([key, value]) => `${key}=${value}`).join(" ")}`);
  console.log(`writeback_rows: ${writebackRows.length}`);
  console.log(`ready_rows: ${readyRows.length}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return artifact;
}

