function benchControlMapScoreRouting() {
  const started = Date.now();
  const task = "accelerate UMA RAG qwer windows monster repo with hot page promotion and provider hint cache";
  const neurons = loadNeurons();
  const context = createRunContext(task);
  const circuit = scheduleCircuit(classifyTask(task, neurons));
  context.neuronControlMap = buildNeuronControlMap(circuit, context, task);
  const lane = Object.values(context.neuronControlMap.lanes)
    .find((item) => item.candidate_count > item.budget && item.selected_count >= item.budget);
  const selectedBefore = new Set((lane?.selected || []).map((item) => item.id));
  const promote = circuit.find((neuron) =>
    neuronParallelLane(neuron) === lane?.lane
    && !selectedBefore.has(neuron.id)
    && !neuron.id.startsWith("git.")
    && neuron.id !== "tool.file_outline"
  );
  const previousSummary = NEURON_SCORE_SUMMARY_CACHE;
  let afterContext = createRunContext(task);
  let afterCircuit = circuit;
  let selectedAfter = new Map();
  let executable = [];
  let routeElapsed = 0;
  try {
    if (promote) {
      const summary = new Map(neuronScoreSummary());
      summary.set(promote.id, {
        runs: 1,
        utility: 180,
        elapsed: 0,
        high: 6
      });
      NEURON_SCORE_SUMMARY_CACHE = summary;
    }
    const routeStarted = Date.now();
    afterContext = createRunContext(task);
    afterCircuit = scheduleCircuit(classifyTask(task, neurons));
    afterContext.neuronControlMap = buildNeuronControlMap(afterCircuit, afterContext, task);
    selectedAfter = neuronControlSelectionIndex(afterContext.neuronControlMap);
    executable = applyResourceGuard(executableCircuitForPlan(afterCircuit, afterContext, task), afterContext, task);
    routeElapsed = Date.now() - routeStarted;
  } finally {
    NEURON_SCORE_SUMMARY_CACHE = previousSummary;
  }
  const elapsed = Date.now() - started;
  const budgetOk = Boolean(promote)
    && selectedAfter.has(promote.id)
    && afterContext.neuronControlMap.selected_for_parallel_lanes >= 20
    && executable.length >= 12
    && executable.length <= 28
    && routeElapsed <= 80;
  console.log("Neuron Mercury control-map score routing bench");
  console.log(`lane: ${lane?.lane || "-"}`);
  console.log(`promoted_neuron: ${promote?.id || "-"}`);
  console.log(`selected_after: ${promote ? selectedAfter.has(promote.id) : false}`);
  console.log(`selected_parallel_lanes: ${afterContext.neuronControlMap.selected_for_parallel_lanes}`);
  console.log(`executable_after_guard: ${executable.length}`);
  console.log(`routing_elapsed_ms: ${routeElapsed}`);
  console.log(`total_elapsed_ms: ${elapsed}`);
  console.log(`speed budget: ${budgetOk ? "pass" : "fail"}`);
  if (!budgetOk) process.exitCode = 1;
}

