function benchDocsConsistency() {
  const started = Date.now();
  const files = ["README.md", "docs/SCALE_FOUNDATION.md", "docs/ARCHITECTURE.md"];
  const stalePatterns = [
    /\b60-neuron\b/i,
    /\b60 physical seed neurons\b/i,
    /\b60 measured neurons\b/i,
    /\bcurrent 60\b/i,
    /\b200-neuron\b/i,
    /\b200 neurons\b/i,
    /\bcatalog now has 200\b/i,
    /\bcatalog now contains 200\b/i
  ];
  const findings = [];
  for (const file of files) {
    const abs = join(ROOT, file);
    if (!existsSync(abs)) continue;
    const text = readFileSync(abs, "utf8");
    for (const pattern of stalePatterns) {
      if (pattern.test(text)) findings.push({ file, pattern: String(pattern) });
    }
  }
  const neuronCount = loadNeurons().length;
  const elapsed = Date.now() - started;
  const budgetOk = neuronCount >= 500
    && findings.length === 0
    && elapsed <= 30;
  console.log("Neuron Mercury docs consistency bench");
  console.log(`neurons: ${neuronCount}`);
  console.log(`stale_refs: ${findings.length}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log(`speed budget: ${budgetOk ? "pass" : "fail"}`);
  if (!budgetOk) process.exitCode = 1;
}

