function benchLlmFastFinalMerge() {
  const salt = stableHash(["llm-fast-final-merge", process.pid, Date.now(), Math.random()]);
  const model = DEFAULT_LOCAL_LLM_MODEL;
  const intent = `bench.llm_fast.final_merge.${salt}`;
  const prompt = `Mercury first packet final merge proof ${salt}`;
  const parsed = {
    url: process.env.OLLAMA_URL || "http://127.0.0.1:11434",
    model,
    intent,
    prompt,
    enqueueMiss: true,
    numPredict: 64
  };
  const started = Date.now();
  const first = llmFastPreheatFirstResult(parsed, started);
  const jobId = first?.background_completion?.job_id;
  const jobPath = jobId ? slowJobPath(jobId) : null;
  const job = jobPath && existsSync(jobPath) ? readSlowJobFile(jobPath) : null;
  const finalResponse = `Mercury final merge answer ${salt}: first packet gives an immediate useful answer, while the background completion writes the full answer into the reflex/LLM cache so the next identical intent becomes a millisecond cache hit.`;
  let seeded = null;
  if (job) {
    seeded = reflexSeed({
      model: job.model || model,
      intent: job.intent,
      prompt: job.prompt_norm,
      response: finalResponse
    });
    job.status = "seeded";
    job.seeded_at = nowIso();
    job.response_bytes = Buffer.byteLength(finalResponse);
    job.cache_path = seeded.cache_path;
    job.provider_cache_path = null;
    writeSlowJob(job);
  }
  const statusStarted = Date.now();
  const status = slowJobStatusPayload(jobId);
  const statusMs = Date.now() - statusStarted;
  const replayStarted = Date.now();
  const replay = readLlmCache(parsed);
  const replayMs = Date.now() - replayStarted;
  const elapsed = Date.now() - started;
  const pass = Boolean(first)
    && Number(first.response_chars || 0) >= 80
    && Boolean(job)
    && status.ok
    && status.status === "seeded"
    && status.response_ready
    && status.response === finalResponse
    && replay.entry?.response === finalResponse
    && statusMs <= 8
    && replayMs <= 5
    && elapsed <= 500;
  const artifact = {
    schema: "mercury-llm-fast-final-merge-bench-v1",
    created_at: nowIso(),
    pass,
    elapsed_ms: elapsed,
    first_packet_ms: first?.packet?.elapsed_ms ?? null,
    first_answer_chars: first?.response_chars || 0,
    job_id: jobId || null,
    status_ms: statusMs,
    status: status.status || null,
    response_ready: Boolean(status.response_ready),
    response_source: status.response_source || null,
    final_response_chars: finalResponse.length,
    replay_ms: replayMs,
    replay_mode: replay.entry ? "cache_hit" : "cache_miss",
    cache_path: replay.path || null
  };
  atomicWriteJson(join(BENCH_DIR, "llm-fast-final-merge.json"), artifact, { pretty: true });
  if (jobPath && existsSync(jobPath)) unlinkSync(jobPath);
  if (seeded?.cache_path && existsSync(seeded.cache_path)) unlinkSync(seeded.cache_path);
  if (replay.path && existsSync(replay.path)) {
    try { unlinkSync(replay.path); } catch {}
  }
  console.log("Neuron Mercury LLM fast final merge bench");
  console.log(`first_packet_ms: ${artifact.first_packet_ms ?? "-"}`);
  console.log(`first_answer_chars: ${artifact.first_answer_chars}`);
  console.log(`job_id: ${artifact.job_id || "-"}`);
  console.log(`status: ${artifact.status || "-"} ready=${artifact.response_ready ? "yes" : "no"} source=${artifact.response_source || "-"}`);
  console.log(`status_ms: ${artifact.status_ms}`);
  console.log(`replay_ms: ${artifact.replay_ms}`);
  console.log(`elapsed_ms: ${artifact.elapsed_ms}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
}

