function benchWorkflowMemory() {
  const graphRowCount = () => {
    if (!existsSync(memoryGraphPath())) return 0;
    const counted = safeExec("wc", ["-l", memoryGraphPath()], { timeout: 1000, maxBuffer: 1024 });
    const value = Number(String(counted.output || "").trim().split(/\s+/)[0]);
    return Number.isFinite(value) ? value : 0;
  };
  const beforeGraphRows = existsSync(memoryGraphPath())
    ? graphRowCount()
    : 0;
  const result = executePlan("accelerate src/mercury.js with workflow cache memory graph resource guard", {
    profile: true,
    umaNamespace: "bench-workflow-memory",
    usePlanCache: false,
    umaBudgetMs: 12
  });
  const workflowPath = workflowCachePathFor("accelerate src/mercury.js with workflow cache memory graph resource guard", "bench-workflow-memory");
  const workflowExists = existsSync(workflowPath);
  const afterGraphRows = existsSync(memoryGraphPath())
    ? graphRowCount()
    : 0;
  const guardFiles = readdirSync(RESOURCE_GUARD_DIR).filter((name) => /^guard_[a-f0-9]{24}\.json$/.test(name));
  const graphOk = afterGraphRows > beforeGraphRows || (beforeGraphRows === 0 && afterGraphRows === 0);
  const budgetOk = result.elapsedMs <= 1500 && workflowExists && graphOk && guardFiles.length > 0;
  console.log("Neuron Mercury workflow memory bench");
  console.log(`elapsed_ms: ${result.elapsedMs}`);
  console.log(`workflow_exists: ${workflowExists ? "yes" : "no"}`);
  console.log(`graph_rows_before: ${beforeGraphRows}`);
  console.log(`graph_rows_after: ${afterGraphRows}`);
  console.log(`resource_guard_files: ${guardFiles.length}`);
  console.log(`speed budget: ${budgetOk ? "pass" : "fail"}`);
  if (!budgetOk) process.exitCode = 1;
}

