function benchUmaProductProof() {
  const started = Date.now();
  const namespace = `bench-uma-product-${stableHash([process.pid, Date.now(), Math.random()])}`;
  const target = "var/bench/uma-product-proof/hot_route.js";
  mkdirSync(dirname(resolve(process.cwd(), target)), { recursive: true });
  atomicWriteText(resolve(process.cwd(), target), [
    "class UmaProductRoute {}",
    "function loadUmaProductCache() { return 'sqlite queue retry latency product proof'; }",
    "app.get('/uma-product', loadUmaProductCache);",
    "export { UmaProductRoute, loadUmaProductCache };"
  ].join("\n"));
  const targetPages = ingestUmaFile(target, { namespace, maxChars: 2000, maxChunks: 4 });
  const pages = [...targetPages];
  for (let i = 0; i < 5000; i += 1) {
    const text = `broad cold scan noise document ${i} latency queue retry cache unrelated`;
    pages.push({
      page_id: stableHash(["uma-product-noise", i]),
      namespace,
      pointer: `noise/product_corpus.md#chunk-${i}`,
      source_path: "noise/product_corpus.md",
      source_mtime_ms: i,
      source_size: text.length,
      text,
      tokens: umaTokenArray(text)
    });
  }
  const coldNeedles = umaTokenArray("sqlite queue retry latency product proof loadUmaProductCache UmaProductRoute");
  const coldScanStarted = Date.now();
  const coldScores = [];
  for (const page of pages) {
    const tokens = umaTokenArray(page.text);
    let score = 0;
    for (const needle of coldNeedles) {
      if (tokens.includes(needle)) score += 1;
    }
    if (score > 0) coldScores.push({ page, score });
  }
  coldScores.sort((a, b) => b.score - a.score || a.page.pointer.localeCompare(b.page.pointer));
  const coldMatches = coldScores.slice(0, 8).map((item) => item.page);
  const coldScanMs = Date.now() - coldScanStarted;
  writeUmaNamespaceIndex(namespace, pages);
  const targetQuery = `diagnose ${target} sqlite queue retry latency product proof`;
  const symbolQuery = "diagnose loadUmaProductCache UmaProductRoute /uma-product without file path";
  const targetFirst = umaSearch(targetQuery, { namespace, limit: 4, budgetMs: 6 });
  const symbolFirst = umaSearch(symbolQuery, { namespace, limit: 4, budgetMs: 6 });
  for (let i = 0; i < 3; i += 1) umaSearch(targetQuery, { namespace, limit: 2, budgetMs: 6 });
  flushUmaHitStats();
  const hotCache = writeUmaHotCache(namespace, 4);
  const hotFirst = umaSearch("sqlite queue retry latency product proof without file path", { namespace, limit: 4, budgetMs: 6 });
  const batch = umaBatchSearch([
    targetQuery,
    symbolQuery,
    "sqlite queue retry latency product proof without file path",
    targetQuery
  ], { namespace, limit: 3, budgetMs: 6, maxQueries: 8 });
  const umaRouteMs = [targetFirst.elapsed_ms, symbolFirst.elapsed_ms, hotFirst.elapsed_ms]
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value));
  const fastestUmaMs = umaRouteMs.length ? Math.max(1, Math.min(...umaRouteMs)) : Infinity;
  const speedup = Number((Math.max(1, coldScanMs) / fastestUmaMs).toFixed(2));
  const pass = pages.length >= 5000
    && coldMatches.length >= 1
    && targetFirst.target_file_first
    && symbolFirst.symbol_first
    && hotFirst.hot_page_first
    && batch.ok
    && batch.route_counts.target_file_first >= 1
    && targetFirst.candidate_pages <= targetPages.length
    && symbolFirst.candidate_pages <= targetPages.length
    && hotCache.pages.length >= 1
    && fastestUmaMs <= 6
    && speedup >= 2;
  const artifact = {
    schema: "mercury-uma-product-proof-v1",
    created_at: nowIso(),
    pass,
    namespace,
    pages: pages.length,
    target_pages: targetPages.length,
    cold_scan_ms: coldScanMs,
    cold_scan_kind: "unindexed tokenization plus full-page scoring",
    cold_matches: coldMatches.length,
    target_first_ms: targetFirst.elapsed_ms,
    symbol_first_ms: symbolFirst.elapsed_ms,
    hot_page_ms: hotFirst.elapsed_ms,
    batch_ms: batch.elapsed_ms,
    fastest_uma_ms: fastestUmaMs,
    speedup_vs_cold_scan: speedup,
    routes: {
      target_file_first: targetFirst.target_file_first,
      symbol_first: symbolFirst.symbol_first,
      hot_page_first: hotFirst.hot_page_first,
      batch: batch.route_counts
    },
    boundaries: [
      "This measures retrieval and evidence routing, not model generation.",
      "Cold scan is deterministic broad page filtering over the same synthetic namespace.",
      "UMA acceleration comes from project namespace, source page table, symbol table, hot-page cache, and batch query fanout."
    ]
  };
  atomicWriteJson(join(BENCH_DIR, "uma-product-proof.json"), artifact, { pretty: true });
  console.log("Neuron Mercury UMA product proof");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`pages: ${pages.length}`);
  console.log(`cold_scan_ms: ${coldScanMs}`);
  console.log(`target_first_ms: ${targetFirst.elapsed_ms}`);
  console.log(`symbol_first_ms: ${symbolFirst.elapsed_ms}`);
  console.log(`hot_page_ms: ${hotFirst.elapsed_ms}`);
  console.log(`batch_ms: ${batch.elapsed_ms}`);
  console.log(`speedup_vs_cold_scan: ${speedup}x`);
  console.log(`routes: target=${targetFirst.target_file_first ? "yes" : "no"} symbol=${symbolFirst.symbol_first ? "yes" : "no"} hot=${hotFirst.hot_page_first ? "yes" : "no"}`);
  console.log(`elapsed_ms: ${Date.now() - started}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return artifact;
}

