async function benchResidentThermalStateEndpoint(args = []) {
  const parsed = parseBenchResidentArgs(args);
  const health = await waitForHttpOk(`${parsed.url}/health`, { timeoutMs: 4000, intervalMs: 100, probeTimeout: 800 });
  if (!health.ok) {
    console.log("Neuron Mercury resident thermal state endpoint bench");
    console.log(`url: ${parsed.url}`);
    console.log(`mode: unavailable (${health.attempts_error})`);
    console.log("speed budget: fail");
    process.exitCode = 1;
    return;
  }
  const firstStarted = Date.now();
  let first;
  try {
    first = await fetchJson(`${parsed.url}/thermal-state?limit=160`, { timeout: 5000 });
  } catch (error) {
    first = { ok: false, status: error.name || "error", json: { error: error.message } };
  }
  const firstMs = Date.now() - firstStarted;
  const fullStarted = Date.now();
  let full;
  try {
    full = await fetchJson(`${parsed.url}/thermal-state?full=1&refresh=1&limit=160`, { timeout: 5000 });
  } catch (error) {
    full = { ok: false, status: error.name || "error", json: { error: error.message } };
  }
  const fullMs = Date.now() - fullStarted;
  const replayStarted = Date.now();
  let replay;
  try {
    replay = await fetchJson(`${parsed.url}/neuron-state-field?limit=160`, { timeout: 5000 });
  } catch (error) {
    replay = { ok: false, status: error.name || "error", json: { error: error.message } };
  }
  const replayMs = Date.now() - replayStarted;
  const firstJson = first.json || {};
  const fullJson = full.json || {};
  const replayJson = replay.json || {};
  const firstRows = firstJson.neurons || [];
  const replayRows = replayJson.neurons || [];
  const collapseStates = fullJson.summary?.collapse_states || firstJson.summary?.collapse_states || {};
  const pass = first.ok
    && full.ok
    && replay.ok
    && firstRows.length >= 24
    && replayRows.length >= 24
    && firstRows.some((item) => Number(item.heat || 0) > 0)
    && firstRows.some((item) => item.collapse_state && item.collapse_state !== "cold")
    && Object.keys(collapseStates).length >= 3
    && firstMs <= 80
    && replayMs <= 80
    && fullMs <= 1800;
  const artifact = {
    schema: "mercury-resident-thermal-state-endpoint-bench-v1",
    created_at: nowIso(),
    pass,
    url: parsed.url,
    first_ms: firstMs,
    full_ms: fullMs,
    replay_ms: replayMs,
    first_hot_neurons: firstRows.length,
    replay_hot_neurons: replayRows.length,
    collapse_states: collapseStates,
    first_mode: firstJson.mode || null,
    full_mode: fullJson.mode || null
  };
  atomicWriteJson(join(BENCH_DIR, "resident-thermal-state-endpoint.json"), artifact, { pretty: true });
  console.log("Neuron Mercury resident thermal state endpoint bench");
  console.log(`url: ${parsed.url}`);
  console.log(`first_ms: ${firstMs}`);
  console.log(`full_ms: ${fullMs}`);
  console.log(`replay_ms: ${replayMs}`);
  console.log(`hot_neurons: first=${firstRows.length} replay=${replayRows.length}`);
  console.log(`states: ${Object.entries(collapseStates).map(([key, value]) => `${key}=${value}`).join(" ")}`);
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return artifact;
}

