function benchFirstGenDispatchPlan() {
  const started = Date.now();
  const jobs = Array.from({ length: 16 }, (_, index) => ({
    section: index + 1,
    title: `section ${index + 1}`,
    worker: (index % 8) + 1,
    wave: Math.floor(index / 8) + 1,
    neuron_id: `bench.neuron.${index + 1}`,
    job_id: `bench-job-${index + 1}`
  }));
  const plan = buildFirstGenDispatchPlan(jobs, 8, 240000);
  const uniqueWorkersPerWave = plan.waves.every((wave) => new Set(wave.lanes.map((lane) => lane.worker)).size === wave.lanes.length);
  const ordered = plan.waves.every((wave, index) => wave.wave === index + 1 && wave.lanes.every((lane, laneIndex) => lane.worker === laneIndex + 1));
  const elapsed = Date.now() - started;
  const budgetOk = plan.sections === 16
    && plan.workers === 8
    && plan.waves.length === 2
    && plan.max_concurrency === 8
    && uniqueWorkersPerWave
    && ordered
    && plan.speedup >= 7.9
    && elapsed <= 30;
  console.log("Neuron Mercury first-generation dispatch plan bench");
  console.log(`sections: ${plan.sections}`);
  console.log(`workers: ${plan.workers}`);
  console.log(`waves: ${plan.waves.length}`);
  console.log(`max_concurrency: ${plan.max_concurrency}`);
  console.log(`speedup: ${plan.speedup}x`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log(`speed budget: ${budgetOk ? "pass" : "fail"}`);
  if (!budgetOk) process.exitCode = 1;
}

