function readLlmCache(parsed) {
  ensureDirs();
  const key = llmIntentCacheKey(parsed);
  const path = llmCachePath(key);
  const memory = LLM_ENTRY_CACHE.get(key);
  if (memory) return memory;
  if (!existsSync(path)) return { key, path, entry: null };
  try {
    const entry = JSON.parse(readFileSync(path, "utf8"));
    const cached = { key, path, entry };
    LLM_ENTRY_CACHE.set(key, cached);
    return cached;
  } catch {
    return { key, path, entry: null };
  }
}

function writeLlmCache(parsed, payload) {
  ensureDirs();
  const key = llmIntentCacheKey(parsed);
  const path = llmCachePath(key);
  const entry = {
    created_at: nowIso(),
    url: parsed.url,
    model: parsed.model,
    intent_key: llmIntentKey(parsed),
    prompt_norm: normalizePrompt(parsed.prompt),
    response: payload.response,
    generate_ms: payload.generate_ms,
    total_duration: payload.total_duration || null,
    eval_count: payload.eval_count || null,
    eval_duration: payload.eval_duration || null
  };
  atomicWriteJson(path, entry);
  LLM_ENTRY_CACHE.set(key, { key, path, entry });
  updateLlmModelIndex(entry.model, llmCacheFileRecord(key, path, entry));
  invalidateSemanticReflexModel(parsed.model);
  return { key, path, entry };
}

async function ollamaGenerate(parsed) {
  const body = {
    model: parsed.model,
    prompt: parsed.prompt,
    stream: false,
    options: {
      num_predict: parsed.numPredict ?? 64,
      temperature: 0
    }
  };
  if (parsed.keepAlive !== undefined) body.keep_alive = parsed.keepAlive;
  const generated = await fetchJson(`${parsed.url}/api/generate`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
    timeout: parsed.timeoutMs || 30000
  });
  if (!generated.ok) {
    const error = new Error(`Ollama generate failed with status ${generated.status}`);
    error.status = generated.status;
    throw error;
  }
  return generated.json || {};
}

async function fetchJson(url, options = {}) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), options.timeout || 8000);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    const text = await response.text();
    let json = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      json = { raw: text };
    }
    return { ok: response.ok, status: response.status, json };
  } finally {
    clearTimeout(timeout);
  }
}

async function waitForHttpOk(url, options = {}) {
  const deadline = Date.now() + (options.timeoutMs || 3000);
  let lastError = null;
  while (Date.now() < deadline) {
    try {
      const res = await fetchJson(url, { timeout: options.probeTimeout || 800 });
      if (res.ok) return { ok: true, attempts_error: null, response: res };
    } catch (error) {
      lastError = `${error.name || "error"}: ${error.message}`;
    }
    await new Promise((resolvePromise) => setTimeout(resolvePromise, options.intervalMs || 100));
  }
  return { ok: false, attempts_error: lastError || "not_ready" };
}

async function llmProbe(args = []) {
  const parsed = parseLlmProbeArgs(args);
  const started = Date.now();
  console.log("Neuron Mercury local LLM probe");
  console.log(`url: ${parsed.url}`);
  try {
    const tags = await fetchJson(`${parsed.url}/api/tags`, { timeout: 4000 });
    const tagMs = Date.now() - started;
    if (!tags.ok) {
      console.log(`status: unavailable (${tags.status})`);
      console.log(`tags_ms: ${tagMs}`);
      process.exitCode = 1;
      return;
    }
    const models = tags.json?.models || [];
    console.log(`status: available`);
    console.log(`tags_ms: ${tagMs}`);
    console.log(`models: ${models.map((model) => model.name).join(", ") || "(none)"}`);
    const model = parsed.model || models[0]?.name;
    if (!model) return;
    parsed.model = model;

    const generateStarted = Date.now();
    const generated = await ollamaGenerate({ ...parsed, numPredict: 12 });
    const generateMs = Date.now() - generateStarted;
    const response = String(generated.response || "").trim().replace(/\s+/g, " ");
    console.log(`model: ${model}`);
    console.log(`generate_ms: ${generateMs}`);
    console.log(`response: ${response.slice(0, 160)}`);
  } catch (error) {
    console.log(`status: unavailable (${error.name || "error"}: ${error.message})`);
    process.exitCode = 1;
  }
}

async function llmFast(args = []) {
  const parsed = parseLlmFastArgs(args);
  const started = Date.now();
  if (parsed.sub === "status") {
    const status = slowJobStatusPayload(parsed.jobId || parsed.prompt || args.find((arg) => !arg.startsWith("--") && arg !== "status"));
    const out = {
      ...status,
      elapsed_ms: Date.now() - started
    };
    if (parsed.json) console.log(JSON.stringify(out));
    else {
      console.log("Neuron Mercury LLM fast status");
      console.log(`mode: ${out.mode}`);
      console.log(`ok: ${out.ok ? "yes" : "no"}`);
      console.log(`elapsed_ms: ${out.elapsed_ms}`);
      console.log(`job_id: ${out.job_id || "-"}`);
      if (out.ok) {
        console.log(`status: ${out.status}`);
        console.log(`model: ${out.model || "-"}`);
        console.log(`intent_key: ${out.intent_key || "-"}`);
        console.log(`response_ready: ${out.response_ready ? "yes" : "no"}`);
        console.log(`first_answer_chars: ${out.metadata?.first_answer_chars || 0}`);
        if (out.response) console.log(`response: ${String(out.response).slice(0, 500)}`);
      }
      if (out.error) console.log(`error: ${out.error}`);
    }
    if (!out.ok) process.exitCode = 1;
    return;
  }
  if (parsed.sub === "merge") {
    const out = mergeSlowJobFinalAnswer(parsed.jobId || parsed.prompt || args.find((arg) => !arg.startsWith("--") && arg !== "merge"), parsed.response || parsed.seedResponse || "");
    if (parsed.json) console.log(JSON.stringify(out));
    else {
      console.log("Neuron Mercury LLM fast merge");
      console.log(`mode: ${out.mode}`);
      console.log(`ok: ${out.ok ? "yes" : "no"}`);
      console.log(`elapsed_ms: ${out.elapsed_ms}`);
      console.log(`job_id: ${out.job_id || "-"}`);
      console.log(`status: ${out.status || "-"}`);
      console.log(`response_ready: ${out.response_ready ? "yes" : "no"}`);
      console.log(`response_source: ${out.response_source || "-"}`);
      console.log(`response_chars: ${out.response_chars || 0}`);
      console.log(`status_ms: ${out.status_ms ?? "-"}`);
      console.log(`replay_ms: ${out.replay_ms ?? "-"}`);
      if (out.error) console.log(`error: ${out.error}`);
    }
    if (!out.ok) process.exitCode = 1;
    return;
  }
  if (parsed.seedResponse !== null) {
    if (!parsed.model) parsed.model = "seeded";
    const written = writeLlmCache(parsed, {
      response: parsed.seedResponse,
      generate_ms: 0
    });
    const out = {
      mode: "seeded_reflex",
      elapsed_ms: Date.now() - started,
      model: parsed.model,
      intent_key: llmIntentKey(parsed),
      response: parsed.seedResponse,
      cache_path: written.path
    };
    if (parsed.json) console.log(JSON.stringify(out));
    else {
      console.log("Neuron Mercury LLM fast answer");
      console.log(`mode: ${out.mode}`);
      console.log(`elapsed_ms: ${out.elapsed_ms}`);
      console.log(`model: ${out.model}`);
      console.log(`intent_key: ${out.intent_key}`);
      console.log(`cache_path: ${out.cache_path}`);
      console.log(`response: ${out.response}`);
    }
    return;
  }
  const cached = readLlmCache(parsed);
  if (cached.entry && !parsed.force) {
    const elapsed = Date.now() - started;
    const out = {
      mode: "cache_hit",
      elapsed_ms: elapsed,
      model: cached.entry.model,
      intent_key: cached.entry.intent_key,
      response: cached.entry.response,
      source_generate_ms: cached.entry.generate_ms,
      cache_path: cached.path
    };
    if (parsed.json) {
      console.log(JSON.stringify(out));
    } else {
      console.log("Neuron Mercury LLM fast answer");
      console.log(`mode: ${out.mode}`);
      console.log(`elapsed_ms: ${out.elapsed_ms}`);
      console.log(`model: ${out.model}`);
      console.log(`intent_key: ${out.intent_key}`);
      console.log(`source_generate_ms: ${out.source_generate_ms}`);
      console.log(`response: ${out.response}`);
    }
    return;
  }

  if (!parsed.refresh && !parsed.force) {
    if (parsed.preheatFirst) {
      const out = llmFastPreheatFirstResult(parsed, started);
      if (out) {
        if (parsed.json) console.log(JSON.stringify(out));
        else {
          console.log("Neuron Mercury LLM fast answer");
          console.log(`mode: ${out.mode}`);
          console.log(`elapsed_ms: ${out.elapsed_ms}`);
          console.log(`model: ${out.model || "(unset)"}`);
          console.log(`intent_key: ${out.intent_key}`);
          console.log(`preheat: hits=${out.packet.hit_count} search=${out.packet.search_ms}ms`);
          if (out.background_completion?.queued) console.log(`background_completion: ${out.background_completion.job_id} ${out.background_completion.status}`);
          console.log(`response: ${out.response}`);
        }
        return;
      }
    }
    if (parsed.semantic || parsed.enqueueMiss) {
      const reflex = reflexLookupWithQueue({
        model: parsed.model || "local-llm",
        intent: parsed.intent,
        prompt: parsed.prompt,
        enqueueMiss: parsed.enqueueMiss,
        semantic: parsed.semantic,
        semanticThreshold: parsed.semanticThreshold,
        semanticCandidates: parsed.semantic ? semanticReflexCandidatesCached(parsed.model || "local-llm") : null,
        source: "llm_fast_hot_miss"
      });
      if (reflex.ok) {
        const out = {
          mode: reflex.mode === "semantic_hit" ? "semantic_cache_hit" : "cache_hit",
          elapsed_ms: Date.now() - started,
          model: reflex.model,
          intent_key: reflex.intent_key,
          matched_intent_key: reflex.matched_intent_key || reflex.intent_key,
          score: reflex.score || null,
          response: reflex.response,
          source_generate_ms: reflex.source_generate_ms || 0,
          cache_layer: reflex.cache_layer || (reflex.mode === "semantic_hit" ? "semantic_reflex" : "intent_cache")
        };
        if (parsed.json) console.log(JSON.stringify(out));
        else {
          console.log("Neuron Mercury LLM fast answer");
          console.log(`mode: ${out.mode}`);
          console.log(`elapsed_ms: ${out.elapsed_ms}`);
          console.log(`model: ${out.model}`);
          console.log(`intent_key: ${out.intent_key}`);
          if (out.matched_intent_key) console.log(`matched_intent_key: ${out.matched_intent_key}`);
          if (out.score !== null) console.log(`score: ${out.score}`);
          console.log(`source_generate_ms: ${out.source_generate_ms}`);
          console.log(`cache_layer: ${out.cache_layer}`);
          console.log(`response: ${out.response}`);
        }
        return;
      }
      const elapsed = Date.now() - started;
      const out = {
        mode: "cache_miss",
        elapsed_ms: elapsed,
        model: parsed.model,
        intent_key: llmIntentKey(parsed),
        cache_path: cached.path,
        slow_job: reflex.slow_job || null,
        next: parsed.enqueueMiss ? "miss queued for slow-worker distillation" : "rerun with --refresh to let the local model answer once and write a hot cache entry"
      };
      if (parsed.json) console.log(JSON.stringify(out));
      else {
        console.log("Neuron Mercury LLM fast answer");
        console.log(`mode: ${out.mode}`);
        console.log(`elapsed_ms: ${out.elapsed_ms}`);
        console.log(`model: ${out.model || "(unset)"}`);
        console.log(`intent_key: ${out.intent_key}`);
        if (out.slow_job) console.log(`slow_job: ${out.slow_job.job_id} status=${out.slow_job.status}`);
        console.log(`cache_path: ${out.cache_path}`);
        console.log(`next: ${out.next}`);
      }
      process.exitCode = 2;
      return;
    }
    const elapsed = Date.now() - started;
    const out = {
      mode: "cache_miss",
      elapsed_ms: elapsed,
      model: parsed.model,
      intent_key: llmIntentKey(parsed),
      cache_path: cached.path,
      next: "rerun with --refresh to let the local model answer once and write a hot cache entry"
    };
    if (parsed.json) console.log(JSON.stringify(out));
    else {
      console.log("Neuron Mercury LLM fast answer");
      console.log(`mode: ${out.mode}`);
      console.log(`elapsed_ms: ${out.elapsed_ms}`);
      console.log(`model: ${out.model || "(unset)"}`);
      console.log(`intent_key: ${out.intent_key}`);
      console.log(`cache_path: ${out.cache_path}`);
      console.log(`next: ${out.next}`);
    }
    process.exitCode = 2;
    return;
  }

  let tags;
  try {
    tags = await fetchJson(`${parsed.url}/api/tags`, { timeout: 4000 });
  } catch (error) {
    console.log("Neuron Mercury LLM fast answer");
    console.log(`mode: unavailable (${error.name || "error"}: ${error.message})`);
    console.log(`elapsed_ms: ${Date.now() - started}`);
    process.exitCode = 1;
    return;
  }
  const models = tags.json?.models || [];
  if (!parsed.model) parsed.model = models[0]?.name;
  if (!tags.ok || !parsed.model) {
    console.log("Neuron Mercury LLM fast answer");
    console.log(`mode: unavailable (${tags.status || "no model"})`);
    console.log(`elapsed_ms: ${Date.now() - started}`);
    process.exitCode = 1;
    return;
  }
  const generateStarted = Date.now();
  let generated;
  try {
    generated = await ollamaGenerate(parsed);
  } catch (error) {
    console.log("Neuron Mercury LLM fast answer");
    console.log(`mode: generate_failed (${error.message})`);
    console.log(`elapsed_ms: ${Date.now() - started}`);
    process.exitCode = 1;
    return;
  }
  const generateMs = Date.now() - generateStarted;
  const response = String(generated.response || "").trim().replace(/\s+/g, " ");
  const written = writeLlmCache(parsed, {
    response,
    generate_ms: generateMs,
    total_duration: generated.total_duration,
    eval_count: generated.eval_count,
    eval_duration: generated.eval_duration
  });
  const elapsed = Date.now() - started;
  const out = {
    mode: "model_refresh",
    elapsed_ms: elapsed,
    generate_ms: generateMs,
    model: parsed.model,
    intent_key: llmIntentKey(parsed),
    response,
    cache_path: written.path
  };
  if (parsed.json) console.log(JSON.stringify(out));
  else {
    console.log("Neuron Mercury LLM fast answer");
    console.log(`mode: ${out.mode}`);
    console.log(`elapsed_ms: ${out.elapsed_ms}`);
    console.log(`generate_ms: ${out.generate_ms}`);
    console.log(`model: ${out.model}`);
    console.log(`intent_key: ${out.intent_key}`);
    console.log(`cache_path: ${out.cache_path}`);
    console.log(`response: ${out.response}`);
  }
}

function printTrace(args) {
  const which = args.find((arg) => !arg.startsWith("--")) || "latest";
  const summary = args.includes("--summary");
  const path = which === "latest" ? latestTracePath() : resolve(which);
  if (!path || !existsSync(path)) {
    console.error("No trace found.");
    process.exitCode = 1;
    return;
  }
  const text = readFileSync(path, "utf8");
  if (!summary) {
    console.log(text);
    return;
  }
  const trace = JSON.parse(text);
  const artifacts = trace.artifacts || [];
  const cacheHit = artifacts.some((artifact) => artifact.neuron_id === "cache.plan_result");
  console.log("Neuron Mercury trace summary");
  console.log(`path: ${path}`);
  console.log(`task: ${trace.task}`);
  console.log(`cwd: ${trace.cwd}`);
  console.log(`circuit: ${(trace.circuit || []).length}`);
  console.log(`artifacts: ${artifacts.length}`);
  console.log(`cache hit: ${cacheHit ? "yes" : "no"}`);
  for (const artifact of artifacts.slice(0, 8)) {
    console.log(`- ${artifact.neuron_id}: ${artifact.signal} (${artifact.evidence?.length || 0} evidence)`);
  }
}

function cacheStats() {
  ensureDirs();
  const files = readdirSync(CACHE_DIR)
    .filter((name) => CACHE_FILE_RE.test(name))
    .flatMap((name) => {
      const path = join(CACHE_DIR, name);
      let st;
      try {
        const lst = lstatSync(path);
        if (!lst.isFile()) return [];
        st = statSync(path);
      } catch {
        return [];
      }
      const namespace = name.match(CACHE_FILE_RE)?.[1] || "unknown";
      return [{ name, path, namespace, size: st.size, mtimeMs: st.mtimeMs }];
    });
  const bytes = files.reduce((sum, file) => sum + file.size, 0);
  return { files, count: files.length, bytes };
}

function pruneCache(maxFiles = 1000) {
  ensureDirs();
  const limit = Number.isFinite(maxFiles) && maxFiles > 0 ? Math.floor(maxFiles) : 1000;
  const stats = cacheStats();
  const sorted = [...stats.files].sort((a, b) => b.mtimeMs - a.mtimeMs);
  const keep = new Set(sorted.slice(0, limit).map((file) => file.path));
  let removed = 0;
  let removedBytes = 0;
  for (const file of sorted) {
    if (keep.has(file.path)) continue;
    unlinkSync(file.path);
    removed += 1;
    removedBytes += file.size;
  }
  const after = cacheStats();
  return {
    before_count: stats.count,
    after_count: after.count,
    removed,
    removed_bytes: removedBytes,
    max_files: limit
  };
}

function cacheCommand(args) {
  const sub = args[0] || "stats";
  if (sub === "stats") {
    const stats = cacheStats();
    const namespaces = stats.files.reduce((acc, file) => {
      acc[file.namespace] = (acc[file.namespace] || 0) + 1;
      return acc;
    }, {});
    console.log("Neuron Mercury cache stats");
    console.log(`files: ${stats.count}`);
    console.log(`bytes: ${stats.bytes}`);
    console.log(`namespaces: ${JSON.stringify(namespaces)}`);
    return;
  }
  if (sub === "audit") {
    const target = args[1];
    if (!target) {
      console.error("Usage: node src/mercury.js cache audit <target-file>");
      process.exitCode = 1;
      return;
    }
    const abs = resolve(process.cwd(), target);
    if (!existsSync(abs)) {
      console.error(`File not found: ${target}`);
      process.exitCode = 1;
      return;
    }
    const fast = fileFingerprint(target);
    const strict = strictFileFingerprint(target);
    console.log("Neuron Mercury cache audit");
    console.log(`target: ${target}`);
    console.log(`fast fingerprint: ${JSON.stringify(fast)}`);
    console.log(`strict sha256: ${strict.sha256}`);
    console.log("note: runtime cache keys use fast mtime/size fingerprints for speed; strict hash is available for audits.");
    return;
  }
  if (sub === "prune") {
    const maxFilesArg = args.find((arg) => arg.startsWith("--max-files="));
    const maxFiles = maxFilesArg ? Number(maxFilesArg.split("=")[1]) : Number(args[1] || 1000);
    const result = pruneCache(maxFiles);
    console.log("Neuron Mercury cache prune");
    console.log(`before: ${result.before_count}`);
    console.log(`after: ${result.after_count}`);
    console.log(`removed: ${result.removed}`);
    console.log(`removed bytes: ${result.removed_bytes}`);
    console.log(`max files: ${result.max_files}`);
    return;
  }
  console.error(`Unknown cache command: ${sub}`);
  process.exitCode = 1;
}

function workflowCacheStats(args = []) {
  ensureDirs();
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const limit = limitArg ? Math.max(1, Number(limitArg.split("=")[1]) || 12) : 12;
  const files = readdirSync(WORKFLOW_CACHE_DIR)
    .filter((name) => /^workflow_[a-f0-9]{24}\.json$/.test(name))
    .map((name) => {
      const path = join(WORKFLOW_CACHE_DIR, name);
      const st = statSync(path);
      let item = null;
      try {
        item = JSON.parse(readFileSync(path, "utf8"));
      } catch {}
      return { path, size: st.size, mtimeMs: st.mtimeMs, item };
    })
    .sort((a, b) => b.mtimeMs - a.mtimeMs);
  console.log("Neuron Mercury workflow cache");
  console.log(`path: ${WORKFLOW_CACHE_DIR}`);
  console.log(`files: ${files.length}`);
  for (const file of files.slice(0, limit)) {
    console.log(`- ${file.item?.task_hash || "unknown"} findings=${file.item?.findings?.length || 0} circuit=${file.item?.circuit_ids?.length || 0} ${file.path}`);
  }
}

function memoryGraphStats(args = []) {
  ensureDirs();
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const limit = limitArg ? Math.max(1, Number(limitArg.split("=")[1]) || 12) : 12;
  const path = memoryGraphPath();
  const rows = readMemoryGraphRows(5000);
  const byType = {};
  const byNamespace = {};
  for (const row of rows) {
    byType[row.type || "unknown"] = (byType[row.type || "unknown"] || 0) + 1;
    byNamespace[row.namespace || "unknown"] = (byNamespace[row.namespace || "unknown"] || 0) + 1;
  }
  console.log("Neuron Mercury memory graph");
  console.log(`path: ${path}`);
  console.log(`events: ${rows.length}`);
  console.log(`by_type: ${JSON.stringify(byType)}`);
  console.log(`by_namespace: ${JSON.stringify(byNamespace)}`);
  for (const row of rows.slice(-limit).reverse()) {
    console.log(`- ${row.at} ${row.type} findings=${row.finding_count ?? "-"} targets=${(row.targets || []).join(",") || "-"}`);
  }
}

function taskMemoryCommand(args = []) {
  const json = args.includes("--json");
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const summary = buildTaskMemorySummary({ limit: limitArg ? Math.max(1, Number(limitArg.split("=")[1]) || 5000) : 5000 });
  const path = join(MEMORY_GRAPH_DIR, "task-memory-summary.json");
  atomicWriteJson(path, summary, { pretty: true });
  if (json) {
    console.log(JSON.stringify(summary));
    return summary;
  }
  console.log("Neuron Mercury task memory");
  console.log(`events: ${summary.events}`);
  console.log(`tool_routes: ${JSON.stringify(summary.tool_routes)}`);
  console.log(`risk_hotspots: ${summary.risk_hotspots.length}`);
  console.log(`success_paths: ${summary.success_paths.length}`);
  console.log(`report: ${path}`);
  for (const item of summary.risk_hotspots.slice(0, 8)) console.log(`- hotspot hits=${item.hits} ${item.file}`);
  for (const item of summary.success_paths.slice(0, 5)) console.log(`- success ${item.diagnosis_ms}ms ${item.path}: ${item.task}`);
  return summary;
}

function taskRouteArgs(args = []) {
  const pathArg = args.find((arg) => arg.startsWith("--path="));
  const task = args.filter((arg) => !arg.startsWith("--")).join(" ").trim()
    || "diagnose project acceleration risk";
  return {
    task,
    path: pathArg ? pathArg.split("=").slice(1).join("=") : ".",
    json: args.includes("--json")
  };
}

function taskMemoryRouteHints(memory, taskLower) {
  const wantsSpend = /\b(cost|spend|billing|anthropic|openai|claude|paid|charge)\b/i.test(taskLower);
  const wantsLatency = /\b(latency|slow|hot path|performance|speed)\b/i.test(taskLower);
  const hotspots = memory.risk_hotspots || [];
  const success = memory.success_paths || [];
  const successRiskFiles = success
    .flatMap((item) => item.failure_risks || [])
    .map((risk) => String(risk).replace(/^(cost|stale):/, ""))
    .filter(Boolean)
    .map((file) => ({ file, hits: 1, source: "success_path_failure_risk" }));
  const hotspotFiles = [...successRiskFiles, ...hotspots]
    .filter((item, index, arr) => item.file && arr.findIndex((other) => other.file === item.file) === index);
  return {
    schema: "mercury-task-memory-route-hints-v1",
    spend_first: wantsSpend,
    latency_first: wantsLatency,
    route_prefix: wantsSpend
      ? ["spend_guard", "cost_scan", "target_file_first_diagnosis"]
      : wantsLatency
        ? ["code_cortex", "uma_target_file_first", "doctor"]
        : [],
    hotspot_files: hotspotFiles.slice(0, wantsSpend || wantsLatency ? 8 : 3),
    reusable_success_paths: success.slice(0, 3),
    memory_hit: Boolean((wantsSpend || wantsLatency) && (hotspots.length || success.length))
  };
}

function taskRouteCommand(args = []) {
  const parsed = taskRouteArgs(args);
  const started = Date.now();
  const memory = cachedTaskMemorySummary({ limit: 1500 });
  const umaStatus = umaNamespaceStatus(projectUmaNamespace());
  const spend = spendGuardSummary();
  const targets = extractTargetFiles(parsed.task);
  const taskLower = parsed.task.toLowerCase();
  const highRisk = /\b(pay|paid|billing|charge|anthropic|openai|claude|delete|production|deploy|secret|token|key|credential)\b/i.test(parsed.task)
    || spend.status === "risk";
  const monster = /\b(monster|large|huge|repo|workspace|all|everything|hidden|leak|latency|slow|spend|cost)\b/i.test(parsed.task);
  const firstGeneration = /\b(5000|long[-_ ]?form|long[-_ ]?report|report|article|draft|generate|write)\b/i.test(parsed.task);
  const hasMemory = memory.success_paths.length > 0 || memory.risk_hotspots.length > 0;
  const memoryHints = taskMemoryRouteHints(memory, taskLower);
  const hotPathTask = /\b(cost|spend|billing|anthropic|openai|claude|paid|charge|latency|slow|hot path)\b/i.test(taskLower);
  const virtualRoute = virtualFieldRoute(parsed.task, ["--lanes=16", "--budget=8"]);
  const rosen = rosenRoute(parsed.task, {
    namespace: umaStatus.namespace,
    limit: 6,
    bridgeLimit: hotPathTask ? 0 : 128,
    budgetMs: hotPathTask ? 4 : 6,
    umaBudgetMs: hotPathTask ? 1 : 2,
    uma: hotPathTask ? false : true,
    readStore: hotPathTask ? false : true,
    persist: 0,
    memoryLimit: hotPathTask ? 80 : 800,
    memoryBridges: hotPathTask ? 1 : 2,
    maxQueries: hotPathTask ? 1 : 2
  });
  const hasUma = umaStatus.exists && umaStatus.pages > 0 && !umaStatus.needs_file_table_refresh;
  let mode = "fast";
  if (highRisk) mode = "tribunal";
  else if (monster || !targets.length) mode = "swarm";
  const needsMonsterDoctor = monster
    && /\b(monster|large|huge|repo|workspace|all|everything)\b/i.test(taskLower)
    && !/\b(cost|spend|billing|anthropic|openai|claude|paid|charge)\b/i.test(taskLower);
  const commands = [];
  commands.push(`node src/mercury.js rosen-route ${JSON.stringify(parsed.task)} --limit=8 --budget-ms=8`);
  if (spend.status !== "clear" || /\b(cost|spend|billing|anthropic|openai|claude|paid)\b/i.test(taskLower)) commands.push(`node src/mercury.js spend-guard --path=${parsed.path} --limit=1000`);
  if (!hasUma || umaStatus.needs_file_table_refresh) commands.push(`node src/mercury.js uma project refresh --path=${parsed.path} --limit=500`);
  if (firstGeneration) commands.push(`node src/mercury.js first-gen-accelerate ${JSON.stringify(parsed.task)} --path=${parsed.path} --limit=500 --sections=8 --workers=4`);
  if (needsMonsterDoctor) commands.push(`node src/mercury.js monster-doctor ${JSON.stringify(parsed.task)} --path=${parsed.path} --limit=1000 --warm=6`);
  else commands.push(`node src/mercury.js doctor ${JSON.stringify(parsed.task)}`);
  if (hasMemory) commands.push("node src/mercury.js task-memory --limit=5000");
  const route = {
    schema: "mercury-task-route-v1",
    created_at: nowIso(),
    task: parsed.task,
    path: parsed.path,
    mode,
    features: {
      high_risk: highRisk,
      monster,
      first_generation: firstGeneration,
      target_files: targets,
      uma_ready: hasUma,
      spend_guard: spend.status,
      memory_success_paths: memory.success_paths.length,
      memory_hotspots: memory.risk_hotspots.slice(0, 8),
      memory_route_hints: memoryHints,
      virtual_route: {
        active_lanes: virtualRoute.active_lanes || 0,
        active_virtual_neurons: virtualRoute.active_virtual_neurons || 0,
        unique_physical_control_neurons: virtualRoute.unique_physical_control_neurons || 0,
        elapsed_ms: virtualRoute.elapsed_ms || 0,
        lanes: (virtualRoute.lanes || []).map((lane) => ({
          lane: lane.lane,
          score: lane.score,
          activation_budget: lane.activation_budget,
          controllers: lane.controllers
        }))
      },
      rosen_bridge: {
        candidates: rosen.candidates,
        selected_count: rosen.selected_count,
        elapsed_ms: rosen.elapsed_ms,
        top_bridges: rosen.selected.slice(0, 5)
      }
    },
    commands,
    elapsed_ms: Date.now() - started
  };
  appendMemoryGraphEvent({
    type: "task_route",
    task: parsed.task,
    mode,
    path: parsed.path,
    target_files: targets,
    spend_guard: spend.status,
    uma_ready: hasUma,
    rosen_selected: rosen.selected_count,
    virtual_route_lanes: virtualRoute.active_lanes || 0,
    virtual_route_controllers: virtualRoute.unique_physical_control_neurons || 0,
    active_virtual_neurons: virtualRoute.active_virtual_neurons || 0,
    first_generation: firstGeneration
  });
  if (parsed.json) {
    console.log(JSON.stringify(route));
    return route;
  }
  console.log("Neuron Mercury task route");
  console.log(`mode: ${route.mode}`);
  console.log(`task: ${route.task}`);
  console.log(`uma_ready: ${route.features.uma_ready}`);
  console.log(`spend_guard: ${route.features.spend_guard}`);
  console.log(`virtual_route: ${route.features.virtual_route.active_lanes}/${route.features.virtual_route.unique_physical_control_neurons} ${route.features.virtual_route.elapsed_ms}ms`);
  console.log(`rosen_bridges: ${route.features.rosen_bridge.selected_count}/${route.features.rosen_bridge.candidates} (${route.features.rosen_bridge.elapsed_ms}ms)`);
  console.log(`first_generation: ${route.features.first_generation ? "yes" : "no"}`);
  console.log(`elapsed_ms: ${route.elapsed_ms}`);
  for (const command of commands) console.log(`- ${command}`);
  return route;
}

function findAccelerateTaskFastReplay(task, path, scopeFingerprint, namespace) {
  ensureDirs();
  let names = [];
  try {
    names = readdirSync(CACHE_DIR).filter((name) => /^accelerate_task_fast_[a-f0-9]{24}\.json$/.test(name));
  } catch {
    return null;
  }
  const ranked = names
    .map((name) => {
      const file = join(CACHE_DIR, name);
      try {
        return { file, mtimeMs: statSync(file).mtimeMs };
      } catch {
        return null;
      }
    })
    .filter(Boolean)
    .sort((a, b) => b.mtimeMs - a.mtimeMs)
    .slice(0, 240);
  for (const item of ranked) {
    try {
      const parsed = JSON.parse(readFileSync(item.file, "utf8"));
      const report = parsed.report || {};
      if (report.task !== task) continue;
      if (report.path !== path) continue;
      if (report.scope_fingerprint?.digest !== scopeFingerprint.digest) continue;
      return { ...parsed, cache_path: parsed.cache_path || item.file, fallback: "digest_scan" };
    } catch {}
  }
  return null;
}

function accelerateTaskCommand(args = []) {
  const json = args.includes("--json");
  const refresh = args.includes("--refresh");
  const pathArg = args.find((arg) => arg.startsWith("--path="));
  const path = pathArg ? pathArg.split("=").slice(1).join("=") : ".";
  const include = parseCsvArg(args, "include");
  const exclude = parseCsvArg(args, "exclude");
  const scopeArgs = [`--path=${path}`];
  if (include.length) scopeArgs.push(`--include=${include.join(",")}`);
  if (exclude.length) scopeArgs.push(`--exclude=${exclude.join(",")}`);
  const task = args.filter((arg) => !arg.startsWith("--")).join(" ").trim()
    || "diagnose project acceleration risk";
  const started = Date.now();
  const scopeFingerprint = workflowScopeFingerprint(path, include, exclude, 160);
  const fastUmaState = umaNamespaceStatus(projectUmaNamespace());
  const fastCacheKey = {
    schema: "accelerate-task-fast-cache-v1",
    cwd: process.cwd(),
    task,
    path,
    include,
    exclude,
    namespace: fastUmaState.namespace,
    source_digest: scopeFingerprint.digest,
    source_files: scopeFingerprint.scanned_files,
    uma_refresh_needed: Boolean(fastUmaState.needs_file_table_refresh)
  };
  if (!refresh) {
    const cached = readJsonCache("accelerate_task_fast", fastCacheKey)
      || findAccelerateTaskFastReplay(task, path, scopeFingerprint, fastUmaState.namespace);
    if (cached?.report) {
      const report = {
        ...cached.report,
        created_at: nowIso(),
        scope_fingerprint: scopeFingerprint,
        cache: {
          mode: "accelerate_task_fast_replay",
          cache_path: cached.cache_path || cachePath("accelerate_task_fast", fastCacheKey),
          source_created_at: cached.created_at,
          original_elapsed_ms: cached.report.elapsed_ms || 0,
          lookup: cached.fallback || "exact_key"
        },
        elapsed_ms: Date.now() - started
      };
      appendMemoryGraphEvent({
        type: "accelerate_task_fast_replay",
        task,
        path,
        namespace: fastUmaState.namespace,
        elapsed_ms: report.elapsed_ms,
        original_elapsed_ms: cached.report.elapsed_ms || 0
      });
      if (json) {
        console.log(JSON.stringify(report));
        return report;
      }
      console.log("Neuron Mercury accelerate task");
      console.log("mode: accelerate_task_fast_replay");
      console.log(`elapsed_ms: ${report.elapsed_ms}`);
      console.log(`original_elapsed_ms: ${cached.report.elapsed_ms || 0}`);
      return report;
    }
  }
  const route = silencedConsole(() => taskRouteCommand([task, `--path=${path}`, "--json"]));
  const umaState = umaNamespaceStatus(projectUmaNamespace());
  const cacheKey = {
    schema: "accelerate-task-cache-v1",
    cwd: process.cwd(),
    task,
    path,
    include,
    exclude,
    namespace: umaState.namespace,
    source_digest: scopeFingerprint.digest,
    source_files: scopeFingerprint.scanned_files,
    uma_refresh_needed: Boolean(umaState.needs_file_table_refresh),
    first_generation: route.features.first_generation
  };
  if (!refresh) {
    const cached = readJsonCache("accelerate_task", cacheKey);
    if (cached?.report) {
      const report = {
        ...cached.report,
        created_at: nowIso(),
        scope_fingerprint: scopeFingerprint,
        cache: {
          mode: "accelerate_task_replay",
          cache_path: cached.cache_path || cachePath("accelerate_task", cacheKey),
          source_created_at: cached.created_at,
          original_elapsed_ms: cached.report.elapsed_ms || 0
        },
        elapsed_ms: Date.now() - started
      };
      appendMemoryGraphEvent({
        type: "accelerate_task_replay",
        task,
        path,
        namespace: umaState.namespace,
        elapsed_ms: report.elapsed_ms,
        original_elapsed_ms: cached.report.elapsed_ms || 0
      });
      if (json) {
        console.log(JSON.stringify(report));
        return report;
      }
      console.log("Neuron Mercury accelerate task");
      console.log("mode: accelerate_task_replay");
      console.log(`elapsed_ms: ${report.elapsed_ms}`);
      console.log(`original_elapsed_ms: ${cached.report.elapsed_ms || 0}`);
      return report;
    }
  }
  const steps = [];
  const runStep = (name, fn) => {
    const stepStarted = Date.now();
    try {
      const result = silencedConsole(fn);
      steps.push({ name, ok: true, elapsed_ms: Date.now() - stepStarted, result });
      return result;
    } catch (error) {
      const result = { ok: false, error: `${error.name || "error"}: ${error.message}` };
      steps.push({ name, ok: false, elapsed_ms: Date.now() - stepStarted, result });
      return result;
    }
  };
  const rosenStep = runStep("rosen_route", () => rosenRoute(task, {
    namespace: projectUmaNamespace(),
    limit: 6,
    bridgeLimit: 128,
    budgetMs: 6,
    umaBudgetMs: 2,
    persist: 0,
    memoryBridges: 2,
    maxQueries: 2
  }));
  if (route.features.spend_guard !== "clear" || /\b(cost|spend|billing|anthropic|openai|claude|paid)\b/i.test(task)) {
    runStep("spend_guard", () => spendGuard([...scopeArgs, "--limit=1000", "--json"]));
  }
	  if (!route.features.uma_ready) {
	    runStep("uma_refresh", () => projectUmaCommand(["project", "refresh", `--path=${path}`, "--limit=500", "--json"]));
	  }
  let coldStart = null;
  const firstGen = route.features.first_generation
    ? runStep("first_gen_parallel_plan", () => firstGenAccelerateCommand([task, ...scopeArgs, "--limit=500", "--sections=8", "--workers=4", "--serial-ms=120000", "--json"]))
    : null;
  if (!route.features.first_generation) {
    coldStart = runStep("cold_start_packet", () => coldStartAccelerateCommand([task, ...scopeArgs, "--limit=500", "--budget-ms=12", "--json"]));
  }
  const needsMonsterDoctor = route.features.monster
    && /\b(monster|large|huge|repo|workspace|all|everything)\b/i.test(task)
    && !/\b(cost|spend|billing|anthropic|openai|claude|paid|charge)\b/i.test(task);
  const diagnosis = route.features.first_generation
    ? null
    : !needsMonsterDoctor
	    ? runStep("doctor", () => executePlan(task, { profile: true, umaNamespace: projectUmaNamespace(), umaBudgetMs: 12 }))
	    : runStep("monster_doctor", () => monsterDoctor([task, ...scopeArgs, "--limit=1000", "--warm=6", "--json"]));
  const memory = runStep("task_memory", () => cachedTaskMemorySummary({ limit: 5000 }));
  const report = {
    schema: "mercury-accelerate-task-v1",
    created_at: nowIso(),
    cwd: process.cwd(),
    task,
    path,
    scope_fingerprint: scopeFingerprint,
    workflow_replay_key: {
      fast_path: cachePath("accelerate_task_fast", fastCacheKey),
      path: cachePath("accelerate_task", cacheKey)
    },
    route,
    steps: steps.map((step) => ({
      name: step.name,
      ok: step.ok,
      elapsed_ms: step.elapsed_ms,
      summary: step.name === "monster_doctor"
        ? {
            cost_findings: step.result.cost_scan?.finding_count,
            hot_files: step.result.code_cortex?.totals?.hot_files,
            diagnosis_ms: step.result.diagnosis?.elapsed_ms
          }
        : step.name === "spend_guard"
        ? {
            status: step.result.status,
            paid_runtime_files: step.result.paid_runtime_files?.length,
            loop_paid_runtime_files: step.result.loop_paid_runtime_files?.length
          }
	        : step.name === "task_memory"
	        ? {
	            events: step.result.events,
	            success_paths: step.result.success_paths?.length,
	            risk_hotspots: step.result.risk_hotspots?.length
	          }
        : step.name === "cold_start_packet"
        ? {
            route: step.result.packet?.route,
            hits: step.result.packet?.hit_count,
            slow_job: step.result.slow_job?.status || "not_queued",
            elapsed_ms: step.result.timings?.elapsed_ms
          }
        : step.name === "rosen_route"
        ? {
            candidates: step.result.candidates,
            selected_count: step.result.selected_count,
            top_bridge: step.result.selected?.[0]?.to || null,
            elapsed_ms: step.result.elapsed_ms
          }
        : step.name === "first_gen_parallel_plan"
        ? {
            mode: step.result.mode,
            sections: step.result.sections,
            workers: step.result.workers,
            waves: step.result.waves?.length,
            immediate_draft_bytes: step.result.immediate_draft_bytes,
            judge_score: step.result.judge?.score || 0,
            pointer_coverage: step.result.judge?.pointer_coverage || 0,
            distilled_reflexes: step.result.distillation?.seeded_count || 0,
            active_neurons: step.result.neuron_map?.active_neurons,
            virtual_route_lanes: step.result.neuron_map?.virtual_route?.active_lanes || 0,
            virtual_route_controllers: step.result.neuron_map?.virtual_route?.unique_physical_control_neurons || 0,
            active_virtual_neurons: step.result.neuron_map?.virtual_route?.active_virtual_neurons || 0,
            estimated_speedup: step.result.estimate?.speedup,
            elapsed_ms: step.result.timings?.elapsed_ms
          }
        : {}
      })),
	    cold_start_summary: {
	      route: coldStart?.packet?.route || firstGen?.packet?.route || null,
	      hit_count: coldStart?.packet?.hit_count || firstGen?.packet?.hit_count || 0,
      slow_job: coldStart?.slow_job?.status || "not_queued",
      elapsed_ms: coldStart?.timings?.elapsed_ms || firstGen?.timings?.cold_start_ms || 0,
      virtual_route_lanes: coldStart?.packet?.virtual_route?.active_lanes || firstGen?.packet?.virtual_route?.active_lanes || 0,
      virtual_route_controllers: coldStart?.packet?.virtual_route?.unique_physical_control_neurons || firstGen?.packet?.virtual_route?.unique_physical_control_neurons || 0,
      active_virtual_neurons: coldStart?.packet?.virtual_route?.active_virtual_neurons || firstGen?.packet?.virtual_route?.active_virtual_neurons || 0,
      source: coldStart ? "cold_start_packet" : firstGen ? "first_gen_embedded_cold_start" : "none"
    },
    first_generation_summary: firstGen ? {
      mode: firstGen.mode,
      sections: firstGen.sections,
      workers: firstGen.workers,
      waves: firstGen.waves?.length || 0,
      immediate_draft_bytes: firstGen.immediate_draft_bytes || 0,
      judge_score: firstGen.judge?.score || 0,
      pointer_coverage: firstGen.judge?.pointer_coverage || 0,
      distilled_reflexes: firstGen.distillation?.seeded_count || 0,
      replay: firstGen.mode === "distilled_first_generation_replay",
      active_neurons: firstGen.neuron_map?.active_neurons || 0,
      virtual_route_lanes: firstGen.neuron_map?.virtual_route?.active_lanes || 0,
      virtual_route_controllers: firstGen.neuron_map?.virtual_route?.unique_physical_control_neurons || 0,
      active_virtual_neurons: firstGen.neuron_map?.virtual_route?.active_virtual_neurons || 0,
      estimated_speedup: firstGen.estimate?.speedup || 0,
      elapsed_ms: firstGen.timings?.elapsed_ms || 0
    } : null,
    rosen_summary: {
      selected_count: rosenStep?.selected_count || 0,
      candidates: rosenStep?.candidates || 0,
      elapsed_ms: rosenStep?.elapsed_ms || 0,
      top_bridges: rosenStep?.selected?.slice(0, 5) || []
    },
    diagnosis_summary: diagnosis?.diagnosis || diagnosis?.patchPlan || null,
    memory_summary: {
      events: memory.events,
      success_paths: memory.success_paths?.length || 0,
      risk_hotspots: memory.risk_hotspots?.slice(0, 8) || []
    },
    elapsed_ms: Date.now() - started
  };
  const reportPath = join(BENCH_DIR, "accelerate-task-latest.json");
  atomicWriteJson(reportPath, report, { pretty: true });
  const cachePathWritten = writeJsonCache("accelerate_task", cacheKey, {
    schema: "accelerate-task-cache-v1",
    created_at: nowIso(),
    cache_path: cachePath("accelerate_task", cacheKey),
    report
  });
  report.cache = {
    mode: "stored",
    cache_path: cachePathWritten
  };
  writeJsonCache("accelerate_task_fast", fastCacheKey, {
    schema: "accelerate-task-fast-cache-v1",
    created_at: nowIso(),
    cache_path: cachePath("accelerate_task_fast", fastCacheKey),
    report
  });
  atomicWriteJson(reportPath, report, { pretty: true });
  appendMemoryGraphEvent({
    type: "accelerate_task",
    task,
    path,
    mode: route.mode,
    elapsed_ms: report.elapsed_ms,
    steps: report.steps.map((step) => ({ name: step.name, ok: step.ok, elapsed_ms: step.elapsed_ms }))
  });
  if (json) {
    console.log(JSON.stringify(report));
    return report;
  }
  console.log("Neuron Mercury accelerate task");
  console.log(`mode: ${route.mode}`);
  console.log(`elapsed_ms: ${report.elapsed_ms}`);
  console.log(`report: ${reportPath}`);
	  for (const step of report.steps) console.log(`- ${step.name}: ${step.ok ? "ok" : "fail"} ${step.elapsed_ms}ms`);
	  return report;
	}

function coldStartArgs(args = []) {
  const pathArg = args.find((arg) => arg.startsWith("--path="));
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const budgetArg = args.find((arg) => arg.startsWith("--budget-ms="));
  const namespaceArg = args.find((arg) => arg.startsWith("--namespace="));
  const modelArg = args.find((arg) => arg.startsWith("--model="));
  const task = args.filter((arg) => !arg.startsWith("--")).join(" ").trim()
    || "produce a first useful answer with UMA acceleration";
  return {
    task,
    path: pathArg ? pathArg.split("=").slice(1).join("=") : ".",
    limit: limitArg ? Math.max(1, Number(limitArg.split("=")[1]) || 300) : 300,
    budgetMs: budgetArg ? Math.max(1, Number(budgetArg.split("=")[1]) || 12) : 12,
    namespace: namespaceArg ? namespaceArg.split("=").slice(1).join("=") : projectUmaNamespace(),
    model: modelArg ? modelArg.split("=").slice(1).join("=") : DEFAULT_LOCAL_LLM_MODEL,
    include: parseCsvArg(args, "include"),
    exclude: parseCsvArg(args, "exclude"),
    refresh: args.includes("--refresh"),
    noQueue: args.includes("--no-queue"),
    json: args.includes("--json")
  };
}

function coldStartAccelerateCommand(args = []) {
  ensureDirs();
  const parsed = coldStartArgs(args);
  const started = Date.now();
  const status = umaNamespaceStatus(parsed.namespace);
  let refresh = null;
  if (parsed.refresh || !status.exists || status.pages === 0 || status.needs_file_table_refresh) {
    const scopedArgs = [`--path=${parsed.path}`, `--limit=${parsed.limit}`, `--namespace=${parsed.namespace}`, "--json"];
    if (parsed.include.length) scopedArgs.push(`--include=${parsed.include.join(",")}`);
    if (parsed.exclude.length) scopedArgs.push(`--exclude=${parsed.exclude.join(",")}`);
    refresh = silencedConsole(() => codeCortexCommand(scopedArgs));
  }
  const searchStarted = Date.now();
  const uma = umaSearch(parsed.task, {
    namespace: parsed.namespace,
    limit: 8,
    threshold: 0.01,
    budgetMs: parsed.budgetMs
  });
  const context = createRunContext(parsed.task);
  context.umaNamespace = parsed.namespace;
  context.umaHits = uma.results || [];
  context.umaElapsedMs = uma.elapsed_ms;
  context.umaTimedOut = Boolean(uma.timed_out);
  context.umaRoute = {
    target_file_first: Boolean(uma.target_file_first),
    symbol_first: Boolean(uma.symbol_first),
    hot_page_first: Boolean(uma.hot_page_first),
    candidate_pages: uma.candidate_pages || 0
  };
  const packet = buildUmaEvidencePacket(context, { excerptChars: 180 });
  const virtualRoute = virtualFieldRoute(parsed.task, ["--lanes=16", "--budget=8"]);
  packet.virtual_route = virtualRoute;
  const scaffold = buildColdStartScaffold(parsed.task, packet);
  const providerPrompt = [
    "You are Neuron Mercury cold-start synthesis.",
    "Write the first complete answer using this compressed UMA packet.",
    "Do not request full files unless evidence is empty.",
    `Virtual neuron route: lanes=${(virtualRoute.lanes || []).map((lane) => lane.lane).join(",")}; controllers=${virtualRoute.unique_physical_control_neurons}; virtual=${virtualRoute.active_virtual_neurons}.`,
    "",
    scaffold,
    "",
    evidencePacketPrompt(packet)
  ].join("\n");
  const slowJob = parsed.noQueue ? null : enqueueSlowReflex({
    model: parsed.model,
    intent: `cold-start:${stableHash([parsed.namespace, parsed.task])}`,
    prompt: providerPrompt,
    source: "cold_start_accelerate"
  });
  const report = {
    schema: "mercury-cold-start-accelerate-v1",
    created_at: nowIso(),
    task: parsed.task,
    namespace: parsed.namespace,
    path: parsed.path,
    mode: "first_useful_packet_before_model",
    refresh: refresh ? {
      files_scanned: refresh.files_scanned,
      pages: refresh.pages,
      totals: refresh.totals
    } : null,
    virtual_route: virtualRoute,
    packet,
    scaffold,
    slow_job: slowJob,
    timings: {
      search_ms: Date.now() - searchStarted,
      uma_ms: uma.elapsed_ms,
      elapsed_ms: Date.now() - started,
      budget_ms: parsed.budgetMs,
      timed_out: Boolean(uma.timed_out)
    }
  };
  const reportPath = join(COLD_START_DIR, `cold_${stableHash([parsed.namespace, parsed.task, Date.now()])}.json`);
  atomicWriteJson(reportPath, report, { pretty: true });
  atomicWriteJson(join(COLD_START_DIR, "latest.json"), report, { pretty: true });
  appendMemoryGraphEvent({
    type: "cold_start_accelerate",
    task: parsed.task,
    path: parsed.path,
    namespace: parsed.namespace,
    route: packet.route,
    hit_count: packet.hit_count,
    virtual_route_lanes: (virtualRoute.lanes || []).map((lane) => lane.lane),
    virtual_route_controllers: virtualRoute.unique_physical_control_neurons || 0,
    slow_job_status: slowJob?.status || "not_queued",
    elapsed_ms: report.timings.elapsed_ms
  });
	  if (parsed.json) {
	    console.log(JSON.stringify(report));
	    return report;
	  }
	  console.log("Neuron Mercury cold-start accelerate");
	  console.log(`mode: ${report.mode}`);
  console.log(`route: ${packet.route} hits=${packet.hit_count}`);
  console.log(`virtual_route: ${(virtualRoute.lanes || []).map((lane) => lane.lane).join(",") || "-"} controllers=${virtualRoute.unique_physical_control_neurons || 0}`);
  console.log(`elapsed_ms: ${report.timings.elapsed_ms}`);
	  console.log(`slow_job: ${slowJob?.job_id || "-"} ${slowJob?.status || "-"}`);
	  console.log(`report: ${reportPath}`);
	  return report;
	}

function firstGenArgs(args = []) {
  const sectionsArg = args.find((arg) => arg.startsWith("--sections="));
  const workersArg = args.find((arg) => arg.startsWith("--workers="));
  const serialArg = args.find((arg) => arg.startsWith("--serial-ms="));
  const parsed = coldStartArgs(args);
  return {
    ...parsed,
    sections: sectionsArg ? Math.max(2, Math.min(64, Number(sectionsArg.split("=")[1]) || 8)) : 8,
    workers: workersArg ? Math.max(1, Math.min(32, Number(workersArg.split("=")[1]) || 4)) : 4,
    serialMs: serialArg ? Math.max(1, Number(serialArg.split("=")[1]) || 120000) : 120000
  };
}

function firstGenSectionTitles(task, count) {
  const base = /\b(report|article|5000|write|draft|generate)\b/i.test(task)
    ? ["claim", "context", "evidence", "mechanism", "risks", "case study", "implementation", "summary"]
    : ["triage", "evidence", "hot path", "risk", "fix path", "verification", "guardrail", "handoff"];
  return Array.from({ length: count }, (_, index) => base[index % base.length]);
}

function buildFirstGenNeuronMap(task, titles, workers, packet) {
  const neurons = scheduleCircuit(classifyTask(task, loadNeurons()));
  const lanes = Array.from({ length: workers }, (_, index) => ({
    worker: index + 1,
    substrate: index === 0 ? "hot_cpu_reflex" : "slow_model_worker",
    sections: []
  }));
  const packetItems = packet.items || [];
  const virtualLanes = packet.virtual_route?.lanes || [];
  titles.forEach((title, index) => {
    const neuron = neurons[index % Math.max(1, neurons.length)];
    const virtualLane = virtualLanes[index % Math.max(1, virtualLanes.length)] || null;
    const virtualControllers = virtualLane?.controllers || [];
    lanes[index % workers].sections.push({
      section: index + 1,
      title,
      neuron_id: neuron?.id || "synthesis.section",
      cluster: neuron ? neuronCluster(neuron.id) : "synthesis",
      virtual_lane: virtualLane?.lane || null,
      virtual_controller: virtualControllers[index % Math.max(1, virtualControllers.length)] || null,
      evidence_pointer: packetItems[index % Math.max(1, packetItems.length)]?.pointer || null
    });
  });
  return {
    schema: "mercury-first-gen-neuron-map-v1",
    policy: "split first generation into evidence-bound section lanes before slow model synthesis",
    catalog_neurons: loadNeurons().length,
    active_neurons: [...new Set(lanes.flatMap((lane) => lane.sections.map((item) => item.neuron_id)))].length,
    virtual_route: packet.virtual_route ? {
      active_lanes: packet.virtual_route.active_lanes || 0,
      active_virtual_neurons: packet.virtual_route.active_virtual_neurons || 0,
      unique_physical_control_neurons: packet.virtual_route.unique_physical_control_neurons || 0,
      lanes: (packet.virtual_route.lanes || []).map((lane) => lane.lane)
    } : null,
    lanes
  };
}

function buildFirstGenAssemblyDraft(task, titles, packet, neuronMap) {
  const evidence = packet.items || [];
  const sourceLine = packet.sources?.length ? `Sources: ${packet.sources.slice(0, 4).join(", ")}` : "Sources: pending UMA refresh";
  const lines = [
    `First-generation accelerated draft for: ${task}`,
    `Route: ${packet.route}; UMA hits: ${packet.hit_count}; candidate pages: ${packet.candidate_pages}`,
    neuronMap.virtual_route ? `Virtual route: ${neuronMap.virtual_route.lanes.join(",")} via ${neuronMap.virtual_route.unique_physical_control_neurons} controllers; active virtual=${neuronMap.virtual_route.active_virtual_neurons}` : "Virtual route: pending",
    sourceLine,
    "",
    "Working thesis:",
    evidence[0]
      ? `Use ${evidence[0].pointer} as the first anchor; expand from verified UMA evidence instead of waiting for a full-context model call.`
      : "No evidence packet is available yet; keep this as a structure-only draft and force refresh before factual claims.",
    ""
  ];
  titles.forEach((title, index) => {
    const item = evidence[index % Math.max(1, evidence.length)];
    const lane = (neuronMap.lanes || []).find((entry) => entry.sections.some((section) => section.section === index + 1));
    const section = lane?.sections.find((entry) => entry.section === index + 1);
    lines.push(`## ${index + 1}. ${title}`);
    lines.push(`Neuron lane: worker ${lane?.worker || 1}, ${section?.neuron_id || "synthesis.section"}`);
    if (item) {
      lines.push(`Evidence: ${item.pointer} score=${item.score}`);
      lines.push(`${item.excerpt}`);
    } else {
      lines.push("Evidence: TODO from slow worker; do not invent facts.");
    }
    lines.push("");
  });
  lines.push("Assembly rule: merge section outputs by pointer coverage, then distill the final answer into reflex memory for replay.");
  return lines.join("\n");
}

function pickSectionEvidence(title, index, packet, maxItems = 3) {
  const items = packet.items || [];
  if (!items.length) return [];
  const titleTokens = semanticTokens(title);
  const scored = items.map((item, itemIndex) => {
    const textTokens = semanticTokens(`${item.pointer || ""} ${item.excerpt || ""}`);
    let overlap = 0;
    for (const token of titleTokens) if (textTokens.has(token)) overlap += 1;
    return {
      item,
      score: overlap * 10 + Number(item.score || 0) + (itemIndex === index % items.length ? 2 : 0)
    };
  });
  return scored
    .sort((a, b) => b.score - a.score)
    .slice(0, maxItems)
    .map((entry) => entry.item);
}

function buildFirstGenSectionDrafts(task, titles, packet, neuronMap) {
  const drafts = [];
  for (let index = 0; index < titles.length; index += 1) {
    const title = titles[index];
    const lane = (neuronMap.lanes || []).find((entry) => entry.sections.some((section) => section.section === index + 1));
    const section = lane?.sections.find((entry) => entry.section === index + 1);
    const evidence = pickSectionEvidence(title, index, packet, 3);
    const pointers = evidence.map((item) => item.pointer).filter(Boolean);
    const body = evidence.length
      ? [
          `This section starts from ${pointers[0]} and stays inside the compressed UMA packet instead of waiting for a whole-file model pass.`,
          `Operational claim: ${task} should be advanced by routing ${title} through ${section?.neuron_id || "synthesis.section"} on worker ${lane?.worker || 1}.`,
          ...evidence.map((item, evidenceIndex) => `Evidence ${evidenceIndex + 1}: ${item.pointer} -> ${item.excerpt}`),
          "Gap rule: if the pointer coverage is insufficient, mark the gap for slow-worker synthesis rather than inventing facts."
        ]
      : [
          "No UMA evidence is available for this section yet.",
          "Keep this section as a structure-only slot and force refresh before factual expansion."
        ];
    drafts.push({
      section: index + 1,
      title,
      worker: lane?.worker || 1,
      neuron_id: section?.neuron_id || "synthesis.section",
      cluster: section?.cluster || "synthesis",
      evidence_pointers: pointers,
      draft: [
        `## ${index + 1}. ${title}`,
        `Lane: worker ${lane?.worker || 1}; neuron=${section?.neuron_id || "synthesis.section"}; cluster=${section?.cluster || "synthesis"}`,
        ...body
      ].join("\n")
    });
  }
  return drafts;
}

function buildFirstGenDispatchPlan(sectionJobs, workers, serialMs) {
  const normalizedWorkers = Math.max(1, Number(workers) || 1);
  const wavesById = new Map();
  for (const job of sectionJobs || []) {
    const wave = Math.max(1, Number(job.wave) || Math.floor((Number(job.section) - 1) / normalizedWorkers) + 1);
    const worker = Math.max(1, Number(job.worker) || ((Number(job.section) - 1) % normalizedWorkers) + 1);
    if (!wavesById.has(wave)) wavesById.set(wave, []);
    wavesById.get(wave).push({
      section: job.section,
      title: job.title,
      worker,
      neuron_id: job.neuron_id,
      job_id: job.job_id || null,
      evidence_pointer: job.evidence_pointer || null
    });
  }
  const waves = [...wavesById.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([wave, lanes]) => ({
      wave,
      concurrency: Math.min(normalizedWorkers, lanes.length),
      lanes: lanes.sort((a, b) => a.worker - b.worker || a.section - b.section)
    }));
  const maxConcurrency = Math.max(0, ...waves.map((wave) => wave.concurrency));
  const serialSectionMs = sectionJobs.length ? serialMs / sectionJobs.length : serialMs;
  const criticalPathMs = waves.length * serialSectionMs;
  return {
    schema: "mercury-first-gen-dispatch-plan-v1",
    policy: "section workers are grouped by wave for bounded concurrent synthesis, not single-file FIFO queueing",
    workers: normalizedWorkers,
    sections: sectionJobs.length,
    waves,
    max_concurrency: maxConcurrency,
    critical_path_ms: Number(criticalPathMs.toFixed(3)),
    speedup: visualSpeedup(serialMs, Math.max(1, criticalPathMs))
  };
}

function firstGenSpendGuardedProviderHint(workers) {
  return {
    schema: "mercury-slow-provider-hint-v1",
    provider: "reflex_queue_only",
    route: "spend_guarded_section_fanout",
    url: null,
    model: null,
    transport: "none",
    model_hot_path: "forbidden",
    paid_provider_fanout: "blocked",
    max_paid_concurrency: 0,
    max_local_concurrency: Math.max(1, Number(workers) || 1),
    reason: "first-generation sections may fan out locally, but paid-provider fanout is blocked unless an explicit future policy unlocks it"
  };
}

function judgeFirstGenDrafts(sectionDrafts, packet) {
  const pointers = new Set((packet.items || []).map((item) => item.pointer).filter(Boolean));
  const used = new Set(sectionDrafts.flatMap((draft) => draft.evidence_pointers || []).filter(Boolean));
  const sectionsWithEvidence = sectionDrafts.filter((draft) => (draft.evidence_pointers || []).length > 0).length;
  const draftBytes = Buffer.byteLength(sectionDrafts.map((draft) => draft.draft).join("\n\n"));
  const pointerCoverage = pointers.size ? Number((used.size / pointers.size).toFixed(3)) : 0;
  const score = Math.min(100, Math.round(
    (sectionsWithEvidence / Math.max(1, sectionDrafts.length)) * 40
    + pointerCoverage * 35
    + Math.min(1, draftBytes / Math.max(1200, sectionDrafts.length * 180)) * 25
  ));
  return {
    schema: "mercury-first-gen-judge-v1",
    score,
    pass: score >= 70,
    sections: sectionDrafts.length,
    sections_with_evidence: sectionsWithEvidence,
    unique_packet_pointers: pointers.size,
    used_packet_pointers: used.size,
    pointer_coverage: pointerCoverage,
    draft_bytes: draftBytes,
    rule: "first generation must produce evidence-bound section drafts before slow model completion"
  };
}

function distillFirstGenDrafts(parsed, deliverableDraft, sectionDrafts) {
  const started = Date.now();
  const baseIntent = `first-gen:${stableHash([parsed.namespace, parsed.task])}`;
  const overall = seedReflex(
    `${baseIntent}:deliverable`,
    parsed.task,
    deliverableDraft,
    parsed.model
  );
  const sections = sectionDrafts.map((draft) => {
    const intent = `${baseIntent}:section:${draft.section}`;
    const prompt = `${parsed.task} section ${draft.section} ${draft.title}`;
    const written = seedReflex(intent, prompt, draft.draft, parsed.model);
    recordReflexScore({
      event: "first_gen_draft_distilled",
      model: written.entry.model,
      intent_key: written.entry.intent_key,
      section: draft.section,
      elapsed_ms: 0
    });
    return {
      section: draft.section,
      title: draft.title,
      intent,
      intent_key: written.entry.intent_key,
      cache_path: written.path,
      bytes: Buffer.byteLength(draft.draft || "")
    };
  });
  recordReflexScore({
    event: "first_gen_draft_distilled",
    model: overall.entry.model,
    intent_key: overall.entry.intent_key,
    sections: sections.length,
    elapsed_ms: Date.now() - started
  });
  return {
    schema: "mercury-first-gen-distillation-v1",
    model: parsed.model,
    base_intent: baseIntent,
    overall: {
      intent: `${baseIntent}:deliverable`,
      intent_key: overall.entry.intent_key,
      cache_path: overall.path,
      bytes: Buffer.byteLength(deliverableDraft || "")
    },
    sections,
    seeded_count: 1 + sections.length,
    elapsed_ms: Date.now() - started,
    policy: "hot-path drafts are immediately promoted to reflex memory while slow workers refine later"
  };
}

function firstGenAccelerateCommand(args = []) {
  ensureDirs();
  const parsed = firstGenArgs(args);
  const started = Date.now();
  const baseIntent = `first-gen:${stableHash([parsed.namespace, parsed.task])}`;
  if (!parsed.refresh) {
    const replay = reflexLookupWithQueue({
      model: parsed.model,
      intent: `${baseIntent}:deliverable`,
      prompt: parsed.task,
      semantic: false,
      enqueueMiss: false,
      source: "first_gen_distilled_replay"
    });
    if (replay.ok) {
      const virtualRoute = virtualFieldRoute(parsed.task, ["--lanes=16", "--budget=8"]);
      const report = {
        schema: "mercury-first-gen-accelerate-v1",
        created_at: nowIso(),
        task: parsed.task,
        namespace: parsed.namespace,
        path: parsed.path,
        mode: "distilled_first_generation_replay",
        sections: parsed.sections,
        workers: parsed.workers,
        packet: null,
        scaffold_bytes: 0,
        immediate_draft_bytes: Buffer.byteLength(replay.response || ""),
        immediate_draft: replay.response,
        deliverable_draft: replay.response,
        section_drafts: [],
        judge: {
          schema: "mercury-first-gen-judge-v1",
          score: 100,
          pass: true,
          replay: true,
          rule: "previous evidence-bound hot-path draft replayed from reflex memory"
        },
        distillation: {
          schema: "mercury-first-gen-distillation-v1",
          base_intent: baseIntent,
          replay: true,
          seeded_count: 0,
          overall: {
            intent: `${baseIntent}:deliverable`,
            intent_key: replay.matched_intent_key || replay.intent_key
          }
        },
        virtual_route: virtualRoute,
        neuron_map: {
          schema: "mercury-first-gen-neuron-map-v1",
          active_neurons: 0,
          virtual_route: {
            active_lanes: virtualRoute.active_lanes || 0,
            active_virtual_neurons: virtualRoute.active_virtual_neurons || 0,
            unique_physical_control_neurons: virtualRoute.unique_physical_control_neurons || 0,
            lanes: (virtualRoute.lanes || []).map((lane) => lane.lane)
          },
          lanes: []
        },
        section_jobs: [],
        waves: [],
        estimate: {
          serial_ms: parsed.serialMs,
          parallel_ms: Date.now() - started,
          speedup: visualSpeedup(parsed.serialMs, Math.max(1, Date.now() - started)),
          note: "Replay path: previous first-generation hot-path draft was already distilled into reflex memory."
        },
        timings: {
          replay_ms: replay.elapsed_ms,
          elapsed_ms: Date.now() - started
        }
      };
      appendMemoryGraphEvent({
        type: "first_gen_replay",
        task: parsed.task,
        path: parsed.path,
        namespace: parsed.namespace,
        bytes: report.immediate_draft_bytes,
        virtual_route_lanes: (virtualRoute.lanes || []).map((lane) => lane.lane),
        virtual_route_controllers: virtualRoute.unique_physical_control_neurons || 0,
        active_virtual_neurons: virtualRoute.active_virtual_neurons || 0,
        elapsed_ms: report.timings.elapsed_ms
      });
      if (parsed.json) {
        console.log(JSON.stringify(report));
        return report;
      }
      console.log("Neuron Mercury first-generation accelerate");
      console.log(`mode: ${report.mode}`);
      console.log(`immediate_draft_bytes: ${report.immediate_draft_bytes}`);
      console.log(`virtual_route: ${(virtualRoute.lanes || []).map((lane) => lane.lane).join(",") || "-"} controllers=${virtualRoute.unique_physical_control_neurons || 0}`);
      console.log(`replay_ms: ${report.timings.replay_ms}`);
      console.log(`elapsed_ms: ${report.timings.elapsed_ms}`);
      return report;
    }
  }
  const cold = silencedConsole(() => coldStartAccelerateCommand([
    parsed.task,
    `--path=${parsed.path}`,
    `--limit=${parsed.limit}`,
    `--namespace=${parsed.namespace}`,
    `--budget-ms=${parsed.budgetMs}`,
    ...(parsed.include.length ? [`--include=${parsed.include.join(",")}`] : []),
    ...(parsed.exclude.length ? [`--exclude=${parsed.exclude.join(",")}`] : []),
    "--no-queue",
    "--json"
  ]));
  const titles = firstGenSectionTitles(parsed.task, parsed.sections);
  const neuronMap = buildFirstGenNeuronMap(parsed.task, titles, parsed.workers, cold.packet);
  const immediateDraft = buildFirstGenAssemblyDraft(parsed.task, titles, cold.packet, neuronMap);
  const sectionDrafts = buildFirstGenSectionDrafts(parsed.task, titles, cold.packet, neuronMap);
  const judge = judgeFirstGenDrafts(sectionDrafts, cold.packet);
  const guardedProviderHint = firstGenSpendGuardedProviderHint(parsed.workers);
  const deliverableDraft = [
    immediateDraft,
    "",
    "Hot-path section drafts:",
    "",
    ...sectionDrafts.map((draft) => draft.draft),
    "",
    `Judge: score=${judge.score}, pointer_coverage=${judge.pointer_coverage}, sections_with_evidence=${judge.sections_with_evidence}/${judge.sections}`
  ].join("\n");
  const sectionJobs = titles.map((title, index) => {
    const lane = (neuronMap.lanes || []).find((entry) => entry.sections.some((section) => section.section === index + 1));
    const sectionMeta = lane?.sections.find((section) => section.section === index + 1);
    const sectionPrompt = [
      `Task: ${parsed.task}`,
      `Section ${index + 1}/${parsed.sections}: ${title}`,
      `Neuron: ${sectionMeta?.neuron_id || "synthesis.section"} (${sectionMeta?.cluster || "synthesis"})`,
      `Virtual field: lane=${sectionMeta?.virtual_lane || "pending"} controller=${sectionMeta?.virtual_controller || "pending"}`,
      `Worker lane: ${lane?.worker || 1}`,
      "Use the UMA evidence packet. Produce only this section. Keep facts tied to pointers.",
      "",
      cold.scaffold,
      "",
      sectionDrafts[index]?.draft || immediateDraft,
      "",
      evidencePacketPrompt(cold.packet)
    ].join("\n");
    const job = enqueueSlowReflex({
      model: parsed.model,
      intent: `first-gen:${stableHash([parsed.namespace, parsed.task])}:section:${index + 1}`,
      prompt: sectionPrompt,
      source: "first_gen_accelerate",
      providerHint: guardedProviderHint,
      providerHintLocked: true,
      metadata: {
        family: "first_generation_section",
        paid_provider_fanout: "blocked",
        max_paid_concurrency: 0,
        namespace: parsed.namespace,
        task_hash: stableHash([parsed.namespace, parsed.task]),
        section: index + 1,
        title,
        worker: lane?.worker || ((index % parsed.workers) + 1),
        wave: Math.floor(index / parsed.workers) + 1,
        neuron_id: sectionMeta?.neuron_id || "synthesis.section",
        cluster: sectionMeta?.cluster || "synthesis"
      }
    });
    return {
      section: index + 1,
      title,
      worker: lane?.worker || ((index % parsed.workers) + 1),
      wave: Math.floor(index / parsed.workers) + 1,
      neuron_id: sectionMeta?.neuron_id || "synthesis.section",
      virtual_lane: sectionMeta?.virtual_lane || null,
      virtual_controller: sectionMeta?.virtual_controller || null,
      evidence_pointer: sectionMeta?.evidence_pointer || null,
      job_id: job.job_id,
      status: job.status,
      seen_count: job.seen_count,
      provider_hint: job.provider_hint,
      provider_hint_locked: true
    };
  });
  const dispatchPlan = buildFirstGenDispatchPlan(sectionJobs, parsed.workers, parsed.serialMs);
  const waves = dispatchPlan.waves.map((wave) => wave.lanes.map((job) => job.section));
  const estimatedSectionMs = parsed.serialMs / parsed.sections;
  const estimatedParallelMs = dispatchPlan.critical_path_ms || Math.ceil(parsed.sections / parsed.workers) * estimatedSectionMs;
  const distillation = distillFirstGenDrafts(parsed, deliverableDraft, sectionDrafts);
  const report = {
    schema: "mercury-first-gen-accelerate-v1",
    created_at: nowIso(),
    task: parsed.task,
    namespace: parsed.namespace,
    path: parsed.path,
    mode: "parallel_first_generation_plan",
    sections: parsed.sections,
    workers: parsed.workers,
    packet: cold.packet,
    scaffold_bytes: Buffer.byteLength(cold.scaffold || ""),
    immediate_draft_bytes: Buffer.byteLength(deliverableDraft || ""),
    immediate_draft: immediateDraft,
    deliverable_draft: deliverableDraft,
    section_drafts: sectionDrafts,
    judge,
    distillation,
    neuron_map: neuronMap,
    dispatch_plan: dispatchPlan,
    provider_fanout_guard: guardedProviderHint,
    section_jobs: sectionJobs,
    waves,
    estimate: {
      serial_ms: parsed.serialMs,
      parallel_ms: Number(estimatedParallelMs.toFixed(3)),
      speedup: visualSpeedup(parsed.serialMs, estimatedParallelMs),
      note: "Estimate assumes independent section generation on available slow workers/providers; hot path only prepares evidence-bound jobs."
    },
    timings: {
      cold_start_ms: cold.timings.elapsed_ms,
      elapsed_ms: Date.now() - started
    }
  };
  const reportPath = join(COLD_START_DIR, `first_gen_${stableHash([parsed.namespace, parsed.task, Date.now()])}.json`);
  atomicWriteJson(reportPath, report, { pretty: true });
  atomicWriteJson(join(COLD_START_DIR, "first-gen-latest.json"), report, { pretty: true });
  appendMemoryGraphEvent({
    type: "first_gen_accelerate",
    task: parsed.task,
    path: parsed.path,
    namespace: parsed.namespace,
    sections: parsed.sections,
    workers: parsed.workers,
    dispatch_waves: dispatchPlan.waves.length,
    dispatch_max_concurrency: dispatchPlan.max_concurrency,
    immediate_draft_bytes: report.immediate_draft_bytes,
    judge_score: judge.score,
    pointer_coverage: judge.pointer_coverage,
    distilled_reflexes: distillation.seeded_count,
    active_neurons: neuronMap.active_neurons,
    virtual_route_lanes: neuronMap.virtual_route?.lanes || [],
    virtual_route_controllers: neuronMap.virtual_route?.unique_physical_control_neurons || 0,
    active_virtual_neurons: neuronMap.virtual_route?.active_virtual_neurons || 0,
    route: cold.packet.route,
    hit_count: cold.packet.hit_count,
    estimated_speedup: report.estimate.speedup,
    elapsed_ms: report.timings.elapsed_ms
  });
  if (parsed.json) {
    console.log(JSON.stringify(report));
    return report;
  }
  console.log("Neuron Mercury first-generation accelerate");
  console.log(`mode: ${report.mode}`);
  console.log(`sections: ${report.sections} workers=${report.workers} waves=${report.waves.length}`);
  console.log(`immediate_draft_bytes: ${report.immediate_draft_bytes}`);
  console.log(`distilled_reflexes: ${report.distillation.seeded_count}`);
  console.log(`active_neurons: ${report.neuron_map.active_neurons}`);
  console.log(`route: ${report.packet.route} hits=${report.packet.hit_count}`);
  console.log(`estimate: ${report.estimate.serial_ms}ms -> ${report.estimate.parallel_ms}ms (${report.estimate.speedup}x)`);
  console.log(`elapsed_ms: ${report.timings.elapsed_ms}`);
	  console.log(`report: ${reportPath}`);
	  return report;
	}

function loadBenchSuite(path) {
  const suitePath = resolve(process.cwd(), path);
  const suite = JSON.parse(readFileSync(suitePath, "utf8"));
  if (!Array.isArray(suite.tasks)) {
    throw new Error("Bench suite must include a tasks array.");
  }
  return { suitePath, suite };
}

function summarizeBenchResult(task, result) {
  const findings = result.patchPlan.findings || [];
  const rankTotals = {};
  for (const finding of findings) {
    for (const [rank, count] of Object.entries(finding.evidence_rank_summary || {})) {
      rankTotals[rank] = (rankTotals[rank] || 0) + count;
    }
  }
  const artifactSignals = Object.fromEntries(
    result.artifacts.map((artifact) => [artifact.neuron_id, artifact.signal])
  );
  const targetHits = result.patchPlan.target_files.filter((file) => task.expected_targets?.includes(file)).length;
  const targetPrecision = result.patchPlan.target_files.length
    ? targetHits / result.patchPlan.target_files.length
    : 0;

  return {
    id: task.id,
    task: task.task,
    elapsed_ms: result.elapsedMs,
    circuit_size: result.circuit.length,
    target_files: result.patchPlan.target_files,
    expected_targets: task.expected_targets || [],
    target_precision: Number(targetPrecision.toFixed(3)),
    finding_count: findings.length,
    risk_families: findings.map((finding) => finding.neuron_id),
    rank_totals: rankTotals,
    high_evidence_count: rankTotals.high || 0,
    artifact_signals: artifactSignals,
    timings: result.timings,
    neuron_timings: Object.fromEntries(result.artifacts.map((artifact) => [artifact.neuron_id, artifact.elapsed_ms])),
    trace_path: result.tracePath
  };
}

function writeBenchHistory(report, path) {
  ensureDirs();
  const historyPath = join(BENCH_DIR, "history.jsonl");
  const budget = evaluateSpeedBudget(report);
  const row = {
    created_at: report.created_at,
    suite: report.suite,
    cwd: report.cwd,
    task_count: report.task_count,
    total_ms: report.totals.elapsed_ms,
    max_run_ms: report.totals.max_run_elapsed_ms,
    high_evidence_count: report.totals.high_evidence_count,
    avg_target_precision: report.totals.avg_target_precision,
    min_run_high_evidence_count: budget.metrics?.min_run_high_evidence_count ?? report.totals.high_evidence_count,
    min_run_target_precision: budget.metrics?.min_run_target_precision ?? report.totals.avg_target_precision,
    speed_budget_ok: budget.ok,
    report_path: path
  };
  appendFileSync(historyPath, JSON.stringify(row) + "\n", "utf8");
  return historyPath;
}

function parseBenchHistoryArgs(args) {
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const suiteArg = args.find((arg) => arg.startsWith("--suite="));
  return {
    limit: limitArg ? Math.max(1, Number(limitArg.split("=")[1]) || 12) : 12,
    suite: suiteArg ? suiteArg.split("=").slice(1).join("=") : null
  };
}

function readBenchHistoryRows(limit, suite = null) {
  ensureDirs();
  const historyPath = join(BENCH_DIR, "history.jsonl");
  if (!existsSync(historyPath)) return { historyPath, rows: [] };
  const rows = readTailText(historyPath, 1024 * 1024)
    .split(/\r?\n/)
    .filter(Boolean)
    .map((line) => {
      try {
        return JSON.parse(line);
      } catch {
        return null;
      }
    })
    .filter((row) => row && (!suite || row.suite === suite))
    .slice(-limit);
  return { historyPath, rows };
}

function speedTrendSummary(options = {}) {
  ensureDirs();
  const limit = Math.max(1, Number(options.limit) || 48);
  const { historyPath, rows: benchRows } = readBenchHistoryRows(limit);
  const rowsBySuite = {};
  for (const row of benchRows) {
    const suite = row.suite || "unknown";
    if (!rowsBySuite[suite]) rowsBySuite[suite] = [];
    rowsBySuite[suite].push(row);
  }
  const suiteTrends = Object.entries(rowsBySuite).map(([suite, rows]) => {
    const first = rows[0] || {};
    const latest = rows[rows.length - 1] || {};
    const firstMs = Number(first.max_run_ms ?? first.total_ms ?? 0);
    const latestMs = Number(latest.max_run_ms ?? latest.total_ms ?? 0);
    const bestMs = Math.min(...rows.map((row) => Number(row.max_run_ms ?? row.total_ms ?? Infinity)).filter(Number.isFinite));
    return {
      suite,
      rows: rows.length,
      first_ms: firstMs,
      latest_ms: latestMs,
      best_ms: Number.isFinite(bestMs) ? bestMs : 0,
      speedup_since_first: visualSpeedup(firstMs || latestMs || 1, latestMs || 1),
      latest_budget_ok: latest.speed_budget_ok !== false,
      latest_high_evidence: latest.min_run_high_evidence_count ?? latest.high_evidence_count ?? 0,
      latest_precision: latest.min_run_target_precision ?? latest.avg_target_precision ?? 0
    };
  }).sort((a, b) => b.speedup_since_first - a.speedup_since_first || a.latest_ms - b.latest_ms);
  const memoryRows = readMemoryGraphRows(5000);
  const recentMemory = memoryRows.slice(-limit);
  const memoryByType = {};
  for (const row of recentMemory) memoryByType[row.type || "unknown"] = (memoryByType[row.type || "unknown"] || 0) + 1;
  const laneHealth = neuronLaneHealthSummary(1500);
  const cacheStats = llmCacheFastSummary();
  const umaProject = umaNamespaceStatus(projectUmaNamespace());
  const hotCache = hotCacheSummary(umaProject.namespace);
  const qwerPlan = silencedConsole(() => cachedQwerSpeedPlan({ ttlMs: 1000 }));
  const residentCaches = {
    task_route: { items: RESIDENT_TASK_ROUTE_CACHE.size, limit: RESIDENT_TASK_ROUTE_CACHE_LIMIT },
    accelerate_task: { items: RESIDENT_ACCELERATE_TASK_CACHE.size, limit: RESIDENT_ACCELERATE_TASK_CACHE_LIMIT },
    qwer_speed_plan: {
      active: Boolean(QWER_SPEED_PLAN_CACHE),
      age_ms: QWER_SPEED_PLAN_CACHE ? Date.now() - QWER_SPEED_PLAN_CACHE.at : 0
    },
    speed_state: {
      active: Boolean(SPEED_STATE_CACHE),
      age_ms: SPEED_STATE_CACHE ? Date.now() - SPEED_STATE_CACHE.at : 0
    }
  };
  const fastestSuites = suiteTrends.filter((item) => item.latest_budget_ok).slice(0, 6);
  const slowerSuites = suiteTrends.filter((item) => !item.latest_budget_ok).slice(0, 6);
  const report = {
    schema: "mercury-speed-trends-v1",
    created_at: nowIso(),
    cwd: process.cwd(),
    history_path: historyPath,
    window_rows: benchRows.length,
    suite_trends: suiteTrends,
    fastest_suites: fastestSuites,
    needs_attention: slowerSuites,
    resident_caches: residentCaches,
    qwer_speed_plan: {
      provider: qwerPlan.provider_hint?.provider || "none",
      route: qwerPlan.provider_hint?.route || "none",
      cache_mode: qwerPlan.cache?.mode || "none",
      qwer_pending: qwerPlan.queue?.qwer_pending || 0,
      qwen_cache: qwerPlan.provider_cache?.qwen_files || 0
    },
    uma: {
      namespace: umaProject.namespace,
      pages: umaProject.pages,
      files: umaProject.files,
      symbols: umaProject.symbol_count,
      hot_pages: hotCache.pages,
      hot_events: hotCache.events || 0,
      refresh_needed: Boolean(umaProject.needs_file_table_refresh)
    },
    uma_batch: {
      namespace_index_cache: UMA_NAMESPACE_INDEX_CACHE.size,
      source_page_cache: UMA_SOURCE_PAGES_CACHE.size,
      symbol_lookup_cache: UMA_SYMBOL_LOOKUP_CACHE.size,
      project_namespace_default: true,
      keep_warm_active: Boolean(RESIDENT_UMA_WARM_TIMER),
      keep_warm_mode: RESIDENT_UMA_WARM_STATE?.mode || null,
      resident_endpoint: "/uma/batch-search"
    },
    neuron_lanes: {
      rows: laneHealth.rows,
      lanes: laneHealth.lanes.length,
      promote: laneHealth.promote.slice(0, 5),
      throttle: laneHealth.throttle.slice(0, 5)
    },
    neuron_coverage: neuronCoverageTrendSummary(5000, { taskLimit: 12 }),
    memory_graph: {
      rows: memoryRows.length,
      recent_rows: recentMemory.length,
      by_type: memoryByType
    },
    reflex_cache: {
      files: cacheStats.files,
      qwen_files: cacheStats.qwen_files,
      indexed_models: cacheStats.indexed_models
    }
  };
  const path = join(BENCH_DIR, "speed-trends.json");
  atomicWriteJson(path, report, { pretty: true });
  report.path = path;
  return report;
}

function speedTrendStateSummary(options = {}) {
  const limit = Math.max(1, Number(options.limit) || 48);
  const { rows: benchRows } = readBenchHistoryRows(limit);
  const rowsBySuite = {};
  for (const row of benchRows) {
    const suite = row.suite || "unknown";
    if (!rowsBySuite[suite]) rowsBySuite[suite] = [];
    rowsBySuite[suite].push(row);
  }
  const suiteTrends = Object.entries(rowsBySuite).map(([suite, rows]) => {
    const latest = rows[rows.length - 1] || {};
    const latestMs = Number(latest.max_run_ms ?? latest.total_ms ?? 0);
    const bestMs = Math.min(...rows.map((row) => Number(row.max_run_ms ?? row.total_ms ?? Infinity)).filter(Number.isFinite));
    return {
      suite,
      rows: rows.length,
      latest_ms: latestMs,
      best_ms: Number.isFinite(bestMs) ? bestMs : 0,
      latest_budget_ok: latest.speed_budget_ok !== false
    };
  }).sort((a, b) => a.latest_ms - b.latest_ms);
  return {
    window_rows: benchRows.length,
    suite_trends: suiteTrends,
    fastest_suites: suiteTrends.filter((item) => item.latest_budget_ok).slice(0, 4),
    needs_attention: suiteTrends.filter((item) => !item.latest_budget_ok).slice(0, 4),
    path: join(BENCH_DIR, "speed-trends.json")
  };
}

function speedTrendsCommand(args = []) {
  const json = args.includes("--json");
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const report = speedTrendSummary({ limit: limitArg ? Number(limitArg.split("=")[1]) || 48 : 48 });
  if (json) {
    console.log(JSON.stringify(report));
    return report;
  }
  console.log("Neuron Mercury speed trends");
  console.log(`window_rows: ${report.window_rows}`);
  console.log(`resident_cache: route=${report.resident_caches.task_route.items}, accelerate=${report.resident_caches.accelerate_task.items}, qwer_plan=${report.resident_caches.qwer_speed_plan.active ? "warm" : "cold"}`);
  console.log(`qwer: provider=${report.qwer_speed_plan.provider}, route=${report.qwer_speed_plan.route}, cache=${report.qwer_speed_plan.cache_mode}, qwen_cache=${report.qwer_speed_plan.qwen_cache}`);
  console.log(`uma: pages=${report.uma.pages}, hot=${report.uma.hot_pages}, symbols=${report.uma.symbols}, refresh_needed=${report.uma.refresh_needed ? "yes" : "no"}`);
  console.log(`neuron_lanes: rows=${report.neuron_lanes.rows}, promote=${report.neuron_lanes.promote.length}, throttle=${report.neuron_lanes.throttle.length}`);
  for (const suite of report.fastest_suites.slice(0, 6)) {
    console.log(`- ${suite.suite}: latest=${suite.latest_ms}ms best=${suite.best_ms}ms budget=${suite.latest_budget_ok ? "pass" : "fail"} rows=${suite.rows}`);
  }
  if (report.needs_attention.length) {
    console.log("attention:");
    for (const suite of report.needs_attention) console.log(`- ${suite.suite}: latest=${suite.latest_ms}ms budget=fail`);
  }
  console.log(`report: ${report.path}`);
  return report;
}

function benchHistory(args) {
  const parsed = parseBenchHistoryArgs(args);
  const { historyPath, rows } = readBenchHistoryRows(parsed.limit, parsed.suite);
  console.log("Neuron Mercury bench history");
  console.log(`history: ${historyPath}`);
  if (parsed.suite) console.log(`suite: ${parsed.suite}`);
  if (!rows.length) {
    console.log("rows: 0");
    return;
  }
  const fastest = Math.min(...rows.map((row) => row.max_run_ms || row.total_ms || 0));
  const slowest = Math.max(...rows.map((row) => row.max_run_ms || row.total_ms || 0));
  const latest = rows[rows.length - 1];
  console.log(`rows: ${rows.length}`);
  console.log(`latest: ${latest.suite} max=${latest.max_run_ms ?? latest.total_ms}ms high=${latest.min_run_high_evidence_count ?? latest.high_evidence_count} precision=${latest.min_run_target_precision ?? latest.avg_target_precision} budget=${latest.speed_budget_ok === false ? "fail" : "pass"}`);
  console.log(`range: fastest=${fastest}ms slowest=${slowest}ms`);
  for (const row of rows) {
    const maxRun = row.max_run_ms ?? row.total_ms;
    const minHigh = row.min_run_high_evidence_count ?? row.high_evidence_count;
    const minPrecision = row.min_run_target_precision ?? row.avg_target_precision;
    const budget = row.speed_budget_ok === false ? "fail" : "pass";
    console.log(`- ${row.created_at} ${row.suite}: max=${maxRun}ms high=${minHigh} precision=${minPrecision} budget=${budget}`);
  }
}

function writeBenchReport(suite, summaries) {
  ensureDirs();
  const runTotals = Object.values(summaries.reduce((acc, item) => {
    const run = item.run || 1;
    if (!acc[run]) {
      acc[run] = {
        run,
        elapsed_ms: 0,
        high_evidence_count: 0,
        finding_count: 0,
        target_precision_sum: 0,
        task_count: 0
      };
    }
    acc[run].elapsed_ms += item.elapsed_ms;
    acc[run].high_evidence_count += item.high_evidence_count;
    acc[run].finding_count += item.finding_count;
    acc[run].target_precision_sum += item.target_precision;
    acc[run].task_count += 1;
    return acc;
  }, {})).map((run) => ({
    run: run.run,
    elapsed_ms: run.elapsed_ms,
    high_evidence_count: run.high_evidence_count,
    finding_count: run.finding_count,
    avg_target_precision: run.task_count ? Number((run.target_precision_sum / run.task_count).toFixed(3)) : 0
  })).sort((a, b) => a.run - b.run);
  const report = {
    suite: suite.name || "unnamed",
    created_at: nowIso(),
    cwd: process.cwd(),
    task_count: summaries.length,
    totals: {
      elapsed_ms: summaries.reduce((sum, item) => sum + item.elapsed_ms, 0),
      max_run_elapsed_ms: runTotals.length ? Math.max(...runTotals.map((run) => run.elapsed_ms)) : 0,
      high_evidence_count: summaries.reduce((sum, item) => sum + item.high_evidence_count, 0),
      finding_count: summaries.reduce((sum, item) => sum + item.finding_count, 0),
      avg_target_precision: summaries.length
        ? Number((summaries.reduce((sum, item) => sum + item.target_precision, 0) / summaries.length).toFixed(3))
        : 0
    },
    run_totals: runTotals,
    results: summaries
  };
  const path = join(BENCH_DIR, `bench_${Date.now()}.json`);
  atomicWriteJson(path, report);
  const historyPath = writeBenchHistory(report, path);
  return { path, report, historyPath };
}

function preciseMs() {
  return Number(process.hrtime.bigint()) / 1e6;
}

function measureMs(fn, repeat = 1) {
  const samples = [];
  let value = null;
  for (let i = 0; i < repeat; i += 1) {
    const started = preciseMs();
    value = fn();
    samples.push(Number((preciseMs() - started).toFixed(3)));
  }
  const sorted = samples.slice().sort((a, b) => a - b);
  const total = samples.reduce((sum, sample) => sum + sample, 0);
  return {
    value,
    samples,
    min_ms: sorted[0] || 0,
    median_ms: sorted[Math.floor(sorted.length / 2)] || 0,
    avg_ms: Number((total / Math.max(1, samples.length)).toFixed(3))
  };
}

function visualSpeedup(beforeMs, afterMs) {
  const before = Math.max(0.001, Number(beforeMs) || 0.001);
  const after = Math.max(0.001, Number(afterMs) || 0.001);
  return Number((before / after).toFixed(2));
}

function primeKernel(limit = 65000) {
  let count = 0;
  let checksum = 0;
  for (let n = 2; n <= limit; n += 1) {
    let prime = true;
    for (let d = 2; d * d <= n; d += 1) {
      if (n % d === 0) {
        prime = false;
        break;
      }
    }
    if (prime) {
      count += 1;
      checksum = (checksum + n) % 1000000007;
    }
  }
  return { count, checksum };
}

function htmlEscape(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

