function parseProductArgs(args = []) {
  const sub = args.find((arg) => !arg.startsWith("--")) || "status";
  const taskArgs = args.filter((arg) => !arg.startsWith("--") && arg !== sub);
  const pathArg = args.find((arg) => arg.startsWith("--path="));
  const limitArg = args.find((arg) => arg.startsWith("--limit="));
  const portArg = args.find((arg) => arg.startsWith("--port="));
  const hostArg = args.find((arg) => arg.startsWith("--host="));
  const include = parseCsvArg(args, "include");
  const exclude = parseCsvArg(args, "exclude");
  return {
    sub,
    task: taskArgs.join(" ") || "diagnose project acceleration risk",
    path: pathArg ? pathArg.split("=").slice(1).join("=") : ".",
    limit: limitArg ? Math.max(40, Math.min(2000, Number(limitArg.split("=")[1]) || 240)) : 240,
    host: hostArg ? hostArg.split("=").slice(1).join("=") : "127.0.0.1",
    port: portArg ? Math.max(1, Number(portArg.split("=")[1]) || 17345) : 17345,
    include,
    exclude,
    json: args.includes("--json"),
    refresh: args.includes("--refresh"),
    fast: args.includes("--fast")
  };
}

function productStableScopeArgs(parsed) {
  const include = parsed.include?.length
    ? parsed.include
    : ["src", "scripts", "README.md", "package.json"];
  const exclude = parsed.exclude?.length
    ? parsed.exclude
    : ["docs", "var", "paper-data"];
  return [
    `--path=${parsed.path}`,
    `--include=${include.join(",")}`,
    `--exclude=${exclude.join(",")}`
  ];
}

