function benchDiskSpdProofArtifactGuard(args = []) {
  const started = Date.now();
  const dir = join(VAR_DIR, "external-bench");
  mkdirSync(dir, { recursive: true });
  const before = latestDiskSpdBeforeAfter();
  const poisonPath = join(dir, "diskspd-before-after-20990101T000000Z.json");
  const poison = {
    schema: "mercury-diskspd-before-after-v1",
    created_at: "2099-01-01T00:00:00.000Z",
    pass: false,
    policy: "poison artifact for latest-pass guard",
    rows: [
      { lane: "seq_read", throughput_ratio: 0.1, latency_ratio: 9, pass: false }
    ]
  };
  atomicWriteJson(poisonPath, poison, { pretty: true });
  const after = latestDiskSpdBeforeAfter();
  try { unlinkSync(poisonPath); } catch {}
  const compareScript = existsSync(join(ROOT, "scripts", "windows-diskspd-compare.ps1"))
    ? readFileSync(join(ROOT, "scripts", "windows-diskspd-compare.ps1"), "utf8")
    : "";
  const proofScript = existsSync(join(ROOT, "scripts", "windows-product-proof.ps1"))
    ? readFileSync(join(ROOT, "scripts", "windows-product-proof.ps1"), "utf8")
    : "";
  const checks = [
    { id: "baseline_available", pass: Boolean(before?.pass), detail: before?.path || "missing" },
    { id: "poison_rejected", pass: Boolean(after?.pass) && after.path !== poisonPath, detail: after?.path || "missing" },
    { id: "compare_preserves_failed_latest", pass: /preserving previous diskspd-before-after-latest\.json/i.test(compareScript), detail: "failed compare cannot overwrite latest" },
    { id: "compare_allow_failed_latest_opt_in", pass: /AllowFailedLatest/.test(compareScript), detail: "failed latest requires explicit opt-in" },
    { id: "proof_preserves_failed_latest", pass: /preserving previous latest proof artifacts/i.test(proofScript), detail: "failed full proof cannot overwrite latest" },
    { id: "skip_qwen_not_latest", pass: /Qwen skipped; preserving previous full latest proof artifacts/i.test(proofScript), detail: "partial proof cannot overwrite full proof" }
  ];
  const elapsed = Date.now() - started;
  const pass = checks.every((check) => check.pass) && elapsed <= 100;
  atomicWriteJson(join(BENCH_DIR, "diskspd-proof-artifact-guard.json"), {
    schema: "mercury-diskspd-proof-artifact-guard-bench-v1",
    created_at: nowIso(),
    pass,
    elapsed_ms: elapsed,
    checks
  }, { pretty: true });
  console.log("Neuron Mercury DiskSpd proof artifact guard bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  for (const check of checks) console.log(`- ${check.pass ? "pass" : "fail"} ${check.id}: ${check.detail}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log("budget_ms: 100");
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return { pass, checks, elapsed_ms: elapsed };
}

function benchSpeedStateProductProof(args = []) {
  const started = Date.now();
  const full = cachedSpeedStateSnapshot({}, { ttlMs: 5000, refresh: true });
  const cacheStarted = Date.now();
  const cached = cachedSpeedStateSnapshot({}, { ttlMs: 5000 });
  const cacheElapsed = Date.now() - cacheStarted;
  const summary = speedStateSummary(cached);
  const elapsed = Date.now() - started;
  const proof = full.product_proof;
  const summaryProof = summary.product_proof;
  const checks = [
    { id: "full_product_proof_present", pass: Boolean(proof?.metrics), detail: proof?.pass ? "pass" : "missing_or_fail" },
    { id: "summary_product_proof_present", pass: Boolean(summaryProof), detail: summaryProof?.pass ? "pass" : "missing_or_fail" },
    { id: "qwen_speedup_visible", pass: Number(summaryProof?.qwen_first_request_speedup || 0) >= 2, detail: `${summaryProof?.qwen_first_request_speedup || 0}x` },
    { id: "hot_cache_visible", pass: Number(summaryProof?.qwen_cache_ms || 0) > 0 && Number(summaryProof?.qwen_cache_ms || 0) <= 5, detail: `${summaryProof?.qwen_cache_ms || 0}ms` },
    { id: "disk_no_regression_visible", pass: Number(summaryProof?.diskspd_min_throughput_ratio || 0) >= 0.9 && Number(summaryProof?.diskspd_max_latency_ratio || 99) <= 1.25, detail: `throughput=${summaryProof?.diskspd_min_throughput_ratio || 0} latency=${summaryProof?.diskspd_max_latency_ratio || 0}` },
    { id: "refresh_state_visible", pass: typeof summaryProof?.refresh_needed === "boolean", detail: summaryProof?.refresh_needed ? "refresh_needed" : "fresh" },
    { id: "speed_state_refresh_budget", pass: elapsed <= 5000, detail: `${elapsed}ms` },
    { id: "speed_state_cache_budget", pass: cacheElapsed <= 50 && cached.cache?.mode === "speed_state_cache_hit", detail: `${cacheElapsed}ms ${cached.cache?.mode || "unknown"}` }
  ];
  const pass = checks.every((check) => check.pass);
  atomicWriteJson(join(BENCH_DIR, "speed-state-product-proof.json"), {
    schema: "mercury-speed-state-product-proof-bench-v1",
    created_at: nowIso(),
    pass,
    elapsed_ms: elapsed,
    checks,
    product_proof: summaryProof
  }, { pretty: true });
  console.log("Neuron Mercury speed-state product proof bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  for (const check of checks) console.log(`- ${check.pass ? "pass" : "fail"} ${check.id}: ${check.detail}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log(`cache_elapsed_ms: ${cacheElapsed}`);
  console.log("budget_ms: refresh=5000 cache=50");
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return { pass, checks, elapsed_ms: elapsed };
}

