function benchInstallerManifest(args = []) {
  const started = Date.now();
  const out = silencedConsole(() => buildInstallerManifest(["--target=100000000"]));
  const elapsed = Date.now() - started;
  const pass = Boolean(out.ok)
    && existsSync(out.private_path)
    && existsSync(out.public_safe_path)
    && out.manifest.scale.target_neurons === ONE_HUNDRED_MILLION_NEURONS
    && out.manifest.scale.virtual_shard_count >= 20000
    && out.manifest.scale.physical_seed_neurons >= 500
    && out.manifest.runtime_gate.model_hot_path === "forbidden"
    && /public pages show outcomes/i.test(out.manifest.disclosure_policy.rule)
    && elapsed <= 8000;
  console.log("Neuron Mercury installer manifest bench");
  console.log(`pass: ${pass ? "yes" : "no"}`);
  console.log(`target_neurons: ${out.manifest.scale.target_neurons}`);
  console.log(`virtual_shards: ${out.manifest.scale.virtual_shard_count}`);
  console.log(`runtime_ready: ${out.manifest.runtime_gate.ready ? "yes" : "no"}`);
  console.log(`model_hot_path: ${out.manifest.runtime_gate.model_hot_path}`);
  console.log(`private_exists: ${existsSync(out.private_path) ? "yes" : "no"}`);
  console.log(`public_safe_exists: ${existsSync(out.public_safe_path) ? "yes" : "no"}`);
  console.log(`elapsed_ms: ${elapsed}`);
  console.log("budget_ms: 8000");
  console.log(`speed budget: ${pass ? "pass" : "fail"}`);
  if (!pass) process.exitCode = 1;
  return { pass, out };
}

function mercuryUniverseMap(options = {}) {
  const started = Date.now();
  const speed = speedStateSnapshot({ full: Boolean(options.full) });
  const readiness = productReadinessSnapshot({ refresh: Boolean(options.refresh) });
  const neurons = loadNeurons();
  const typeCounts = {};
  for (const neuron of neurons) typeCounts[neuron.type || "unknown"] = (typeCounts[neuron.type || "unknown"] || 0) + 1;
  const scale = buildScalePlan(["--target=100000000", "--shard-size=4096"]);
  const nodes = [
    { id: "computer", label: "Computer State", group: "root", status: "observed", detail: `${speed.host?.cpu?.cores || 0} cpu cores, gpu=${speed.runtime?.gpu_count || 0}` },
    { id: "runtime", label: "Runtime Detector", group: "hardware", status: "ready", detail: `${speed.runtime?.provider_priority?.length || 0} providers` },
    { id: "resident", label: "Resident Control Plane", group: "service", status: readiness.services?.some((s) => s.running) ? "ready" : "check", detail: readiness.services?.map((s) => `${s.name}:${s.running ? "on" : "off"}`).join(", ") || "none" },
    { id: "qwer", label: "Qwer / Local LLM Slow Path", group: "model", status: speed.qwer_speed?.policy?.model_hot_path === "forbidden" ? "guarded" : "check", detail: speed.qwer_speed?.provider_hint?.provider || "unknown" },
    { id: "reflex", label: "Reflex Cache", group: "memory", status: "ready", detail: `${speed.reflex_cache?.files || 0} files` },
    { id: "uma", label: "UMA/RAG Project Memory", group: "memory", status: speed.uma_project?.pages > 0 ? "ready" : "check", detail: `${speed.uma_project?.pages || 0} pages, ${speed.uma_project?.symbol_count || 0} symbols` },
    { id: "code_cortex", label: "Code Cortex", group: "memory", status: speed.uma_project?.symbol_count > 0 ? "ready" : "check", detail: `${speed.uma_project?.page_table_files || 0} file tables` },
    { id: "rosen", label: "Rosen Bridge Field", group: "rosen", status: speed.rosen_cortex?.ready ? "ready" : "check", detail: `${speed.rosen_cortex?.bridges || 0} bridges` },
    { id: "pairs", label: "Rosen Pair State Field", group: "rosen", status: speed.rosen_pairs?.ready ? "ready" : "check", detail: `${speed.rosen_pairs?.pairs || 0} pairs, ${speed.rosen_pairs?.pulse_events || 0} pulses` },
    { id: "neurons", label: "Neuron Catalog", group: "neuron", status: neurons.length >= 500 ? "ready" : "check", detail: `${neurons.length} physical neurons` },
    { id: "lanes", label: "Sparse Activation Lanes", group: "neuron", status: speed.neuron_lane_health?.lanes > 0 ? "ready" : "check", detail: `${speed.neuron_lane_health?.lanes || 0} lanes` },
    { id: "product", label: "Product Gate", group: "product", status: readiness.ready ? "ready" : "check", detail: `${readiness.checks?.filter((c) => c.pass).length || 0}/${readiness.checks?.length || 0} checks` },
    { id: "scale", label: "100M Virtual Neuron Plan", group: "future", status: "planned", detail: `${scale.virtual_shard_count} shards @ ${scale.virtual_shard_size}` }
  ];
  const edges = [
    ["computer", "runtime", "detects"],
    ["runtime", "qwer", "routes slow path"],
    ["computer", "resident", "hosts"],
    ["resident", "reflex", "serves"],
    ["resident", "uma", "keeps warm"],
    ["uma", "code_cortex", "indexes symbols"],
    ["uma", "rosen", "promotes bridges"],
    ["rosen", "pairs", "tracks state"],
    ["rosen", "neurons", "boosts selection"],
    ["neurons", "lanes", "sparse activation"],
    ["lanes", "product", "accelerates"],
    ["pairs", "product", "pulses changes"],
    ["scale", "neurons", "virtualizes"]
  ].map(([from, to, label]) => ({ from, to, label }));
  return {
    schema: "mercury-universe-rosen-map-v1",
    created_at: nowIso(),
    elapsed_ms: Date.now() - started,
    ready: readiness.ready,
    philosophy: "Do not control 100M neurons at once; sense state changes and wake only the bridge, memory, lane, and neuron family that matters.",
    namespace: speed.uma_project?.namespace || projectUmaNamespace(),
    nodes,
    edges,
    hardware_state: {
      host: speed.host,
      runtime: speed.runtime,
      policy: speed.policy
    },
    memory_state: {
      reflex_cache: speed.reflex_cache,
      uma_project: speed.uma_project,
      uma_hot_cache: speed.uma_hot_cache,
      workflow_replay: speed.workflow_replay,
      task_memory: speed.task_memory
    },
    rosen_state: {
      cortex: speed.rosen_cortex,
      pairs: speed.rosen_pairs
    },
    neuron_state: {
      catalog_total: neurons.length,
      by_type: typeCounts,
      lane_health: speed.neuron_lane_health,
      virtual_scale_plan: scale
    },
    product_state: readiness
  };
}

