  console.log(`ready: ${map.ready ? "yes" : "no"}`);
  console.log(`nodes: ${map.nodes.length}`);
  console.log(`edges: ${map.edges.length}`);
  console.log(`rosen_bridges: ${map.rosen_state.cortex.bridges}`);
  console.log(`rosen_pairs: ${map.rosen_state.pairs.pairs}`);
  console.log(`uma_pages: ${map.memory_state.uma_project.pages}`);
  console.log(`neurons: ${map.neuron_state.catalog_total}`);
