	  const ragLane = lanes.find((lane) => lane.category === "UMA / RAG");
	  const diagnosisLane = lanes.find((lane) => lane.category === "Nested Neurons");
		  const coldStartTask = `create first diagnosis report for ${targetRel} using UMA evidence packet before any model call`;
